const int N = 1e5 + 1;

int h[N], a[N];

struct node {
    int l, m, r;
    ll mx;
    node *L, *R;
    node (int lb, int rb) : mx(0) {
        l = lb, r = rb;
        m = l + r >> 1;
        if (l == r) return;
        L = new node(l, m);
        R = new node(m + 1, r);
    }
    void fix() {
        mx = max(L->mx, R->mx);
    }
    void upd(int lb, int rb, ll x) {
        if (r < lb || rb < l) return;
        if (lb <= l && r <= rb) {
            mx = x;
            return;
        }
        L->upd(lb, rb, x);
        R->upd(lb, rb, x);
        fix();
    }
    ll query(int lb, int rb) {
        if (r < lb || rb < l) return 0;
        if (lb <= l && r <= rb) return mx;
        ll lq = L->query(lb, rb);
        ll rq = R->query(lb, rb);
        return max(lq, rq);
    }
};

void solve() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++)
        cin >> h[i], --h[i];
    for (int i = 0; i < n; i++)
        cin >> a[i];

    node *rt = new node(0, n - 1);
    for (int i = 0; i < n; i++) {
        ll mx = rt->query(0, h[i] - 1);
        ll cur = rt->query(h[i], h[i]);
        rt->upd(h[i], h[i], max(cur, mx + a[i]));
    }
    cout << (rt->query(0, n - 1)) << '\n';
}
int main() {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    // int _; cin >> _; while (_--)
    solve();
    return 0;
}

