long long maxquery(int index,int lb,int rb,int lq,int rq)
{
    if((lb==lq&&rb==rq)||lb==rb)
	return t[index];
    int mid=(lb+rb)/2;
    long long maxx=0;
    if(rq<=mid)
	maxx=max(maxx,maxquery(index*2,lb,mid,lq,rq));
    else if(lq>mid)
	maxx=max(maxx,maxquery(index*2+1,mid+1,rb,lq,rq));
    else
    {
	maxx=max(maxx,maxquery(index*2,lb,mid,lq,mid));
	maxx=max(maxx,maxquery(index*2+1,mid+1,rb,mid+1,rq));
    }
    return maxx;
}
void update(int index,int lb,int rb,int ld,long long value)
{
    if(lb==rb&&lb==ld)
    {
	t[index]=max(t[index],value);
	return;
    }
    int mid=(lb+rb)/2;
    if(ld<=mid)
    {
	update(index*2,lb,mid,ld,value);
	t[index]=max(t[index],t[index*2]);
    }
    else
    {
	update(index*2+1,mid+1,rb,ld,value);
	t[index]=max(t[index],t[index*2+1]);
    }
}
