void init(ll n_){
    n=1;
    while(n<n_){
        n*=2;
    }
    rep(i,n*2-1){
        seg[i]=0;
    }
}
void update(ll k,ll a){
    k+=n-1;
    seg[k]=a;
    while(k>0){
        k--;
        k/=2;
        seg[k]=max(seg[2*k+1],seg[2*k+2]);
    }
}
//半開区間
ll query(ll a,ll b,ll k,ll l,ll r){
    if(r<=a||l>=b)return 0;
    if(l>=a&&r<=b)return seg[k];
    else {
        return max(query(a,b,k*2+1,l,(l+r)/2),query(a,b,k*2+2,(l+r)/2,r));
    }
}
