void segment_tree(v64& a, v64& t, int v, int tl, int tr){

	// RESIZE t to 4*n
	// a is the array and t is the segment tree made from array
	// initialise v = 1
	// tl and tr are bounds
	// initially tl = 0 and tr = n-1

	if(tl==tr) t[v] = a[tl];
	else{
		int tm = (tl+tr)/2;

		segment_tree(a, t, 2*v, tl, tm);             // left child
		segment_tree(a, t, 2*v + 1, tm+1, tr);       // right child

		t[v] = max(t[2*v], t[2*v + 1]);                  // the function we want 
	}
}

void update(v64& t, int pos, ll new_val, int v, int tl, int tr){

	// pos is the position that is to be updated

	if(tl==tr) t[v] = new_val;
	else{
		int tm = (tl+tr)/2;

		if(pos <= tm) update(t, pos, new_val, 2*v, tl, tm);
		else update(t, pos, new_val, 2*v + 1, tm+1, tr);

		t[v] = max(t[2*v], t[2*v + 1]);                  // the function we want
	}
}

ll query(v64& t, int v, int tl, int tr, int l, int r){

	// tl and tr are our intervals we get while processing
	// l and r are the intervals we require
	// tl = 0 and tr = n-1 and v = 1 at start

	if(l>r) return 0;                                // thing you want to return in this case like 0 for sum

	if(l==tl && r==tr) return t[v];
	else{
		int tm = (tl+tr)/2;
		return max(query(t, 2*v, tl, tm, l, min(r,tm)), query(t, 2*v + 1, tm+1, tr, max(l,tm+1), r));
	}
}

