    ll mid=(low+high)/2;

    update((2*node)+1,low,mid,l,r,val);
    update((2*node)+2,mid+1,high,l,r,val);

    seg[node]=max(seg[(2*node)+1],seg[(2*node)+2]);
}

ll query(ll node,ll low,ll high,ll l,ll r)
{
    if(l>high||r<low||l>r)
        return 0;

    if(l<=low&&r>=high)
        return seg[node];

    ll mid=(low+high)/2;

    return max(query((2*node)+1,low,mid,l,r),query((2*node)+2,mid+1,high,l,r));    
}

