void Modify(int l, int r, int x, ll val, int pos) {
    if (l == r) {
        mx[pos] = val;
        return ;
    }
    int mid = (l + r) >> 1;
    if (x <= mid) Modify(l, mid, x, val, pos << 1);
    else Modify(mid + 1, r, x, val, pos << 1 | 1);
    mx[pos] = max(mx[pos << 1], mx[pos << 1 | 1]);
}

inline ll Query(int l, int r, int L, int R, int pos) {
    if (L <= l && r <= R) return mx[pos];
    int mid = (l + r) >> 1;
    ll res = 0;
    if (L <= mid) res = Query(l, mid, L, R, pos << 1);
    if (mid < R) res = max(res, Query(mid + 1, r, L, R, pos << 1 | 1));
    return res;
}

