LL query (int a, int b) {
	int va = M + a, vb = M + b;
	LL wyn = w[va];
	if (va != vb) wyn = max(wyn, w[vb]);
	while (va / 2 != vb / 2) {
      	if (va % 2 == 0) wyn = max(wyn, w[va + 1]);
      	if (vb % 2 == 1) wyn = max(wyn, w[vb - 1]);
      	va /= 2; vb /= 2;
	}
	return wyn;
}

void init (int a) {
