typedef enum { MINIMUM, MAXIMUM } MinMax;

template <typename T>
class SegmentTree {
public:
    int bit_, N;
    vector<T> buf_;
    T invalid;
    MinMax mode; // MINIMUM / MAXIMUM

    SegmentTree(int size, MinMax mode=MINIMUM) : mode(mode) {
        N = 1;
        bit_ = 0;
        while (N < size) {
            N *= 2;
            ++bit_;
        }

        switch (mode) {
            case MINIMUM:
                if (sizeof(T) == 4) {
                    invalid = INT_MAX;
                } else if (sizeof(T) == 8) {
                    invalid = LLONG_MAX;
                }
                break;
            case MAXIMUM:
                if (sizeof(T) == 4) {
                    invalid = INT_MIN;
                } else if (sizeof(T) == 8) {
                    invalid = LLONG_MIN;
                }
                break;
        }
        buf_.assign(N*2, invalid);
    }

    T merge(T l, T r) {
        switch (mode) {
            case MINIMUM:
                return min(l, r);
            case MAXIMUM:
                return max(l, r);
        }
    }

    void update(int i, T x) {
        // assert(0 <= n && n < N);
        i = N + i - 1;

        if (merge(buf_[i], x) != x) return;

        buf_[i] = x;
        while (i > 0) {
			i = (i - 1) / 2;
			buf_[i] = merge(buf_[i*2+1], buf_[i*2+2]);
        }
    }

    T query(int lo, int hi) { // [lo, hi)
        return query(lo, hi, 0, 0, N);
    }
    T query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return invalid;

        if (a <= l && r <= b) {
            return buf_[k];
        } else {
			T lv = query(a, b, 2*k+1, l, (l+r)/2);
			T rb = query(a, b, 2*k+2, (l+r)/2, r);
			return merge(lv, rb);
        }
    }

    void dump() {
#ifdef DEBUG
        cerr << vector<T>(buf_.begin()+N, buf_.end()) << endl;
#endif
    }
};



ll solve(int N, vi& h, vi& a) {
    SegmentTree<ll> st(262143, MAXIMUM);

    ll best = 0;
    rep(i,N){
        int hi=h[i], ai=a[i];
        ll b = max(0LL, st.query(0, hi));
        st.update(hi, ai+b);
        debug(" %d) %d: %d+%lld\n", i, hi, ai, b);
        best = max(best, ai+b);
    }
    return best;
}

