using L = long long;

struct Tree {
	int size = 1;
	vector<L> tree;

	Tree(int n) {
		while(size < n)
			size *= 2;
		tree.resize(size * 2);
	}

	void set(int pos, L val) {
		tree[pos += size] = val;
		while(pos >>= 1)
			tree[pos] = max(tree[pos * 2], tree[pos * 2 + 1]);
	}

	L get(int l, int r) {
		L ans = max(tree[l += size], tree[r += size]);
		while(l / 2 != r / 2) {
			if(~l & 1)
				ans = max(ans, tree[l ^ 1]);
			if(r & 1)
				ans = max(ans, tree[r ^ 1]);
			l >>= 1;
			r >>= 1;
		}
		return ans;
	}
};

