long long int getMax(long long int l,long long int r,long long int crr_l,long long int crr_r,long long int si)
{
    if(crr_l>r||crr_r<l)
        return -1e15;

    if(crr_l>=l&&crr_r<=r)
        return tree[si];

    long long int mid=(crr_l+crr_r)/2;

    return max(getMax(l,r,crr_l,mid,(2*si)+1),getMax(l,r,mid+1,crr_r,(2*si)+2));
}

void update(long long int idx,long long int value,long long int l,long long int r,long long int si)
{
    if(l==r)
    {
        tree[si]=value+getMax(0,idx-1,0,n,0);
        return;
    }

    long long int mid=(l+r)/2;

    if(idx<=mid)
        update(idx,value,l,mid,(2*si)+1);
    else
        update(idx,value,mid+1,r,(2*si)+2);

    tree[si]=max(tree[(2*si)+1],tree[(2*si)+2]);
}

