        tree[node]=val;

        return;
    }

    int mid=(st+end)/2;

    if(ind<=mid)
    update(2*node,st,mid,val,ind);
    else
    update(2*node+1,mid+1,end,val,ind);

    tree[node]=max(tree[2*node],tree[2*node+1]);
}

ll query(int node,int st,int end,int l,int r)
{
    if(st>r or end<l)
    return 0;

    if(st>=l and end<=r)
    return tree[node];

    int mid=(st+end)/2;

    ll x,y;

    x=query(2*node,st,mid,l,r);

    y=query(2*node+1,mid+1,end,l,r);

    return max(x,y);
}


