template <typename T>
class segment_tree
{
private:
    int n;
    vector<T> tree;

public:
    segment_tree(int size)
    {
        int temp = 1;
        while (temp < size)
            temp = temp * 2;

        n = temp * 2;
        tree.resize(n, 0); // empty seg. tree
    }

    T query(int l, int r, int ql, int qr, int pos)
    {
        if (ql > r || qr < l)
        {
            return 0;
        }
        else if (ql <= l && qr >= r)
        {
            return tree[pos];
        }
        int mid = (l + r) / 2;
        return max(query(l, mid, ql, qr, 2 * pos + 1), query(mid + 1, r, ql, qr, 2 * pos + 2));
    }
    void update(int l, int r, int pos, long long val, int range)
    {
        if (l == r)
        {
            tree[pos] = val;
            return;
        }
        int mid = (l + r) / 2;
        if (mid >= range)
            update(l, mid, 2 * pos + 1, val, range);
        else
            update(mid + 1, r, 2 * pos + 2, val, range);

        tree[pos] = max(tree[pos * 2 + 1], tree[pos * 2 + 2]);
    }
};

