struct SegmentTree{
private:
	int N;
	vector<long long> node;
	const long long DEFAULT = 0;
public:
	void init(int n){ //初期化する O(N)
		node.clear();
		N = 1;
		while(N < n) N *= 2;
		for(int i=0; i<2*N-1; i++) node.push_back(DEFAULT);
	}
	void update(int i, long long x){ //値を変更する O(log N)
		i += N - 1;
		node[i] = x;
		while(i > 0){
			i = (i-1)/2; //親の取得は(i-1)/2
			node[i] = max(node[i*2+1], node[i*2+2]); //子の取得はi*2+1,i*2+2
		}
	}
	long long maximum(int a, int b, int k=0, int l=0, int r=-1){ //[a,b)の最小値を求める O(log N)
		if(r == -1) r = N;
		if(r <= a || b <= l) return DEFAULT; //交差する場合
		if(a <= l && r <= b) return node[k]; //完全に含む場合
		return max( maximum(a, b, k*2+1, l, (l+r)/2) , maximum(a, b, k*2+2, (l+r)/2, r) );
	}
};

