struct SegmentTree{
	int size=1;
	vector<int>dat;
	SegmentTree(int x){
		while(size<x)size*=2;
		dat.resize(size*2-1);
	}
	void update(int a,int x,int k=0,int l=0,int r=-1){
		if(r==-1)r=size;
		if(r-l==1){
			dat[k]=x;
			return;
		}
		if(a<(l+r)/2)update(a,x,k*2+1,l,(l+r)/2);
		else update(a,x,k*2+2,(l+r)/2,r);
		dat[k]=max(dat[k*2+1],dat[k*2+2]);
	}
	int query(int a,int b,int k=0,int l=0,int r=-1){
		if(r==-1)r=size;
		if(r<=a||b<=l)return 0;
		if(a<=l&&r<=b)return dat[k];
		int lv=query(a,b,k*2+1,l,(l+r)/2);
		int rv=query(a,b,k*2+2,(l+r)/2,r);
		return max(lv,rv);
	}
};
