ll Max(ll a,ll b)
{
    ll Res = 0;

    for( a += n , b += n ; a<=b ; a /= 2 , b /= 2 )
    {
        if (a%2 == 1) Res = max( Res , Tree[a++] );
        if (b%2 == 0) Res = max( Res , Tree[b--] );
    }

    return Res;
}

void Update(ll k,ll x)
{
    k += n;
    Tree[k] = x;

    for( k /= 2 ; k >= 1 ; k /= 2 ) Tree[k] = max( Tree[2*k] , Tree[2*k+1] );
}

