int seg[2*N];

void update(int id,int val)
{
    for(seg[id+=n] = val;id>1;id>>=1)
        seg[id>>1] = max(seg[id],seg[id^1]);
}

int query(int r)
{
    int res = 0;
    r+=n+1;

    for(int l=n;l<r;l>>=1,r>>=1)
    {
        if(l&1) res = max(res,seg[l++]);
        if(r&1) res = max(res,seg[--r]);
    }

    return res;
}

