  int n;
  scanf("%d", &n);

  for (int i = 0; i < n; i++) scanf("%d", hs + i), hs[i]--;
  for (int i = 0; i < n; i++) scanf("%d", as + i);

  st.init(n);
  ll maxsum = 0;

  for (int i = 0; i < n; i++) {
    ll sum = st.max_range(0, hs[i]) + as[i];
    st.set(hs[i], sum);
    if (maxsum < sum) maxsum = sum;
  }

  printf("%lld\n", maxsum);
  return 0;
}

