int h[200007];
int a[200007];
ll tree[2*MAX+7];

void Update(ll a, ll b)
{
    a+=MAX;
    while(a != 0)
    {
        tree[a]=max(tree[a], b);
        a/=2;
    }
    return;
}

ll Query(ll a, ll b)
{
    a+=MAX;
    b+=MAX;
    ll odp=0;
    while(a <= b)
    {
        if(b%2==0) odp=max(odp, tree[b]);
        if(a%2==1) odp=max(odp, tree[a]);
        a=(a+1)/2;
        b=(b-1)/2;
    }
    return odp;
}

