ll calculatemaxbeauty(vector<int> &heights, vector<ll> &beauties, vector<ll> &dp, int flower)
{
    if (dp[flower] != -1)
        return dp[flower];
    for (int i = flower + 1; i < n; ++i)
    {
        if (heights[flower] < heights[i])
            dp[flower] = max(dp[flower], calculatemaxbeauty(heights, beauties, dp, i));
    }
    return dp[flower] = dp[flower] + beauties[flower];
}
