		a.resize(_n);
	}
	void update(ll pos,ll val)
	{
		pos++;
		while(pos<_n)
		{
			a[pos]+=val;
			pos+=(pos&(-pos));
		}
	}
	ll query(ll pos)
	{
		pos++;
		ll ans=0;
