void add(int v,int l,int r,int pos,LL val)
{
	if (l == r)
	{
		t[v] = val;
		return;
	}

	int m = (l + r) >> 1;

	if (pos <= m)
		add(v*2, l, m, pos, val);
	else
		add(v * 2+1, m + 1, r, pos, val);

	t[v] = max(t[v * 2], t[v * 2+1]);
}

LL get(int v,int l,int r,int pos)
{
	if (l == r)
