using namespace std;

template <typename T>
struct BIT
{
	int N, K;
	vector<T> bit;

	BIT(int X)
	{
		bit = vector<T>(X + 1, 0);
		N = X + 1;
		K = pow(2, (int)(log(X) / log(2)));
	}

	void chmax(int idx, T w)
	{
		for (int x = idx; x <= N; x += x & -x)
		{
			bit[x] = max(bit[x], w);
		}
	}

	T getmax(int idx)
	{
		T res = 0;
		for (int x = idx; x > 0; x -= x & -x)
			res = max(res, bit[x]);
		return res;
	}
};

