class segTree {
private:
	int n;

	vector<ll> tree;
public:
	int base = 1;
	segTree(int n) {
		this->n = n;
		while (base <= n) base *= 2;

		tree = vector<ll>(base * 2);
	}

	ll get (ll h) {
		ll x = h + base;
		ll best = 0;

		while (x > 1) {
			if (x % 2) {
				best = max(best, tree[x - 1]);
			}
			x /= 2;
		}
		return best;
	}

	void update(ll h, ll curVal) {
		for (int i = base + h; i > 0; i /= 2) {
			tree[i] = max(tree[i], curVal);
		}
	}

};

void solve() {
	int n; cin >> n;
	vector<ll> height(n), a(n);
	for (auto &it : height) cin >> it;
	for (auto &it : a) cin >> it;

	segTree st(n);
	vector<ll>  dp(n + 1, 0);

	for (auto i = 0; i < n; ++i) {
		auto best = st.get(height[i]);
		dp[height[i]] = best + a[i];
		st.update(height[i], dp[height[i]]);
	}

	ll maxRet = 0;
	for (auto i : dp) {
		maxRet = max(maxRet, i);
	}

	cout << maxRet; 
}

