#define int long long
typedef long long ll;

struct SegmentTree {
private:
    vector<ll> tree, lazy;
    ll n, root, size;
public:
    SegmentTree(){}
    SegmentTree(int _n) : n(_n), root(1) {
        ll x = (ll)(ceil(log2(n)));
        size = 2*(ll)pow(2, x);
        tree.resize(size);
        lazy.resize(size);
    }
    void pendingUpdate(ll node, ll start, ll end) {
        if(lazy[node]) {
            tree[node] += lazy[node];
            if(start != end) {
                lazy[2*node] += lazy[node];
                lazy[2*node+1] += lazy[node];
            }
            lazy[node] = 0;
        }
    }
    void updateRange(ll l, ll r, ll diff) { updateRange(root, 0, n-1, l, r, diff);}
    void updateRange(ll node, ll start, ll end, ll l, ll r, ll diff) {
        pendingUpdate(node, start, end);
        if(start > end || start > r || end < l) return;
        if(start >= l && end <= r) {
            tree[node] += diff;
            if(start != end) {
                lazy[2*node] += diff;
                lazy[2*node+1] += diff;
            }
            return;
        }
        ll mid = (start + end) / 2;
        updateRange(2*node, start, mid, l, r, diff);
        updateRange(2*node+1, mid+1, end, l, r, diff);
        tree[node] = max(tree[2*node], tree[2*node+1]);
    }
    ll query(ll l, ll r) { return query(root, 0, n-1, l, r);}
    ll query(ll node, ll start, ll end, ll l, ll r) {
        if(r < start || end < l) return 0;
        pendingUpdate(node, start, end);
        if(l <= start && end <= r) return tree[node];
        ll mid = (start+end)/2;
        return max(query(2*node, start, mid, l, r), query(2*node+1, mid+1, end, l, r));
    }
};

