	int mid = (st+ed)/2;
	if(pos<=mid)
	{
		update(2*node,st,mid,pos,val);
	}
	else update(2*node+1,mid+1,ed,pos,val);

	tree[node] = max(tree[2*node],tree[2*node+1]);
}

