int n;
void modify(int i,int x)
{
	c[i]=x;
	while(i<=n)
	{
		bit[i]=c[i];
		for(int j=1;j<lowbit(i);j<<=1)bit[i]=max(bit[i],bit[i-j]);
		i+=lowbit(i);
	}
}
int query(int l,int r)
{
	int ans=c[r];
	while(true)
	{
		ans=max(ans,c[r]);
		if(r==l)break;
		r--;
		while(r-l>=lowbit(r))
		{
			ans=max(ans,bit[r]);
			r-=lowbit(r);
		}
	}
	return ans;
}
