int N;
int A[MAXN];
pii H[MAXN];

LL val[MAXN*4], mx[MAXN*4];

void build(int node, int left, int right) {
    if (left == right) {
        return;
    }

    int m = (left + right) / 2;
    build(node*2, left, m);
    build(node*2 + 1, m+1, right);
}

void update(int node, int left, int right, int i, LL newval) {
    if (left == right) {
        val[node] = mx[node] = newval;
    } else {
        int m = (left + right) / 2;
        if (i <= m) 
            update(node*2, left, m, i, newval);
        else 
            update(node*2+1, m+1, right, i, newval);

        mx[node] = max(mx[node*2], mx[node*2+1]);
    }
}

LL query(int node, int left, int right, int l, int r) {
    if (r < l) return 0;
    if (r < left || right < l) return 0;
    if (l <= left && right <= r) return mx[node];

    int m = (left + right) / 2;
    return max(query(node*2, left, m, l, min(r,m)), query(node*2+1, m+1, right, max(l,m+1), r));
}

