struct segtree{
    int n; lint arr[MAX];
    segtree(int n_){
        n = 2;
        while(n < n_) n *= 2;
        rep(i, n*2) arr[i] = 0;
    }
    void update(int k, lint a){
        k += n - 1;
        arr[k] = a;
        while(k > 0){
            k = (k - 1) / 2;
            arr[k] = max(arr[k * 2 + 1], arr[k * 2 + 2]);
        }
    }
    lint query_(int a, int b, int k, int l, int r){
        if(r <= a || b <= l) return 0;
        if(a <= l && r <= b) return arr[k];
        else{
            lint vl = query_(a, b, k * 2 + 1, l, (l + r) / 2);
            lint vr = query_(a, b, k * 2 + 2, (l + r) / 2, r);
            return max(vl, vr);
        }
    }
    lint query(int a, int b){
        return query_(a, b, 0, 0, n);
    }
};

int main(){
    int n; cin >> n;
    vector<lint> h(n), a(n);
    rep(i, n){
        cin >> h[i]; h[i]--;
    }
    rep(i, n) cin >> a[i];

    segtree st(n);
    rep(i, n){
        dp[h[i]] = st.query(0, h[i]);
        dp[h[i]] += a[i];
        st.update(h[i], dp[h[i]]);
    }
    lint ans = 0;
    rep(i, n) ans = max(ans, dp[i]);
    out(ans);
}

