struct SegmentTree{
    int numNode;
    std::vector<ll> data;

    SegmentTree(int n){
        numNode = 1;
        while(numNode < n){
            numNode *= 2;
        }

        data.assign(numNode * 2, 0);
    }

    void set(int k, ll v){
        k += numNode;
        data[k] = v;

        while(k > 1){
            k /= 2;
            data[k] = std::max(data[k*2], data[k*2+1]);
        }
    }

    ll max(int l, int r){
        l += numNode;
        r += numNode;

        ll res = 0;
        for(;l<r;l/=2,r/=2){
            if(l & 1){
                res = std::max(res, data[l]);
                l += 1;
            }

            if(r & 1){
                r -= 1;
                res = std::max(res, data[r]);
            }
        }

        return res;
    }

    ll at(int k){
        return data[k + numNode];
    }
};

