ll solve(vector<ll> &tree,int a,int b,int i,int left,int right){
  if(b<=left||right<=a){
    return 0;
  }
  if(a<=left&&right<=b){
    return tree.at(i);
  }
  return max<ll>(solve(tree,a,b,2*i+1,left,(left+right)/2),solve(tree,a,b,2*i+2,(left+right)/2,right));
}

