void update(int h,long long val,int l,int r,int st){
    if (l==r) seg[st]=max(seg[st],val);
    else {
        int mid=(l+r)/2;
        if (h<=mid) update(h,val,l,mid,st*2);
        else update(h,val,mid+1,r,st*2+1);
        seg[st]=max(seg[st*2],seg[st*2+1]);
    }
}
long long take(int l,int r,int u,int v,int st){
    if (u<=l&&r<=v) return seg[st];
    else if (v<l||r<u) return 0;
    else{
            int mid=(l+r)/2;
            return max(take(l,mid,u,v,st*2),take(mid+1,r,u,v,st*2+1));
    }
}
