struct Segment_Tree{
	struct Node{
		ll val; 
		int stdl,stdr;
		Node *lson,*rson;
	};
	Node* root;
	Segment_Tree(){ root=new Node; }
	inline void build_tree(Node* now,int l,int r){
		now->val=0;
		now->stdl=l;
		now->stdr=r;
		if(l==r) return;
		build_tree(now->lson=new Node,l,(l+r)>>1);
		build_tree(now->rson=new Node,(l+r+2)>>1,r);
	}
	inline ll query(Node* now,int l,int r){
		ll ret=0;
		if(l<=now->stdl&&now->stdr<=r){
			ret=max(ret,now->val);
		} else {
			if(l<=(now->stdl+now->stdr)>>1){
				ret=max(ret,query(now->lson,l,r));
			}
			if(r>(now->stdl+now->stdr)>>1){
				ret=max(ret,query(now->rson,l,r));
			}
		}
		return ret;
	}
	inline void update(Node* now,int v,ll k){
		if(now->stdl==now->stdr){
			now->val=max(k,now->val);
		} else {
			if(v<=(now->stdl+now->stdr)>>1){
				update(now->lson,v,k);
			} else {
				update(now->rson,v,k);
			}
			now->val=max(now->lson->val,now->rson->val);
		}
	}
};
