const int N = 2e5 + 5;
int a[N], h[N];
long long seg[4 * N];
long long dp[N];

long long query(int l, int r, int start, int end, int pos) {

	if (start >= l && end <= r) {  // [start [l , r] end]
		return seg[pos];
	}

    if (r < start || l > end)
		return INT_MIN;
	int mid = (start + end) >> 1;
	long long Left = query(l, r, start, mid, 2 * pos);
	long long right = query(l, r, mid + 1, end, 2 * pos + 1);
	return max(Left, right);
}
void update(int updateIndex, long long value, int start, int end, int pos) {
	if (start == end) {
		seg[pos] = value;
		return;
	}
	int mid = (start + end) >> 1;
	if (mid >= updateIndex) {
		update(updateIndex, value, start, mid, 2 * pos);
	}
	else {
		update(updateIndex, value, mid + 1, end, 2 * pos + 1);
	}
    seg[pos] = max(seg[2 * pos], seg[2 * pos + 1]);
}
