	for (int i = 1; i <= n; i++) {
		if (h[i] != 1)
			dp[h[i]] = query(1, n, 0, 1, h[i] - 1);
		dp[h[i]] += v[i];
		update(1, n, 0, h[i], dp[h[i]]);
	}
	long long int ans = 0;
	for ( long long int i = 1; i <= n; i++) {
		ans = max(ans, dp[i]);
	}
	cout << ans;
	return 0;
}

