typedef long long llong;
typedef vector<int> VI;
typedef vector<VI> VVI;

class SegmentTree {
   int N;
   vector<llong> tree;
   void update(int p, llong val, int idx, int L, int R) {
      if (p < L || p > R) return;
      if (L == R) {
         tree[idx] = val;
         return;
      }
      int mid = L + (R-L)/2;
      update(p, val, idx*2, L, mid);
      update(p, val, idx*2+1, mid+1, R);
      tree[idx] = max(tree[idx*2], tree[idx*2+1]);
   }
   llong query(int p, int q, int idx, int L, int R) {
      if (q < L || p > R) return 0;
      if (p <= L && R <= q) return tree[idx];
      int mid = L + (R-L)/2;
      return max( query(p, q, idx*2, L, mid), query(p, q, idx*2+1, mid+1, R) );
   }
public:
   SegmentTree(int _N) : N(_N), tree(4*_N) {}
   llong query(int p, int q) {
      return query(p, q, 1, 0, N-1);
   }
   void update(int p, llong val) {
      update(p, val, 1, 0, N-1);
   }
};

