long long aint[4*NMAX],dp[NMAX],sol,maxim;
void update(int nod,int st,int dr)
{
    if(st==dr)
    {
        aint[nod]=value;
        return;
    }
    int mid=(st+dr)/2;
    if(pos<=mid)
        update(2*nod,st,mid);
    else
        update(2*nod+1,mid+1,dr);
    aint[nod]=max(aint[2*nod],aint[2*nod+1]);
}
void query(int nod,int st,int dr)
{
    if(start<=st && dr<=finish)
    {
        maxim=max(maxim,aint[nod]);
        return;
    }
    int mid=(st+dr)/2;
    if(start<=mid)
        query(2*nod,st,mid);
    if(mid<finish)
        query(2*nod+1,mid+1,dr);
}
