		return t[x];
	}

	int mid = (l + r) / 2;
	ll res = 0;
	res = max(res, get(x * 2, l, mid, tl, min(mid, tr)));
	res = max(res, get(x * 2 + 1, mid + 1, r, max(mid + 1, tl), tr));

