	int mid = (l + r) / 2;

	if(mid < pos){
		update(2 * x + 1, mid + 1, r, pos, val);
	}
	else{
		update(2 * x, l, mid, pos, val);
	}

	t[x] = max(t[2 * x], t[2 * x + 1]);
}
