vector<int> par;
void init_dsu(int n) { par.clear(); par.resize(n,-1); }
int root(int x) { return par[x]<0?x:par[x]=root(par[x]); }
void Union(int x, int y) {
    if((x=root(x)) == (y=root(y)))  return;
    if(par[y] < par[x])   swap(x,y);
    par[x] += par[y];
    par[y] = x;
}

int main() {
    int n;
    cin >> n;
    vi h(n), b(n);
    for (auto& i : h)   cin >> i;
    for (auto& i : b)   cin >> i;
    vi dp(n, 0);
    dp[0] = b[0];
    set<int> roots;
    init_dsu(n);
    roots.insert(0);
    vi ind(n + 2, -1);
    for (int i = 0; i < n; ++i) ind[h[i]] = i;
    for (int i = 1; i < n; ++i) {
        dp[i] = b[i];
        int curr = -1;
        for (auto it = roots.begin(); it != roots.end(); ++it) {
            int r = root(*it);
            if (h[r] < h[i]) {
                if (curr < 0 || dp[r] >= dp[curr]) {
                    curr = r;
                }
            }
        }
        if (curr >= 0 && curr < n)  dp[i] += dp[curr];
        bool sent = false;
        if (ind[h[i]+1] >= 0 && ind[h[i]+1] < n && roots.count(root(ind[h[i]+1]))) {
            Union(i, ind[h[i]+1]);
            sent = true;
        }
        if (ind[h[i]-1] >= 0 && ind[h[i]-1] < n && roots.count(root(ind[h[i]-1]))) {
            Union(i, ind[h[i]-1]);
            sent = true;
        }
        if (!sent)  roots.insert(i);
    }
    ll ans = 0;
    for (int i = 0; i < n; ++i) ans = max(ans, dp[i]);
    cout << ans << endl;
    return 0;
}

