	s[k].l=l;s[k].r=r;s[k].val=0;
	if(l==r)	return;
	int mid=(l+r)>>1;
	build(k<<1,l,mid);
	build(k<<1|1,mid+1,r);
}
void modify(int k,int ind,int x){
	if(s[k].l==s[k].r){
		s[k].val=x;
		return;
	}
	int mid=(s[k].l+s[k].r)>>1;
	if(ind<=mid)	modify(k<<1,ind,x);
	else			modify(k<<1|1,ind,x);
	s[k].val=max(s[k<<1].val,s[k<<1|1].val);
}
int query(int k,int l,int r){
	if(l<=s[k].l&&s[k].r<=r){
		return s[k].val;
	}
	int mid=(s[k].l+s[k].r)>>1;
	if(r<=mid)			return query(k<<1,l,r);
	else if(l>mid)		return query(k<<1|1,l,r);
	else				return max(query(k<<1,l,mid),
						query(k<<1|1,mid+1,r));
}
