#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef long double ld;

const int N = 2e5 + 10;
ll tree[4 * N];

void update(int node, int l, int r, int idx, ll val)
{
  if(l > r || l > idx || r < idx)
    return;
  if(l == r)
  {
    tree[node] = val;
    return;
  }
  int mid = (l + r) >> 1;
  update(node << 1, l, mid, idx, val);
  update((node << 1) + 1, mid + 1, r, idx, val);
  tree[node] = max(tree[(node << 1)], tree[(node << 1) + 1]);
}

ll query(int node, int l, int r, int st, int en)
{
    if(l > en || r < st || l > r || st > en)
      return 0;
    if(st <= l && r <= en)
      return tree[node];
    int mid = (l + r) >> 1;
    return max(query((node << 1), l, mid, st, en), query((node << 1) + 1, mid + 1, r, st, en));
}

