#define SIZE 200010

int N;
LL answer;
LL segTree[4 * SIZE], values[SIZE];
PII numbers[SIZE];


LL getMax(int Qbeg, int Qend, int Tbeg = 0, int Tend = N - 1, int ind = 0) { 
    if (Tend < Qbeg || Tbeg > Qend) {
        return 0;
    }

    if (Qbeg <= Tbeg && Tend <= Qend)  {    
        return segTree[ind];
    }

    int Tmid = (Tbeg + Tend) >> 1;
    LL ret1 = getMax(Qbeg, Qend, Tbeg, Tmid, 2 * ind + 1);
    LL ret2 = getMax(Qbeg, Qend, Tmid + 1, Tend, 2 * ind + 2);

    return max(ret1, ret2);
}

void update(int pos, LL val, int Tbeg = 0, int Tend = N - 1, int ind = 0) { 
    if (Tbeg > pos || Tend < pos) {
        return;
    }


    if (Tbeg == Tend && Tbeg == pos)  {    
        segTree[ind] = val; 
        return;
    } 

    int Tmid = (Tbeg + Tend) >> 1;
    update(pos, val, Tbeg, Tmid, 2 * ind + 1);
    update(pos, val, Tmid + 1, Tend, 2 * ind + 2);

    segTree[ind] = max(segTree[2 * ind + 1], segTree[2 * ind + 2]);
} 


int main() {
    scanf("%d", &N);

