    }

    sort(numbers, numbers + N);

    REP (i, 0, N) {
        LL val = getMax(0, numbers[i].sec);
        update(numbers[i].sec, val + values[numbers[i].sec]);

        answer = max(answer, val + values[numbers[i].sec]);
    }

    printf("%lld\n", answer);
    return 0;
}

