template<typename T = long long>
class SegmentTree {
public:
    std::vector<T> ary;
    int n;
    const T default_value = 0;
    SegmentTree(int n) {
        this->n = 1;
        while (this->n < n) this->n *= 2;
        ary.resize(this->n * 2 - 1, 0);
    }
    T ope(T l, T r) {
        return std::max(l, r);
    }
    void update(int k, T d) {
        k += n - 1;
        ary[k] += d;
        while (k > 0) {
            k = (k - 1) / 2;
            ary[k] = ope(ary[2 * k + 1], ary[2 * k + 2]);
        }
    }
    T query(int a, int b) {
        return query(a, b, 0, n, 0);
    }
    T query(int a, int b, int l, int r, int i) {
        if (a <= l && b >= r) return ary[i];
        if (a >= r || b <= l) return default_value;
        int m = (l + r) / 2;
        T vl = query(a, b, l, m, 2 * i + 1);
        T vr = query(a, b, m, r, 2 * i + 2);
        return ope(vl, vr);
    }
};
void solve() {
    int n;
    cin >> n;
    VLL h(n), a(n), b(n), m(n);
    REP(i,0,n) cin >> h[i];
    REP(i,0,n) cin >> a[i];
    REP(i,0,n) b[i] = h[i];
    sort(all(b));
    map<LL,int> r;
    REP(i,0,n) {
        m[i] = b[i];
        r[b[i]] = i;
    }
    REP(i,0,n) b[i] = r[h[i]];
    SegmentTree<> seg(n);
    REP(i,0,n) {
        LL maxv = seg.query(0,b[i]);
        seg.update(b[i], maxv + a[i]);
    }
    cout << seg.query(0,n) << endl;
}

int main() {
    solve();

    return 0;
}

