void update(int pos, ll val, int v=0, int tl=0, int tr=MAX)
{
	if(tl==tr) {
		st[v]=val;
		return;
	}
	int tm=(tl+tr)/2;
	if(pos<=tm) {
		update(pos, val, left(v), tl, tm); 
	}
	else {
		update(pos, val, right(v), tm+1, tr);
	}
	st[v]=max(st[left(v)], st[right(v)]);
}

ll query(int v, int tl, int tr, int l, int r)
{
	if(l>r) return 0;
	if(tl==l and tr==r) {
		return st[v];
	}
