ll dp(int id){
	if(id == n){
		return 0;
	}
	if(memo[id] != -1){
		return memo[id];
	}
	ll ans = 0;
	ll neks = INT_MAX;
	FOR(i, id+1, n){
		if(arr[i][0] > arr[id][0] && arr[id][0] < neks){
			ans = max(ans, arr[i][1] + dp(i));
			neks = arr[i][0];
		}
	}
	return memo[id] = ans;
}

