public:
    vector<long long> bit;
    int M;

    BIT(int M):
        bit(vector<long long>(M+1, -(1ll<<60))), M(M) {}

    long long sum(int i) {
        if (i<=0) return 0;
        return max(bit[i],sum(i-(i&-i)));
    }

    void add(int i, long long x) {
        if (i > M) return;
        bit[i] = max(bit[i], x);
        add(i+(i&-i), x);
    }
};

