void build(ll arr[], ll v, ll L, ll R)
{
	if (L == R)
		seg[v] = arr[L];
	else
	{
		ll mid = (L+R)/2;
		build(arr, 2*v, L, mid);
		build(arr, 2*v + 1, mid + 1, R);
		seg[v] = max(seg[2*v], seg[2*v + 1]);
	}
}

void update(ll v, ll L, ll R, ll x, ll y)
{
	if (L <= x && x <= R)
	{
		if (L == R)
			seg[v] += y;
		else
		{
			ll mid = (L+R)/2;
			update(2*v, L, mid, x, y);
			update(2*v + 1, mid + 1, R, x, y);
			seg[v] = max(seg[2*v], seg[2*v + 1]);
		}
	}
}

ll query(ll v, ll L, ll R, ll x, ll y)
{
	if (y < L || x > R)
		return 0;
	else if (x <= L && R <= y)
		return seg[v];
	else
	{
		ll mid = (L+R)/2;
		return max(query(2*v,L,mid,x,y), query(2*v + 1,mid+1,R,x,y));
	}
}

void print(ll v,ll L, ll R)
{
	if (L == R)
		cout << "L " << L << " R " << R << " " << seg[v] << endl;
	else
	{
		ll mid = (L+R)/2;
		print(2*v,L,mid);
		print(2*v+1,mid+1,R);
		cout << "L " << L << " R " << R << " " << seg[v] << endl;
	}
}

