void turunkan(int p, int l, int r) {
	st[p] = st[p] + lazy[p];
	if (l == r) {
		lazy[p] = 0;
		return;
	}
	lazy[p << 1] += lazy[p];
	lazy[p << 1 | 1]  += lazy[p];
	lazy[p] = 0;
}

void update(int p, int l, int r, int x, int y, ll val) {
	turunkan(p, l, r);
	if (l > y || r < x) return;
	if (l >= x && r <= y) {
		lazy[p] = val;
		turunkan(p, l, r);
		return;
	}
	int mid = (l + r) >> 1;
	update(p << 1, l, mid, x, y, val);
	update(p << 1 | 1, mid + 1, r, x, y, val);
	st[p] = max(st[p << 1], st[p << 1 | 1]);
}

ll query(int p, int l, int r, int x, int y) {
	turunkan(p, l, r);
	if (l > y || r < x) return -INF;
	if (l >= x && r <= y) {
		//cout << p << ' ' << l << ' ' << r << ' ' << x << ' ' << y << ' ' << st[p] << '\n';
		return st[p];
	}
	int mid = (l + r) >> 1;
	return max(query(p << 1, l, mid, x, y), query(p << 1 | 1, mid + 1, r, x, y)); 
}

