const int N = 2e5 + 5;
int n, h[N];
ll a[N], tree[4 * N], lazy[4 * N];

void prop(int i, int l, int r) {
    tree[i] = max(tree[i], lazy[i]);
    if(l < r) {
        lazy[2 * i + 1] = max(lazy[2 * i + 1], lazy[i]);
        lazy[2 * i + 2] = max(lazy[2 * i + 2], lazy[i]);
    }
    lazy[i] = 0;
}
ll query(int i, int l, int r, int L, int R) {
    if(r < L || R < l) return 0;
    prop(i, l, r);
    if(L <= l && r <= R) return tree[i];
    int m = (l + r) / 2;
    return max(query(2 * i + 1, l, m, L, R), query(2 * i + 2, m + 1, r, L, R));
}
void upd(int i, int l, int r, int L, int R, ll x) {
    prop(i, l, r);
    if(r < L || R < l) return;
    if(L <= l && r <= R) {
        lazy[i] = max(lazy[i], x);
        prop(i, l, r);
        return;
    }
    int m = (l + r) / 2;
    upd(2 * i + 1, l, m, L, R, x);
    upd(2 * i + 2, m + 1, r, L, R, x);
    tree[i] = max(tree[2 * i + 1], tree[2 * i + 2]);
}

