  {
    auto p = point(1, w[i]);

    ll q = qry(h[i], p);
    if(!q) ans = max(ans, w[i]), q = w[i];
    else ans = max(ans, q);

    upd(h[i], point(q, 1));
    //~ cerr << q <<  ' ' << ans << endl;
  }

