template <typename CLASS1>
class Binary_Index_Tree{
  private:
    CLASS1 n;
    // [1, n]
    vector<CLASS1> bit;

  public:
    Binary_Index_Tree(CLASS1 n_){
      bit.resize(n_+1, 0);
      n = n_+1;
      return;
    };

    ~Binary_Index_Tree(void){
      return;
    };

    CLASS1 submax(CLASS1 i){
      if(i < -1 || n <= i){
        fprintf(stderr, "Binary_Index_Tree Sum Position Error\n");
        exit(0);
      }
      CLASS1 s=0;
      i += 1;
      while(i>0){
        s = max(s, bit[i]);
        i -= i&(-i);
      }
      return s;
    };

    void update(CLASS1 i, CLASS1 x){
      if(i < 0 || n <= i){
        fprintf(stderr, "Binary_Index_Tree Update Position Error\n");
        exit(0);
      }
      i += 1;
      while(i <= n){
        bit[i] = max(bit[i], x);
        i += i&(-i);
      }
      return;
    };

};


