void update(int i,int l,int r,int pos,int val){
    if(l > r){
        return;
    }
    if(l == r){
        seg[i] = val;
        return;
    }
    int mid = (l+r) >> 1;
    if(pos > mid){
        update(2*i+1,mid+1,r,pos,val);
    }
    else{
        update(2*i,l,mid,pos,val);
    }
    seg[i] = max(seg[2*i],seg[2*i+1]);
}

int query(int i,int l,int r,int u,int v){
    if(l > r || u > v || r < u || l > v){
        return 0;
    }
    if(u <= l && r <= v){
        return seg[i];
    }
    int mid = (l+r) >> 1;
    return max(query(2*i,l,mid,u,v),query(2*i+1,mid+1,r,u,v));
}

