void update(int nd,int l,int r,int i,ll v)
{
    if(l>r || r< i || i<l ) return;
    if(l==r)
        return void(tree[nd]=v);
    int lt=2*nd,rt=lt|1,mi=(l+r)/2;
    update(lt,l,mi,i,v);
    update(rt,mi+1,r,i,v);
    tree[nd]=max(tree[lt],tree[rt]);
}

ll query(int nd,int l,int r,int i,int j)
{
    if(l>r || r< i || j<l ) return 0;
    if(i<=l && r<=j) return tree[nd];
    int mi=(l+r)/2,lt=2*nd, rt=lt|1 ;   
    return max(     query(lt,l,mi,i,j),
                    query(rt,mi+1,r,i,j)   )    ;
}

