	if(e<upd||upd<s){return seg[ix];}
	long long lft=(2*ix+1),rgt=(2*ix+2),mid=((s+e)/2);
	seg[ix]=MAX(update(lft,s,mid,upd,val),update(rgt,mid+1,e,upd,val));
	return seg[ix];
}
