template<class T>
class SegmentTree {
public:
    SegmentTree(int n_, T init_, std::function<T(T, T)> comp_) : n(1), init(init_), comp(comp_) {
        while (n < n_) n *= 2;
        d.resize(2 * n - 1, init);
    }
    // d[k] = a
    void update(int k, T x) {
        k += n - 1;
        d[k] = x;
        while (k > 0) {
            k = (k - 1) >> 1;
            d[k] = comp(d[2 * k + 1], d[2 * k + 2]);
        }
    }
    // comp() [a,b)
    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return init;
        if (a <= l && r <= b) return d[k];
        T vl = query(a, b, 2 * k + 1, l, (l + r) >> 1);
        T vr = query(a, b, 2 * k + 2, (l + r) >> 1, r);
        return comp(vl, vr);
    }
private:
    int n;
    const T init;
    std::function<T(T, T)> comp;
    vector<T> d;
};

