template <typename T>
struct BIT {
    int n;
    vector<T> f_tree;
    BIT(int n): n(n) {
        f_tree.assign(n + 1, 0);
    }

    void update(int x, T v) {
        ++x;
        for (; x <= n; x += (x & -x)) {
            f_tree[x] = max(f_tree[x], v);
        }
    }

    T query(int x) const {
        ++x;
        T res = 0;
        for (; x; x -= (x & -x)) {
            res = max(res, f_tree[x]);
        }

        return res;
    }
};

