ll ConstructST(ll ss, ll se, ll si){
	if(se == ss) return st[si] = arr[ss];
	ll mid = ss + (se-ss)/2;
	return st[si] = max(ConstructST(ss, mid, 2*si+1), 
						ConstructST(mid+1, se, 2*si+2));
}

ll getMax(ll ss, ll se, ll si, ll l, ll r){
	if (l<=ss && se<=r) return st[si];
	if (ss > r || se < l) return -1;

	ll mid = ss + (se-ss)/2;
	return max(getMax(ss, mid, 2*si+1, l, r),getMax(mid+1, se, 2*si+2, l, r));
}

void upDate(ll ss, ll se, ll si, ll i, ll v){
	if (ss == se){
		arr[i] = v;
		st[si] = v;
	}
	else{
		ll mid = ss + (se-ss)/2;
		if (ss <= i && i <=mid)
			upDate(ss, mid, 2*si+1, i, v);
		else
			upDate(mid+1, se, 2*si+2, i, v);
		st[si] = max(st[2*si+1], st[2*si+2]);
	}
}

ll getPos(ll x){
	return getMax(0, N-1, 0, 0, x);
}

void updatePos(ll i, ll v){
	upDate(0, N-1, 0, i, v);
}


