ll tree[T*2];
ll H[N];
ll A[N];

void add(int poz, ll val){
	poz += T;

	tree[poz] = val;

	poz/=2;
	while(poz){
		tree[poz] = max(tree[poz*2], tree[poz*2+1]);
		poz/=2;
	}
}

ll ask(int pocz, int kon){
	pocz += T-1;
	kon += T+1;
	ll ret = 0;

	while(pocz/2 != kon/2){
		if(!(pocz&1))
			ret = max(ret, tree[pocz+1]);
		if(kon&1)
			ret = max(ret, tree[kon-1]);
		pocz/=2;
		kon/=2;
	}
	return ret;
}

