const ll mxN = 2e5+100;
vec<ll> tree(4*mxN,0LL);
void update(int qidx, int idx, int ss, int se, ll delta){
    if(qidx<ss or qidx>se){return;}
    else if(ss==se){tree[idx]+=delta;}
    else{
        int mid = (ss+se)/2;
        if(qidx<=mid){
            update(qidx,2*idx+1,ss,mid,delta);
        } else{
            update(qidx,2*idx+2,mid+1,se,delta);
        }
        tree[idx] = max(tree[2*idx+1],tree[2*idx+2]);
    }
}
ll query(int idx, int ss, int se, int qs, int qe){
    if(qe<ss or qs>se){return -1;}
    else if(qs<=ss and se<=qe){
        return tree[idx];
    } else {
        int mid = (ss+se)/2;
        return max(query(2*idx+1,ss,mid,qs,qe),
                    query(2*idx+2,mid+1,se,qs,qe));
    }
}
