struct T {
	vector<long long> t;

	void init(int n) {
		t.resize(4 * n);
	}

	void pull(int v) {
		t[v] = max(t[2 * v], t[2 * v + 1]);
	}

	void build(int v, int tl, int tr) {
		if (tl == tr) {
			t[v] = 0;
		} else {
			int mid = tl + tr >> 1;
			build(2 * v, tl, mid);
			build(2 * v + 1, mid + 1, tr);
			pull(v);
		}
	}

	void set(int v, int tl, int tr, int i, long long val) {
		if (i < tl or i > tr) return;
		else if (i == tl and i == tr) {
			t[v] = val;
		} else {
			int mid = tl + tr >> 1;
			set(2 * v, tl, mid, i, val);
			set(2 * v + 1, mid + 1, tr, i, val);
			pull(v);
		}
	}

	long long get(int v, int tl, int tr, int l, int r) {
		if (tl > r or tr < l) return 0;
		else if (tl >= l and tr <= r) return t[v];
		else {
			int mid = tl + tr >> 1;
			return max(get(2 * v, tl, mid, l, r), get(2 * v + 1, mid + 1, tr, l, r));
		}
	}
};

