struct SegTree {
	int sz;
	vector<long> X;
	SegTree(int N){
		sz = 1;
		while(sz < N) sz <<= 1;
		//初期値代入
		X.assign(2*sz,0);
	}
	long f(long a,long b){
		return max(a,b);
	}
  	void Set(int k,const long x){
    	X[k+sz] = x;
  	}
  	void Build(){
    	for(int k=sz-1;k>0;k--){
      		X[k] = f(X[2*k],X[2*k+1]);
    	}
  	}
  	void Update(int k,const long x){
    	k += sz;
    	X[k] = x;
    	while(k >>= 1){
      		X[k] = f(X[2*k+0],X[2*k+1]);
    	}
  	}
  	long Query(int a,int b){
    	long L = 0, R = 0;
    	for(a += sz,b += sz+1;a < b;a >>= 1,b >>= 1){
      		if(a & 1) L = f(L,X[a++]);
      		if(b & 1) R = f(X[--b],R);
    	}
    	return f(L,R);
  	}
}; 
