template<class V>
class UpdateProxy {
  using Updater = function<void(const V&)>;
  Updater updater;
public:
  UpdateProxy(Updater up): updater(up) {}
  void operator=(const V& v) {
    updater(v);
  }
};

template<class V>
class SegTree{
  /*
    Segment tree.
    V: 結合法則、単位元
    eg.
      RMQ: SegTree<int>(N, LLONG_MIN, lambda(int a, int b){ return max(a, b); })
      RmQ: SegTree<int>(N, LLONG_MAX, lambda(int a, int b){ return min(a, b); })
  */
  /*!
    https://ei1333.github.io/luzhiled/snippets/structure/segment-tree.html
    https://codeforces.com/blog/entry/18051
  */
  int n;
  vec<V> vs;
  V id_elem;
  using Fn = function<V(V, V)>;
  Fn fn;
public:

  SegTree(int n0, const V& id_elem, Fn fn): id_elem(id_elem), fn(fn) {
    for(n = 1; n < n0; n *= 2);
    vs.resize(2 * n, id_elem);
  }

  const V& operator[](int i) const { return vs[n + i]; }
  UpdateProxy<V> operator[](int i) {
    return UpdateProxy<V>(lambda(const V& v){
      i += n;
      for(vs[i] = v; i > 1; i /= 2) { vs[i / 2] = fn(vs[i], vs[i ^ 1]); }
    });
  }

  void set_before_rebuild(int i, const V& v) { vs[n + i] = v; }
  void rebuild() {
    downtil(n - 1, 0, i) { vs[i] = fn(vs[i / 2], vs[i / 2 | 1]); }
  }

  V query(int l, int r) { /* 半開区間 */
    V vl = id_elem, vr = id_elem;
    for(l += n, r += n; l < r; l /= 2, r /= 2) {
      if(l & 1) vl = fn(vl, vs[l++]);
      if(r & 1) vr = fn(vs[--r], vr);
    }
    return fn(vl, vr);
  }
};
