void upd(int id,ll num){
	dat[id]=num;
	if (id!=0) while (1){
		id=(id-1)/2;
		dat[id]=max(dat[id*2+1],dat[id*2+2]);
		if (id==0) break;
	}
}
ll recovery(int l,int r,int id,int a,int b){
	if (r<a || b<l) return 0;
	if (a<=l && r<=b) return dat[id];
	return max(recovery(l,(l+r)/2,id*2+1,a,b),recovery((l+r)/2+1,r,id*2+2,a,b));
}
