long long maxquery(int index,int lb,int rb,int lq,int rq)
{
    if((lb==lq&&rb==rq)||lb==rb)
    {
	return t[index];
    }
    int mid=(lb+rb)/2;
    long long ret=0;
    if(rq<=mid)
    {
	ret=max(ret,maxquery(index*2,lb,mid,lq,rq));
    }
    else if(lq>mid)
    {
	ret=max(ret,maxquery(index*2+1,mid+1,rb,lq,rq));
    }
    else
    {
	ret=max(ret,maxquery(index*2,lb,mid,lq,mid));
	ret=max(ret,maxquery(index*2+1,mid+1,rb,mid+1,rq));
    }
    return ret;
}
void update(int index,int lb,int rb,int leaf,long long value)
{
    if(lb==rb&&lb==leaf)
    {
	t[index]=max(t[index],value);
	return;
    }
    int mid=(lb+rb)/2;
    if(leaf<=mid)
    {
	update(index*2,lb,mid,leaf,value);
	t[index]=max(t[index],t[index*2]);
    }
    else
    {
	update(index*2+1,mid+1,rb,leaf,value);
	t[index]=max(t[index],t[index*2+1]);
    }
}
