void update(ll l ,ll r, ll rt, ll x, ll val){
    if(l>r) return;
    if(l==r && x==l){ //
        tree[rt] = val; return;
    }
    ll m = (l+r)/2;
    tree[rt] = max(tree[rt], val);
    if(x<=m){ // l x m
        update(l, m, rt*2, x, val);
    }
    else {
        update(m+1, r, rt*2+1, x, val);
    }
}

ll query(ll l ,ll r, ll rt, ll x, ll y){
    if(l>r) return -1;
    if(y<l || r<x){ // x y l r x y
        return -1;
    }
    if(x<=l && r<=y){ // x l r y
        return tree[rt];
    }
    ll m = (l+r)/2;
    return max(query(l, m, rt*2, x, y), query(m+1, r, rt*2+1, x, y));
}

