void update(int node, long long val, int cur, int st, int end){
    if(st==end){
        if (st==node)
            tree[cur] = val;
        return;
    }
    if (node<st || node> end)
        return;
    int mid = (st+end)/2;
    update(node, val, 2*cur, st, mid);
    update(node, val, 2*cur+1, mid+1, end);
    tree[cur] = max(tree[2*cur], tree[2*cur+1]);
}

long long query(int l, int r, int cur, int st, int end){
    if (r<st || l>end)
        return INT_MIN;
    if (l<=st && end<=r)
        return tree[cur];
    int mid = (st+end)/2;
    return max(query(l, r, 2*cur, st, mid), query(l, r, 2*cur+1, mid+1, end));
}


