     }

     int queryUtil(int l, int r, int i, int L, int R)
     {    
          if( r < L or R < l ) return -inf;     // change here 
          if( L <= l && r <= R)   return segt[i];

          int mid = l + (r-l)/2;
          int a = queryUtil(l    , mid, 2*i + 1, L, R);
          int b = queryUtil(mid+1, r  , 2*i + 2, L, R);

          return ff(a,b);                    
     }

     int upd(int i)
     {    

         int a = segt[ 2*i + 1 ];
         int b = segt[ 2*i + 2 ];

         return ff(a,b);         
     }

     void build()
     {         

          buildUtil(0, sz-1, 0);                  // l, r, i
     }

     int query(int L, int R)
     {    
          return queryUtil(0, sz-1, 0, L, R);     // l, r, i, L, R
     }

     void update(int idx ,int val)
     {
          updateUtil(0, sz-1, 0, idx, val);       // l, r , i, idx , val
     }

     void buildUtil(int l, int r , int i)
     {    

          if( l == r )
          {    
               segt[i] = from[r];
               return;
          }

          int mid = l + (r-l)/2;
          buildUtil(l,   mid, 2*i + 1 );
          buildUtil(mid+1, r, 2*i + 2 );

          segt[i] = upd(i);

     }



     void updateUtil( int l, int r, int i, int idx, int val)
     {

          if( l > idx || r < idx ) return ;

          if( l == r and l == idx )
          {
               segt[i] = val;
               from[idx] = val;
               return;
          }

          int mid = l + (r-l)/2;
          updateUtil(l, mid, i*2 + 1, idx, val);
          updateUtil(mid+1, r, i*2 + 2, idx, val);

          segt[i] = upd(i);
     }

};



