            return;
        }
        if (left == right) {
            tree[root] = val;
        } else {
            int mid = left + (right - left) / 2;
            if (idx >= left && idx <= mid) {
                update(left, mid, idx, 2 * root, val);
            } else {
                update(mid + 1, right, idx, 2 * root + 1, val);
            }
            tree[root] = merge(tree[2 * root], tree[2 * root + 1]);
        }
    }

    V query(int left, int right, int q_left, int q_right, int root) {
        if (q_left <= left && q_right >= right) {
            return tree[root];
        }
        if (q_left > right || q_right < left) {
            return defaultValue;
        }
        int mid = left + (right - left) / 2;
        return merge(query(left, mid, q_left, q_right, 2 * root), query(mid + 1, right, q_left, q_right, 2 * root + 1));
    }

public:
    SegmentTree(int size, function<V(V, V)> merge, V defaultValue = 0) : size(size), defaultValue(defaultValue),
                                                                         merge(merge) {
        int vertexSize = 4 * size;
        tree = arr<V>(vertexSize);
    }

    SegmentTree(arr<V> &array, function<V(V, V)> merge, V defaultValue = 0) : size(array.size()), merge(merge),
                                                                              defaultValue(defaultValue) {
        int vertexSize = 4 * size;
        tree = arr<V>(vertexSize);
        init(0, size - 1, 1, array);
    }

    void update(int idx, V val) {
        update(0, size, idx, 1, val);
    }

    V query(int q_left, int q_right) {
        return query(0, size, q_left, q_right, 1);
    }
};

