	for (i = 1; i < n; i++)
	{
		dp[i] = a[i];

		auto it = m.lower_bound(h[i] + 1);
		if (it != m.begin())
		{
			it--;
			dp[i] += it->second;
		}

		m[h[i]] = dp[i];

		it = m.upper_bound(h[i]);

		while (it != m.end() && it->second <= dp[i])
		{
			auto temp = it;
			temp++;
			m.erase(it);
			it = temp;
		}
		ans = max(ans, dp[i]);
	}

	cout << ans << endl;
}

