        tree[i] = val;
        return;
    }
    int mid = (low + high)/2;
    if(h <=mid) update(2*i,low,mid,val,h,A);
    else
        update(2*i+1,mid+1,high,val,h,A);
    tree[i] = max(tree[2*i],tree[2*i+1]);
}
