ll query(int segIdx,int segLeft,int segRight,int left,int right){
    if(segLeft>=left && segRight<=right){
        return segTree[segIdx];
    }

    if(segLeft>right || segRight<left){
        return -1e18;
    }
    int segMid=(segLeft+segRight)/2;
    return max(query(segIdx*2,segLeft,segMid,left,right) , query(segIdx*2+1,segMid+1,segRight,left,right));
}

void update(int segIdx,int segLeft,int segRight,int idx,ll value){
    if(segLeft==idx && segRight==idx){
        segTree[segIdx]=value;
        return;
    }

    if(segLeft>idx || segRight<idx) return;

    int segMid=(segLeft+segRight)/2;
    update(segIdx*2,segLeft,segMid,idx,value);
    update(segIdx*2+1,segMid+1,segRight,idx,value);
    segTree[segIdx]=max(segTree[segIdx*2],segTree[segIdx*2+1]);
}
