struct node {
	int s,e,m,val;
	node *l, *r;
	node (int _s, int _e) {
		s = _s, e = _e;
		m = (s+e)/2;
		val=0;
		if(s!=e) {
			l=new node(s,m);
			r=new node(m+1,e);
		}
	}
	void update(int x, int nval) {
		if(s==e){
			chmax(val,nval);
			return;
		}
		if(x<=m)l->update(x,nval);
		else r->update(x,nval);
		val=max(l->val,r->val);
	}
	int query(int x, int y) {
		if(s==x&&e==y){
			return val;
		}
		if(x>m)return r->query(x,y);
		else if(y<=m)return l->query(x,y);
		else return max(l->query(x,m), r->query(m+1,y));
	}
} *seg;


