	tree.init(n);
	tree.build(1, 1, n);
	for (int i = 1; i <= n; i++) {
		long long mx = tree.get(1, 1, n, 1, h[i]);
		dp[i] = mx + a[i];
		tree.set(1, 1, n, h[i], dp[i]);
	}
	long long ans = 0;
	for (int i = 1; i <= n; i++) {
		ans = max(ans, dp[i]);
	}
	cout << ans << endl;
}

