void UPDATE(int k, long long int v) {
	value[k + geta - 1] = v;

	int u = k + geta - 1;
	u /= 2;
	while (u) {
		value[u] = max(value[2 * u], value[2 * u + 1]);
		u /= 2;
	}
}

long long int Q(int i, int j, int K) {

	if (j < l[K]) { return 0; }
	if (r[K] < j) { return 0; }
	//cout << "check  i="<<i<<"  j= " <<j << endl;
	if ((i <= l[K]) && (r[K] <= j)) { return value[K]; }

	return max(Q(i, j, 2 * K), Q(i, j, 2 * K + 1));

}

int CALC_l(int k) {

	if (k >= geta) { l[k] = k - geta + 1; return l[k]; }

	if (l[2 * k] > 0) { return l[2 * k]; }
	else { l[k] = CALC_l(2 * k); }

	return l[k];
}

int CALC_r(int k) {

	if (k >= geta) { r[k] = k - geta + 1; return r[k]; }

	if (r[2 * k+1] > 0) { return r[2 * k+1]; }
	else { r[k] = CALC_r(2 * k+1); }

	return r[k];
}

