void pushdown(int o ,int z,int l , int r  , ll num){
    if(l > z || r < z)    return;
    //printf("%d %d \n",l,r);

    int mid = (l + r) / 2;
    tree[o] = max(num , tree[o]);
    if(l == r)  return ;

    pushdown(o * 2 + 1 , z , l , mid  , num);
    pushdown(o * 2 + 2 , z , mid + 1 , r  , num);
}

ll qu(int o ,int l ,int r,int x , int y){
    if(l > y || r < x)    return 0;
    if(l >= x && r <= y)    return tree[o];

    int mid = (l + r) / 2;

    ll res = 0;
    res = max ( res , qu(o * 2 + 1 , l , mid , x , y ));
    res = max ( res , qu(o * 2 + 2 , mid + 1 , r , x , y ));

    return res;
}

