class ST {
    vector<ll> t;
    int n;

    void updateUtil(int v, int tl, int tr, int pos, ll newVal) {
        if(tl == tr) {
            t[v] = newVal;
            return;
        }
        int tm = (tl + tr)/2;
        if(pos <= tm) updateUtil(v*2, tl, tm, pos, newVal);
        else updateUtil(v*2+1, tm+1, tr, pos, newVal);
        t[v] = max(t[v*2], t[v*2+1]);
    }

    ll queryUtil(int v, int tl, int tr, int l, int r) {
        if(l > r) return 0;
        if(tl == l && tr == r) return t[v];
        int tm = (tl + tr)/2;
        return max( queryUtil(v*2, tl, tm, l, min(r, tm)),
                queryUtil(v*2+1, tm+1, tr, max(l, tm+1), r) );
    }

public :

    ST(int n) {
        this->n = n;
        t.assign(4*n, 0);
    }

    void update(int pos, ll newVal) {
        updateUtil(1, 0, n-1, pos, newVal);
    }

    ll query(int l, int r) {
        return queryUtil(1, 0, n-1, l, r);
    }
};

