    }
    rep(i,0,n){
    	dp[i]=max(query(1,0,N,0,heights[i]-1),(ll)0)+beauties[i];
    	update(1,0,N,heights[i],dp[i]);
    }
    // rep(i,0,50){
    // 	cout<<dp[i]<<" "<<heights[i]<<"    ";
    // }
    // cout<<endl;
    cout<<*max_element(dp,dp+n)<<endl;
}

