void Update(int curr, int left, int right, int idx, ll val)
{
    if(left == right)
    {
        segtree[curr] = max(segtree[curr], val);
        return;
    }
    int mid = left + (right-left) / 2;
    if(idx <= mid) Update(curr*2, left, mid, idx, val);
    else Update(curr*2+1, mid+1, right, idx, val);
    segtree[curr] = max(segtree[curr*2], segtree[curr*2+1]);
}

ll Query(int curr, int left, int right, int qleft, int qright)
{
    if(qleft > right || qright < left) return 0;
    if(left >= qleft && right <= qright) return segtree[curr];
    int mid = left + (right-left) / 2;
    ll ansLeft = Query(curr*2, left, mid, qleft, qright);
    ll ansRight = Query(curr*2+1, mid+1, right, qleft, qright);
    return max(ansLeft, ansRight);
}

