vector<int> mx(TREE_SZ, -2e18);

int get_max(int v, int l, int r, int L, int R) {
    if (r <= L || R <= l) {
        return -2e18;
    }
    if (L <= l && r <= R) {
        return mx[v];
    }
    int m = (l + r) / 2;
    return max(
                get_max(2 * v + 1, l, m, L, R),
                get_max(2 * v + 2, m, r, L, R)
            );
}

void set_elem(int v, int l, int r, int i, int x) {
    mx[v] = max(mx[v], x);
    if (l == r - 1) {
        return;
    }
    int m = (l + r) / 2;
    if (i < m) {
        set_elem(2 * v + 1, l, m, i, x);
    } else {
        set_elem(2 * v + 2, m, r, i, x);
    }
}

