ll arr[maxn], t[4 * maxn], lazy[4 * maxn];

ll query(int node, int a, int b, int i, int j) {
    if (a > b || a > j || b < i) return -inf;
    if (lazy[node] != 0) {
        t[node] += lazy[node];
        if (a != b) {
            lazy[node * 2] += lazy[node];
            lazy[node * 2 + 1] += lazy[node];
        }
        lazy[node] = 0;
    }
    if (a >= i && b <= j) return t[node];
    ll q1 = query(node * 2, a, (a + b) / 2, i, j);
    ll q2 = query(node * 2 + 1, (a + b) / 2 + 1, b, i, j);

    return max(q1, q2);
}

void update(int node, int a, int b, int i, int j, ll inc) {
    if (a > b) return;
    if (lazy[node] != 0) {
        t[node] += lazy[node];
        if (a != b) {
            lazy[node * 2] += lazy[node];
            lazy[node * 2 + 1] += lazy[node];
        }
        lazy[node] = 0;
    }
    if (a > b || a > j || b < i) return;

    if (a >= i && b <= j) {
        t[node] += inc;
        if (a != b) {
            lazy[node * 2] += inc;
            lazy[node * 2 + 1] += inc;
        }
        return;
    }
    update(node * 2, a, (a + b) / 2, i, j, inc);
    update(node * 2 + 1, (a + b) / 2 + 1, b, i, j, inc);
    t[node] = max(t[node * 2], t[node * 2 + 1]);
}

