    if (lup > r || l > rup)
        return;
    int mid = (l + r) / 2;
    update(2 * idx, lup, rup, val, l, mid);
    update(2 * idx + 1, lup, rup, val, mid + 1, r);
    tree[idx] = max(tree[2 * idx], tree[2 * idx + 1]);
}

ll query(int idx, int lup, int rup, int l, int r) {
    if (lup <= l && r <= rup)
        return tree[idx];
    if (lup > r || l > rup)
        return 0;
    int mid = (l + r) / 2;
    return max(query(2 * idx, lup, rup, l, mid), query(2 * idx + 1, lup, rup, mid + 1, r));
}

int main() {
    ios::sync_with_stdio(false); cin.tie(NULL); 
    cin >> n;
    for(int i=1;i<=n;i++)
        cin >> h[i];
    for(int i=1;i<=n;i++)
        cin >> b[i];

    for(int i=1;i<=n;i++) {
        if (h[i] == 1)
            update(1, 1, 1, b[i], 1, n);
        else {
            ll beauty = query(1, 1, h[i] - 1, 1, n);
            update(1, h[i], h[i], beauty + b[i], 1, n);
        }
    }

    cout << tree[1];
    return 0;
}

