	SegmentTree(int n_) {
		n = 1;
		while (n < n_) {
			n *= 2;
		}

		dat.assign(n * 2 - 1, mini);
	};
	~SegmentTree() {
		dat.clear();
	};

	void update(int k, long long val) {
		k += n - 1;
		dat[k] = val;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = max(dat[k*2 + 1], dat[k*2 + 2]);
		}
	}

	long long query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l) {
			return mini;
		}

		if (a <= l && r <= b) {
			return dat[k];
		} else {
			long long vl = query(a, b, k*2 + 1, l, (l+r)/2);
			long long vr = query(a, b, k*2 + 2, (l+r)/2, r);
			return max(vl, vr);
		}
	}

	// [a, b)の範囲での値
	long long query(int a, int b) {
		return query(a, b, 0, 0, n);
	}

