ll rmq(int a, int b) {
	a += N;
	b += N;
	ll cres = 0;
	while (a <= b) {
		if (a%2 == 1) cres = max(cres, st[a++]);
		if (b%2 == 0) cres = max(cres, st[b--]);
		a /= 2;
		b /= 2;
	}
	return cres;
}

