    for (int i = 0; i < n; i++) {
        cin >> h[i];
    }
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    SimpleSegmentTree tree(n+1, (getTwoNodeValueFunc)getMax, (updateOneNodeValueFunc)update);
    ll ans = a[0];
    dp[0] = a[0];
    tree.update(dp[0], h[0]);
    for (int i = 1; i < n; i++) {
        ll maxV = tree.query(1, h[i]-1);
        dp[i] = maxV + a[i];
        tree.update(dp[i], h[i]);
        if (ans < dp[i]) {
            ans = dp[i];
        }
    }
    printf("%lld\n", ans);
    return 0;
}

