	    dp[i]=v[i].b; // first option
	    // 2nd option 
	    auto it=meaningful.lower_bound(v[i].h+1);
	    if(it!=meaningful.begin()){
	        it--;
	        dp[i]+=it->second;
	    }
	    meaningful[v[i].h]=dp[i]; //insert into map
	    //delete all unnecessary heights which cant be extended in the future
	    it=meaningful.upper_bound(v[i].h);
	    while(it!=meaningful.end() and it->second<=dp[i]){
	        auto temp=it;
	        temp++;
	        meaningful.erase(it);
	        it=temp;
	    }
	    ans=max(ans,dp[i]);
	}
	return ans;
}

