    node c;
    return c;
  }
  if(L<=l&&r<=R)
  {
    return bit[id];
  }
  int mid=(l+r)/2;
  return merge(get(2*id,l,mid,L,R),get(2*id+1,mid+1,r,L,R));
}

void upd(int id,int l,int r,int L,int R,int v)
{
  if(R<l||r<L)
    return;
  if(L<=l&&r<=R)
  {
    bit[id].x=v;
    return;
  }
  int mid=(l+r)/2;
  upd(2*id,l,mid,L,R,v);
  upd(2*id+1,mid+1,r,L,R,v);
  bit[id]=merge(bit[2*id],bit[2*id+1]);
}


