void build(ll v, ll tl, ll tr, ll pos, ll val)
{
	if(tl==tr)
	{
		t[v]=max(t[v], val); return;
	}
	ll tm=(tl+tr)/2;
	if(pos<=tm)
	{
		build(v+v, tl, tm, pos, val);
	}
	else
	{
		build(v+v+1, tm+1, tr, pos, val);
	}
	t[v]=max(t[v+v], t[v+v+1]);
}

ll get(ll v, ll tl, ll tr, ll l, ll r) // tl, tr -> tree range
{
	if(l > r) return 0;
	if(l==tl and r==tr) { return t[v]; }
	ll tm=(tl + tr)/2;
	ll op1=get(v+v, tl, tm, l, min(r, tm));
	ll op2=get(v+v+1, tm+1, tr, max(tm+1, l), r);
	return max(op1, op2);
}

