template < typename T >
class FenwickMax {
public:
  int n;
  vector< T > bit;
  FenwickMax(int _n) {
    n = _n;
    bit.resize(n + 1);
  }
  void update(int p, T x) {
    while(p <= n) {
      bit[p] = max(bit[p], x);
      p += (p & (-p));
    }
  }
  T query(int p) {
    T s = 0;
    while(p) {
      s = max(s, bit[p]);
      p -= (p & (-p));
    }
    return s;
  }
};

int main() {
