  }
  sort(p.begin(), p.end(), [&](int i, int j) -> bool {
    if(h[i] != h[j]) return h[i] < h[j];
    return a[i] < a[j];
  });
  FenwickMax< ll > dp(n);
  for(int i = 1; i <= n; ++i) {
    int ps = p[i - 1] + 1;
    ll bst = dp.query(ps);
    dp.update(ps, bst + a[ps - 1]);
  }
