inline void upd(int u,int s,int e,int idx,ll val)
{
    if(s==e){
        tree[u]=val; return;
    }
    int m=(s+e)/2;
    if(idx<=m) upd(2*u+1,s,m,idx,val);
    else upd(2*u+2,m+1,e,idx,val);
    tree[u]=max(tree[2*u+1],tree[2*u+2]);
}

inline ll que(int u,int s,int e,int l,int r)
{
    if(s>r || e<l) return -1;
    if(s>=l && e<=r) return tree[u];
    int m=(s+e)/2;
    return max(que(2*u+1,s,m,l,r),que(2*u+2,m+1,e,l,r));
}

inline ll solve(int n)
{
    fill(tree,-1); 
    repr(i,n-1,0){
        ll temp=que(0,0,n-1,h[i],n-1); 
        if(temp!=-1) upd(0,0,n-1,h[i],temp+arr[i]),aux[h[i]]=temp+arr[i];
        else upd(0,0,n-1,h[i],arr[i]),aux[h[i]]=arr[i];
    }
