    // dp[i] := 最大が高さiのときの花の美しさの総和の最大値
    // これもDPっていうんか？
    vector<ll> dp(n+1, 0);
    segtree sgt(dp);
    REP(i, n) {
        sgt.apply(h[i], h[i]+1, sgt.fetch(0, h[i]) + a[i]);
    }
    cout << sgt.fetch(0, n+1) << endl;

}

