void update(int x, ll value, int li=0, int ri=n, int index=1) {
    if(li == ri) tree[index] = value;
    else {
        int mid = (li+ri)/2;
        if(x <= mid) update(x, value, li, mid, 2*index);
        else update(x, value, mid+1, ri, 2*index+1);
        tree[index] = max(tree[2*index], tree[2*index+1]);
    }
}

ll query(int ql, int qr, int li=0, int ri=n, int index=1) {
    if(li > qr || ri < ql) return 0LL;
    else if(li >= ql && ri <= qr) {
        return tree[index];
    }
    else {
        int mid = (li+ri)/2;
        return max(query(ql,qr,li,mid,2*index), query(ql,qr,mid+1,ri,2*index+1));
    }
}

