void updatelazy(ll start,ll end,ll index,ll val,ll low,ll high)
{
  if(start > end)
  {
    return;
  }
  if(lazy[index] != -1)
  {
    tree[index] = max(tree[index],lazy[index]);
    if(start != end)
    {
      lazy[2*index] = max(lazy[index],lazy[2*index]);
      lazy[2*index + 1] = max(lazy[index],lazy[2*index]);
    }
    lazy[index] = -1;
  }
  if(start > high || end < low)
  {
    return;
  }
  if(start >= low && end <= high)
  {
    tree[index] = val;
    if(start != end)
    {
      lazy[2*index] = max(lazy[index],lazy[2*index]);
      lazy[2*index + 1] = max(lazy[index],lazy[2*index]);
    }
    lazy[index] = -1;
    return;
  }
  ll mid = (start + end) >> 1;
  updatelazy(start,mid,2*index,val,low,high);
  updatelazy(mid + 1,end,2*index + 1,val,low,high);
  tree[index] = max(tree[2*index],tree[2*index + 1]);
  return;
}
