const int N = 2e5 + 5;

struct SegmentTree {
    ll t[N << 2];

    void init(int u, int b, int e) {
        if (b == e) {
            t[u] = 0;
            return;
        }
        int mid = (b + e) >> 1;
        init(u << 1, b, mid);
        init(u << 1 | 1, mid + 1, e);
        t[u] = max(t[u << 1], t[u << 1 | 1]);
    }

    void upd(int u, int b, int e, int i, ll x) {
        if (i < b or e < i) return;
        if (i <= b and e <= i) {
            t[u] = x;
            return;
        }
        int mid = (b + e) >> 1;
        upd(u << 1, b, mid, i, x);
        upd(u << 1 | 1, mid + 1, e, i, x);
        t[u] = max(t[u << 1], t[u << 1 | 1]);
    }

    ll query(int u, int b, int e, int i, int j) {
        if (j < b or e < i) return 0LL;
        if (i <= b and e <= j) return t[u];
        int mid = (b + e) >> 1;
        ll p1 = query(u << 1, b, mid, i, j);
        ll p2 = query(u << 1 | 1, mid + 1, e, i, j);
        return max(p1, p2);
    }
} t;

