struct Seg {
    int id, l, r, m, val;
    void build(int idx, int s, int e);
    Seg& left();
    Seg& right();
    void update(int pos, int nval);
    int query(int s, int e);
} nodes[MAXN*4];
Seg& Seg::left() { return nodes[id*2]; }
Seg& Seg::right() { return nodes[id*2+1]; }
void Seg::build(int idx, int s, int e) {
    id = idx, l = s, r = e, m = (l+r) >> 1;
    if (l != r) left().build(idx*2, s, m), right().build(idx*2+1, m+1, e);
}
int Seg::query(int s, int e) {
    if (l == s && e == r) return val;
    if (e <= m) return left().query(s, e);
    if (s > m) return right().query(s, e);
    return max(left().query(s, m), right().query(m+1, e));
}
void Seg::update(int pos, int nval) {
    if (l == r) {
         val = max(val, nval);
         return;
    }
    if (pos <= m) left().update(pos, nval);
    else right().update(pos, nval);
    val = max(left().val, right().val);
}

