// This problem is a variation of Longest Increasing Subsequence

const int MAXN = 2e5 + 10;
int N;
int dp[MAXN], h[MAXN], a[MAXN];
int bit[MAXN];

// update the fenwick tree
void update(int idx, int val){
    while(idx <= N){
        bit[idx] = max(bit[idx], val);
        idx += (idx & -idx);
    }
}

// answer the query for idx
int query(int idx){
    int result = 0;
    while(idx > 0){
        result = max(result, bit[idx]);
        idx -= (idx & -idx);
    }
    return result;
}

int32_t main() {

    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> N;

    for(int i = 1; i <= N; ++i)
        cin >> h[i];

    for(int i = 1; i <= N; ++i)
        cin >> a[i];

    for(int i = 1; i <= N; ++i){
        // dp[i] --> stores the max total beauty if the increasing sequence
        // ended at a tree of height i.

        // query(h[i] - 1) --> returns the maximum value of beauty of a sequence in range [0, h[i] - 1].
        dp[i] = query(h[i] - 1) + a[i]; // add beauty of the current tree to the max sequence

        // update the max beauty value at index h[i] i.e, the value for increasing sequence ending at this tree
        update(h[i], dp[i]);
    }

    int best = 0;
    for(int i = 1; i <= N; ++i){
        // find the max value by traversing through total beauty values
        // of each flower height.
        best = max(best, dp[i]);
    }

    // Print the max possible answer.
    cout << best << "\n";

    return 0;
}

