void stc(int node, int l, int r){
	if (l == r) st[node] = 0;
	else {
		int m = (l+r)/2;
		stc(node*2, l, m);
		stc(node*2+1, m+1, r);
		st[node] = 0;
	}
}

void stu(int node, int l, int r, int ind, ll val){
	if (l == r) st[node] = val;
	else {
		int m = (l+r)/2;
		if (ind <= m) stu(node*2, l, m, ind, val);
		else stu(node*2+1, m+1, r, ind, val);
		st[node] = max(st[node*2], st[node*2+1]);
	}
}

ll stq(int node, int l, int r, int sl, int sr){
	if (inside) return st[node];
	else if (outside) return 0;
	else {
		int m = (l+r)/2;
		return max(stq(node*2, l, m, sl, sr), stq(node*2+1, m+1, r, sl, sr));
	}
}

