#define ll long long int

struct flower{
    ll h; //height
    ll b; //beauty
};
// any element is inserted and deleted atmost once so time complexity is O(NlogN)
ll solve(vector<flower>& v,ll n){
	vector<ll> dp(n+1);
	dp[1]=v[1].b;
	map<ll,ll> meaningful; //to store meaningful indices which can extend further
	meaningful[v[1].h]=v[1].b;
	ll ans=dp[1];
	for(int i=2;i<=n;++i){
	    dp[i]=v[i].b; // first option
	    // 2nd option 
	    auto it=meaningful.upper_bound(v[i].h);
	    if(it!=meaningful.begin()){
	        it--;
	        dp[i]+=it->second;
	    }
	    meaningful[v[i].h]=dp[i]; //insert into map
	    //delete all unnecessary heights which cant be extended in the future
	    it=meaningful.upper_bound(v[i].h);
	    while(it!=meaningful.end() and it->second<=dp[i]){
	        auto temp=it;
	        temp++;
	        meaningful.erase(it);
	        it=temp;
	    }
	    ans=max(ans,dp[i]);
	}
	return ans;
}

int main()
{
	ll n=0;cin>>n;
    vector<flower> v(n+1);
    for(int i=1;i<=n;++i)
        cin>>v[i].h;
    for(int i=1;i<=n;++i)
        cin>>v[i].b;
    cout<<solve(v,n)<<'\n';
	return 0;
}

