            Max[ind] = x;
            return ;
      }
      int mid = (s + e)/2;
      if(l < mid) Add(s, mid, L(ind), l, r, x);
      else Add(mid, e, R(ind), l, r, x);
      Max[ind] = max(Max[L(ind)], Max[R(ind)]);
}
int Query(int s, int e, int ind, int l, int r){
      if(s >= l && e <= r)
            return Max[ind];
      int mid = (s + e)/2, ret = 0;
      if(l < mid) ret = max(ret, Query(s, mid, L(ind), l, r));
      if(r > mid) ret = max(ret, Query(mid, e, R(ind), l, r));
      return ret;
}
