    if (a <= l && r <= b) return dp[k]; // contain completely
    else {
        ll vl = query(a, b, k*2+1, l, (l+r)/2);
        ll vr = query(a, b, k*2+2, (l+r)/2, r);
        return max(vl, vr);
    }
}

