{
    bool operator() (const ll &idx1, const ll &idx2) const
    {
        return hts[idx1] < hts[idx2];
    }
};

ll solve()
{
    set<ll, custom_comparator> meaning;
    ll res = 0;
    DP[0] = beauty[0];
    meaning.insert(0);
    for (int i = 1; i < N; ++i)
    {
        DP[i] = beauty[i];
        auto it = meaning.upper_bound(i);
        if (it != meaning.begin())
        {
            it = prev(it);
            DP[i] = DP[*it] + beauty[i];
        }
