        it = meaning.upper_bound(i);
        while (it != meaning.end() && DP[*it] <= DP[i])
        {
            auto temp = next(it);
            meaning.erase(it);
            it = temp;
        }
    }
    res = *max_element(DP, DP + N);
    return res;
}

