LL update( int cx , int cy , int q , int id , LL val ) {
	if( q < cx || cy < q )
		return tree[id];
	if( cx == cy )
		return tree[id] = val;
	int mid = (cx + cy) >> 1;
	LL left = update( cx , mid , q , id*2 , val );
	LL right = update( mid+1 , cy , q , id*2+1 , val );
	return tree[id] = max( left , right );
}

LL query( int cx , int cy , int qx , int qy , int id ) {
	if( qy < cx || cy < qx )
		return 0;
	if( qx <= cx && cy <= qy )
		return tree[id];
	int mid = (cx + cy) >> 1;
	LL left = query( cx , mid , qx , qy , id*2 );
	LL right = query( mid+1 , cy , qx , qy , id*2+1 );
	return max( left , right );
}

