void search(const ll N, const int pos, vll& end){
  if(N-1==pos){
    dp[pos] = a[pos];
    return;
  }
  search(N, pos+1, end);
  dp[pos] = a[pos];
  rep(i, pos+1, end[pos]+1){
    if(h[pos] >= h[i]) continue;
    dp[pos] = max(dp[pos], dp[i]+a[pos]);
  }
  return;
}

