int main()
{
    int n;
    cin >> n;

    int base = 1;
    while(base < n) {
        base *= 2;
    }
    vector<ll> tree(2*base);

    for(int i = 0; i < n; i++) {
        cin >> height[i];
        dp[i] = 0;
    }
    for(int i = 0; i < n; i++) {
        cin >> beauty[i];
    }

    for(int i = 0; i < n; i++) {
        dp[height[i]] = beauty[i];
        /*for(int h = 1; h < height[i]; h++) {
            dp[height[i]] = max(dp[height[i]], dp[h]+beauty[i]);
        }*/
        //find max from 1 to height[i]-1.
        int l = base+0, r = base+height[i]-2;
        ll maxval = 0;
        while(l <= r) {
            if(l%2) {
                maxval = max(maxval, tree[l]);
                l++;
            }
            if(r%2 == 0) {
                maxval = max(maxval, tree[r]);
                r--;
            }
            l /= 2;
            r /= 2;
        }
        //set dp[height[i]] to maxval.
        maxval = max(maxval+beauty[i], dp[height[i]]);
        int k = base+height[i]-1;
        tree[k] = maxval;
        while(k > 1) {
            tree[k/2] = max(tree[k/2], maxval);
            k /= 2;
        }
        dp[height[i]] = maxval;
    }

    ll ans = 0;
    for(int i = 1; i <= n; i++) {
        ans = max(ans, dp[i]);
    }
    cout << ans << endl;
}

