void updt(int a, long long war)
{
	tree[a+=pot]=max(tree[a],war);
	for(a>>=1; a; a>>=1)
		tree[a]=max(tree[a<<1],tree[(a<<1)^1]);
}

long long query(int a, int b)
{
	long long ret=0;
	for(a+=pot-1,b+=pot+1; a/2!=b/2; a>>=1,b>>=1)
	{
		if(!(a&1))
			ret=max(ret,tree[a+1]);
		if(b&1)
			ret=max(ret,tree[b-1]);	
	}
	return ret;
}

