int main() {
  int N;
  scanf("%d", &N);
  static int H[200001];
  for (auto i = 1; i <= N; ++i)
    scanf("%d", &H[i]);
  static int A[200001];
  for (auto i = 1; i <= N; ++i)
    scanf("%d", &A[i]);
  static long long F[200001];
  auto fupd = [&](int k, long long v) {
    while (k <= N) {
      F[k] = max(F[k], v);
      k += k & -k;
    }
  };
  auto fqry = [&](int k) {
    auto res = 0ll;
    while (k) {
      res = max(res, F[k]);
      k -= k & -k;
    }
    return res;
  };
  auto res = 0ll;
  for (auto i = 1; i <= N; ++i) {
    auto tmp = fqry(H[i]) + A[i];
    fupd(H[i], tmp);
    res = max(res, tmp);
  }
  printf("%lld\n", res);
  return 0;
}

