ll solve() {
	vector<ll> dp(N);
	map<ll, ll> map; //height to dp
	dp[0] = b[0];
	map[h[0]] = b[0];
	ll ans = dp[0];

	for (int i = 1; i < N; i++) {
		// cout << i << endl;
		dp[i] = b[i];
		auto it = map.lower_bound(h[i] + 1);
		if (it != map.begin()) {
			// cout << "Entered\n";
			it--;
			// dp[i] = max(dp[i], )
			dp[i] += it->second;
			map[h[i]] = dp[i];
			it = map.upper_bound(h[i]);
			while (it != map.end() && it->second <= dp[i]) {
				// cout << "Deleted\n";
				auto temp = it;
				temp++;
				map.erase(it);
				it = temp;
			}
		}
		// cout << dp[i] << endl;
		ans = max(ans, dp[i]);
		// printf("dp[i]: %lld, ans: %lld\n", dp[i], ans);
	}
	return ans;
}

