#include <bits/stdc++.h>

using namespace std;

typedef long long int ll;

const int N = (int) 2e5 + 10;

struct node {
    int l, r;
    node *left, *right;
    ll val;
    node(int L, int R) {
        val = 0, l = L, r = R;
        if(l == r) return;
        int m = l + r >> 1;
        left = new node(l, m);
        right = new node(m + 1, r);
    }
    ll query_max(int L, int R) {
        if(r < L || l > R) return 0;
        if(L <= l && r <= R) return val;
        return max(left->query_max(L, R), right->query_max(L, R));
    }
    void update(int i, ll x) {
        if(r < i || i < l) return;
        if(l == r) {
            val = x;
            return;
        }
        left->update(i, x);
        right->update(i, x);
        val = max(left->val, right->val);
    }
};

int n;
int a[N], h[N];
node *st;

void solve() {
    cin >> n;
    st = new node(1, n);
    for(int i = 1; i <= n; ++i) {
        cin >> h[i];
    }
    for(int i = 1; i <= n; ++i) {
        cin >> a[i];
    }
    for(int i = 1; i <= n; ++i) {
        int height = h[i];
        ll max_val = st->query_max(1, height);
        ll cur = max_val + a[i];
        st->update(height, cur);
    }
    cout << st->query_max(1, n) << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.precision(20);
    cout << fixed;
    solve();
    return 0;
}

