using ll = long long;
const int N = 2e5+500;
vector<ll> t(2*N);
void update(int k, ll value, int v, int tl, int tr) {
	if(tl==tr) {
		t[v] = value;
		return;
	} 
	int mid = tl + (tr-tl)/2;
	if(k<=mid) {
		update(k,value, v*2,tl,mid);
	} else {
		update(k,value,v*2+1,mid+1,tr);
	}
	t[v] = max(t[v*2],t[v*2+1]);
}
int query(int v, int tl, int tr, int l, int r) {
	if(l>r) return 0;
	if(l==tl && r==tr) {
		return t[v];
	} 
	int mid = tl + (tr-tl)/2;
	return max(query(v*2,tl,mid,l,min(mid,r)), query(v*2+1,mid+1,tr,max(l,mid+1),r));
}
