struct segmentTree{

    int N;
    vector<long long> node;
    const long long INF = LLONG_MIN;

    void init(int siz){
        N = 1;
        while(N < siz){
            N <<= 1;
        }
        node.resize(N * 2 - 1, INF);
    }

    void build(vector<long long> &dat){
        for(int i = 0, len = dat.size() ; i < len ; ++i){
            node[i + N - 1] = dat[i];
        }
        for(int i = N - 2 ; i >= 0 ; --i){
            node[i] = max(node[i * 2 + 1], node[i * 2 + 2]);
        }
    }

    void update(int k, long long x){
        k += N - 1;
        node[k] = x;
        while(k > 0){
            k = (k - 1) / 2;
            node[k] = max(node[k * 2 + 1], node[k * 2 + 2]);
        }
    }

    long long getMax(int a, int b, int k, int l, int r){
        if(r <= a || b <= l){
            return INF;
        }
        if(a <= l && r <= b){
            return node[k];
        }
        long long vl = getMax(a, b, k * 2 + 1, l, (l + r) / 2);
        long long vr = getMax(a, b, k * 2 + 2, (l + r) / 2, r);
        return max(vl, vr);
    }

    long long getMax(int a, int b){
        return getMax(a, b, 0, 0, N);
    }

};

