struct SegTree {
    int n, len;
    vii lo, hi;
    vll seg;
    SegTree (int n) : n(n) {
        len = 4 * n + 1;
        lo.assign(len, 0);
        hi.assign(len, 0);
        seg.assign(len, 0);
        init(1, 1, n);
    }

    void init(int i, int l, int r) {
        lo[i] = l;
        hi[i] = r;
        if (l == r) return;
        int m = (l + r) / 2;
        init(2 * i, l, m);
        init(2 * i + 1, m + 1, r);
    }

    void update(int i, ll del) {
        incr(1, i, del);
    }

    void incr(int i, int j, ll del) {
        if (lo[i] > j or hi[i] < j) return;
        if (lo[i] == hi[i]) {
            seg[i] += del;
            return;
        }
        incr(2 * i, j, del);
        incr(2 * i + 1, j, del);
        seg[i] = max(seg[2 * i], seg[2 * i + 1]);
        // cerr << j << ", " << i << ": " << seg[i] << '\n';
    }

    ll maximum(int i) {
        return read(1, 1, i);
    }

    ll read(int i, int l, int r) {
        ll v = seg[i];
        if (lo[i] > r or hi[i] < l) return 0;
        if (l <= lo[i] and hi[i] <= r) return seg[i];

        ll res = read(2 * i, l, r);
        res = max(res, read(2 * i + 1, l, r));

        return res;
    }
};

