const int N = 2e5 + 5;
int n;
// dp[i]: the maximum beauty value that you can achieve with flower [1, i]
ll dp[N];
ll h[N];
ll a[N];

void maximize(ll& a, ll b) {
    if (a < b) a = b;
}

struct SegmentTree {
    vector<ll> tree;
    int len;

    explicit SegmentTree(): len(0) {}

    void pushup(int i) {
        tree[i] = max(tree[i << 1], tree[i << 1 | 1]);
    }

    void build(int n) {
        len = n;
        tree.assign(len << 1, 0ll);
    }

    void update(int pos, ll new_val) {
        tree[pos + len - 1] = new_val;
        for (pos += len - 1; pos; pos >>= 1) maximize(tree[pos], new_val);
    }

    ll query(int l, int r) const {
        if (l > r) return 0;
        ll ans = 0;
        for (l += len - 1, r += len; l < r; l >>= 1, r >>= 1) {
            if (l & 1) maximize(ans, tree[l++]);
            if (r & 1) maximize(ans, tree[--r]);
        }
        return ans;
    }

    void debug() const {
        for (auto it : tree) printf("%lld ", it);
        putchar('\n');
    }

    void clear() {
        tree.clear();
    }
};

void solve() {
    SegmentTree st;
    st.build(n);
    memset(dp, 0, sizeof dp);
    ll ans = 0;
    for (int i = 0; i < n; ++i) {
        dp[i] = a[i]; // choose only this
        ll max_dp = st.query(1, h[i] - 1);
        maximize(dp[i], max_dp + a[i]);
        st.update(h[i], dp[i]);
        maximize(ans, dp[i]);
    }
    printf("%lld\n", ans);
}

