//Globals
class segment_tree{
private:
    vec<ll> tree;
    ll n;
    void point_update(int index, int start, int end, int qstart, int qend, ll delta){

        if(qend<start or qstart>end){return;}
        else if(start==end){tree[index]+=delta;}
        else{
            int mid = (start+end)/2;
            point_update(2*index+1,start,mid,qstart,qend,delta);
            point_update(2*index+2,mid+1,end,qstart,qend,delta);
            tree[index] = max(tree[2*index+1],tree[2*index+2]);

        }
    }
    ll query(int index, int start, int end, int qstart, int qend){
        if(qend<start or qstart>end){return -1;}
        else if(start>=qstart and end<=qend){return tree[index];}
        else{
            int mid = (start+end)/2;
            ll left = query(2*index+1,start,mid,qstart,qend);
            ll right = query(2*index+2,mid+1,end,qstart,qend);
            return max(left,right);
        }
    }
public:
    segment_tree(ll size){
        n = size;
        tree.resize(2*n);
    }
    void update(int start, int end, ll delta){
        point_update(0,0,n-1,start,end,delta);
    }
    ll get(int start, int end){
        return query(0,0,n-1,start,end);
    }
};
