const int N = 2e5 + 7;

ll t[4 * N];

void upd(int v, int tl, int tr, int p, ll x) {
  if (tl == tr) {
    t[v] = max(t[v], x);
  } else {
    int tm = (tl + tr) / 2;
    if (p <= tm) upd(2 * v + 1, tl, tm, p, x);
    else upd(2 * v + 2, tm + 1, tr, p, x);
    t[v] = max(t[2 * v + 1], t[2 * v + 2]);
  }
}

ll get(int v, int tl, int tr, int l, int r) {
  if (tl > r || tr < l) {
    return 0;
  } else if (tl >= l && tr <= r) {
    return t[v];
  } else {
    int tm = (tl + tr) / 2;
    return max(get(2 * v + 1, tl, tm, l, r), get(2 * v + 2, tm + 1, tr, l, r));
  }
}

