struct node {
    int l, r;
    node *left, *right;
    ll val;
    node(int L, int R) {
        val = 0, l = L, r = R;
        if(l == r) return;
        int m = l + r >> 1;
        left = new node(l, m);
        right = new node(m + 1, r);
    }
    int query_max(int L, int R) {
        if(r < L || l > R) return 0;
        if(L <= l && r <= R) return val;
        return max(left->query_max(L, R), right->query_max(L, R));
    }
    void update(int i, ll x) {
        if(r < i || i < l) return;
        if(l == r) {
            val = x;
            return;
        }
        left->update(i, x);
        right->update(i, x);
        val = max(left->val, right->val);
    }
};

