void update(int node, int start, int end, int ind, ll x){
	if(start == end){
		if(x>tree[node]){
			tree[node] = x;
		}
		//cout << node << endl;
		return;
	}

	int mid = (start+end)/2;

	if( ind >= start && ind <= mid){
		update(2*node, start, mid, ind, x);
	}
	else{
		update(2*node+1, mid+1, end, ind, x);	
	}

	tree[node] = func(tree[2*node], tree[2*node+1]);
	//cout << node << endl;
	return;
}

ll query(int node, int start, int end, int l, int r){
	if( l>end or r<start ){
		return 0;
	}

	if( l<= start and r>=end ){
		return tree[node];
	}

	int mid = (start+end)/2;
	ll left = query(2*node, start, mid, l, r);
	ll right = query(2*node+1, mid+1, end, l, r);

	//cout << left << right << node << endl;

 	return func(left, right);
}

