const int N = 2e5 + 5;

ll dp[N], seg[4*N + 4];

void upd(int node, int l, int r, int pos, ll val)
{
	if (l == r)
	{
		seg[node] = val;
		return;
	}
	int mid = (l+r)/2;
	if (mid >= pos) upd(2*node, l, mid, pos, val);
	else upd(2*node+1, mid+1, r, pos, val);
	seg[node] = max(seg[2*node], seg[2*node+1]);
}

ll qu(int node, int l, int r, int x, int y)
{
	if (l > y or r < x) return 0;
	if (l >= x and r <= y) return seg[node];
	int mid = (l+r)/2;
	return max(qu(2*node, l, mid, x, y), qu(2*node+1, mid+1, r, x, y));
}

