struct segtree {
    int n;
    vector<ll> T;

    segtree() = default;
    segtree(int n) : n(n) {
        T.resize(4 * n);
    }

    void upd(int i, ll x, int v, int l, int r) {
        if (l == r) {
            T[v] = max(T[v], x);
            return ;
        }

        auto m = (l + r) / 2;

        if (i <= m)
            upd(i, x, 2 * v, l, m);
        else
            upd(i, x, 2 * v + 1, m + 1, r);

        T[v] = max(T[2 * v], T[2 * v + 1]);
    }

    ll get(int lq, int rq, int v, int l, int r) {
        if (r < lq || l > rq)
            return 0;

        if (lq <= l && r <= rq)
            return T[v];

        auto m = (l + r) / 2;
        return max(get(lq, rq, 2 * v, l, m), get(lq, rq, 2 * v + 1,m + 1, r));
    }

    void upd(int i, ll x) {
        upd(i, x, 1, 0, n - 1);
    }

    ll get(int lq, int rq) {
        return get(lq, rq, 1, 0, n - 1);
    }
};

