        if(r == -1) r += n;
        if(r < x || l > y) return 0;
        if(l >= x && r <= y) return seg[i];
        int m = (l+r) >> 1;
        return max(query(x, y, l, m, i*2+1), query(x, y, m+1, r, i*2+2));
