#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MAXN=200005ll;
const ll INF=0x3f3f3f3f3f3f3f3fll;

struct segmentTreeNode {
    ll l,r,add,sum,mx,mn;
};

void pup(segmentTreeNode tree[], ll index) {
    tree[index].sum = tree[index<<1].sum+tree[index<<1|1].sum;
    tree[index].mx = max(tree[index<<1].mx,tree[index<<1|1].mx);
    tree[index].mn = min(tree[index<<1].mn,tree[index<<1|1].mn);
}

void pdn(segmentTreeNode tree[], ll index) {
    if (tree[index].add) {
        tree[index<<1].sum += (tree[index<<1].r-tree[index<<1].l+1)*tree[index].add;
        tree[index<<1|1].sum +=(tree[index<<1|1].r-tree[index<<1|1].l+1)*tree[index].add;
        tree[index<<1].mx += tree[index].add;
        tree[index<<1|1].mx += tree[index].add;
        tree[index<<1].mn += tree[index].add;
        tree[index<<1|1].mn += tree[index].add;
        tree[index<<1].add += tree[index].add;
        tree[index<<1|1].add += tree[index].add;
        tree[index].add = 0;
    }
}
void build(segmentTreeNode tree[], ll l, ll r, ll index, vector<ll>& data) {
    tree[index].l = l;
    tree[index].r = r;
    tree[index].add = 0;
    if (l == r) {
        tree[index].sum = data[l];
        tree[index].mn = tree[index].mx = tree[index].sum;
        return;
    }
    ll mid = (l+r)>>1;
    build(tree,l,mid,index<<1,data);
    build(tree,mid+1,r,index<<1|1,data);
    pup(tree,index);
}
void upd(segmentTreeNode tree[], ll l, ll r, ll index, ll val) {
    if (l <= tree[index].l && r >= tree[index].r) {
        tree[index].sum += (tree[index].r-tree[index].l+1)*val;
        tree[index].mn += val;
        tree[index].mx += val;
        tree[index].add += val;
        return;
    }
    pdn(tree,index);
    ll mid = (tree[index].l+tree[index].r)>>1;
    if (l <= mid) upd(tree,l,r,index<<1,val);
    if (r > mid) upd(tree,l,r,index<<1|1,val);
    pup(tree,index);
}
ll query(segmentTreeNode tree[], ll l, ll r, ll index) {
    if (l <= tree[index].l && r >= tree[index].r) {
        // return tree[index].sum;
        return tree[index].mx;
        // return tree[index].mn;
    }
    pdn(tree,index);
    ll mid = (tree[index].l+tree[index].r)>>1;
    ll sumres = 0, mxres = -INF, mnres = INF;
    if (l <= mid) {
        sumres += query(tree,l,r,index<<1);
        mxres = max(query(tree,l,r,index<<1),mxres);
        mnres = min(query(tree,l,r,index<<1),mnres);
    }
    if (r > mid) {
        sumres += query(tree,l,r,index<<1|1);
        mxres = max(query(tree,l,r,index<<1|1),mxres);
        mnres = min(query(tree,l,r,index<<1|1),mnres);
    }
    // return sumres;
    return mxres;
    // return mnres;
}

