struct node {
	int s, e;
	ll mn, mx, sum;
	bool lset;
	ll add_val, set_val;
	node * l, *r;
	node (int _s, int _e, int A[] = NULL): s(_s), e(_e), mn(0), mx(0), sum(0), lset(0), add_val(0), set_val(0), l(NULL), r(NULL) {

		if (A == NULL) return;
		if (s == e) mn = mx = sum = A[s];
		else {
			l = new node(s, (s + e) >> 1, A), r = new node((s + e + 2) >> 1, e, A);
			combine();
		}
	}
	void create_children() {
		if (s == e) return;
		if (l != NULL) return;
		int m = (s + e) >> 1;
		l = new node(s, m);
		r = new node(m + 1, e);
	}

	void combine() {
		if (l == NULL) return;
		sum = l->sum + r->sum;
		mn = min(l->mn, r->mn);
		mx = max(l->mx, r->mx);
	}

	void update(int pos, int val) {

		if (e == s) {

			mx = val;
		}

		else {

			int mid = (e + s) / 2;

			if (pos <= mid) {
				l->update(pos, val);

			}
			else {
				r->update(pos, val);
			}


			combine();
		}



	}



	ll range_max(int x, int y) {
		if (s == x && e == y) return mx;
		if (l == NULL || lset) return mx;
		int m = (s + e) >> 1;
		if (y <= m) return l->range_max(x, y);
		if (x > m) return r->range_max(x, y);
		return max(l->range_max(x, m), r->range_max(m + 1, y));
	}
	~node() {
		if (l != NULL) delete l;
		if (r != NULL) delete r;
	}
};










