using namespace std;
using ll = long long;
using pii = pair < int, int >;

struct SegmentTree {
	vector < ll > st;
	SegmentTree (int n) {
		st.resize (4 * n);
	}

	void update (int index, ll value, int low, int high, int pos) {
		if (low > index || high < index) {
			return;
		}
		if (low == high) {
			st[pos] = value;
			return;
		}
		int mid = low + (high - low) / 2;
		update (index, value, low, mid, pos + pos + 1);
		update (index, value, mid + 1, high, pos + pos + 2);
		st[pos] = max (st[pos + pos + 1], st[pos + pos + 2]);
	}

	ll query (int left, int right, int low, int high, int pos) {
		if (left > high || low > right) return 0;
		if (left <= low && right >= high) return st[pos];
		int mid = low + (high - low) / 2;
		return max (
			query (left, right, low, mid, (pos << 1) + 1),
			query (left, right, mid + 1, high, (pos << 1) + 2)
		);
	}
};

int main() {
	int n;
	scanf ("%d", &n);
	vector < int > h (n), a (n);
	for (int & x : h) scanf ("%d", &x);
	for (int & x : a) scanf ("%d", &x);
	// O (N ^ 2) solution
	vector < ll > dp (n);
	SegmentTree tree (n + 1);
	ll answer = 0ll;
	for (int i = 0; i < n; i++) {
		ll max_value = tree.query (1, h[i] - 1, 0, n, 0);
		dp[i] = max_value + a[i];
		tree.update (h[i], dp[i], 0, n, 0);
		answer = max (answer, dp[i]);
	}
	printf ("%lld\n", answer);
	return 0;
}

