long long find(int v, int seg_start, int seg_end, int query_left, int query_right) {
  if (query_left > query_right) return 0;
  if (query_left == seg_start && query_right == seg_end) {
    return tree[v];
  }
  int seg_mid = (seg_start + seg_end) / 2;
  return max(find(v*2, seg_start, seg_mid, query_left, min(seg_mid, query_right)),
            find(v*2 + 1, seg_mid + 1, seg_end, max(seg_mid + 1, query_left), query_right));
}

void log(int v) {
  cout << v << " " << tree[v*2] << " " << tree[v*2 + 1] << "\n";
}

void update(int v, int seg_start, int seg_end, int pos, long long val) {
  if (seg_start == pos && seg_end == pos) {
    tree[v] = val;
    return;
  }
  int seg_mid = (seg_start + seg_end) / 2;
  if (pos <= seg_mid) {
    update(v*2, seg_start, seg_mid, pos, val);
  } else {
    update(v*2+1, seg_mid + 1, seg_end, pos, val);
  }
  //log(v);
  tree[v] = max(tree[v*2], tree[v*2+1]);
}

