class ft {
  vector<ll> f;
public:
  ft(int n) {
    f.resize(n);
  }

  void add(int x, ll v) {
    for (; x < (int)f.size(); x += x & -x) {
      f[x] = max(f[x], v);
    }
  }

  ll get(int x) {
    ll ret = 0;
    for (; x; x -= x & -x) {
      ret = max(ret, f[x]);
    }
    return ret;
  }
};


