template<typename T>
struct BIT{
    int N;
    vector<T> dat;
    BIT(int n) : N(n), dat(n+1,0){ }
    void add(int i, T num){
        for(int x = i+1; x <= N; x += (x & -x)) dat[x] = max(dat[x], num);
    }
    T mx(int i){
        T ret = 0;
        for(int x = i+1; x > 0; x -= (x & -x)) ret = max(ret, dat[x]);
        return ret;
    }
};

