struct SegmentTree{
private:
  vector<long long> node;
  int n;
public:
  SegmentTree(int sz){
    n = 1;
    while(n < sz) n *= 2;
    node.resize(2*n-1,0);
  }
  void add(int idx, long long x){
    idx += n-1;
    node[idx] += x;
    while(idx > 0){
      idx = (idx-1)/2;
      node[idx] = max(node[idx*2+2],node[idx*2+1]);
    }
  }
  long long getmax(int a, int b, int t=0, int l=0, int r=-1){
    if(r < 0) r = n;
    if(b <= l or a >= r) return 0;
    if(a <= l and b >= r) return node[t];
    long long vl = getmax(a,b,2*t+1,l,(l+r)/2);
    long long vr = getmax(a,b,2*t+2,(l+r)/2,r);
    return max(vl,vr);
  }
};

int main(){
