	{
		tree.resize(3 * n + 1);
	}

	// void build(ll a[],int n)
	// {

	// }

	void update(ll node, ll start, ll end, ll ind, ll val)
	{
		if (start == end)
		{
			tree[node] = max(tree[node], val);
		}
		else
		{
			int mid = (start + end) / 2;

			if (ind >= start && ind <= mid)
				update(2 * node + 1, start, mid, ind, val);

			if (ind >= mid + 1 && ind <= end)
				update(2 * node + 2, mid + 1, end, ind, val);

			tree[node] = max(tree[2 * node + 1], tree[2 * node + 2]);
		}
	}

	ll query(ll node, ll start, ll end, ll l, ll r)
	{

		//completely inside

		if (start >= l && end <= r)
			return tree[node];

		ll mid = (start + end) / 2;

		if (r < start || end < l)
		{
			return -1;
		}

		return max(query(2 * node + 1, start, mid, l, r), query(2 * node + 2, mid + 1, end, l, r));
	}
};

