    {
        t[node] = val;
        return;
    }

    int left = (node<<1);
    int right = (left|1);
    int m = (i+j)>>1;

    if(idx <= m)
        update(left, i, m, idx, val);
    else
        update(right, m+1, j, idx, val);
    t[node] = max(t[left], t[right]);
}
