#define NEUTRAL -1
#define OP max
class Seg {
  public:
    int t = 1;
    vector<long long> dp;

    Seg(int n) {
      while (t <= n) {
        t *= 2;
      }

      dp = vector<long long>(t * 2 - 1, NEUTRAL);
    }

    int up(int node) {
      return (node - 1) / 2;
    }

    int down(int node) {
      return (node * 2) + 1;
    }

    void update(int i, long long x) {
      i += t - 1;
      dp[i] = x;

      while (i != 0) {
        i = up(i);
        int c = down(i);
        dp[i] = max(dp[c], dp[c + 1]);
      }
    }

    long long find(int l, int r, int node=0, int sl=0, int sr=-1) {
      if (sr < 0) sr = t;

      if (sr <= l || r <= sl) {
        return NEUTRAL;
      }

      if (l <= sl && sr <= r) {
        return dp[node];
      }

      int sc = (sl + sr) / 2;
      int c = down(node);
      return max(find(l, r, c, sl, sc), find(l, r, c + 1, sc, sr));
    }
};

