ll bit[N];
void update(int idx, ll x, int n){  /// point update (add)
    while(idx<=n){
        bit[idx] += x;
        idx += (idx & (-idx));
    }
}
ll get(int i, int j){   /// range sum
    ll sum = 0;
    while(j>=i){
        sum += bit[j];
        j -= (j & (-j));
    }
    i--;
    while(i>j){
        sum -= bit[i];
        i -= (i & (-i));
    }
    return sum;
}

