const int MOD = 1000000007;

class MaxSegTree {
public:
    // create a MaxSegTree instance with minimal size 
    // actual size will be adjusted to a power of 2
    MaxSegTree(int size) {
        int actualSize = 1;
        while (actualSize < size) actualSize *= 2;
        nodes.resize(actualSize * 2 - 1, 0);
    }

    // return the number of leafs allowed in this container
    int size() {
        return (nodes.size() + 1) / 2;
    }

    void setAt(int i, LL v) {
        int index = leafIndex(i);
        nodes[index] = v;
        while (0 < index) {
            index = (index - 1) / 2;
            nodes[index] = max(nodes[2 * index + 1], nodes[2 * index + 2]);
        }
    }

    LL maxInRange(int begin, int end) {
        return maxInRangeImpl(begin, end, 0, 0, (nodes.size()+1) / 2);
    }

    void dumpTree() {
        int index = 0;
        for (int size = 1;; size *= 2) {
            rep(i, size) { 
                if (nodes.size() <= index) {
                    cout << endl;
                    return;
                }
                cout << nodes[index] << ' ';
                ++ index;
            }
            cout << endl;
        }
    }

private:
    //! index 0: [0..2^n)
    //! index 1: [0..2^(n-1))
    //! index 2: [2^(n-1)..2^n-1)
    //! parent-index of node at i = (i-1)/2
    //! indexes of children of node at i = 2i + 1, 2i + 2
    //! index of i-th leaf node = i + 2^(n-1) -1 = i + actualSize - 1

    int leafIndex(int i) { return i + size() - 1; }

    LL maxInRangeImpl(int begin, int end, int segIndex, int segBegin, int segEnd) {
        if (end <= segBegin || segEnd <= begin) {
            return 0; //! the range and the segment do not have intersection
        }
        if (begin <= segBegin && segEnd <= end) {
            //! the range is completely included in the segment
            return nodes[segIndex];
        }
        return max( maxInRangeImpl(begin, end, 2 * segIndex + 1, segBegin, (segBegin + segEnd)/2), 
                    maxInRangeImpl(begin, end, 2 * segIndex + 2, (segBegin + segEnd)/2, segEnd) );
    }

    vector<LL> nodes;
};


