struct Solver {
    int N;
    vector<long long> tree;

    void initialize(int N) {
        tree.resize(4 * N + 4, 0);
    }

    long long query(int node, int b, int e, int low, int high) {
        if (b > high || e < low) {
            return 0;
        } else if (b >= low && e <= high) {
            return tree[node];
        } else {
            int mid = (b + e) / 2;
            long long left = query(node << 1, b, mid, low, high);
            long long right = query(1 + (node << 1), mid + 1, e, low, high);
            return max(left, right);
        }
    }

    long long query(int low, int high) {
        return query(1, 0, N, low, high);
    }

    void update(int node, int b, int e, int idx, long long val) {
        if (b > idx || e < idx) {
            return;
        } else if (b == e) {
            tree[node] = val;
        } else {
            int mid = (b + e) / 2;
            update(node << 1, b, mid, idx, val);
            update(1 + (node << 1), mid + 1, e, idx, val);
            tree[node] = max(tree[node << 1], tree[1 + (node << 1)]);
        }
    }

    void update(int idx, long long val) {
        update(1, 0, N, idx, val);
    }

    long long solve(int _N, vector<int>& h, vector<int>& a) {
        N = _N;
        initialize(N);
        vector<long long> count(N + 1, 0);

        for (int i = 0; i < N; ++i) {
            // Pick a[i] with height h[i]
            int currHeight = h[i];
            count[i] = query(0, currHeight - 1) + a[i];
            update(currHeight, count[i]);
        }

        long long result = 0;

        for (int i = 0; i < size(count); ++i) {
            result = max(result, count[i]);
        }

        return result;
    }
};

