}

long long solve() {
  long long ans = 0;
  rmq = RMQ(n + 1);
  for(int i = 0; i < n; ++i) {
    long long now = a[i];
    now += rmq.pick(0, h[i]);
    rmq.update(h[i], now);
    ans = max(ans, now);
  }
  return ans;
}

