inline long long get(int pos){
    long long cur = 0;
    for(int i = pos; i >= 1; i &= i + 1, i--){
        cur = max(cur, t[i]);
    }
    return cur;
}

inline void upd(int pos, long long val){
    for(int i = pos; i <= n; i |= i + 1){
        t[i] = max(t[i], val);
    }
}

