class SegmentTree {
public:
	int N;
	vector<ll> maximum, delta;

	SegmentTree() {}

	SegmentTree(int N) {
		this->N = N;
		maximum = vector<ll>(4 * N + 1);
		delta = vector<ll>(4 * N + 1);
		//you don't need to init unless default values are not zero
		//init(1, 0, N - 1);
	}

	void update(int l, int r, ll val) {update(1, 0, N - 1, l, r, val);} //inclusive range

	ll query(int l, int r) {return query(1, 0, N - 1, l, r);} //inclusive range

	void init(int i, int lo, int hi) {
		//if default segtree values are not zero, initialize node i
		if (lo == hi) return;

		int m = (lo + hi) / 2;
		init(2 * i, lo, m);
		init(2 * i + 1, m + 1, hi);
	}

	void push(int i) {
		delta[2 * i] += delta[i];
		delta[2 * i + 1] += delta[i];
		delta[i] = 0;
	}

	void pull(int i) {
		maximum[i] = max(maximum[2 * i] + delta[2 * i], maximum[2 * i + 1] + delta[2 * i + 1]);
	}

	void update(int i, int lo, int hi, int l, int r, ll val) {
		if (r < lo || hi < l) return;
		if (l <= lo && hi <= r) {
			delta[i] = val;
			return;
		}

		push(i);

		int m = (lo + hi) / 2;
		update(2 * i, lo, m, l, r, val);
		update(2 * i + 1, m + 1, hi, l, r, val);

		pull(i);
	}

	ll query(int i, int lo, int hi, int l, int r) {
		if (r < lo || hi < l) return 0;
		if (l <= lo && hi <= r) {
			return maximum[i] + delta[i];
		}

		push(i);

		int m = (lo + hi) / 2;
		ll maxLeft = query(2 * i, lo, m, l, r);
		ll maxRight = query(2 * i + 1, m + 1, hi, l, r);

		pull(i);

		return max(maxLeft, maxRight);
	}
};

