void seekAndUpdate (int id ) {
  pair<int, int > pp = make_pair(h[id], a[id]);
  myset.insert(pp);
  auto it = myset.find(pp);
  if (it != myset.begin()) {
    it --;
    auto pre = it;
    it ++;
    pp.second += pre -> second;
    myset.erase(it);
    myset.insert(pp);
  }
  while (it != myset.end()) {
    it ++;
    auto tmp = it;
    if (tmp == myset.end()) break;
    it --;
    if (pp.second > tmp -> second) {
      myset.erase(tmp);
    } else {
      break;
    }
  }
}

