	ll res = 0;

	for(ll i=0;i<n;i++) {
		if((mask & (1<<i)) != 0 && adj[idx][i]) {
			res = (res + solve(dp,adj,idx-1,mask^(1<<i)))%N;
		}
	}

	dp[idx][mask] = (res+N)%N;
	return dp[idx][mask];
}

