	{
		st[node]=0;
		return;
	}
	int mid=(l+r)>>1;
	build(node<<1,l,mid);
	build(node<<1|1,mid+1,r);
	st[node]=max(st[node<<1],st[node<<1|1]);
}
void update(int node,int l,int r,int pos,ll val)
{
	if(l==r)
	{
		st[node]=val;
		return;
	}
	int mid=(l+r)>>1;
	if(pos<=mid) update(node<<1,l,mid,pos,val);
	else update(node<<1|1,mid+1,r,pos,val);
	st[node]=max(st[node<<1],st[node<<1|1]);
}
