        if(b==-1)b=n;
        if(r==-1)r=n;
        if(b<=l||r<=a)return -LINF;
        if(a<=l&&r<=b){
            return node[k];
        }
        else{
            return max(get(a,b,2*k+1,l,(l+r)/2),get(a,b,2*k+2,(l+r)/2,r));
        }
    }
};

