template<typename T>
struct BIT {
  int n;
  vector<T> d;
  BIT(int n=0):n(n),d(n+1) {}
  void add(int i, T x=1) {
    for (i++; i <= n; i += i&-i) {
      d[i] = max(d[i],x);
    }
  }
  T get_max(int i) {//sum of [0,i]
    T x = 0;
    for (i++; i; i -= i&-i) {
      x = max(x,d[i]);
    }
    return x;
  }
