	{
		ll curr_mid = (curr_l + curr_r) >> 1;
		ll left_value = query(2 * node + 1, curr_l, curr_mid, query_l, min(query_r, curr_r)); 
		ll right_value = query(2 * node + 2, curr_mid + 1, curr_r, max(query_l, curr_l), query_r);
		return combine(left_value, right_value);
	}
}

void point_update(ll node, ll curr_l, ll curr_r, ll pos)
{
	if(curr_l == curr_r)
		tree_arr[node] = dp[curr_r];
	else
	{
		ll curr_mid = (curr_l + curr_r) >> 1;
		if(curr_mid >= pos)
			point_update(2 * node + 1, curr_l, curr_mid, pos);
		else
			point_update(2 * node + 2, curr_mid + 1, curr_r, pos);
		tree_arr[node] = combine(tree_arr[2 * node + 1],tree_arr[2 * node + 2]);
	}
}

