void update(int v, int tl, int tr, int x, int y){
	if (tl == tr){
		tree[v] = y;
		return ;
	}
	int tm = (tl+tr)>>1;
	int lc = v << 1;
	int rc = lc+1;
	if ( x <= tm){
		update(lc, tl, tm, x, y);
	}
	else{
		update(rc, tm+1, tr, x, y);
	}
	tree[v] = max(tree[lc], tree[rc]);
}

int query(int v, int tl, int tr, int ql, int qr){
	if (ql > qr)
		return 0;
	if (tl == ql && tr ==  qr){
		return tree[v];
	}
	int tm = (tl+tr)>>1;
	int lc = v << 1;
	int rc = lc + 1;
	return max(query(lc, tl, tm, ql, min(qr, tm)), query(rc, tm+1, tr, max(ql, tm+1), qr));
}

