template<class T, class S> class SegmentTree{
private:
	vector<T> node;
	ll n;
	T e;
	function<T(T, T)> ope;
	function<T(T, S)> update;
public:
	SegmentTree(vector<T> &v, T e_, function<T(T, T)> ope_,
		function<T(T, S)> update_): e(e_), ope(ope_), update(update_) {
		for (n = 1; n < (ll)v.size(); n *= 2);
		node.resize(2*n-1, e);
		REP(i, (ll)v.size()) { node[i+n-1] = v[i]; }//初期化
		DEP(i, n-1) { node[i] = ope(node[2*i+1], node[2*i+2]); }//構築
	}
	SegmentTree(ll size, T e_, function<T(T, T)> ope_,
		function<T(T, T)> update_): e(e_), ope(ope_), update(update_) {
		for (n = 1; n < size; n *= 2);
		node.resize(2*n-1, e);
	}
	T Range(ll a, ll b) { return Range(a, b, 0, 0, n); }
	void Update(ll i, S x){
		i += n-1;
		node[i] = update(node[i], x);
		while (i>0){
			i=(i-1)/2;
			node[i] = ope(node[2*i+1], node[2*i+2]);
		}
	}
private:
	T Range(ll a, ll b, ll k, ll l, ll r){ //注目ノードk=[l,r)
		if (r<=a || b<=l) return e; //完全に外
		if (a<=l && r<=b) return node[k];//完全に含まれる
		return ope(Range(a, b, k*2+1, l, (l+r)/2), Range(a, b, k*2+2, (l+r)/2, r));
	}
};



void solve()
{
	ll N;
	cin >> N;
	vll h = cinv(N);
	vll a = cinv(N);
	EACH(e, h) e--;

	SegmentTree<ll, ll> sgt(N, 0LL,
		[](ll x, ll y){ return max(x, y); },
		[](ll x, ll y){ return y; }
	);

	REP(i, N){
		ll val = sgt.Range(0, h[i]) + a[i];
		sgt.Update(h[i], val);
	}

	cout << sgt.Range(0,N) << '\n';

}

