namespace SOLVE {
	struct fenwick {
		int maxn;
		VLL A; // stores the fenwick tree

		void build(int n) {
			maxn = n;
			A.resize(maxn+1);
		}

		// update x with value v
		// this means i jump UP: all future when jumping down will see it
		void update(int x, ll v) {
			if (x > maxn) {
				return;
			}
			A[x] = max(A[x], v);
			int next = x + (x & -x);
			update(next, v);
		}

		ll query(int x) {
			if (x == 0) {
				return A[0];
			}
			int next = x - (x & -x);
			return max(query(next), A[x]);
		}
	};

