const int32_t MAX_N = 2e5;
const int32_t MAX_H = 2e5;

class SegmentTree {
private:
	void Update(int32_t node, int32_t low, int32_t high, int32_t qInd, int64_t qVal) {
		if(low > qInd || high < qInd) {
			return;
		}
		else if(low >= qInd && high <= qInd) {
			data[node] = qVal;
			return;
		}

		int32_t mid = (low + high) / 2;
		Update(2 * node, low, mid, qInd, qVal);
		Update(2 * node + 1, mid + 1, high, qInd, qVal);

		data[node] = std::max(data[2 * node], data[2 * node + 1]);
	}

	int64_t Query(int32_t node, int32_t low, int32_t high, int32_t qLow, int32_t qHigh) {
		if(low > qHigh || high < qLow) {
			return 0;
		}
		else if(low >= qLow && high <= qHigh) {
			return data[node];
		}

		int32_t mid = (low + high) / 2;

		return std::max(Query(2 * node, low, mid, qLow, qHigh), Query(2 * node + 1, mid + 1, high, qLow, qHigh));
	}

public:
	int32_t treeSize;
	int64_t data[4 * MAX_H + 5];

	void Init(int32_t pTreeSize) {
		treeSize = pTreeSize;
	}

	void Update(int32_t ind, int64_t val) {
		Update(1, 1, treeSize, ind, val);
	}

	int64_t Query(int32_t low, int32_t high) {
		return Query(1, 1, treeSize, low, high);
	}
};

