void build(vector<lli> &a, int v, int tl, int tr)
{
	if (tl == tr)
	{
		t[v] = make_data(a[tl]);
	}
	else
	{
		int tm = (tl + tr) / 2;
		build(a, v * 2, tl, tm);
		build(a, v * 2 + 1, tm + 1, tr);
		t[v] = combine(t[v * 2], t[v * 2 + 1]);
	}
}

void update(int v, int tl, int tr, int pos, lli new_val)
{
	if (tl == tr)
	{
		t[v] = make_data(new_val);
	}
	else
	{
		int tm = (tl + tr) / 2;
		if (pos <= tm)
			update(v * 2, tl, tm, pos, new_val);
		else
			update(v * 2 + 1, tm + 1, tr, pos, new_val);
		t[v] = combine(t[v * 2], t[v * 2 + 1]);
	}
}
data query(int v, int tl, int tr, int l, int r)
{
	if (l > r)
		return make_data(0);
	if (l == tl && r == tr)
		return t[v];
	int tm = (tl + tr) / 2;
	if (r <= tm)
	{
		return query(2 * v, tl, tm, l, r);
	}
	if (l > tm)
	{
		return query(2 * v + 1, tm + 1, tr, l, r);
	}

	return combine(query(v * 2, tl, tm, l, tm),
				   query(v * 2 + 1, tm + 1, tr, tm + 1, r));
}

