struct milk {
    int l, r, x, y, maxx, tek = 0;
    milk() {
        l = r = -1;
        x = 0, maxx = tek =  0;
        y = Flash_new_51() + 51;
    }

    milk (int l1, int r1, int mx, int tek1, int x1) {
        l = l1, r = r1, maxx = mx, tek = tek1, x = x1;
    }
};
int h[N], a[N], start = -1;
vector <milk> tree;

int kek (int v) {
    if (v == -1) return 0;
    return tree[v].maxx;
}

void upd (int v) {
    if (v == -1) return;
    int L = tree[v].l, R = tree[v].r;
    tree[v].maxx = max(tree[v].tek, max(kek(L), kek(R)));
}

pair <int, int> split (int v, int x) {
    if (v == -1) return {-1, -1};

    int tek = tree[v].x;
    if (tek <= x) {
        auto to = split(tree[v].r, x);
        tree[v].r = to.ff;
        upd(v);
        return {v, to.ss};
    }
    auto to = split(tree[v].l, x);
    tree[v].l = to.ss;
    upd(v);
    return {to.ff, v};
}

int merge (int L, int R) {
    if (L == -1) return R;
    if (R == -1) return L;
    if (tree[L].y > tree[R].y) {
        tree[L].r = merge(tree[L].r, R);
        upd(L);
        return L;
    }
    tree[R].l = merge(L, tree[R].l);
    upd(R);
    return R;
}


