ll right(ll p)
{
    return (p<<1) + 1;
}
void update(ll p, ll l, ll r, ll pos, ll val)
{
    if(l>pos||r<pos)
        return;
    if(l==r)
    {
        st[p] = val;
        return;
    }
    ll mid = (l+r)/2;
    update(left(p), l, mid, pos, val);
    update(right(p), mid+1, r, pos, val);
    st[p] = MAX2(st[left(p)], st[right(p)]);
    return;
}
ll query(ll p, ll l, ll r, ll i, ll j)
{
    if(i>r||j<l)
        return ninf;
    if(l>=i&&r<=j)
        return st[p];
    ll mid = (l+r)/2;
    ll lv = query(left(p), l, mid, i, j);
    ll rv = query(right(p), mid+1, r, i, j);
    ll rev = MAX2(lv, rv);
    return rev;
}
