using namespace std;

const int MX = 200 * 1000 + 7;

ll t[4 * MX];

void c(int v, int tl, int tr, int pos, ll val) {
    if (tl == tr) {
        t[v] = max(t[v], val);
    } else {
        int tm = (tl + tr) >> 1;
        if (pos <= tm) {
            c(v + v, tl, tm, pos, val);
        } else {
            c(v + v + 1, tm + 1, tr, pos, val);
        }
        t[v] = max(t[v + v], t[v + v + 1]);
    }
}

ll gt(int v, int tl, int tr, int l, int r) {
    if (r < tl || l > tr) {
        return 0;
    }
    if (tl >= l && tr <= r) {
        return t[v];
    }
    int tm = (tl + tr) >> 1;
    return max(gt(v + v, tl, tm, l, r), gt(v + v + 1, tm + 1, tr, l, r));
}

