class SegmentTree {
public:
	SegmentTree(){}//一応あるだけ

	//引数：頂点数
	SegmentTree(int size)
	{
		n = 1;
		while(n < size)n *= 2;
		dat.resize(n * 2, 0);
	}

	//k番目の値をaに変更
	void update(int k, ll a)
	{
		//葉の接点
		k += n - 1;
		dat[k] = a;
		//登りながら更新
		while(k > 0) {
			k = (k - 1) / 2;
			dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}

	// [a,b)の最大値を求める
	ll query(int a, int b) {
		return query_impl(a, b, 0, 0, n);
	}

private:
	int n;          //頂点数
	vector<ll> dat;//セグ木の本体

	ll query_impl(int a, int b, int k, int l, int r)
	{
		//　[a,b) と [l,r)　に交差無し
		if(r <= a || b <= l)return 0;
		//[a,b) が [l,r) を完全包含
		if(a <= l && r <= b)return dat[k];
		else {
			//左枝と右枝の最大値
			ll vl = query_impl(a, b, k * 2 + 1, l, (l + r) / 2);
			ll vr = query_impl(a, b, k * 2 + 2, (l + r) / 2, r);
			return max(vl, vr);
		}
	}
};
