#include <bits/stdc++.h>

using namespace std;

template<typename C>
class seg_tree {
  vector<C> tree;
  function<C(C, C)> key;
  C def;
  int p = 1;
public:
  seg_tree(int n, function<C(C, C)> _key, C _def) : key(_key), def(_def) {
    while (p < n) {
      p <<= 1;
    }
    tree.resize(p << 1, def);
  }

  seg_tree(const vector<C>& a, function<C(C, C)> _key, C _def) : key(_key), def(_def) {
    while (p < a.size()) {
      p <<= 1;
    }
    tree.resize(p << 1, def);
    for (int i = 0; i < a.size(); ++i) {
      tree[i ^ p] = a[i];
    }
    for (int i = p - 1; i; --i) {
      tree[i] = key(tree[i << 1], tree[i << 1 | 1]);
    }
  }

  C get(int l, int r) {
    C res = def;
    for (l ^= p, r ^= p; l <= r; l >>= 1, r >>= 1) {
      if (l & 1) {
        res = key(res, tree[l++]);
      }
      if ((r & 1) == 0) {
        res = key(res, tree[r--]);
      }
    }
    return res;
  }

  void update(int k, C x) {
    k ^= p;
    tree[k] += x;
    for (k >>= 1; k; k >>= 1) {
      tree[k] = key(tree[k << 1], tree[k << 1 | 1]);
    }
  }
};

