    else {
        int mid = (le + ri) / 2;
        if(pos <= mid)
            update(val, pos, node * 2, le, mid);
        else
            update(val, pos, node * 2 + 1, mid + 1, ri);
        aint[node] = max(aint[node * 2], aint[node * 2 + 1]);
    }
}

ll query(int from, int to, int node, int le, int ri) {
    if(from <= le && ri <= to)
        return aint[node];

