int query(vector<int> & tree,int l, int r)  
{  
    int res = -inf; 

    // loop to find the sum in the range 
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) 
    { 
        if (l&1)  
            res = max(res,tree[l++]); 

        if (r&1)  
            res = max(res,tree[--r]); 
    } 

    return res; 
} 


