ll RMQ(ll r){
    ll res = 0;
    ll i;
    for(i = 0;i*(w+1)<r;i++){
        res = max(res,bucket[i]);
    }
    for(ll j = i*w;j<=r;j++){
        res = max(res,dp[j]);
    }
    return res;
}
void update(ll id,ll val){
