#include <cstdio>

const int MaxN = 200000 + 5;

int N;
int H[MaxN], A[MaxN];

template <typename Typ>
inline Typ max(Typ x, Typ y) { return x > y ? x : y; }

struct FenwickTree {
  long long t[MaxN];

  inline int lowbit(int i) {
    return i & -i;
  }

  inline void update(int x, long long v) {
    for (int i = x; i <= N; i += lowbit(i))
      t[i] = max(t[i], v);
  }

  inline long long query(int x) {
    long long res = 0;
    for (int i = x; i > 0; i -= lowbit(i))
      res = max(res, t[i]);
    return res;
  }
};
FenwickTree T;

void init() {
  scanf("%d", &N);
  for (int i = 1; i <= N; ++i) scanf("%d", &H[i]);
  for (int j = 1; j <= N; ++j) scanf("%d", &A[j]);
}

void solve() {
  for (int i = 1; i <= N; ++i)
    T.update(H[i], T.query(H[i] - 1) + A[i]);
  printf("%lld\n", T.query(N));
}

int main() {
  init();
  solve();
  return 0;
}

