struct SegmentTree {
	std::vector<i64> seg;
	int sz = 1;

	SegmentTree(int n) {
		while(sz < n) sz <<= 1;
		seg.assign(sz * 2, 0);
	}
	void set(int k, i64 x) {
		k += sz;
		if(seg[k] >= x) return;
		seg[k] = x;

		while(k >>= 1) seg[k] = std::max(seg[2 * k + 0], seg[2 * k + 1]);
	}
	i64 get(int a, int b) {
		i64 L = 0, R = 0;
		for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
			if(a & 1) L = std::max(L, seg[a++]);
			if(b & 1) R = std::max(seg[--b], R);
		}
		return std::max(L, R);
	}
	i64 operator[](int k) {
		return seg[k + sz];
	}
};

