vector < long long > aib;

long long Query (int poz) {
  long long ans = 0;
  while (poz > 0) {
    ans = max (ans, aib[poz]);
    poz -= poz & (-poz);
  }
  return ans;
}

void Update (int poz, long long val) {
  while (poz < (int)aib.size()) {
    aib[poz] = max (aib[poz], val);
    poz += poz & (-poz);
  }
}

int main () {
  int N;
  read(N);
  vector < int > h(N), a(N);
  for (int i = 0; i < N; ++i)
    read(h[i]);
  for (int i = 0; i < N; ++i)
    read(a[i]);
  aib.resize(N + 1);
  vector < long long > dp(N + 1);
  for (int i = 0; i < N; ++i) {
    long long best = Query (h[i] + 1) + a[i];
    if (best > dp[h[i]]) {
      dp[h[i]] = best;
      Update (h[i] + 1, dp[h[i]]);
    }
  }
  long long ans = 0;
  for (int i = 0; i <= N; ++i)
    ans = max (ans, dp[i]);
  cout << ans;
}

