        if (start == end) {
            if (start == idx) {
                Seg[node] = val;
                return;
            }
        }
        int mid = start + (end - start) / 2;
        updateRange(2 * node, start, mid, idx, val);
        updateRange(2 * node + 1, mid + 1, end, idx, val);
        Seg[node] = max(Seg[2 * node], Seg[2 * node + 1]);
    }


