struct segtree{
    vector<ll> seg;
    segtree(ll n){
        seg.resize(4*n+4,0);
    }
    ll merge(ll a, ll b){
        return a+b;
    }
    ll get(ll pos,ll l,ll r,ll st,ll en){
        if(l>en || r<st || l>r){
            return 0;
        }
        if(st<=l && en>=r){
            return seg[pos];
        }
