const int SIZE = 2e5 + 7;
const int MAX = 1 << 18;

ll h[SIZE], a[SIZE], dp[SIZE];
ll tree[2*MAX];

void update(int p, ll v)
{
    p += MAX;
    tree[p] = max(tree[p], v);
    while(p >= 1)
    {
        p /= 2;
        tree[p] = max(tree[2*p], tree[2*p+1]);
    }
}

ll query(int a, int b)
{
    a += MAX; b += MAX;
    ll res = max(tree[a], tree[b]);
    while(a/2 != b/2)
    {
        if(a%2 == 0) res = max(res, tree[a+1]);
        if(b%2 == 1) res = max(res, tree[b-1]);
        a /= 2; b /= 2;
    }
    return res;
}

