#include <bits/stdc++.h>

#define ll long long

using namespace std;

const int N = (int)2e5 + 7;

int n;

struct seg {
	ll tree[4 * N];

	seg() {
		memset(tree, 0, sizeof tree);
	}

	void upd(int pos, ll val, int v = 1, int l = 1, int r = n) {
		if (l == r) {
			tree[v] = val;
			return ;
		}
		int mid = (l + r) >> 1;
		if (pos <= mid)
			upd(pos, val, v + v, l, mid);
		else
			upd(pos, val, v + v + 1, mid + 1, r);
		tree[v] = max(tree[v + v], tree[v + v + 1]);
	}

	ll get(int l, int r, int v = 1, int tl = 1, int tr = n) {
		if (tl > r || tr < l) return 0;
		if (l <= tl && tr <= r) return tree[v];
