void update(int node, int start, int end, int index, ll val) {
    if (start == end) {
        assert(start == index);
        tree[node] = max(tree[node], val);
        return;
    }
    int mid = (start + end) / 2;
    if (start <= index && index <= mid)
        update(node * 2 + 1, start, mid, index, val);
    else
        update(node * 2 + 2, mid + 1, end, index, val);
    tree[node] = max(tree[node * 2 + 1], tree[node * 2 + 2]);
}

ll query(int node, int start, int end, int l, int r) {
    if (start > r || end < l) return -inf;
    if (l <= start && end <= r) return tree[node];
    int mid = (start + end) /2;
    ll x = query(node * 2 + 1, start, mid, l, r),
       y = query(node * 2 + 2, mid + 1, end, l, r);
    return max(x, y);
}

