const ll M=2e5+5;
ll segtree[4*M],H[M],h[M],a[M];

void build(ll st,ll en,ll idx)
{
	if(st==en)
		segtree[idx]=H[st];
	else
	{
		ll md=(st+en)/2;
		build(st,md,2*idx+1);
		build(md+1,en,2*idx+2);
		segtree[idx]=max(segtree[2*idx+1],segtree[2*idx+2]);
	}
}

void update(ll st,ll en,ll idx,ll l,ll x)
{
	if(st==en)
	{
		H[l]=x;
		segtree[idx]=x;
	}
	else
	{
		ll md=(st+en)/2;
		if(st<=l && l<=md)
			update(st,md,2*idx+1,l,x);
		else
			update(md+1,en,2*idx+2,l,x);
		segtree[idx]=max(segtree[2*idx+1],segtree[2*idx+2]);
	}
}

ll query(ll st,ll en,ll idx,ll l,ll r)
{

	if(st>r || en<l)return 0;

	if(st>=l && en<=r)return segtree[idx];

	ll md=(st+en)/2;
	return max(query(st,md,2*idx+1,l,r),query(md+1,en,2*idx+2,l,r));
}


