node* build(ll L,ll R)
{
    node *n = new node();
    if(L==R)
    {
        //leaf
        return n;
    }
    ll mid = (L+R)/2;
    n->lch = build(L,mid);
    n->rch = build(mid+1,R);
    n->pull();
    return n;

}
void update(node* n,ll id,ll val,ll L,ll R)
{
    if(L==R)
    {
        n->s = max(n->s,val);
        return;
    }
    ll mid = (L+R)/2;
    if(id<=mid)update(n->lch,id,val,L,mid);
    else update(n->rch,id,val,mid+1,R);
    n->pull();
    return;
}
ll query(node* n,ll l,ll r,ll L,ll R)
{
    if(l>R||r<L)return 0;
    if(l<=L&&r>=R)return n->s;
    ll mid = (L+R)/2;

    return max(query(n->lch,l,r,L,mid),query(n->rch,l,r,mid+1,R));

}

