void Build(ll tree[], ll A[], int start, int end, int node){
	if(start == end){
		tree[node] = A[start];
		return;
	}
	int mid = (start+end)/2;
	Build(tree, A, start, mid, 2*node+1);
	Build(tree, A, mid+1, end, 2*node+2);
	tree[node] = max(tree[2*node+1], tree[2*node+2]);
}

ll max(ll x, ll y){
	return (x>y)?x:y;
}

ll Query(ll tree[], int start, int end, int node, int l, int r){
	if(r < start || end < l){return 0;}
	if(l <= start && end <= r){return tree[node];}
	int mid = (start+end)/2;
	ll p1 = Query(tree, start, mid, 2*node+1, l, r);
	ll p2 = Query(tree, mid+1, end, 2*node+2, l, r);
	return max(p1, p2);
}

void Update(ll tree[], ll A[], int start, int end, int node, int idx, ll val){
	if(start == end){
		A[start] = val;
		tree[node] = val;
		return;
	}

	int mid = (start+end)/2;
	if(idx <= mid){Update(tree, A, start, mid, 2*node+1, idx, val);}
	else{Update(tree, A, mid+1, end, 2*node+2, idx, val);}
	tree[node] = max(tree[2*node+1], tree[2*node+2]);
}

