// Min Query Segment tree

#define N 200005
ll h[N],v[N],dp[N];
ll lo[4*N+1], hi[4*N+1], mi[4*N+1], delta[4*N+1];
ll n;

void build(ll i,ll a,ll b)
{
    lo[i]=a;
    hi[i]=b;

    if(a==b)
        return;

    ll m=(a+b)/2;
    build(2*i,a,m);
    build(2*i+1,m+1,b);
}

void prop(ll i)
{
    delta[2*i]+=delta[i];
    delta[2*i+1]+=delta[i];
    delta[i]=0;
}

void update(ll i)
{
    mi[i]=max(mi[2*i]+delta[2*i],mi[2*i+1]+delta[2*i+1]);
}

void increment(ll i,ll a,ll b,ll val)
{
    if(b<lo[i]||hi[i]<a)
        return;
    if(a<=lo[i]&&hi[i]<=b)
    {
        delta[i]+=val;
        return;
    }

    prop(i);

    increment(2*i,a,b,val);
    increment(2*i+1,a,b,val);

    update(i);
}

ll query(ll i,ll a,ll b)
{   
