struct segment_tree {
  vector<int> node;
  int n;
  const function<int(int,int)> fn;
  const int initial;

  segment_tree(int n, function<int(int,int)> fn, int initial) : fn(fn), initial(initial) {
    int msb = 1LL << ((n==0) ? 0 : 64 - __builtin_clzll(n)-1);
    this->n = (n==msb) ? n : msb << 1;
    node.resize(2 * this->n - 1);
    fill(node.begin(), node.end(), initial);
  }

  inline int r_child(int v) { return v*2+2; }
  inline int l_child(int v) { return v*2+1; }
  inline int parent(int v) { return (v + (v%2)) / 2 - 1; }

  int query(int ql, int qr, int v=0, int l=0, int r=-1) {
    r = (r==-1) ? n-1 : r;
    if(ql<=l && r<=qr) return node[v];
    int ret = initial, mid=(l+r)/2;
    if(ql <= mid)   ret = fn(ret, query(ql, qr, l_child(v), l,     mid));
    if(qr >= mid+1) ret = fn(ret, query(ql, qr, r_child(v), mid+1, r  ));
    return ret;
  }

  void set_value(int index, int val) {
    int v = node.size()/2 + index;
    node[v] = val;
    while((v=parent(v)) != -1) node[v] = fn(node[r_child(v)], node[l_child(v)]);
  }

  void add_value(int index, int val) { set_value(index, node[node.size()/2 + index] + val); }
  int get_value(int index) { return node[node.size()/2 + index]; }
};


