int segtree[800005];
int left(int p) {return (p<<1);}
int right(int p) {return ((p<<1)+1);}
int rangemax(int p,int l,int r,int i,int j)
{
  if(i<=l && r<=j) return segtree[p];
  if(i>r || j<l) return 0;
  return max(rangemax(left(p),l,(l+r)/2,i,j),rangemax(right(p),(l+r)/2+1,r,i,j));
}
void update(int p,int l,int r,int index,int val)
{
  if(index>r||index<l) return;
  if(l==r && l==index) {segtree[p]=val;return;}
  update(left(p),l,(l+r)/2,index,val);
  update(right(p),(l+r)/2+1,r,index,val);
  segtree[p]=max(segtree[left(p)],segtree[right(p)]);
}
