{
	if (tl == tr)
	{
		T[v] = new_val;
	}
	else
	{
		ll tm = (tl + tr) / 2;
		if (pos <= tm)
			update(2 * v, tl, tm, pos, new_val);
		else
			update(2 * v + 1, tm + 1, tr, pos, new_val);
		T[v] = max(T[2 * v], T[2 * v + 1]);
	}
}
