template<class T, int MAX_N>class RMQ {
	const int N = 0, sqrtN = ceil(sqrt(MAX_N)); int B = 0;
	vector<T> A, Min; const T Init;

public:
	RMQ(int _N, T _init = 0) :N(_N), B((_N + sqrtN - 1) / sqrtN), Init(_init) {
		A.resize(sqrtN * B, Init);
		Min.resize(B, Init);
	}
	void update(int i, T x) {
		A[i] = x;
		int j = i / sqrtN, l = j * sqrtN, r = (j + 1) * sqrtN;
		Min[j] = *max_element(A.begin() + l, A.begin() + r);
	}
	//[s, t)の最大値
	T find(int s, int t) {
		T ret = Init;
		for (int i = 0; i < B; i++) {
			int l = i * sqrtN, r = (i + 1) * sqrtN;
			if (r <= s || t <= l) {
				continue;
			} else if (s <= l && r <= t) {
				ret = max(ret, Min[i]);
			} else {
				for (int j = max(s, l); j < min(t, r); j++) {
					ret = max(ret, A[j]);
				}
			}
		}
		return ret;
	}
};

