void update(int low, int high, int ind, ll val, int node){
	if(low == high){
		tree[node] = val;
		return;
	}
	int mid = (low + high) / 2;
	if(ind <= mid)
		update(low, mid, ind, val, 2 * node);
	else update(mid + 1, high, ind, val, 2 * node + 1);
	tree[node] = max(tree[2 * node], tree[2 * node + 1]);
}
ll query(int low, int high, int begin, int end, int node){
	if(low > end || high < begin || begin > end)
		return -1e18;
	if(low >= begin && high <= end)
		return tree[node];
	int mid = (low + high) / 2;
	return max(query(low, mid, begin, end, 2 * node), query(mid + 1, high, begin, end, 2 * node + 1));
}
