ll tree[4*MAXM];

void build(int root, int l, int r)
{
	if (l == r) {
		tree[root] = beuity[l];
		return ;
	}
	int mid = (l+r)/2;
	build(root*2, l, mid);
	build(root*2+1, mid+1, r);
	tree[root] = max(tree[root*2], tree[root*2+1]);	
}

void update(int root, int l, int r, int pos, ll val) 
{
	if (l>r or l>pos or r<pos)	return ;
	if (l == r) {
		tree[root] = val;
		return;
	}
	int mid = (l+r)>>1;
	update(2*root, l, mid, pos, val);
	update(2*root+1, mid+1, r, pos, val);
	tree[root] = max(tree[root*2], tree[root*2+1]);
}

ll query(int root, int l ,int r, int ql,int qr)
{
	if (l > r or l > qr or r < ql)	return 0LL;
	if (ql <= l and qr >= r)	return tree[root];
	int mid = (l+r)>>1;
	ll r1 = query(2*root, l, mid, ql, qr);
	ll r2 = query(2*root+1, mid+1, r, ql, qr);
	return max(r1, r2);
}

