int main(void) {
  cout << std::fixed << std::setprecision(10);
  cin.tie(0);
  std::ios::sync_with_stdio(false);

  int n;
  cin>>n;
  std::vector<int64_t> h(n),a(n);
  for(int i = 0; i < n; ++i){
    cin>>h[i];
  }
  for(int i = 0; i < n; ++i){
    cin>>a[i];
  }

  //in-line DP
  //dp[f][g]=花fまで考えて，現在抜いていない花の右端がgのときのmax
  //        =dp[f-1][g](g!=f)
  //        =max(h[i]<h[g]|dp[f-1][i]+a[g])(g==f)

  //->in-lineにできる
  //  ほしい情報: h[i]<h[g]を満たすようなdp[i]のmax
  //    ->セグ木にのせればできそう

  RMQTree rmq_tree(0,n+1);
  rmq_tree.Init(std::vector<int64_t>(n+1,0));
  int64_t dp[200000]={};
  dp[0]=a[0];
  rmq_tree.SetValue(h[0],a[0]);
  for(int f=1;f<n;f++){
    int64_t new_value=rmq_tree.GetResult(1,h[f]);
    new_value+=a[f];
    dp[f]=new_value;
    rmq_tree.SetValue(h[f],new_value);
  }

  int64_t result=0;
  for(int i=0;i<n;i++){
    result=std::max(result,dp[i]);
  }
  cout<<result<<endl;



  return 0;
}

