		ll height, value, idx;
		tie(height, idx, value) = val[i];

		TR(height);
		TR(value);
		TR(idx);

		if(stack.rbegin()->xx < idx){
			ll foo = stack.rbegin()->yy + value;
			stack[idx] = foo;
		} else {
			auto it = stack.lower_bound(idx);
			stack[idx] = prev(it)->yy + value;

			it = stack.upper_bound(idx);
			while(stack[idx] >= it->yy){
				stack.erase(it);
				it = stack.upper_bound(idx);
				if(it == stack.end())
