struct SegTree{
    int sz = 2;
    vector<long long> dat;
    SegTree(int n){
        while(n >= sz) sz *= 2;
        dat.assign(sz*2, 0);
    }
    void set(int x, long long n){
        int l = sz, r = x-1+sz;
        long long res = 0;
        while(l <= r){
            if(l&1) res = max(res, dat[l++]);
            if(r&1^1) res = max(res, dat[r--]);
            l /= 2; r /= 2;
        }
        dat[x += sz] = n + res;
        for(;x;x/=2) dat[x/2] = max(dat[x], dat[x^1]);
    }
};
