		dp[h[i]] = a[i] + seg.getmax(0,h[i]);//findmax( dp, h[i] );
		seg.update(h[i], dp[h[i]]);
	}

	ll res = 0;
	rep(i,n){
		res = max( res, dp[i] );
	}

	cout << res << endl;
	return 0;
}

