ll getsum(vector<ll>& bitree,int idx){
	ll sum = 0;
	while(idx > 0){
		sum += bitree[idx];
		idx -= (idx & (-idx));
	}
	return sum;
}

void update(vector<ll>& bitree,int idx,ll val){
	int n = bitree.size()-1;
	while(idx <= n){
		bitree[idx]+=val;
		idx += (idx & (-idx));
	}
}

