class SegTree{
    int tl,tr,sum;
    SegTree *left, *right;

    public:

    SegTree(int l, int r){
        sum = 0;
        tl = l;
        tr = r;
        left = nullptr;
        right = nullptr;
    }

    void makeChildren(){
        int tm = (tl+tr)/2;
        left = new SegTree(tl,tm);
        right = new SegTree(tm+1,tr);
    }

    void update(int pos, int val){
        sum = max(sum,val);
        if(tl == tr) return;
        if(left == nullptr) makeChildren();
        if(pos <= left->tr) left->update(pos,val);
        else right->update(pos,val);
    }

    int get(int l, int r){
        if(l > tr || r < tl) return 0;
        if(tl >= l && tr <= r) return sum;
        if(left == nullptr) return 0;
        return max(left->get(l,r),right->get(l,r));
    }
};

