template<typename T>
class segTree
{
public:
    int n;
    vector<T> st;

    segTree() {}
    segTree(int _n) {
        n = _n;
        st.resize(4*n);
    }
    segTree(vector<T> a) {
        n = a.size();
        st.resize(4*n);
        for(int i=0; i<n; i++) {
            update(i, a[i]);
        }
    }

    T combine(T a, T b)
    {
        return max(a, b);
    }

    // void build(int v, int tl, int tr)
    // {
    //     if(tl==tr) {
    //         st[v]=something;
    //         return;
    //     }

    //     int tm=(tl+tr)/2;
