		return t[index];
	int mid=(lb+rb)/2;
	if(rq<=mid)
		return query(index*2,lb,mid,lq,rq);
	else if(lq>mid)
		return query(index*2+1,mid+1,rb,lq,rq);
	else
		return max(query(index*2,lb,mid,lq,mid),query(index*2+1,mid+1,rb,mid+1,rq));
