{
	if(lb==rb&&lb==leaf_id)
	{
		t[index]=value;
		return;
	}
	int mid=(lb+rb)/2;
	if(leaf_id>mid)
	{
		t[index]=max(t[index],value);
		update(index*2+1,mid+1,rb,leaf_id,value);
	}
	else
	{
		t[index]=max(t[index],value);
		update(index*2,lb,mid,leaf_id,value);
	}
}
