	vector<long long> segtree(2 * S);
	function<void(int, long long)> update = [&](int pos, long long val) {
		pos += S;
		segtree[pos] = val;
		while (pos > 1) {
			pos >>= 1;
			segtree[pos] = max(segtree[pos * 2], segtree[pos * 2 + 1]);
		}
	};
	function<long long(int, int, int, int, int)> _rangemax = [&](int a, int b, int k, int l, int r) {
		if (a <= l && r <= b) return segtree[k];
		if (r <= a || b <= l) return (long long)(0);
		long long lres = _rangemax(a, b, k * 2, l, (l + r) >> 1);
		long long rres = _rangemax(a, b, k * 2 + 1, (l + r) >> 1, r);
		return max(lres, rres);
	};
	function<long long(int, int)> rangemax = [&](int a, int b) {
		return _rangemax(a, b, 1, 0, S);
	};
	for (int i = 0; i < N; ++i) {
		long long res = rangemax(0, ord[i]);
		update(ord[i], res + A[ord[i]]);
	}
	long long ans = rangemax(0, N);
	cout << ans << '\n';
	return 0;
}

