#include <bits/stdc++.h>
#define ll long long
#define pll pair <ll,ll>
#define Mid ((L+R)/2)
#define Left (2*Node)
#define Right (2*Node+1)

using namespace std;

const ll N = 200200;
const ll M = 4 * N;
const ll Inf = 1e18;

ll n;
pll h[N];
ll a[N];
ll Dp[N];
ll SegTree[M];

void Merge(ll Node)
{
    SegTree[Node] = max(SegTree[Left],SegTree[Right]);
}

void Build(ll Node = 1,ll L = 0,ll R = n)
{
    if(L == R)
    {
        SegTree[Node] = Dp[L];
        return ;
    }

    Build(Left,L,Mid);
    Build(Right,Mid+1,R);

    Merge(Node);
}

void Update(ll i,ll Node = 1,ll L = 0,ll R = n)
{
    if(i < L || R < i)  return ;
    if(i <= L && R <= i)
    {
        SegTree[Node] = Dp[i];
        return ;
    }

    Update(i,Left,L,Mid);
    Update(i,Right,Mid+1,R);

    Merge(Node);
}

ll Query(ll i,ll j,ll Node = 1,ll L = 0,ll R = n)
{
    if(j < L || R < i)      return -Inf;
    if(i <= L && R <= j)    return SegTree[Node];

    return max( Query(i,j,Left,L,Mid)
              , Query(i,j,Right,Mid+1,R) );
}

