    Dp[n] = 0;
    for(ll i = 0; i < n; ++i)   Dp[i] = -Inf;

    Build();

    for(ll i = n - 1; ~i; --i)
    {
        ll idx = h[i].second;

        Dp[idx] = a[idx] + Query(idx+1,n);

        Update(idx);
    }

    ll Ans = -Inf;

    for(ll i = 0; i < n; i++)   Ans = max(Ans,Dp[i]);

    cout << Ans;
}

