/*!* [fenwick] *!*/
/*+* フェニック木
     長さNの配列の部分和と更新をO(log N)で行う *+*/
template <typename T, typename F = function<T(T, T)>>
struct Fenwick {
    int N;
    vector<T> array;
    const F f;
    const T id;
    Fenwick() {}
    Fenwick(int len, const F f, const T &id) : N(len), f(f), id(id) {
        array.assign(N, id);
    }
    inline int LSB(int x) { return x & (-x); }
    void update(int i, T val) {
        for (; i < N; i += LSB(i + 1)) {
            array[i] = f(array[i], val);
        }
    }
    // sum of the elements [0:i]
    T sum(int i) {
        T s = id;
        for (i++; i; i -= LSB(i)) {
            s = f(s, array[i - 1]);
        }
        return s;
    }
};

struct Data {
    i64 h, a;
};

int main() {
    int N;
    cin >> N;
    vector<Data> data(N);
    for(Data &x : data) {
        cin >> x.h;
        x.h--;
    }
    for(Data &x : data) cin >> x.a;
    Fenwick<i64> fenwick(N + 1, [](i64 x, i64 y) -> i64 {return max(x, y);}, 0);
    for(int i = 0; i < N; i++) {
        i64 x = fenwick.sum(data[i].h);
        fenwick.update(data[i].h, x + data[i].a);
    }
    i64 ans = 0;
    for(int i = 0; i < N; i++) {
        ans = max(ans, fenwick.array[i]);
    }
    cout << ans << endl;
    return 0;
}

