int N, h[MN], a[MN];
ll t[3*MN];

void update(int id, int l, int r, int i, ll v) {
    if (l == r) {t[id] = v; return;}
    int m = (l + r) / 2;
    if (i <= m) update(id * 2, l, m, i, v);
    else update(id * 2 + 1, m + 1, r, i, v);
    t[id] = max(t[id * 2], t[id*2+1]);
}

ll query(int id, int l, int r, int ll, int rr) {
    if (l > r || l > rr || r < ll) return 0;
    if (l >= ll && r <= rr) return t[id];
    int m = (l+r)/2;
    if (rr<=m) return query(id*2,l,m,ll,rr);
    else if (ll>m) return query(id*2+1,m+1,r,ll,rr);
    else return max(query(id*2,l,m,ll,m),query(id*2+1,m+1,r,m+1,rr));
}

