   void update(int i, ll v){
       i += o;
       O[i] = v;
       while(i>1){
           O[i >> 1] = max(O[i], O[i^1]);
           i >>= 1;
       }
   }
   ll gmax(int s, int e){
       s += o; e += o;
       ll m = max(O[s],O[e]);
       while( s <= e){
            m = max({m, O[s], O[e]});
            ++s >>= 1;
            --e >>= 1;
       }
       return m;
   }
} I;

