    void update(int k,const E &x){
        k += n;
        dat[k] = g(dat[k], x);
        while(k>>=1)
            dat[k]=f(dat[(k<<1)|0],dat[(k<<1)|1]);    
    }
    T operator [](int k) const { return dat[k+n]; }
    // [a,b)
    T query(int a,int b) const {
        T vl=ti,vr=ti;
        for(int l=a+n,r=b+n;l<r;l>>=1,r>>=1) {
            if(l&1) vl=f(vl,dat[l++]);
            if(r&1) vr=f(dat[--r],vr);
        }
        return f(vl,vr);
    }
};
int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    using T = ll;  // type T　
    using E = ll;  // type E
    // 区間**
    auto f = [](T a, T b){ // return type T value
        return max(a,b);
    };
    auto g = [](T a, E b){ // return type T value
        return b;  // return b;
    };
    T ti = 0;  // identify element　入れる値
    SegmentTree<T,E,decltype(f),decltype(g)> seg(f,g,ti);
    int n;cin >> n;
    vector<ll> h(n),a(n);
    REP(i,n){
        cin >> h[i];
        h[i]--;
    }
    REP(i,n) cin >> a[i];
    vector<ll> b(n);
    seg.build(b);
    ll ans=0;
    REPR(i,n){
        ll tmp=seg.query(h[i],n);
        chmax(ans,tmp+a[i]);
        seg.update(h[i],tmp+a[i]);
    }
    cout << ans << endl;
}

