template<typename T>
class segTree{
public:
    int n;
    int SZ;
    vector<T> tree;
    T combine(T& a, T& b)
    {
        T res = max(a, b);
        return res;
    }
    segTree(vector<T> &arr) {
        n = arr.size();
        SZ = 2 * n;
        tree.resize(SZ+1-1, 0);
        for (int i = 0; i < n; ++i)
            tree[n + i] = arr[i];
        for (int i = n - 1; i > 0; --i){
            tree[i] = combine(tree[i << 1], tree[i << 1 | 1]);
        }
    }
    segTree(int N, T arr[])
    {
        n = N;
        SZ = 2 * n;
        tree. resize(SZ);
        for (int i = 0; i < n; ++ i)
            tree[n+i] = arr[i];
        for (int i = n - 1; i >= 0; -- i)
            tree[i] = combine(tree[i << 1], tree[i << i | 1]);
    }
    segTree() {}
    void update(int p, T value)
    {
        for (tree[p += n] = value; p > 1; p >>= 1)
            tree[p >> 1] = combine(tree[p], tree[p ^ 1]);
    }
    void update(int left, int right, T value)
    {
        for(left += n, right += n; left < right; left >>= 1, right >>= 1)
        {
            if (left & 1)
            {
                tree[left] = combine(tree[left], value);
                left ++;
            }
            if (right & 1)
            {
                -- right;
                tree[right] = combine(tree[right], value);
            }
        }
    }
    T query(int p)
    {
        T res = 0;
        for (p += n; p > 0; p >>= 1)
        {
            res = combine(res, tree[p]);
        }
        return res;
    }
    T query(int left, int right)
    {
        T res = 0;
        for (left += n, right += n; left < right; left >>= 1, right >>= 1)
        {
            if (left & 1)
                res = combine(res, tree[left ++]);
            if (right & 1)
                res = combine(res, tree[-- right]);
        }
        return res;
    }
    void display() {
        for(auto x: tree) cerr << x << ' '; cerr << "\n";
    }
};

