struct SegmentTree
{
  ll n;
  vector<Node> v;
  SegmentTree(ll size)
  {
    n=4*size+1;
    v.resize(n);
  }
  Node combine(Node v1, Node v2){
    Node ans;
    ans.an=max(v1.an, v2.an);
    return ans;
  }
  void build(ll ipos,ll fpos,ll pos=1)
  {
    if(ipos>fpos)
    return ;
    if(ipos==fpos){
      v[pos].an=dp[ipos];
    }
    else
    {
    ll mid=(ipos+fpos)/2;
    build(ipos,mid,pos*2);
    build(mid+1,fpos,pos*2+1);
    v[pos]=combine(v[2*pos], v[2*pos+1]);
    }
  }
  void update(ll index,ll val,ll ipos,ll fpos,ll pos=1)
  {
    if(ipos>fpos)
    return ;
    if(ipos==fpos)
    v[pos].an+=val;
    else
    {
      v[pos].an+=val;
      ll mid=(ipos+fpos)/2;
      if(mid>=index)
      update(index,val,ipos,mid,pos*2);
      else
      update(index,val,mid+1,fpos,pos*2+1);
      v[pos]=combine(v[2*pos], v[2*pos+1]);
    }
  }
  ll get_max(ll l,ll r,ll ipos,ll fpos, ll pos=1)
  {
    if(l>fpos or r<ipos or fpos<ipos)return 0;
    if(l<=ipos and r>=fpos) return v[pos].an;
    ll mid=(ipos+fpos)/2;
    return max(get_max(l, r, ipos, mid, pos*2), get_max(l, r, mid+1, fpos, pos*2+1));
  }
};
