const int MAXN=2e5+10;
struct {
	long long l,r,w,lazy;
}tree[MAXN<<2];
int n;
long long a[MAXN],b[MAXN];

void build(int l,int r,int tr){
	tree[tr].l=l;tree[tr].r=r;
	if(tree[tr].l==tree[tr].r) return;
	int mid=l+r>>1;
	build(l,mid,tr<<1);
	build(mid+1,r,tr<<1|1);
	return;
}

void down(int tr){
	tree[tr<<1].lazy=max(tree[tr<<1].lazy,tree[tr].lazy);
	tree[tr<<1].w=max(tree[tr<<1].w,tree[tr].lazy);
	tree[tr<<1|1].lazy=max(tree[tr<<1|1].lazy,tree[tr].lazy);
	tree[tr<<1|1].w=max(tree[tr<<1|1].w,tree[tr].lazy);
	tree[tr].lazy=0;
}

void change(int tr,int poi,long long num){
	if(tree[tr].l==poi&&tree[tr].r==poi){
		tree[tr].w=max(num,tree[tr].w);
		return;
	}
	if(tree[tr].lazy) down(tr);
	int mid=tree[tr].l+tree[tr].r>>1;
	if(poi<=mid)	change(tr<<1,poi,num);
	else			change(tr<<1|1,poi,num);
	tree[tr].w=max(tree[tr<<1].w,tree[tr<<1|1].w);
	return;
}

long long ask(int l,int r,int tr){
	if(l<=tree[tr].l&&tree[tr].r<=r) return tree[tr].w;
	if(tree[tr].lazy) down(tr);
	int mid=tree[tr].l+tree[tr].r>>1;
	long long ans=0;
	if(l<=mid) ans=ask(l,r,tr<<1);
	if(r> mid) ans=max(ask(l,r,tr<<1|1),ans);
	return ans;
}

