    dp[1]=v[1].bty;
    int ans = dp[1];
    meaningful[v[1].hi] = dp[1];

    for(int i=2;i<=n;i++)
    {
        dp[i] = v[i].bty;
         auto it = meaningful.lower_bound(v[i].hi+1);

         if(it!=meaningful.begin())
         {
             it--;
             dp[i]+= it->second;
         }
         meaningful[v[i].hi] = dp[i];

         auto it = meaningful.upper_bound(v[i].hi);

         while(it!=meaningful.end() && it->second<=dp[i])
         {
             auto temp = it;
             temp++;
             meaningful.erase(it);

             it = temp;
         }
        ans = max(ans,dp[i]);
    }

    return ans;
}

