#include <bits/stdc++.h>

using namespace std;

template <typename T>
class fenwick {
 public:
  vector <T> bit;
  vector <T> arr;
  int init = 0;
  int n;
  fenwick(int _n) : n(_n + 1) { 
    arr = vector <T>(n, init);
    bit = vector <T>(n, init);
  }

  fenwick(vector <int>& nums) : fenwick(nums.size()) {
    int len = nums.size();
    for (int i = 0; i < len; i++) {
      modify(i, nums[i]);
    }                      
  }

  void modify(int i, T val) { 
    int idx = i + 1;
    while (idx < n) {
      bit[idx] = max(bit[idx], val);
      idx = idx + (idx & -idx);
    }
    arr[i] = val;
  }

  T get(int i) {
    T res = init;
    int idx = i + 1;
    while (idx > 0) {
      res = max(res, bit[idx]);
      idx = idx - (idx & -idx);
    }
    return res;
  }
};

int main() {
