    cin >> b[i];
  } 
  vector <long long> dp(n + 1, 0);
  fenwick <long long> fn(n + 1);
  for (int i = 0; i < n; i++) {
    long long good = fn.get(h[i] - 1);
    long long dec = max(dp[h[i]], good + b[i]);
    if (dec > dp[h[i]]) {
      fn.modify(h[i], dec);
      dp[h[i]] = dec;
    } 
  }

  long long ans = 0;
  for (int i = 0; i <= n; i++) {
    ans = max(ans, dp[i]);
  } 
  cout << ans << endl;
  return 0;
}

