void update(int node,int b,int e,int i,ll val)
{
    if(i>e || b>i) return;
    if(b>=i && e<=i) {
        tree[node]+= val;
        return;
    }
    int left = node*2;
    int right = node*2+1;
    int mid = (b+e)/2;
    update(left,b,mid,i,val);
    update(right,mid+1,e,i,val);
    tree[node] = max(tree[left],tree[right]);
}

ll query(int node,int b,int e,int i,int j)
{
    if(i>e || b>j) return 0;
    if(b>=i && e<=j) return tree[node];
    int left = node*2;
    int right = node*2 + 1;
    int mid= (b+e)/2;
    int q1 = query(left,b,mid,i,j);
    int q2 = query(right,mid+1,e,i,j);
    return max(q1,q2);

}


