	vector<ll> a(n),h(n);
	for(int i=0;i<n;i++) cin>>h[i];
	for(int i=0;i<n;i++) cin>>a[i];
	for(int i=0;i<n;i++){
	    ll M  = seg.find(0,h[i]);
	    seg.update(h[i], M + a[i] ) ;
	}
	cout<<seg.find(0,n+1)<<endl;

	return 0;
}

