const int N = 2e5 + 5;

struct Seg {
  int n = 0;
  array<ll, N << 1> a{};

  Seg(int n) : n(n) {}

  void update(int idx, ll value) {
    idx += n;
    for (a[idx] = max(a[idx], value); idx > 1; idx >>= 1) {
      a[idx >> 1] = max(a[idx], a[idx ^ 1]);
    }
  }

  ll get(int l, int r) {
    ll res = 0;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1)
        res = max(res, a[l++]);
      if (r & 1)
        res = max(res, a[--r]);
    }
    return res;
  }
};

