        if (h[i] == 1) {
            t.upd(1, 1, n, h[i], dp[i]);
            continue;
        }
        dp[i] += 1LL * t.query(1, 1, n, 1, h[i] - 1);
        t.upd(1, 1, n, h[i], dp[i]);
