void build(ll* a,ll* tree,ll ti,ll l,ll r){
	if(l==r){
		tree[ti]=a[l];
		return;
	}
	ll mid = (l+r)/2;
	build(a,tree,2*ti,l,mid);
	build(a,tree,2*ti+1,mid+1,r);
	tree[ti] = max(tree[2*ti],tree[2*ti+1]);
}

ll query(ll* tree,ll ti,ll l,ll r,ll left,ll right){
	if(left==-1 || right==-1) return 0;
	if(l>=left && r<=right) return tree[ti];
	if(l>right || r<left) return 0;
	ll mid = (l+r)/2;
	ll first = query(tree,2*ti,l,mid,left,right);
	ll second = query(tree,2*ti+1,mid+1,r,left,right);
	return max(first,second);
}

void update(ll* tree,ll ti,ll index,ll l,ll r,ll x){
	if(l==r){
		tree[ti]=x;
		return;
	}
	ll mid = (l+r)/2;
	if(index<=mid){
		update(tree,2*ti,index,l,mid,x);
	}else{
		update(tree,2*ti+1,index,mid+1,r,x);
	}
	tree[ti] = max(tree[2*ti],tree[2*ti+1]);
	return;
}

