ll h[maxn], val[maxn], n;
ll tree[4*maxn];

void update(int ind, ll val, int li=0, int ri=n, int index=1) {
	if(li == ri) tree[index] = max(tree[index], val);
	else {
		int mid = (li + ri) / 2;

		if(ind <= mid) update(ind, val, li, mid, 2*index);
		else update(ind, val, mid+1, ri, 2*index+1);

		tree[index] = max(tree[2*index], tree[2*index+1]);
	}
}

ll query(int ql, int qr, int li=0, int ri=n, int index=1) {
	if(li > qr || ri < ql) return 0LL;
	else if(li >= ql && ri <= qr) return tree[index];
	else {
		int mid = (li + ri) / 2;
		return max(query(ql, qr, li, mid, 2*index), query(ql, qr, mid+1, ri, 2*index+1));
	}
}

