//don't need build

void push(int v) {
    if (tnew[v]!=0) {
        t[v] = max(t[v], tnew[v]);
        tnew[v*2] = max(tnew[v*2], tnew[v]);
        tnew[v*2+1] = max(tnew[v*2+1], tnew[v]);
        tnew[v] = 0;
    }
}

ll findmax(int v, int vl, int vr, int l, int r) {
    push(v);
    if (l>r || vl>vr || l>vr || r<vl) {
        return 0;
    }
    if (l<=vl && vr<=r) {
        return t[v];
    }
    int vm = (vl+vr)/2;
    ll x = findmax(v*2, vl, vm, l, r), y = findmax(v*2+1, vm+1, vr, l, r);
    return max(x,y);
}

void update(int v, int vl, int vr, int l, int r, ll x) {
    push(v);
    if (l>r || vl>vr || l>vr || r<vl) {
        return;
    }
    if (l<=vl && vr<=r) {
        tnew[v] = x;
        push(v);
        return;
    }
    int vm = (vl+vr)/2;
    update(v*2, vl, vm, l, r, x);
    update(v*2+1, vm+1, vr, l, r, x);
    t[v] = max(t[v*2], t[v*2+1]);
    return;
}

ll solve(int n) {
    dp[1] = a[1];
    update(1, 1, n, h[1], n, dp[1]);

    for (int i=2; i<=n; i++) {
        dp[i] = max(a[i], findmax(1, 1, n, 1, h[i]-1) + a[i]);
        update(1, 1, n, h[i], n, dp[i]);
    }
    for (int i=1; i<2*n; i++) push(i);
    return t[1];
}

ll slow(int n) {
    dp[1] = a[1];
    for (int i=2; i<=n; i++) {
        dp[i] = a[i];
        for (int j=1; j<i; j++) {
            if (h[j] < h[i]) {
                dp[i] = max(dp[i], dp[j] + a[i]);
            }
        }
    }
    ll ans=0;
    for (int i=1; i<=n; i++) ans = max(ans, dp[i]);
    return ans;
}

