struct ST
{
private:
    int n;
    vector<ll> node;

public:
    ST(vector<ll> v)
    {
        n = 1;
        while (n < v.size())
            n *= 2;
        node.resize(n * 2 - 1, 0);
        for (int i = 0; i < v.size(); i++)
            node[i + n - 1] = v[i];
        for (int i = n - 2; i >= 0; i--)
            node[i] = max(node[i * 2 + 1], node[i * 2 + 2]);
    }

    void add(int x, ll v)
    {
        x += n - 1;
        node[x] = v;
        while (x > 0)
        {
            x = (x - 1) / 2;
            node[x] = max(node[x * 2 + 1], node[x * 2 + 2]);
        }
    }

    ll get(int a, int b, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0)
            r = n;

        if (b <= l || r <= a)
            return 0;
        if (a <= l && r <= b)
            return node[k];

        ll vl = get(a, b, k * 2 + 1, l, (l + r) / 2);
        ll vr = get(a, b, k * 2 + 2, (l + r) / 2, r);
        return max(vl, vr);
    }
};

