ll getMax(int v, int tl, int tr, int l, int r) {
    if (tl > r || l > tr) return -INF;
    if (l <= tl && tr <= r) return t[v];
    int tm = (tl + tr) / 2;
    return max(getMax(2 * v, tl, tm, l, r), getMax(2 * v + 1, tm + 1, tr, l, r));
}

void setEl(int v, int tl, int tr, int pos, ll val) {
    if (tl == tr) {
        t[v] = val;
        return;
    }
    int tm = (tl + tr) / 2;
    if (pos <= tm)
        setEl(2 * v, tl, tm, pos, val);
    else
        setEl(2 * v + 1, tm + 1, tr, pos, val);
    t[v] = max(t[2 * v], t[2 * v + 1]);
}

