ll sgt[4*N],h[N],a[N];

void update(int l,int r,int pos,ll x,int i){
	if(l>pos||r<pos) return;
	if(l==r){
		sgt[i]=x;
		return;
	}
	int mid=(l+r)/2;
	update(l,mid,pos,x,2*i+1);
	update(mid+1,r,pos,x,2*i+2);
	sgt[i]=max(sgt[2*i+1],sgt[2*i+2]);
}

ll get(int l,int r,int a,int b,int i){
	if(l>b||r<a) return 0;
	if(l>=a&&r<=b) return sgt[i];
	int mid=(l+r)/2;
	return max( get(l,mid,a,b,2*i+1) , get(mid+1,r,a,b,2*i+2) );
}

