#define ll long long int

struct node{
    ll data;
    node* left;
    node* right;

    node(ll da){
        data = da;
    }
    node(){
        data=0;
    }
};

const ll N=2e5+6;
ll n,height[N],beauty[N],sol[N];
node* head;

ll query(node* head,int l,int r,int ql,int qr){
    if(head==nullptr)
        return 0;
    else if(ql<=(l) && qr>=(r))
        return head->data;
    ll mid=(l+r)/2;
    return max(query(head->left,l,mid,ql,qr),query(head->right,mid+1,r,ql,qr));
}

void update(node* head,int l,int r,ll size,ll ans){
    if(l==r){
        head->data = max(head->data,ans);
        return;
    }
    ll mid = (l+r)/2;
    if(size<=mid){
        if(head->left == nullptr)
            head->left = new node;
        update(head->left,l,mid,size,ans);
        head->data = max(head->data,head->left->data);
    }
    else{
        if(head->right == nullptr)
            head->right = new node;
        update(head->right,mid+1,r,size,ans);
        head->data = max(head->data,head->right->data);
    }
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);
    cin>>n;
    for(int i=1;i<=n;i++)
        cin>>height[i];
    for(int i=1;i<=n;i++)
        cin>>beauty[i];
    head = new node(0);
    for(int i=1;i<=n;i++){
        sol[i]=beauty[i]+query(head,0,N,0,height[i]-1);
        update(head,0,N,height[i],sol[i]);
    }
    ll ans=0;
    for(int i=1;i<=n;i++)
        ans=max(ans,sol[i]);
    cout<<ans<<"\n";

    return 0;
}

