int maximum(std::vector<int> &tree,int cur,int l,int r,int a,int b)
{
	//cout<<cur<<" "<<l<<" "<<r<<" "<<a<<" "<<b<<endl;
	if(l>r)
		return 0;
	if(l>b || r<a)
	{
		return 0;
	}
	if(l>=a && r<=b)
	{
		//cout<<tree[cur]<<endl;
		return tree[cur];
	}

	if(l==r)
		return tree[cur];

	int left=maximum(tree,2*cur,l,((l+r)/2),a,b);
	int right=maximum(tree,2*cur+1,((l+r)/2+1),r,a,b);
	return max(left,right);
} 
void update(vector<int> &tree,int cur,int l,int r,int x,int val)
{
	//cout<<"He";
	if(l>r)
		return;
	if(l==r)
	{
		tree[cur]=max(tree[cur],val);
		return;
	}
	int mid=((l+r)/2);
	if(mid>=x)
	{
		update(tree,cur*2,l,mid,x,val);

	}else{
		update(tree,cur*2+1,mid+1,r,x,val);
	}
	tree[cur]=max(tree[cur],max(tree[cur*2],tree[cur*2+1]));
} 
