class Main {

  static int INF = (int) 1e9 + 7;
  static List<List<Integer>> adj;

  public static void main(String[] args) {
    Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));

    int n = in.nextInt();
    int[] h = new int[n], a = new int[n];
    for (int i = 0; i < n; i++) {
      h[i] = in.nextInt();
    }
    for (int i = 0; i < n; i++) {
      a[i] = in.nextInt();
    }

    long[] dp = new long[n];
    dp[0] = a[0];
    long res = 0;
    for (int i = 1; i < n; i++) {
      long prevMax = 0;
      for (int j = 0; j < i; j++) {
        if (h[j] < h[i]) {prevMax = Math.max(prevMax, dp[j]);}
      }
      dp[i] = prevMax + a[i];
      res = Math.max(res, dp[i]);
    }


    System.out.println(res);
  }

  static int[] dfs(int cur, int parent) {

    // res[0]: counts when cur is painted black
    // res[1]: counts when cur is painted white
    int[] res = new int[2]; 
    Arrays.fill(res, 1);

    for (int next : adj.get(cur)) {
      if (next != parent) {
        int[] child = dfs(next, cur);
        res[0] = mul(res[0], child[1]);
        res[1] = mul(res[1], add(child[0], child[1]));
      }
    }

    return res;



    //System.out.println(cur);
  }

  static void add(int[] a, int i, int j) {
    a[i] += a[j];
    if (a[i] >= INF) {a[i] -= INF;}
  }

  static int add(int a, int b) {
    a = a + b;
    if (a >= INF) {a -= INF;}
    return a;
  }

  static int mul(int a, int b) {
    long res = a * b;

    return (int) (res % INF);
  }

  static int countSetBit(int a) {
    int count = 0; 
    while (a > 0) {
      count += (a & 1);
      a = a >> 1;
    }
    return count;
  }


}

#include <bits/stdc++.h>
using namespace std;

int N, height[200004], points[200004], dp[200004];

int solve(int i) {
	if (i>=N) {
		return 0;
	}

	if (dp[i] != -1) {
		return dp[i];
	}

	for(int k=i+1;k<N;k++) {
		int X = solve(k);
		if (height[k] > height[i]) {
			dp[i] = max(dp[i], points[i] + X);
		} else {
			dp[i] = max(dp[i], X);
		}
	}

	return dp[i];
}

int main() {
	cin>>N;
	for(int i=0;i<N;i++) {
		cin>>height[i];
	}
	for(int i=0;i<N;i++) {
		cin>>points[i];
	}

	memset(dp, -1, sizeof(dp));
	dp[N-1] = points[N-1];

	cout<<solve(0);

	return 0;
}

#include<iostream>
#include<vector>

struct segment_tree_max{
  int n;
  std::vector<int64_t> data;
  int64_t identity;

  int64_t max(int64_t a,int64_t b){return a<b?b:a;}

  segment_tree_max(){}
  segment_tree_max(int sz,int64_t id){
    n = 1;
    while(n<sz)n*=2;
    identity = id;
    data.resize(2*n,identity);
  }
  void set(int i,int64_t val){
    i += n;
    data[i] = val;
    i /= 2;
    while(i){
      data[i] = max(data[2*i],data[2*i+1]);
      i /= 2;
    }
  }
  int64_t get_max(int l,int r){
    l += n, r += n;
    int64_t res = identity;
    while(l<r){
      if(l&1) res = max(res,data[l++]);
      if(r&1) res = max(res,data[--r]);
      l /= 2, r /= 2;
    }
    return res;
  }
  int64_t operator[](int k)const{
    return data[k+n];
  }
};

int main(){

  int n;
  std::cin>>n;
  std::vector<int64_t> h(n),a(n);
  for(auto& hi:h)std::cin>>hi;
  for(auto& ai:a)std::cin>>ai;

/*
  dp[i][j] :=  i 番目まで見て、高さが j のときの美しさの最大値
  初期値は全部 0, 更新は
  for i = 1..n:
    dp[i] = dp[i-1]
    dp[i][hi] = max(dp[i-1][0..hi]) + ai
  i 番目で更新されるのは dp[i][hi] だけなので時系列の i は不必要とわかる
  dp[k] := 高さ k の時の美しさの最大値
  for i = 1..n:
    dp[hi] = max(dp[0..hi]) + ai
  max(dp[0..hi]) を愚直に求めると全体で O(NH) かかる(H = h_i_max)
  h_i_max <= N なので O(N^2)
  ここで segment tree を使うと max(dp[0..hi]) を高速に求められ、
  O(NlogH) = O(NlogN) で解くことが出来る
*/

  segment_tree_max dp(n+1,0);

  for(int i=0;i<n;++i){
    auto& hi = h[i];
    auto& ai = a[i];
    int64_t tmp = dp.get_max(0,hi);
    dp.set(hi,tmp+ai);
  }

  int64_t ans = dp.get_max(0,n+1);
  std::cout<<ans<<std::endl;

}

