class RMQ{
    unsigned int N;
    std::vector<unsigned long long int> data;
public:
    RMQ(const unsigned int n){
        N = 1; while(N < n) N <<= 1;
        data.assign(N << 1, 0);
    }
    unsigned long long int getMax(unsigned int l, unsigned int r){
        unsigned long long int res = 0;
        l += N; r += N;
        while(l < r){
            if(l & 1) chmax(res, data[l++]);
            if(r & 1) chmax(res, data[--r]);
            l >>= 1; r >>= 1;
        }
        return res;
    }
    void assign(unsigned int idx, const unsigned long long int val){
        data[idx += N] = val;
        while(idx >>= 1) data[idx] = std::max(data[idx << 1], data[(idx << 1) | 1]);
    }

};
