void update(int v,int tl,int tr,int pos,int jany)
{
  if(tl == tr)
  {
    t[v] = t[v] + jany;
  }
  else
  {
    int mid = (tl + tr)/2;
    if(pos <= mid)
    {
      update(v + v,tl,mid,pos,jany);
    }
    else
    {
      update(v+v+1,mid+1,tr,pos,jany);
    }
    t[v] = max(t[v+v],t[v+v+1]);
  }
}
int get(int v,int tl,int tr,int l,int r)
