ll h[200005],a[200005],dp[200005],tree[800005];

void build(ll node, ll s,ll e){
  if(s==e){
    tree[node]=dp[s];
  }else{
    ll mid=(s+e)/2;
    build(2*node,s,mid);
    build(2*node+1,mid+1,e);
    tree[node]=max(tree[2*node],tree[2*node+1]);
  }
}

void update(ll node,ll index,ll s,ll e,ll val){
  if(s==e){
    tree[node]=val;
    dp[index]=val;
  }else{
    ll mid=(s+e)/2;
     if(index<=mid) update(2*node,index,s,mid,val);
     else update(2*node+1,index,mid+1,e,val);
     tree[node]=max(tree[2*node],tree[2*node+1]);
  }
}

ll query(ll node,ll l,ll r,ll s,ll e){
  if(r<s || l>e) return 0;
  else if(l<=s && e<=r) return tree[node];
  else {
    ll mid=(s+e)/2;
    return max(query(2*node,l,r,s,mid),query(2*node+1,l,r,mid+1,e));
  }
}


