	pair<int,int> parent,lson,rson;
};

map<pair<int,int>,Tree> tree;

void build(int l,int r,pair<int,int> parent)
{
	if(l==r)
	{
		tree[make_pair(l,r)].data=0;
		tree[make_pair(l,r)].parent=parent;
		tree[make_pair(l,r)].lson=tree[make_pair(l,r)].rson=make_pair(-1,-1);
		return;
	}
	tree[make_pair(l,r)].data=0;
	tree[make_pair(l,r)].parent=parent;
	int m=(l+r)/2;
	tree[make_pair(l,r)].lson=make_pair(l,m);
	tree[make_pair(l,r)].rson=make_pair(m+1,r);
	build(l,m,make_pair(l,r));
	build(m+1,r,make_pair(l,r));
}

void update(int l,int r,ll x)
{
	tree[make_pair(l,r)].data=x;
	pair<int,int> tmp=tree[make_pair(l,r)].parent;
	if(tmp==make_pair(-1,-1))
	{
		return;
	}
	update(tmp.first,tmp.second,max(tree[tmp].data,x));
}

int check(pair<int,int> x,int ql,int qr)
{
	int l=x.first,r=x.second;
	if(qr<l||r<ql) return 0;
	if(ql<=l&&r<=qr) return tree[make_pair(l,r)].data;
	pair<int,int> lson=tree[x].lson,rson=tree[x].rson;
	//int m=(l+r)/2;
	return max(check(lson,ql,qr),check(rson,ql,qr));
}

