    // 短い順番に、データ構造を利用して値を更新する
    for(int i = 0; i < N; i++){
        ll max_v = rmq.query(0, ha[i].first);
        if(max_v == LONG_LONG_MIN){
            rmq.update(ha[i].first, ha[i].second);
        }
        else{
            rmq.update(ha[i].first, ha[i].second + max_v);
        }
    }
    ll ans = -1;
    for(int i = 0; i < N; i++)
        ans = max(ans, rmq.query(i, i + 1));

    cout << ans << endl;

