    auto merge = [](ll a, ll b) {
        return max(a, b);
    };
    SegmentTree<ll> tree(N + 1, merge, 0);
    vector<ll> dp(N, 0);
    for (int i = 0; i < N; i++) {
        ll before = tree.query(0, input[i].first);
        dp[i] = before + input[i].second;
        tree.update(input[i].first, dp[i]);
    }
    ll ans = 0;
    for (int i = 0; i < N; i++) {
        ans = max(ans, dp[i]);
    }
    cout << ans << endl;
}

