const int d = 1 << 19;
vector<ll> t(d << 1);

void add(int i, ll x) {
    i += d;
    t[i] = x;
    for (i >>= 1; i > 0; i >>= 1) {
        t[i] = max(t[i << 1], t[i << 1 | 1]);
    }
}

ll get_max(int u, int l, int r, int a, int b) {
    if (r < a || b < l) return 0;
    if (a <= l && r <= b) return t[u];

    return max(get_max(u << 1, l, (l + r) / 2, a, b),
               get_max(u << 1 | 1, (l + r) / 2 + 1, r, a, b));
}

ll get_max(int l, int r) {
    return get_max(1, d, 2 * d - 1, l + d, r + d);
}

