class BIT {
    vector<ll> bit;
    int n;
    void validate(int idx) const {
        if (idx >= n || idx < 0) {
            cerr << "Index out of range in BIT" << endl;
            assert(false);
        }
    }
public:
    BIT(int _n, ll init = 0) {
        this->n = _n;
        bit.resize(n + 1);
        FOR(i, 0, n)
        {
            update(i, init);
        }
    }
    template<typename T>
    BIT(const vector<T>& arr) : BIT(arr.size()) {
        n = arr.size();
        FOR(i, 0, n)
        {
            update(i, arr[i]);
        }
    }
    /// one-indexed
    ll pref_sum(int len) const {
        validate((len > 0) ? len - 1 : 0);
        ll val = 0;
        while (len > 0) {
            val = max(val, bit[len]);
            len -= (len & -len);
        }
        return val;
    }
    /// zero-indexed
    void update(int idx, ll delta) {
        validate(idx);
        idx++;
        while (idx <= n)
        {
            bit[idx] = max(bit[idx], delta);
            idx += (idx & -idx);
        }
    }
    int size() const {
        return bit.size();
    }
};
inline ostream& operator << (ostream& out, const BIT& bit) {
    vector<ll> vals;
    for (int i = 1; i < bit.size(); ++i) {
        vals.push_back(bit.pref_sum(i) - bit.pref_sum(i - 1));
    }
    return out << vals;
}


