void update(ll node,ll l,ll r,ll id,ll val)
{
	if(l == r)
	{
		tr[node]=max(tr[node],val);
		return;
	}
	ll mid=(l+r)/2;
	if(id<=mid)
		update(2*node,l,mid,id,val);
	else
		update(2*node+1,mid+1,r,id,val);
	tr[node]=max(tr[2*node],tr[2*node+1]);
}
ll query(ll node,ll l,ll r,ll ql,ll qr)
{
	if(ql>r || qr<l)
		return -1;
	if(l>=ql && r<=qr)
		return tr[node];
	ll mid=(l+r)/2;
	return max(query(2*node,l,mid,ql,qr),query(2*node+1,mid+1,r,ql,qr));
}
