int get(int v,int tl,int tr,int l,int r){

    if(tl <= l && r <= tr)return t[v];
    int mid = (l+r)/2;
    return max(((tl <= mid) ? get(2*v,tl,tr,l,mid) : 0),((tr > mid) ? get(2*v+1,tl,tr,mid+1,r) : 0));
}

