using namespace std;

vector<long long> seg;

long long query(int ql, int qr, int lb, int rb, int id) {
  if (qr <= lb || rb <= ql) return 0;
  if (ql <= lb && rb <= qr) return seg[id];
  int m = (lb + rb) / 2;
  return max(query(ql, qr, lb, m, 2 * id), query(ql, qr, m, rb, 2 * id + 1));
}

void modify(int i, long long x, int lb, int rb, int id) {
  if (i < lb || rb <= i) return;
  if (rb - lb == 1) {
    seg[id] = x;
    return;
  }
  int m = (lb + rb) / 2;
  modify(i, x, lb, m, 2 * id);
  modify(i, x, m, rb, 2 * id + 1);
  seg[id] = max(seg[2 * id], seg[2 * id + 1]);
}

int main() {
  ios_base::sync_with_stdio(false);
