  for (int i = 0; i < n; i++) cin >> a[i];

  vector<long long> dp(n);
  for (int i = 0; i < n; i++) {
    dp[i] = a[i] + query(1, h[i], 1, n + 1, 1);
    modify(h[i], dp[i], 1, n + 1, 1);
  }
  cout << query(1, n + 1, 1, n + 1, 1) << '\n';
  return 0;
}

