using namespace std;

struct flower
{
    ll hi;
    ll bty;
};

ll solve(vector<flower>& v,int n)
{
    vector<ll> dp(n);
    map<ll,ll> m;
    dp[0]=v[0].bty;
    m[v[0].hi]=dp[0];
    ll ans=dp[0];
    for(int i=1;i<n;i++)
    {
        dp[i]=v[i].bty;
        auto it=m.lower_bound(v[i].hi+1);
        if(it!=m.begin())
        {
            it--;
            dp[i]+=it->second;
        }
        m[v[i].hi]=dp[i];
        it=m.upper_bound(v[i].hi);
        while(it!=m.end()&&it->second<=dp[i])
        {
            auto temp =it;
            temp++;
            m.erase(it);
            it=temp;
        }
        ans=max(ans,dp[i]);
    }
    return ans;
}
int main()
{
    int n;
    cin>>n;
    vector<flower> v(n);
    for(int i=0;i<n;i++)
        cin>>v[i].hi;
    for(int i=0;i<n;i++)
        cin>>v[i].bty;
    cout<<solve(v,n);
    return 0;
}

