struct tree{
	vi t;
	int n;
	void init(int _n) {
		n = _n;
		t.resize(4 * n);
	}
	void update(int v, int l, int r, int pos, int val) {
		if(l == r - 1)
			t[v] = val;
		else {
			int m = (l + r) / 2;
			if(pos < m)
				update(2 * v, l, m, pos, val);
			else
				update(2 * v + 1, m, r, pos, val);
			t[v] = max(t[2 * v], t[2 * v + 1]);
		}
	}
	void update(int pos, int val) {
		update(1, 0, n, pos, val);
	}
	int get(int v, int l, int r, int vl, int vr) {
		if(l >= vr || vl >= r)
			return 0;
		if(l >= vl && r <= vr)
			return t[v];
		int m = (l + r) / 2;
		return max(get(2 * v, l, m, vl, vr), get(2 * v + 1, m, r, vl, vr));
	}
	int get(int vl, int vr) {
		return get(1, 0, n, vl, vr);
	}
} T;
