int tree[N << 2];
struct seg_tree {
    int combine(int x, int y)  {
        return max(x, y);
    }
    int query(int l, int r, int ql, int qr, int node) {
        if (l > r) return 0;

        if (qr < l || r < ql)
            return 0;
        if (ql <= l and r <= qr) {
            return tree[node];
        }
        int mid = l + r >> 1, lc = node + node, rc = 1 + lc;
        return combine(query(l, mid, ql, qr, lc), query(mid + 1, r, ql, qr, rc));
    }
    void update(int l, int r, int pos, int val, int node) {
        if (pos < l || r < pos)
            return;
        if (l == r and l == pos) {
            tree[node] = val;
            return;
        }
        int mid = l + r >> 1, lc = node + node, rc = 1 + lc;
        update(l, mid, pos, val, lc);
        update(mid + 1, r, pos, val, rc);
        tree[node] = combine(tree[lc], tree[rc]);
    }
};

const int maxn = 2e5 + 4;
int dp[maxn];

void solve() {
    int n;
    cin >> n;
    seg_tree ins;
    vector<int> a(n + 1), b(n + 1);
    rep(i,1,n) cin >> a[i];
    rep(i,1,n) cin >> b[i];
    for (int i = 1; i <= n; ++i) {
        int x = a[i];
        dp[x] = b[i];
        int q = ins.query(1, n, 1, x - 1, 1);
        dp[x] = max(dp[x], dp[x] + q);
        ins.update(1, n, x, dp[x], 1);
    }
    cout << *max_element(dp + 1, dp + 1 + n) << '\n';
}

