ll calc(vector<int> groups, int cost)
{
    if (groups.size() < 3)
    {
        return INF;
    }
    int result = INF;
    sort(groups.begin(), groups.end());
    for (int i = 1; i < groups.size(); i++)
    {
        int med = abs(groups[i] - B);
        int left = INF;
        int right = INF;
        for (int l = 0; l < i; l++)
        {
            left = min(left, abs(groups[l] - C));
        }
        for (int r = i + 1; r < N; r++)
        {
            right = min(right, abs(groups[r] - A));
        }
        result = min(result, cost + med + left + right);
    }
    return result;
}
