ll stree[1000000],a[200000];

void update(ll left,ll right,ll node,ll val,ll pos)
{
    if(left==right) {
        a[pos]=val;
        stree[node]=val;
        return;
    }
    ll mid=(left+right)/2;
    if(left<=pos && pos<=mid)
        update(left,mid,2*node+1,val,pos);
    else
        update(mid+1,right,2*node+2,val,pos);
    stree[node]=max(stree[2*node+1],stree[2*node+2]);
}

ll query(ll left,ll right,ll node,ll st,ll end)
{
    if(right<st||left>end)
        return 0;
    if(left>=st&&end>=right)
        return stree[node];
    ll mid=(left+right)/2;
    return stree[node]=max(query(left,mid,2*node+1,st,end),query(mid+1,right,2*node+2,st,end));
}


