class SegTree {
    ll n;
    vll dat;

    // change if min
    const ll DEF = 0;

    ll _query(ll a, ll b, ll k, ll l, ll r) {
        if (r <= a || b <= l) return DEF;
        if (a <= l && r <= b) return dat[k];

        ll vl = _query(a, b, k * 2 + 1, l, (l + r) / 2);
        ll vr = _query(a, b, k * 2 + 2, (l + r) / 2, r);
        return change(vl, vr);
    }

public:

    SegTree(ll _N) {
        n = 1;
        while (n < _N) n *= 2;
        dat.resize(n * 2 - 1);
        REP(i, n * 2 - 1) dat[i] = DEF;
    };

    // change if min
    inline ll change(ll a, ll b) {
        return max(a, b);
    }

    void update(ll k, ll a) {
        k += n - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = change(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    ll query(ll a, ll b) {
        return _query(a, b, 0, 0, n);
    }
};


