struct flower
{
    ll hi;
    ll bty;
};

ll solve(vector<flower>& v,int n)
{
    vector<ll> dp(n+1);
    map<ll,ll> m;
    dp[1]=v[1].bty;
    m[v[1].hi]=dp[1];
    ll ans=dp[1];
    for(int i=2;i<=n;i++)
    {
        dp[i]=v[i].bty;
        auto it=m.lower_bound(v[i].hi+1);
        if(it!=m.begin())
        {
            it--;
            dp[i]+=it->second;
        }
        m[v[i].hi]=dp[i];
        it=m.upper_bound(v[i].hi);
        while(it!=m.end()&&it->second<=dp[i])
        {
            auto temp =it;
            temp++;
            m.erase(it);
            it=temp;
        }
        ans=max(ans,dp[i]);
    }
    return ans;
}
