struct Node {
	ll l, r, val, maxx;
};

struct Seg {
private:
	int N;
	vector<Node> tree;

public:
	Seg (int N) : N(N), tree(N << 2) { }

	inline void Push_Up (ll idx) {
		tree[idx].val = max(tree[idx << 1].val, tree[idx << 1 | 1].val);
	}

	inline void Update (ll idx, ll l, ll r, ll pos, ll val) {
		if (l < pos || pos > r) return;
		if (l == r) {
			tree[idx].val = val;
			return;
		}
		ll mid = (l + r) >> 1;
		if (pos <= mid) Update(idx << 1, l, mid, pos, val);
		else Update(idx << 1 | 1, mid + 1, r, pos, val);
		Push_Up(idx);
	}

	inline ll Query (ll idx, ll l, ll r, ll l1, ll r1) {
		if (l1 > r || r1 < l) return 0LL;
		if (l1 >= l && r1 <= r) return tree[idx].val;
		ll mid = (l1 + r1) >> 1;
		return max(Query(idx << 1, l, r, l1, mid), Query(idx << 1 | 1, l, r, mid + 1, r1));
	}
};

