using lint = long long;

struct RMQ{
  static const lint MAX_N = 3e5;
  lint n,dat[2 * MAX_N-1];
  RMQ(){}
  RMQ(lint n_){init(n_);}
  void init(lint n_){
    n = 1;
    while(n < n_) n *= 2;
    for(int i = 0; i < 2 * n-1; i++) dat[i] = 0;
  }
  void update(lint k, lint a){
    k += n-1;
    dat[k] = a;
    while(k > 0){
      k = (k - 1) / 2;
      dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }
  lint query(lint a, lint b, lint k, lint l, lint r){
    if(r <= a || b <= l) return 0;
    if(a <= l && r <= b) return dat[k];
    else{
      lint vl = query(a, b,k * 2 + 1, l, (l + r) / 2);
      lint vr=query(a, b, k * 2 + 2,(l + r) / 2, r);
      return max(vl, vr);
    }
  }
  lint query(lint a,lint b){
    return query(a, b, 0, 0, n);
  }
};

