#define mid ((l + r) >> 1)
#define ls k << 1, l, mid
#define rs k << 1 | 1, mid + 1, r

struct Segmenttree {
    ll data;
} t[MAXN << 2];

void pushup(int k) { t[k].data = max(t[k << 1].data, t[k << 1 | 1].data); }
void modify(int k, int l, int r, int pos, ll val) {
    if (l == r) { t[k].data = val; return ; }
    if (pos <= mid) modify(ls, pos, val);
    else modify(rs, pos, val);
    pushup(k);
}
ll query(int k, int l, int r, int ql, int qr) {
    if (qr < ql) return 0;
    //printf("%d %d\n", l, r);
    if (ql <= l && r <= qr) { return t[k].data; }
    ll res = 0;
    if (ql <= mid) res = max(res, query(ls, ql, qr));
    if (qr > mid) res = max(res, query(rs, ql, qr));
    return res;
}

