class BIT{
private:
  int n;
  VL bit;
public:
  BIT(int n_){
    n = n_;
    bit.assign(n+1, 0);
  }

  // return bit[0,i)
  LL max(int i){
    LL s = 0;
    while(i > 0){
      maxi(s, bit[i]);
      i -= i & -i;
    }
    return s;
  }

  void add(int i, LL x){
    ++i;
    while(i <= n){
      maxi(bit[i], x);
      i += i & -i;
    }
  }
};


