struct node
{
    int l, r;
    long long val;
    node *lnode, *rnode;

    node(int L, int R)
    {
        l = L;
        r = R;
        val = 0;

        if (r - l != 1)
        {
            lnode = new node(l, l + r >> 1);
            rnode = new node(l + r >> 1, r);
        }
    }

    long long query(int L, int R)
    {
        if (L >= r || l >= R) return 0;
        if (L <= l && r <= R) return val;

        return max(lnode->query(L, R), rnode->query(L, R));
    }

    void update(int i, long long v)
    {
        if (i >= r || l >= i + 1) return;
        if (r - l == 1) 
        {
            val = v;
            return;
        }

        lnode->update(i, v);
        rnode->update(i, v);
        val = max(lnode->val, rnode->val);
    }
};

