class SegmentTree
{
    public:
    LL aint[4 * NMAX + 5];
    int pos, sti, dri;
    LL ans, val;

    void update(int nod, int st, int dr)
    {
        if(st == dr)
        {
            aint[nod] = max(aint[nod], val);
            return;
        }

        int mij = st + (dr - st) / 2;
        if(pos <= mij)  update(nod * 2, st, mij);
        else    update(nod * 2 + 1, mij + 1, dr);
        aint[nod] = max(aint[nod * 2], aint[nod * 2 + 1]);
    }

    LL query(int nod, int st, int dr)
    {
        if(sti <= st && dr <= dri)
        {
            ans = max(ans, aint[nod]);
            return 0;
        }
        int mij = st + (dr - st) / 2;
        if(sti <= mij)  query(nod * 2, st, mij);
        if(mij < dri)    query(nod * 2 + 1, mij + 1, dr);
        return 0;
    }

    void update(int _pos, LL _val)
    {
        pos = _pos, val = _val;
        update(1, 1, N);
    }

    LL query(int st, int dr)
    {
        ans = 0;
        sti = st, dri = dr;
        query(1, 1, N);
        return ans;
    }

}aint;

