void update(int p, int L, lli value, int i, int j){
	if(i>L || j<L) return;
	if(i==j and i==L){
		// cout<<"updated at p:"<<p<<" with"<<value<<endl;
		T[p]=value;
		return;
	}
	int mid = i+(j-i)/2;
	update(2*p+1, L, value, i, mid);
	update(2*p+2, L, value, mid+1, j);
	T[p] = max(T[2*p+1], T[2*p+2]);
}
lli query(int p, int L, int R, int i, int j){
	if(i>R || j<L) return 0;
	if(L<=i and j<=R){
		return T[p];
	}
	int mid = i+(j-i)/2;
	lli x = query(2*p+1, L, R, i, mid);
	lli y = query(2*p+2, L, R, mid+1, j);
	return max(x, y);
}
