#include<bits/stdc++.h>
using namespace std;
#define ll long long int
#define MAX 200005

void updateTree(ll *arr, ll *tree, int start, int end, int treeNode,
                int idx, ll value){
    if(start == end){
        arr[idx] = value;
        tree[treeNode] = value;
        return;
    }
    int mid = (start + end)/2;
    if(idx > mid) // Move to right
        updateTree(arr, tree, mid+1, end, 2*treeNode+1, idx, value);
    else    // Move to left
        updateTree(arr, tree, start, mid, 2*treeNode, idx, value);

    tree[treeNode] = max(tree[2*treeNode], tree[2*treeNode+1]);
}

ll query(ll *tree, int start, int end, int treeNode, int left, int right){

    if(start>right or end<left)
        return 0;
    if(start>=left and end<=right)
        return tree[treeNode];
    int mid = (start + end)/2;
    ll leftAns = query(tree, start, mid, 2*treeNode, left, right),
       rightAns = query(tree, mid+1, end, 2*treeNode+1, left, right);
    ll ans = max(leftAns, rightAns);
    return ans;
}

ll flowers(int beauty[], int height[], int n){

    // Notice the heights are less than or equal to 2*10^5

    ll *dp = new ll[MAX]();

    // dp[i] stores the maximum sum of beauty when
    // the last height in that subsequence is 'i'

    // Suppose input is
    // n = 9
    // height[] = 4 2 5 8 3 6 1 7 9
    // beauty[] = 6 8 8 4 6 3 5 7 5

    // dp[4] = 6
    // dp[2] = 8
    // Now the next height value is '5'
    // this flower can be appended to any of the smaller heights (either 2 or 4)
    // We append it to that subsequence of flowers which gives maximum sum of beauties
    // So we append it to the subsequence of flower having last height as '2'
    // dp[5] = 16
    // Similarly we proceed for all the flowers

    // So here when we are at a flower having height[i]
    // we need to pick that height among 1, 2, .... , height[i]-1
    // which has maximum sum of beauties
    // like in the above example, if we are at height[i] = 5
    // we want to pick that height among 1, 2, ... , 4
    // which has maximum sum of beauties
    // To quickly find maximum from a range, we can use Segment Tree

    ll maxBeauty = 0;

    ll *tree = new ll[4*MAX]();

    for(int i=0; i<n; i++){
        int h = height[i];
        // Find the maximum from 1, 2, 3, ..., h-1
        ll maximum = query(tree, 0, MAX-1, 1, 1, h-1);

        // We have 2 options for this height:
        // 1) Append it to one of the smaller height subsequence
        // 2) Ignore the current height,
        //    i.e. take the previous value which was present at this height
        ll newBeauty = maximum + beauty[i];
        if(newBeauty > dp[h]){
            updateTree(dp, tree, 0, MAX-1, 1, h, newBeauty);
            if(newBeauty > maxBeauty)
                maxBeauty = newBeauty;
        }
    }

    delete[] dp;
    delete[] tree;

    return maxBeauty;
}

