struct segment_tree
{
	static const int segmaxn=200010;

	#define lc(u) (u<<1)
	#define rc(u) (u<<1|1)

	struct node
	{
		int l,r;
		long long w,f;
	} t[segmaxn*4];

	inline void pushup(int u)
	{
		t[u].w=max(t[lc(u)].w,t[rc(u)].w);
	}

	inline void build(int u,int l,int r)
	{
		t[u].l=l;t[u].r=r;

		if(l==r) return;

		int mid=(l+r)/2;
		build(lc(u),l,mid);
		build(rc(u),mid+1,r);

		pushup(u);
	}

	inline void pushdown(int u)
	{
		if(!t[u].f) return;

		t[lc(u)].f=t[u].f;
		t[rc(u)].f=t[u].f;
		t[lc(u)].w=t[u].f;
		t[rc(u)].w=t[u].f;

		t[u].f=0;
	}

	inline long long range_query(int u,int l,int r)
	{
		long long ans=0;

		if(t[u].l>=l&&t[u].r<=r) return t[u].w;

		pushdown(u);

		int mid=(t[u].l+t[u].r)/2;
		if(l<=mid) ans=max(ans,range_query(lc(u),l,r));
		if(r>mid)  ans=max(ans,range_query(rc(u),l,r));

		return ans;
	}

	inline void range_modify(int u,int l,int r,long long val)
	{
		if(t[u].l>=l&&t[u].r<=r)
		{
			t[u].w=max(t[u].w,val);
			t[u].f=t[u].w;
			return;
		}

		pushdown(u);

		int mid=(t[u].l+t[u].r)/2;
		if(l<=mid) range_modify(lc(u),l,r,val);
		if(r>mid)  range_modify(rc(u),l,r,val);

		pushup(u);
	}
} seg;

