class SegTree {
public:
	//Range Max Query
	vector<int> ar;
	int length;
	SegTree(int n) {
		length = 1;
		while (n > length)length *= 2;
		ar.resize(2 * length - 1);
		for (int i = 0; i < 2 * length - 1; i++)ar[i] = 0;
	}

	void update(int k, int a) {
		//k番目をaにする
		k += length - 1;
		ar[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			ar[k] = max(ar[2 * k + 1], ar[2 * k + 2]);
		}
	}

	int getval(int a, int b, int k, int l, int r) {
		//[a, b)を求める
		if (r <= a || b <= l)return 0;
		else if (a <= l && r <= b)return ar[k];
		else {
			int v1, v2;
			v1 = getval(a, b, 2 * k + 1, l, (l + r) / 2);
			v2 = getval(a, b, 2 * k + 2, (l + r) / 2, r);
			return max(v1, v2);
		}
	}

};

