template <typename T> inline void read(T &var)
{
	T x=0; int w=0; char ch=0;
	while (!isdigit(ch)) w|=ch=='-',ch=getchar();
	while (isdigit(ch)) x=(x<<1)+(x<<3)+(ch^48),ch=getchar();
	var=w?-x:x;
}
void Add(int id,int l,int r,int pos,LL v)
{
	if (l==r&&l==pos) {T[id]=std::max(T[id],v); return;}
	int mid=(l+r)>>1;
	if (pos<=mid) Add(id<<1,l,mid,pos,v);
	else Add(id<<1|1,mid+1,r,pos,v);
	T[id]=std::max(T[id<<1],T[id<<1|1]);
}
LL Query(int id,int l,int r,int pos)
{
	if (r<=pos) return T[id];
	int mid=(l+r)>>1; LL ret=Query(id<<1,l,mid,pos);
	if (mid<pos) ret=std::max(ret,Query(id<<1|1,mid+1,r,pos));
	return ret;
}
int main(int argc, char const *argv[])
{
	read(N); for (Re i=1; i<=N; ++i) read(H[i]);
	for (Re i=1; i<=N; ++i)
		read(A[i]),f[i]=A[i];
	ans=A[1],Add(1,1,N,H[1],f[1]);
	for (Re i=2; i<=N; ++i)
	{
		f[i]=Query(1,1,N,H[i])+A[i];
		Add(1,1,N,H[i],f[i]);
		ans=std::max(ans,f[i]);
	}
	printf("%lld\n",ans);
	return 0;
}

