template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}

template<class T>
vector<T> next_vec(istream& in, size_t n) {
  vector<T> ret(n);
  for (size_t i = 0; i < n; ++i) {
    ret[i] = next<T>(in);
  }
  return ret;
}


struct SegmentTree {
  vec<int64_t> tmax;
  int n;

  SegmentTree(int n_) {
    n = n_;
    tmax = vec<int64_t>(4 * n, 0);
  }

  void update(int pos, int64_t value) {
    int v = 1, le = 0, ri = n;
    while (le + 1 < ri) {
      int e = (le + ri) / 2;
      v *= 2;
      if (pos >= e) {
        ++v;
        le = e;
      } else {
        ri = e;
      }
    }
    tmax[v] = max(tmax[v], value);
    v /= 2;
    while (v) {
      tmax[v] = max(tmax[2 * v], tmax[2 * v + 1]);
      v /= 2;
    }
  }

  int64_t internalGetMax(int v, int left, int right, int rangeLeft, int rangeRight) {
    if (left >= rangeRight || right <= rangeLeft) {
      return 0;
    }
    if (rangeLeft >= left && rangeRight <= right) {
      return tmax[v];
    }
    int e = (rangeLeft + rangeRight) / 2;
    int64_t res = internalGetMax(2 * v, left, right, rangeLeft, e);
    res = max(res, internalGetMax(2 * v + 1, left, right, e, rangeRight));
    return res;
  }

  int64_t getMax(int from, int to) {
    return internalGetMax(1, from, to + 1, 0, n);
  }
};

void solve(istream& in, ostream& out) {
  auto n = next<int>(in);
  auto h = next_vec<int>(in, n);
  auto b = next_vec<int>(in, n);

  SegmentTree stree(n + 1);
  FOR(i, n) {
    int64_t bestLeft = stree.getMax(1, h[i] - 1);
    stree.update(h[i], bestLeft + b[i]);
  }
  out << stree.getMax(1, n) << "\n";
}

