template<typename T>
class SegmentTree
{
    public:
        vector<T> t;
        int n, H;
        void init(int n)
        {
            this->n = n;
            t.resize(2*n);
            this->H = sizeof(int)*8 - __builtin_clz(n);
        }
        void build()
        {   
            for(int i = n-1; i>0;i--)
                t[i] = max(t[i<<1],t[(i<<1)|1]);
        }
        void update(int pos, T val)
        {   pos+=n;
            t[pos] = max(val, t[pos]);
            for( ; pos>1;pos>>=1)
                t[pos>>1] = max(t[pos],t[pos^1]);
        }
        T  query(int l, int r)
        {
            T res = -1e9;
            for(l+=n,r+=n;l<r;l>>=1,r>>=1)
            {
                if(l&1)     res=max(res ,t[l++]);
                if(r&1)     res=max(t[--r], res);
            }
            return res;
        }
};
