struct Segtree {
  vector<ll> v;
  int size;

  Segtree(vector<ll>& moto) {
    size = 1;
    while (size < moto.size()) size *= 2;
    v.resize(size * 2 - 1);
    for (int i = 0; i < moto.size(); i++) {
      v[i + size - 1] = moto[i];
    }
    for (int i = size - 2; i >= 0; i--) {
      v[i] = max(v[i * 2 + 1], v[i * 2 + 2]);
    }
  }

  void change(int now, ll x) {
    now += size - 1;  // 最下段に移動する
    v[now] = max(v[now], x);
    while (now > 0) {
      int p = (now - 1) / 2;
      v[p] = max(v[p], v[now]);
      now = p;
    }
  }

  ll get(int l, int r, int n = 0, int a = 0, int b = 0) {
    if (n == 0) b = size;
    if (l <= a && b <= r)
      return v[n];
    else if (r <= a || b <= l)
      return 0;
    else
      return max(get(l, r, 2 * n + 1, a, (a + b) / 2), get(l, r, 2 * n + 2, (a + b) / 2, b));
  }

  ll operator[](int i) {
    return v[i + (size - 1)];
  }
};

