struct segtree{
    vector<ll> seg;
    segtree(ll n){
        seg.resize(4*n+4,0);
    }
    ll merge(ll a, ll b){
        return max(a,b);
    }
    ll get(ll pos,ll l,ll r,ll st,ll en){
        if(l>en || r<st || l>r){
            return 0;
        }
        if(st<=l && en>=r){
            return seg[pos];
        }
        ll b=(l+r)/2;
        return merge(get(2*pos,l,b,st,en),get(2*pos+1,b+1,r,st,en));
    }
    void update(ll pos,ll l,ll r,ll idx,ll val){
        if(l==r){
			if(seg[pos]<val)
            	seg[pos]=val;
            return;
        }
        ll b=(l+r)/2;
        if(idx<=b){
            update(2*pos,l,b,idx,val);
        }
        else{
            update(2*pos+1,b+1,r,idx,val);
        }
        seg[pos]=merge(seg[2*pos],seg[2*pos+1]);
        return;
    }
};

