void add(int apex, int l, int r, int num, ll value) {
	if (l == r) {
		tree[apex] = value;
		return;
	}
	if (r < num || num < l) return;

	int m = (l + r) / 2;
	add(apex * 2, l, m, num, value);
	add(apex * 2 + 1, m + 1, r, num, value);

	tree[apex] = max(tree[apex * 2], tree[apex * 2 + 1]);
}

ll get(int apex, int l, int r, int L, int R) {
	if (R < l || r < L) return 0;
	if (L <= l && r <= R) return tree[apex];
	int m = (l + r) / 2;
	return max(get(apex * 2, l, m, L, R),
		get(apex * 2 + 1, m + 1, r, L, R));
}

