int minn[8000005];
int maxx[8000005];
int delta[8000005];
int lo[8000005];
int hi[8000005];

void init(int i, int a, int b){
	lo[i] = a;
	hi[i] = b;
	if(a == b)
		return;
	int mid = (lo[i] + hi[i])/2;
	init(2*i, a, mid);
	init(2*i + 1, mid + 1, b);
}

void prop(int i){
	delta[2*i] += delta[i];
	delta[2*i + 1] += delta[i];

	delta[i] = 0;
}

void update(int i){
	minn[i] = min(minn[2*i] + delta[2*i], minn[2*i+1] + delta[2*i+1]);
	maxx[i] = max(maxx[2*i] + delta[2*i], maxx[2*i + 1] + delta[2*i+1]);
}
void increment(int i, int a, int b, int val){
	if(b < lo[i] || hi[i] < b)
		return;
	if(a<= lo[i] && hi[i] <= b){
		delta[i] += val;
		return;
	}
	//partial covering case
	prop(i);
	increment(2*i, a, b, val);
	increment(2*i+1, a, b, val);
	update(i);
} 
pair<int, int> maxmin(int i, int a, int b){
	if(b < lo[i] || hi[i] < a)
		return {INT_MIN + 5, INT_MAX - 5};
	if(a <= lo[i] && hi[i] <= b){
		return {maxx[i] + delta[i], minn[i] + delta[i]};
	}
	//partial covering case
	pair<int, int> left, right;
	prop(i);
	left = maxmin(2*i, a, b);
	right = maxmin(2*i+1, a, b);
	update(i);
	return {max(left.first, right.first), min(left.second, right.second)};
}

