struct SegmentTree {
    vector<long long> t;
    SegmentTree(int sz) {
        t.assign(sz * 4, 0);
    }

    void Update(int v, int tl, int tr, int i, long long val) {
        if (tl + 1 == tr) {
            t[v] = val;
        } else {
            int tm = (tl + tr) / 2;
            if (i < tm) {
                Update(v * 2 + 1, tl, tm, i, val);
            } else {
                Update(v * 2 + 2, tm, tr, i, val);
            }
            t[v] = max(t[v], val);
        }
    }

    long long Get(int v, int tl, int tr, int l, int r) {
        if (tl >= r || tr <= l) return 0;
        if (tl >= l && tr <= r) return t[v];
        int tm = (tl + tr) / 2;
        return max(Get(v * 2 + 1, tl, tm, l, r), Get(v * 2 + 2, tm, tr, l, r));
    }
};

