        //printf("  find_tree: v=%i returns %i\n", v, g[v].maks);
        return g[v].maks;
     }
     long long tmp = max(find_tree(l, r, g[v].left_child), find_tree(l, r, g[v].right_child));
     //printf("  find_tree: v=%i returns %i\n", v, tmp);
     return tmp;
}


