void update(int i, ll v)
{
  while (i <= n)
  {
    bit[i] = max(bit[i], v);
    i += i & -i;
  }
}

ll query(int i)
{
  i -= 1;
  ll ret = 0;
  while (i > 0)
  {
    ret = max(ret, bit[i]);
    i -= i & -i;
  }
  return ret;
}

