const int maxn=2*100005;
struct node{
	ll maxx;
    void assign(ll val)
    {
    	maxx+=val;
    }
    void merge(node &l,node &r)
    {
    	maxx=max(l.maxx,r.maxx);
    }
};
class segtree{
    node t[4*maxn];
public:
    //build with (a,1,0,n-1)
    void build(ll a[], int v, int tl, int tr) {
        if (tl == tr) {
            t[v].assign(a[tl]);
            return;
        } else {
            int tm = (tl + tr) / 2;
            build(a, v*2, tl, tm);
            build(a, v*2+1, tm+1, tr);
            t[v].merge(t[v*2],t[v*2+1]);
        }
    }

    // range query with (1,0,n-1,l,r)
    ll query(int v, int tl, int tr, int l, int r) {
        if (l > tr || r < tl)
            return 0;
        if (l <= tl && tr <= r) {
            return t[v].maxx;
        }
        int tm = (tl + tr) / 2;
        return max(query(v*2, tl, tm, l, r),query(v*2+1, tm+1, tr, l, r));
    }
    //point update with (1,0,n-1,pos,val)
    void pupd(int v, int tl, int tr, int pos, ll val) {
        if (tl == tr) {
            t[v].assign(val);
        } else {
            int tm = (tl + tr) / 2;
            if (pos <= tm)
                pupd(v*2, tl, tm, pos, val);
            else
                pupd(v*2+1, tm+1, tr, pos, val);
            t[v].merge(t[v*2],t[v*2+1]);
        }
    }
};

