void update(int idx , long long v , int l = 0 , int r = n-1 , int p = 1)
{
    if(l == r){st[p] = v;return;}
    int mid = (l+r)>>1;
    if(idx <= mid)  update(idx,v,l,mid,2*p);
    else            update(idx,v,mid+1,r,2*p+1);
