class BIT
{
public:
    vector<int> bit;
    int M;

    BIT(int M):
        bit(vector<int>(M+1, -(1ll<<30))), M(M) {}

    int sum(int i) {
        if (!i) return 0;
        return max(bit[i],sum(i-(i&-i)));
    }

    void add(int i, int x) {
        if (i > M) return;
        bit[i] = max(bit[i], x);
        add(i+(i&-i), x);
    }
};

