const int N = 1e5 + 5;
ll tr[4 * N];

void upd(int l , ll val , int no = 0 , int st = 0 , int en = N - 2){
    if(st > en || st > l || en < l) return ;
    if(st != en){
        int mid = (st + en) >> 1;
        upd(l,val,2*no+1,st,mid);
        upd(l,val,2*no+2,mid + 1, en);
        tr[no] = max(tr[2*no+1],tr[2*no + 2]);
    }
    else tr[no] = max(tr[no] , val);
}

ll get(int r, int l = 0, int no = 0 , int st = 0 , int en = N - 2){
    if(st > en || st > r || en < l) return 0;
    if(st >= l && en <= r) return tr[no];
    int mid = (st + en) >> 1;
    return max(get(r,l,2*no+1,st,mid),get(r,l,2*no+2,mid+1,en));
}


