ll query(int node, int l, int r, int lq, int rq)
{
	if (rq < lq) return 0;
	if (l >= lq && r <= rq) return tree[node];

	ll sum = 0;
	int m = (l + r) / 2;

	if (lq <= m) sum = max(sum, query(node * 2, l, m, lq, rq));
	if (rq > m) sum = max(sum, query(node * 2 + 1, m + 1, r, lq, rq));

	return sum;
}

void update(int node, int l, int r, int pos, ll val)
{
	if (l == r) {

		tree[node] = val;

		return;
	}

	int m = (l + r) / 2;

	if (pos <= m) update(node * 2, l, m, pos, val); else
		update(node * 2 + 1, m + 1, r, pos, val);

	tree[node] = max(tree[node * 2], tree[node * 2 + 1]);
}

