void add(int v,int l,int r,int pos,LL val)
{
	if (l == r)
	{
		t[v] = val;
		return;
	}

	int m = (l + r) >> 1;

	if (L[v] == -1)
		L[v] = addNode();
	if (R[v] == -1)
		R[v] = addNode();

	if (pos <= m)
		add(L[v], l, m, pos, val);
	else
		add(R[v], m + 1, r, pos, val);

	t[v] = max(t[L[v]], t[R[v]]);
}

LL get(int v,int l,int r,int pos)
