void upd(int nd, int s, int e, int id, int v){
	if(s == e){
		t[nd] = v;
		return;
	}
	int md = (s + e) >> 1;
	if(id <= md)
		upd(2*nd, s, md, id, v);
	else
		upd(2*nd + 1, md + 1, e, id, v);
	t[nd] = max(t[2*nd], t[2*nd + 1]);
}

int query(int nd, int s, int e, int l, int r){
	if(s > e || s > r || e < l)
