class SegmentTrees
{
	lvi st;
	ll n;
public:
	SegmentTrees(ll N)
	{
		n=N;
		st.assign(4*n,0);
	}
	ll lfc(ll x) {return x<<1LL;}
	ll rgc(ll x) {return (x<<1LL)+1;}
	void update(ll idx,ll val,ll left,ll right,ll pos=1)
	{
		if(left==right)
		{
			st[pos]=val;
			// error(pos,st[pos]);
		}
		else
		{
			ll mid=(left+right)/2;
			if(idx<=mid)
			{
				update(idx,val,left,mid,lfc(pos));
			}
			else
			{
				update(idx,val,mid+1,right,rgc(pos));
			}
			st[pos]=max(st[lfc(pos)],st[rgc(pos)]);
		}
	}
	ll get_max(ll l,ll r,ll left,ll right,ll pos=1)
	{
		if(l>r) return 0;
		if(l==left && r==right) return st[pos];
		ll mid=(left+right)/2;
		return max(get_max(l,min(r,mid),left,mid,lfc(pos)),get_max(max(mid+1,l),r,mid+1,right,rgc(pos)));
	}
};

