#include <functional>
template <class T>
class SegTree {
    int n;
    vector<T> data;
    T def;
    function<T(T, T)> operation;
    function<T(T, T)> update;
    T _query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return def;
        if (a <= l && r <= b)
        return data[k];
         else {
            T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2);
            T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r);
            return operation(c1, c2);
        }
    }
    public:
// _n:必要サイズ, _def:初期値かつ単位元, _operation:クエリ関数,
// _update:更新関数,例えば和が欲しいなら単位元は０、minならINFとか
//区間minQueryならint func(int a, int b){ return min(a, b); }みたいのをoperationに、和ならint func(int a, int b){ return a + b; }をいれる
        SegTree(size_t _n, T _def, function<T(T, T)> _operation,
            function<T(T, T)> _update)
            : def(_def), operation(_operation), update(_update) {
                n = 1;
                while (n < _n) {
                    n *= 2;
                }
                data = vector<T>(2 * n - 1, def);
        }
        void change(int i, T x) {//updateは足し合わせなら [](T d, T x){ return d + x; }更新なら[](T d, T x){ return x; }
            i += n - 1;//実際の配列のindexへ,実際の配列はセグ木の葉部分
            data[i] = update(data[i], x);//配列そのものを更新したら
            while (i > 0) {//セグ木にも伝播させて更新
                i = (i - 1) / 2;//親に伝播
                data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
            }
        }
        T query(int a, int b) {
            return _query(a, b, 0, 0, n);
        }
        T operator[](int i) {
            return data[i + n - 1];
        }
};

