void modify(int idx, int l, int r, int pos, int val){
	if (r < pos or l > pos) return;
	if (l == r){
		segt[idx] = max(segt[idx],val);
		return;
	}
	int mid = (l+r)>>1;
	modify(2*idx,l,mid,pos,val);
	modify(2*idx+1,mid+1,r,pos,val);
	segt[idx] = max(segt[2*idx],segt[2*idx+1]);
}

int query(int idx, int l, int r, int L, int R){
	if (r < L or l > R) return 0;
	if (l >= L and r <= R) return segt[idx];
	int mid = (l+r)>>1;
	return max(query(2*idx,l,mid,L,R),query(2*idx+1,mid+1,r,L,R));
}

