class segtree
{
  public:
  int depth;//セグ木の深さ(最上部が0）
  int size;
  vector<ll> node;//セグ木本体

  //コンストラクタ
  //初期値の代入もする
  segtree(int n)
  {
    depth=0;
    size=1;
    while(n>size)
    {
      size*=2;
      depth++;
    }
    size*=2;
    node.resize(size,0);
  }

  //値の更新
  //node[k]をaにする
  void update(int k,ll a)
  {
    k+=(1<<depth);//セグ木上のインデックスに読み替え
    node[k]=a;
    while(k>1)
    {
      k/=2;
      node[k]=max(node[k*2],node[k*2+1]);
    }
    return;
  }

  //値の取得
  //閉区間[a,b]での値の最大値
  ll get(int a,int b)
  {
    a+=(1<<depth);
    b+=(1<<depth);
    if(a==b)
      return node[a];
    ll nowa=node[a];
    ll nowb=node[b];
    while(a/2<b/2)
    {
      //左側はより右側を見る
      if((a&1)==0)
        nowa=max(nowa,node[a+1]);
      //右側はより左側を見る
      if((b&1)==1)
        nowb=max(nowb,node[b-1]);
      a/=2;
      b/=2;
    }
    ll ret=max(nowa,nowb);
    return max(ret,node[a]);
  }
};
int main()
{
	int n;
