	cin>>n;
	for(int i=0;i<n;i++)
		cin>>h[i];
	for(int i=0;i<n;i++)
		cin>>a[i];
	fill(dp,dp+200001,0);
	segtree t=segtree(n+1);
	for(int i=0;i<n;i++)
	{
		ll tmp=t.get(0,h[i]-1);
		if(dp[h[i]]<tmp+a[i])
		{
			dp[h[i]]=tmp+a[i];
			t.update(h[i],dp[h[i]]);
		}
	}
	for(int i=0;i<n+1;i++)
		ans=max(ans,dp[i]);
	cout<<ans<<endl;
