const int maxn = 200005;

inline ll L(ll a) {return (a << 1) + 1;}
inline ll R(ll a) {return (a << 1) + 2;}

class SegTree {
	ll T[maxn << 2];

public:
	void build()
	{
		memset(T, 0, sizeof(T));
	}

	void update(ll node, ll st, ll en, ll pos, ll val) {
		if (st > en) return;
		if (st == en) T[node] = val;
		else {
			ll mid = (st + en) >> 1;
			if (pos > mid) update(R(node), mid + 1, en, pos, val);
			else update(L(node), st, mid, pos, val);

			T[node] = max(T[L(node)], T[R(node)]);
		}
	}

	ll query(ll node, ll st, ll en, ll pos) {
		if (st > en) return -1;
		if (st == en) return T[node];
		else {
			ll mid = (st + en) >> 1;
			if (pos > mid) return max(T[L(node)], query(R(node), mid + 1, en, pos));
			else return query(L(node), st, mid, pos);
		}
	}
};

void solve() {
