struct TNode {
	int root, nstart, nend, mid;
	TNode() {}
	TNode(int r, int ns, int ne) {
		//++count_tn;
		//cout << count_tn << endl;
		root = r;
		nstart = ns;
		nend = ne;
		mid = (ns + ne) / 2;
	}
	TNode  getLeft() const {
		return  TNode(root * 2 + 1, nstart, mid);
	}
	TNode  getRight() const {
		return  TNode(root * 2 + 2, mid + 1, nend);
	}
};

TNode superRoot;

void refresh(Node & n0, Node & n1, Node & n2) {
	n0.bea = max(n1.bea, n2.bea);
}
void refresh(int root, int left, int right) {
	refresh(stree[root], stree[left], stree[right]);
}
LL zb[MAX];
void init(int root, int nstart) {
	stree[root].bea = zb[nstart];
	return;
}
void buildt(const TNode & tn) {
	if (tn.nstart == tn.nend) {
		init(tn.root, tn.nstart);
		return;
	}
	auto tn0 = tn.getLeft();
	auto tn1 = tn.getRight();
	buildt(tn0);
	buildt(tn1);
	refresh(tn.root, tn0.root, tn1.root);
}
void update(const TNode & tn, int change) {
	if (change < tn.nstart || change > tn.nend) return;
	if (tn.nstart == tn.nend) {
		init(tn.root, tn.nstart);
		return;
	}
	auto tn0 = tn.getLeft();
	auto tn1 = tn.getRight();
	update(tn0, change);
	update(tn1, change);
	refresh(tn.root, tn0.root, tn1.root);
}

LL query0(const TNode & tn, int b1, int b2 ) {
	if (b2 < tn.nstart || b1 > tn.nend) return 0;
	if (b1 <= tn.nstart && tn.nend <= b2) {
		return stree[tn.root].bea;
	}
	auto tn0 = tn.getLeft();
	auto tn1 = tn.getRight();
	auto r1 = query0(tn0, b1, b2 );
	auto r2 = query0(tn1, b1, b2 );
	return max(r1,r2);
}
