template <typename T>
class RMQ
{
  const T INF = numeric_limits<T>::max();
  int n = 1;
  vector<T> data;

public:
  RMQ(int s)
  {
    while (n < s)
      n *= 2;
    data.resize(2 * n - 1);
  }

  void update(int i, T x)
  {
    i += n - 1;
    data[i] = x;
    while (i > 0)
    {
      i = (i - 1) / 2;
      data[i] = max(data[i * 2 + 1], data[i * 2 + 2]);
    }
  }

  T query(int a, int b) { return query1(a, b, 0, 0, n); }
  T query1(int a, int b, int i, int l, int r)
  {
    if (b <= l || r <= a)
      return INF;
    if (a <= l && r <= b)
      return data[i];
    int m = (l + r) / 2;
    int x = query1(a, b, i * 2 + 1, l, m);
    int y = query1(a, b, i * 2 + 2, m, r);
    return max(x, y);
  }
};

