#define MAXN 200000
#define INF 999999999 // watch it
#define int long long
typedef pair<int,int> hb;

vector<int> tree(4*MAXN,0);

void update(int ind, int v, int node = 1, int i = 1, int j = MAXN){
    if (ind < i || ind > j) return;
    if ( i==j ){
        tree.at(node) = max(tree[node], v);
    }
    else{
        update(ind,v,node*2,i,(i+j)/2);
        update(ind,v,node*2+1,(i+j)/2+1,j);
        tree.at(node) = max(tree.at(node*2), tree.at(node*2+1)); 
    }
}

int queries(int a, int b, int node = 1, int i = 1, int j = MAXN){
    if (a > j || b < i) return INT_MIN;
    if (a <= i && b >= j){
        return tree.at(node);
    }
    return max(queries(a,b,node*2,i,(i+j)/2)  ,  queries(a,b,node*2+1, (i+j)/2+1, j));
}

