class segTree {
private:

	int n;
	int base = 1;
	vector<ll> tree;

public:
	segTree(int n) {
		this->n = n;
		while (base <= n) base *= 2;

		tree = vector<ll>(base * 2);
	}

	ll get (ll h) {
		ll x = h + base;
		ll best = 0;

		while (x > 1) {
			if (x % 2) {
				best = max(best, tree[x - 1]);
			}
			x /= 2;
		}
		return best;
	}

	void update(ll h, ll curVal) {
		for (int i = base + h; i > 0; i /= 2) {
			tree[i] = max(tree[i], curVal);
		}
	}

};

void solve() {
