const int NMAX = 200005;

ll dp[NMAX]; // dp[i] max beauty if last taken flower is height i
ll seg[2*NMAX];

void update(int l, int r, int pos, int idx, ll val){
  if(l==r && l==idx){
    seg[pos] = val;
    return;
  }

  if(l <= idx && idx <= r){ 
    int mid = (l+r)/2;
    update(l, mid, 2*pos+1, idx, val);
    update(mid+1, r, 2*pos+2, idx, val);
    seg[pos] = max(seg[2*pos+1], seg[2*pos+2]);
  }
}

ll ambil(int ql, int qr, int l, int r, int pos){
  if(ql <= l && r <= qr){
    return seg[pos];
  }
  if(r < ql || qr < l){
    return 0;
  }

  int mid = (l+r)/2;
  return max(ambil(ql,qr,l,mid,2*pos+1), ambil(ql,qr,mid+1,r,2*pos+2));
}

