struct BIT {
	LL c[MAXN];
	void set(int p, LL v) {
		while (p < MAXN) {
			c[p] = max(c[p], v);
			p += p & -p;
		}
	}
	LL RMQ(int p) {
		LL res = 0;
		while (p) {
			res = max(res, c[p]);
			p -= p & -p;
