void upd(int in, int l, int r, int idx, ll v){
  if(l > idx || r < idx)
    return;
  if(l == r){
    tree[in] = v;
    return;
  }
  int m = (l + r) / 2;
  upd(2 * in, l, m, idx, v);
  upd(2 * in + 1, m + 1, r, idx, v);
  tree[in] = max(tree[2 * in], tree[2 * in + 1]);
}

ll get(int in, int l, int r, int s, int e){
  if(l > e || r < s)
    return 0;
