void dfs(int v, int p) {

    if(dp[v] > 0) return;

    for (int nv = v-1; nv >= 0; --nv) {
        if (nv == p) continue; // nv が親 p だったらダメ
        if(h[nv] > h[v]) continue;
        dfs(nv, v);
    }

    // 帰りがけ時に、部分木サイズを求める
    dp[v] = 0;
    for (int c = v-1; c >= 0; --c) {
        if (c == p) continue; // nv が親 p だったらダメ
        if(h[c] > h[v]) continue;
        dp[v] = max(dp[v], dp[c]);
    }
    dp[v] += a[v];

}

