void modify(ll x,ll pos,ll id = 1,ll l =0,ll r = n+1){
	if (r - l < 2){
		s[id] = x;
		return;
	}
	ll mid = (l+r)/2;
	if (pos < mid){
		modify(x,pos,id*2,l,mid);
	}
	else {
		modify(x,pos,id*2+1,mid,r);
	}
	s[id] = max(s[id*2],s[id*2+1]);
}

ll query(ll x,ll y,ll id = 1 ,ll l =0, ll r = n+1){
	if (y <= l || x >= r) return 0;
	if (x <= l && r <= y){
		return s[id];
	}
	ll mid = (l+r)/2;
	return max(query(x,y,id*2,l,mid),query(x,y,id*2+1,mid,r));
}

