vector <long long> tree;

long long query (int v, int start, int end, int l, int r)
{
	if (r < start || l > end)
		return 0;

	if (l <= start && r >= end)
		return tree[v];

	int mid = (start + end)/2;
	return max(query(2*v, start, mid, l, r), query(2*v + 1, mid + 1, end, l, r));
}

void update (int v, int start, int end, int index, long long val)
{
	if (start == end) tree[v] = val;
	else
	{
		int mid = (start + end)/2;
		if (index <= mid)
			update(2*v, start, mid, index, val);
		else 
			update(2*v + 1, mid + 1, end, index, val);
		tree[v] = max(tree[2*v], tree[2*v + 1]);
	}
}

