typedef long long ll;

struct segment_tree
{
    int n;
    vector<ll> st;

    segment_tree(int n) : n(n), st(4 * n) {}

    void update(int b, ll v)
    {
        update(1, 0, n, b, v);
    }

    ll query(int b)
    {
        return query(1, 0, n, 0, b);
    }

private:

        void update(int node, int b, int e, int bb, ll v)
        {
            if(b + 1 == e)
            {
                st[node] = max(st[node], v);
                return;
            }

            int m = (b + e) >> 1, l = node << 1, r = l | 1;


            if(bb < m) update(l, b, m, bb, v);
            else update(r, m, e, bb, v);

            st[node] = max(st[l], st[r]);
        }

        ll query(int node, int b, int e, int bb, int ee)
        {
            if(bb <= b && e <= ee)
                return st[node];

            int m = (b + e) >> 1, l = node << 1, r = l | 1;

            ll ans = -1;
            if(bb < m) ans = max(ans, query(l, b, m, bb, ee));
            if(m < ee) ans = max(ans, query(r, m, e, bb, ee));

            return ans;

        }
};

