ll tree[4 * NMAX];
ll lazy[4 * NMAX];

void update(int node, int left, int right, int x, int y, ll val) {
  if (x <= left && right <= y) {
    uax(tree[node], val);
    uax(lazy[node], val);
    return;
  }
  int mid = left + (right - left) / 2;
  if (x <= mid) {
    update(2 * node + 1, left, mid, x, y, val);
  }
  if (mid < y) {
    update(2 * node + 2, mid + 1, right, x, y, val);
  }
}

ll query(int node, int left, int right, int pos) {
  int mid = left + (right - left) / 2;
  if (left != right) {
    update(2 * node + 1, left, mid, left, mid, lazy[node]);
    update(2 * node + 2, mid + 1, right, mid + 1, right, lazy[node]);
  } else {
    return tree[node];
  }
  if (pos <= mid) {
    return query(2 * node + 1, left, mid, pos);
  } else {
    return query(2 * node + 2, mid + 1, right, pos);
  }
}

