ll seg[400000+500];
void update(ll pos, ll val, ll n){
    seg[pos+n] += val;
    pos = (pos+n)/2;
    while(pos > 0)seg[pos] = max(seg[pos*2], seg[pos*2+1]), pos /= 2;
}
ll query(ll l, ll r, ll n){
    if(r < l)return 0;
    l += n, r+= n;
    ll l_max = -1, r_max = -1;
    while(l < r){
        if(l%2) l_max = max(l_max, seg[l++]);
        if(1-r%2) r_max = max(r_max, seg[r--]);
        l /= 2;
        r /= 2;
    }
    ll ret = max(l_max, r_max);
    if(l == r)return max(ret, seg[l]);
    else return ret;
}
