	if(it == candidates.begin()){
		return 0;
	}
	it--;
	return it -> second ;
}

void insertBest(int v, int best){
	if(candidates[v] >= best){
		return;
	}
	candidates[v] = best ;
	auto it = candidates.find(v);
	it++;
	while(it != candidates.end() && it->second <= best){
		auto now = it ;
		it++;
		candidates.erase(now);
	}
}

