const int maxn = 2e5+5;
int h[maxn],a[maxn]; LL A[maxn], bit[maxn];

void upd(const int i, const LL v)
{
    A[i] = v;
    for (int x = i; x < maxn; x |= (x+1)) {
        bit[x] = A[x];
        for (int j = x-1; j > (x&(x+1))-1; j = (j&(j+1))-1)
            bit[x] = max(bit[x],bit[j]);
    }
}

LL get(const int i, const int j)
{
    LL ans = A[j]; int x = j;
    while (i < x) {
        for (x -= 1; x >= i + x - (x&(x+1))+1; x = (x&(x+1))-1)
            ans = max(ans,bit[x]);
        ans = max(ans,A[x]);
    }
    return ans;
}

