struct segment{
	ll tree[N << 2] ;
	segment(){
		mem(tree) ;
	}
	void upd(int i , int b , int e , int p , ll v){
		if(b > p or e < p)return ;
		if(b == e){
			tree[i] = v ;
			return ;
		}
		int mid = (b + e) >> 1 ;
		upd(i << 1 , b , mid , p , v) ;
		upd(i << 1 | 1 , mid + 1 , e , p , v) ;
		tree[i] = max(tree[i << 1], tree[i << 1 | 1]) ;
	}

	ll query(int i , int b , int e , int l , int r){
		if(b > r or e < l)return 0 ;
		if(l <= b and e <= r)return tree[i] ;
		int mid = (b + e) >> 1 ;
		return max(query(i << 1 , b , mid , l , r), query(i << 1 | 1 , mid + 1 , e , l , r)) ;
	}
}seg;



