#define ll long long int
vector<ll> tree(800010,0);
void up(ll x,ll l,ll r,ll node,ll val){
	if(l==r){
		tree[node]=val;
		return;
	}
	else if(l>x || r<x){
		return;
	}
	else{
		ll mid=(l+r)/2;
		up(x,l,mid,2*node,val);
		up(x,mid+1,r,2*node+1,val);
		tree[node]=max(tree[2*node],tree[2*node+1]);
		return;
	}
}
ll qu(ll l,ll r,ll node,ll st,ll en){
	if(l>=st && en>=r){
	return tree[node];
	}
	else if(r<st || en<l){
		return 0;
	}
	else{
		ll mid=(l+r)/2;
		ll x1=qu(l,mid,2*node,st,en);
		ll x2=qu(mid+1,r,2*node+1,st,en);
		return max(x1,x2);
	}
}
