#include<bits/stdc++.h>
using namespace std;
#define MAXN 200000
#define LL long long int

int N, height[MAXN + 3], beauty[MAXN + 3];
LL dp[MAXN + 3], tree[4 * MAXN + 3], answer;

LL query(int node, int l, int r, int a, int b) {
    if (r < a || l > b)
        return 0;

    if (l >= a && r <= b)
        return tree[node];

    int m = (l + r)/2;
    int lft = query(2 * node, l, m, a, b);
    int rght = query(2 * node + 1, m + 1, r, a, b);

    return max(lft, rght);
}

void update(int node, int l, int r, int idx, LL val) {
    if (l == r) {
        tree[node] = max(tree[node], val);
        return;
    }

    int m = (l + r)/2;
    if (idx <= m)
        update(2 * node, l, m, idx, val);
    else
        update(2 * node + 1, m + 1, r, idx, val);
}

int main() {
    cin >> N;
    for (int i = 1; i <= N; i++)
        cin >> height[i];

    for (int i = 1; i <= N; i++)
        cin >> beauty[i];

    memset(tree, 0, sizeof(tree));

    dp[1] = beauty[1];
    update(1, 1, MAXN, height[1], dp[1]);

    answer = dp[1];
    for (int i = 2; i <= N; i++) {
        dp[i] = query(1, 1, MAXN, 1, height[i] - 1) + beauty[i];
        answer = max(answer, dp[i]);

        update(1, 1, MAXN, height[i], dp[i]);
    }

    cout << answer << endl;
}

