void update(int node,int start,int End,ll val,int index)
{
    if(start == End)
    {
        tree[node] = val;
        return;
    }
    int mid = (start + End) / 2;
    if(start <= index && mid >= index)
        update(node*2,start,mid,val,index);
    else
        update(node*2+1,mid+1,End,val,index);
    tree[node] = max(tree[node*2],tree[node*2+1]);
}
long long query(int node,int start,int End,int l, int r)
{
    if(End < l || start > r || start > End)
        return 0;
    if(start >= l && End <= r)
        return tree[node];
    int mid = (start + End)/2;
    return max(query(node*2+1,mid+1,End,l,r),query(node*2,start,mid,l,r));
}

