// セグメント木
// 元の配列は0-indexedとする
// 元の配列のk番目の要素はノードk+size
// ノードkについて親ノードはk/2,子ノードは2k
template<typename T>
struct ST{
  int size;
  vector<T> seg;

  // ここから問題に応じて編集
  // func(a,UNIT)=aとなるような単位元UNITを代入
  T UNIT = 0LL;
  // 結合則の成り立つ演算を書く
  T func(T a, T b){
    return max(a,b);
  }
  // ここまで

  ST(int N){
    size = 1;
    while(size < N) size <<= 1;
    seg.assign(2 * size, UNIT);
    build();
  }

  ST(const vector<T> &v){
    // initialize
    size = 1;
    while(size < (int)v.size()) size <<= 1;
    seg.resize(2 * size);
    // set
    for(int i=0;i < (int)v.size(); i++){
      seg[i + size] = v[i];
    }
    build();
  }

  void set(int k,T& x){
    seg[k + size] = x;
  }

  void build(){
    for(int k=size-1; k>0; k--){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1]);
    }
  }

  void update(int k, T& x){
    k += size; seg[k] = x;
    while(k >>= 1){
      seg[k] = func(seg[2 * k] , seg[2 * k + 1]);
    }
  }

  T query(int a, int b){
    T L = UNIT, R = UNIT;
    for(a+=size,b+=size; a<b; a>>=1,b>>=1){
      if(a & 1) L = func(L,seg[a++]);
      if(b & 1) R = func(seg[--b],R);
    }
    return func(L, R);
  }

  T operator[](const int &k) const{
    return seg[k + size];
  }

};

int main(){
  ini(N);
  vi h(N); in(h,N);
  vl a(N); in(a,N);

  ST<ll> st(N + 1);
  rep(i,N){
    ll cur = st.query(1,h[i]) + a[i];
    st.update(h[i] , cur);
  }
  out( st.query(1,N + 1) );

}

