template<typename T>
struct SegmentTree{
  using OP = function<T(T,T)>;

  int n, defn;
  vector<T> node;
  T t;
  OP op;

  SegmentTree(int n_, T t, OP op) : t(t),op(op){
    n = 1;
    defn = n_;
    while(n < n_) n<<=1;
    node.assign(2*n,t);
  }

  void init(int n_){
    n = 1;
    defn = n_;
    while(n < n_) n<<=1;
    node.assign(2*n,t);
  }

  void set(int k,T x){
    node.at(k+n) = x;
  }

  void build(){
    for(int k = n - 1; k > 0; k--){
      node.at(k) = op(node.at(2*k),node.at(2*k+1));
    }
  }

  void update(int k, T x){
    k += n;
    node.at(k) = x;
    while(k >>= 1){
      node.at(k) = op(node.at(2*k),node.at(2*k+1));
    }
  }

  void update(int l, int r, T x){
    FOR(k,l,r) update(k,x);
  }

  T at(int k){
    return node.at(k+n);
  }

  void add(int k, T a){
    T x = at(k)+a;
    update(k,x);
  }

  T query(int a, int b){
    if(a==0 && b==defn) return all_query();
    T L = t, R = t;
    for(a += n, b += n; a < b; a >>= 1, b >>= 1) {
      if(a & 1) L = op(L, node.at(a++));
      if(b & 1) R = op(node.at(--b), R);
    }
    return op(L, R);
  }

  T all_query() { return node.at(1); }

  template<typename C>
  int findR(int a, int b, C &check){
    return findR(a,b,check,1,0,n);
  }
  template<typename C>
  int findR(int a, int b, C &check, int k, int l, int r){
    if(!check(node.at(k))||r<=a||b<=l) return -1;
    if(k >= n) return k-n;
    int rv = findR(a,b,check,2*k+1,(l+r)/2,r);
    if(rv != -1) return rv;
    return findR(a,b,check,2*k,l,(l+r)/2);
  }

  template<typename C>
  int findL(int a, int b, C &check){
    return findL(a,b,check,1,0,n);
  }
  template<typename C>
  int findL(int a, int b, C &check, int k, int l, int r){
    if(!check(node.at(k))||r<=a||b<=l) return -1;
    if(k >= n) return k-n;
    int lv = findL(a,b,check,2*k,l,(l+r)/2);
    if(lv != -1) return lv;
    return findL(a,b,check,2*k+1,(l+r)/2,r);
  }

  template<typename C>
  int max_right(int l, C &check){
    if(l == defn) return defn;
    l += n;
    T tm = t;
    do{
      while(l%2 == 0) l >>= 1;
      if(!check(op(tm, node.at(l)))){
        while(l < n){
          l *= 2;
          if(check(op(tm, node.at(l)))){
            tm = op(tm, node.at(l));
            l++;
          }
        }
        return l - n;
      }
      tm = op(tm, node.at(l));
      l++;
    }while((l&-l) != l);
    return defn;
  }

  template<typename C>
  int max_left(int r, C &check){
    if(r == 0) return 0;
    r += n;
    T tm = t;
    do{
      r--;
      while(r>1 && (r%2)) r >>= 1;
      if(!check(op(node.at(r), tm))){
        while(r < n){
          r = 2*r + 1;
          if(check(op(node.at(r), tm))){
            tm = op(node.at(r), tm);
            r--;
          }
        }
        return r + 1 - n;
      }
      tm = op(node.at(r), tm);
    }while((r&-r) != r);
    return 0;
  }
};

