        if(a<=l&&r<=b)return dat[k];
        ll m=(l+r)/2;
        ll u=sum_query(a,b,2*k+1,l,m);
        ll v=sum_query(a,b,2*k+2,m,r);
        return (u+v);
    }

    ll get_sum(ll l,ll r){
        return sum_query(l,r,0,0,N);
    }

