void update(ll node, ll start, ll end, ll ix, ll val) {
	if (start==end) {
		segtree[node] = val;
	}
	else {
		ll mid = (start+end)/2;
		if (ix<=mid) 
			update(2*node, start, mid, ix, val);
		else update(2*node+1, mid+1, end, ix, val);
		segtree[node] = max(segtree[2*node], segtree[2*node+1]);
	}
}

ll qmax(ll node, ll start, ll end, ll l, ll r) {
	ll mid = (start+end)/2;
	if(r<start || end<l) 
		return 0;
	else if(l<=start && end<=r)
		return segtree[node];
	else return max(qmax(2*node, start, mid, l, r), qmax(2*node+1, mid+1, end, l, r));
}

