//初期化
void init2(ll n_){
    //簡単のために要素数を2のべき乗に
    n=1;
    while(n<n_) n*=2;

    //全ての値をINT_MAXに
    for(int i=0;i<2*n-1;i++) dat2[i]=0;
}

//k番目の値(0-indexed)をaに変更
void update2(int k,ll a){
    //葉の節点
    k+=n-1;
    dat2[k]=a;
    //登りながら更新
    while(k>0){
        k=(k-1)/2;
        dat2[k]=max(dat2[k*2+1],dat2[k*2+2]);
    }
}

//[a,b)の最小値を求める
//後ろの方の引数は、計算の簡単のための引数
//ｋは接点の番号、l,rはその接点が[l,r)に対応づいていることを表す
//したがって、外からはquery(a,b,0,0,n)として呼ぶ
ll query2(int a,int b,int k,int l,int r){
    //[a,b)と[l,r)が交差しなければ,INT_MAX
    if(r<=a || b<=l) return -1;

    //[a,b)が[l,r)を完全に含んでいれば、この節点の値
    if(a<=l && r<=b) return dat2[k];
    else{
        //そうでなければ、２つの子の最小値
        ll vl=query2(a,b,k*2+1,l,(l+r)/2);
        ll vr=query2(a,b,k*2+2,(l+r)/2,r);
        return max(vl,vr);
    }
}


