ll query(int tidx,int lo,int hi,int i,int j){
	if(lo > j || hi < i)return 0;
	if(i <= lo && hi <= j)return tree[tidx];

	int mid = (lo+hi)/2;
	if(i > mid){
		return query(2*tidx+2,mid+1,hi,i,j);
	}
	else if(j<=mid){
		return query(2*tidx+1,lo,mid,i,j);
	}
	return max(query(2*tidx+1 , lo,mid,i,mid),query(2*tidx+2,mid+1,hi,mid+1,j));
