struct MaxSegmentTree{
  int size_;
  int length_;
  vector<ll> data_;
  umap<int, int> par_info_;
  umap<int, pair<int, int>> chil_info_;

  MaxSegmentTree(int size, ll init = -(1e+18))
    :size_(CalcSize(size)), length_((size_+1)/2), data_(size_, init)
  { Init(); }

  int CalcSize(int size)
  { int n = 1; while(n < size)n *= 2; return 2 * n - 1; }
  void Init(){
    for(int i = (size_/2)-1; i >= 0; --i){
      int l = i*2 + 1, r = i*2 + 2;
      par_info_[l] = i;
      par_info_[r] = i;
      chil_info_[i] = {l,r};
    }
  }

  void Set(int idx, ll x){
    int pos = (size_/2)+idx;
    data_[pos] = x;
    while(pos != 0){
      pos = par_info_[pos];
      ll l, r;tie(l, r) = chil_info_[pos];
      data_[pos] = max(data_[l], data_[r]);
    }
  }

  ll GetMax(int target_l, int target_r, int idx = 0,
	    int range_l = 0, int range_r = -1){
    if(range_r == -1){
      range_r = length_;
      if(target_l > target_r || target_l < 0 || target_r > length_){
	cerr << "SegmentTree GetMin target index error\n";
	cerr << "target_l:" << target_l << " target_r:" << target_r << endl;
	return -(1e+18);
      }
    }

    if(target_r <= range_l || target_l >= range_r) return -(1e+18);
    if(target_r >= range_r && target_l <= range_l) return data_[idx];

    int l, r; tie(l, r) = chil_info_[idx];
    int mid = (range_l + range_r)/2;

    ll val_l = GetMax(target_l, target_r, l, range_l, mid);
    ll val_r = GetMax(target_l, target_r, r, mid, range_r);

    return max(val_l, val_r);
  }  
}; // [left, right)

