class InterMaxTree {
public: 
    InterMaxTree(int size) {
        twodeg = up2deg(size);
        v = vector<ll>(2*twodeg, 0);
    }

    void update(int idx, ll val) {
        int ridx = twodeg+idx;
        v[ridx] = val;
        while (ridx > 1) {
            int p = ridx/2;
            v[p] = max(v[2*p], v[2*p+1]);
            ridx >>= 1;
        }
    }

    // return for [l, r)
    ll get(int l, int r) {
        return bfs_get(1, 0, twodeg, l, r);
    }

    void print() {
        for (int i=0; i<v.size(); i++) {
            printf("for %d val is %lld\n", i, v[i]);
        }
    }
private:
    int up2deg(int size) {
        int td = 1;
        while (td < size) td <<= 1;
        return td;
    }

    ll bfs_get(int idx, int left, int right, int l, int r) {
        int l_idx = 2*idx;
        int r_idx = 2*idx+1;
        int mid = (left+right)/2;

        // base case:
        if (left == l && right == r)
            return v[idx];

        // bfs step:
        if (r <= mid) {
            return bfs_get(l_idx, left, mid, l, r);
        } else if (l >= mid) {
            return bfs_get(r_idx, mid, right, l, r);
        } else {
            return max (bfs_get(l_idx, left, mid, l, mid), bfs_get(r_idx, mid, right, mid, r));
        }
    }

    vector<ll> v;
    int twodeg;
};

int main() {
    int N; cin >> N;
