    ll ans[N]; for (int i=0; i<N; i++) ans[i] = 0;

    InterMaxTree st(N+1);
    for (int i=0; i<N; i++) {
        ll without = st.get(0,h[i]);
        ll pans = without + a[i];
        ll prevans = (i == 0)? 0:ans[i-1];

        st.update(h[i], pans);
        ans[i] = max(pans, prevans);
    }    

    cout << ans[N-1] << endl;
    return 0;
}

