    if (tnew[v]!=0) {
        t[v] = max(t[v], tnew[v]);
        tnew[v*2] = max(tnew[v*2], tnew[v]);
        tnew[v*2+1] = max(tnew[v*2+1], tnew[v]);
        tnew[v] = 0;
    }
}

ll findmax(int v, int vl, int vr, int l, int r) {
    push(v);
    if (l>r || vl>vr || l>vr || r<vl) {
        return 0;
    }
    if (l<=vl && vr<=r) {
        return t[v];
    }
    int vm = (vl+vr)/2;
    ll x = findmax(v*2, vl, vm, l, r), y = findmax(v*2+1, vm+1, vr, l, r);
    return max(x,y);
}

void update(int v, int vl, int vr, int l, int r, ll x) {
    push(v);
    if (l>r || vl>vr || l>vr || r<vl) {
        return;
    }
    if (l<=vl && vr<=r) {
        tnew[v] = x;
        push(v);
        return;
    }
    int vm = (vl+vr)/2;
    update(v*2, vl, vm, l, r, x);
    update(v*2+1, vm+1, vr, l, r, x);
    t[v] = max(t[v*2], t[v*2+1]);
    return;
}

