		if(l==0){
			maxa=max(maxa,a[i]);
			update(l,a[i],0,n-1,1);
		}else{
			long long f=query(l-1,0,n-1,1);
			maxa=max(maxa,f+a[i]);
			update(l,f+a[i],0,n-1,1);
		}
	}
	cout<<maxa;
}

