struct node {
    ll val;
    node() {
        val = 0;
    }
    node(ll _val) { val = _val; };
    node(node a, node b) {
        val = max(a.val, b.val);
    }
};
struct segment_tree {
    ll sz, n;
    vector<node> t;
    segment_tree(ll _n) : sz(_n*4), n(_n) {
        rep(i,0,sz) t.pb(node());
    }
    void build(vi &a, ll v=1, ll tl=0, ll tr=-1) {
        if(tr == -1) tr = n-1;
        if(tl == tr) {
            t[v].val = a[tl];
        } else {
            ll tm = (tl+tr)/2;
            build(a, v*2, tl, tm);
            build(a, v*2+1, tm+1, tr);
            t[v] = node(t[v*2],t[v*2+1]);
        }
    }
    node query(ll l, ll r, ll v=1, ll tl=0, ll tr=-1) {
        if(tr == -1) tr = n-1;
        if(l > r) return node();
        if(l == tl && r == tr) return t[v];
        ll tm = (tl+tr)/2;
        return node( query(l,min(r,tm), v*2, tl, tm)
                ,query(max(l,tm+1), r, v*2+1, tm+1, tr));

    }
    void update(ll pos, ll new_val, ll v=1, ll tl=0, ll tr=-1) {
        if(tr == -1) tr = n-1;
        if(tl == tr) t[v].val = new_val;
        else {
            ll tm = (tl+tr)/2;
            if(pos <= tm) update(pos, new_val, v*2, tl, tm);
            else update(pos, new_val, v*2+1, tm+1, tr);
            t[v] = node(t[v*2], t[v*2+1]);
        }
    }
};

