        void init(int k, int s, int e, int *a){
                if(s+1==e){st[k]=a[s];return;}
                int m=(s+e)/2;
                init(2*k,s,m,a);init(2*k+1,m,e,a);
                st[k]=oper(st[2*k],st[2*k+1]);
        }
