template<typename T, T identity, function<T(T, T)>& op>
class SegTree{
private:
  vector<T> data;
  int size;
  int height; // the number of edges between the root and leaves

  T query_util(int bidx, int eidx, int data_idx, int dbi, int dei){
    if((bidx <= dbi) && (dei <= eidx)){
      return data[data_idx];
    }

    if((eidx <= dbi) || (dei <= bidx)){
      return identity;
    }

    int dmi = (dbi + dei) / 2;
    return op(
              query_util(bidx, eidx, 2 * data_idx + 1, dbi, dmi),
              query_util(bidx, eidx, 2 * data_idx + 1, dmi, dei)
              );
  }
public:
  SegTree(int size):
    size(size){
      height = 0;
      while((1 << height) < size){
        height++;
      }
      for(height = 0; (1 << height) < size; height++){
      }
      data = vector<T>((1 << (height + 1)) - 1, identity);
  }
  SegTree& update(int idx, T val){
    int leaf_idx = (1 << height) - 1 + idx;
    data[leaf_idx] = val;

    for(int node_idx = (leaf_idx - 1) / 2; node_idx > 0; node_idx = (node_idx - 1) / 2){
      data[node_idx] = op(data[2 * node_idx + 1], data[2 * node_idx + 2]);
    }
    data[0] = op(data[1], data[2]);
    return *this;
  }
  T query(int begin, int end){
    return query_util(begin, end, 0, 0, 1 << height);
  }
};

