using namespace std;
using ll = long long;

const ll INF = 1LL<<60;

template<typename T> struct SegmentTree {
    int size;
    vector<T> data;
    const function<T(T, T)> func;
    const T unit;
    // u: unit (+ => 0, xor => 0, min => INF, max => -INF)
    SegmentTree(int sz, const T& u, const function<T(T, T)> f) : unit(u), func(f) {
        size = 1;
        while ( size < sz ) size *= 2;
        data.assign(size * 2, unit);
    }
    SegmentTree(vector<T>& v) : SegmentTree<T>((int)v.size(), -INF, [](ll a, ll b) {return max(a,b);}) {
        for ( int i = 0; i < v.size(); i++ ) InitSet(i, v[i]);
        InitBuild();
    }
    void InitSet(int i, const T& a) {
        data.at(i + size - 1) = a;
    }
    void InitBuild() {
        for ( int i = size - 2; i >= 0; i-- ) {
            data.at(i) = func( data.at(i * 2 + 1), data.at(i * 2 + 2) );
        }
    }
    void Update(int i, const T& a) {
        i += size - 1;
        data.at(i) = a;
        while ( i > 0 ) {
            i = (i - 1) / 2;
            data.at(i) = func( data.at(i * 2 + 1), data.at(i * 2 + 2) );
        }
    }
    // [a, b)の値を取得
    T Query(int a, int b) {
        return query(a, b, 0, 0, size);
    }
private:
    // [a, b)の値を取得
    T query(int a, int b, int k, int l, int r) {
        if ( r <= a || b <= l ) {
            return unit;
        } else if ( a <= l && r <= b ) {
            return data[k];
        } else {
            T x1 = query( a, b, k * 2 + 1, l, ( l + r ) / 2 );
            T x2 = query( a, b, k * 2 + 2, ( l + r ) / 2, r );
            return func(x1, x2);
        }
    }
};


ll solve() {
    ll N;
    cin >> N;
    vector<ll> H(N), A(N);
    for ( int i = 0; i < N; i++ ) cin >> H[i];
    for ( int i = 0; i < N; i++ ) cin >> A[i];

    SegmentTree<ll> seg(N+1, 0, [](ll a, ll b) {return max(a,b);});
    seg.InitBuild();

    for ( int i = 0; i < N; i++ ) {
        ll m = seg.Query(0, H[i]);
        seg.Update(H[i], m + A[i]);
    }
    ll ans = seg.Query(0,N+1);
    return ans;
}

