const ll L = 2e5 + 5;
ll arr[L];
ll flow[L];
ll tree[4 * L];
ll h[L];
void make(ll l, ll r, ll i)
{
	if(l == r)
	{
		tree[i] = arr[l];
		return;
	}
	ll mid = (l + r) >> 1;
	make(l, mid, 2 * i + 1);
	make(mid + 1, r, 2 * i + 2);
	tree[i] = max(tree[2 * i + 1], tree[2 * i + 2]);
}
ll query(ll l, ll r, ll s, ll e, ll i)
{
	if(s <= l && r <= e)
		return tree[i];
	if(r < s || e < l)
		return INT_MIN;
	else
	{
		ll mid = (l + r) >> 1;
		ll a = query(l, mid, s, e, 2 * i + 1);
		ll b = query(mid + 1, r, s, e, 2 * i + 2);
		return max(a, b);
	}
}
void update(ll l, ll r, ll i, ll id, ll val)
{
	if(l == r)
	{
		arr[id] = val;
		tree[i] = val;
		return;
	}
	ll mid = (l + r) >> 1;
	if(id <= mid)
		update(l, mid, 2 * i + 1, id, val);
	else
		update(mid + 1, r, 2 * i + 2, id, val);
	tree[i] = max(tree[2 * i + 1], tree[2 * i + 2]);
}
