void upd(int pos , int val , int id = 1 , int l = 0 , int r = n+1){
	if(r - l < 2){
		ma[id] = max(val , ma[id]);
		return ;
	}

	int mid = (l + r) >> 1;
	if(pos < mid)
		upd(pos , val , id * 2 , l , mid);
	else
		upd(pos , val , id * 2 + 1 , mid , r );
	ma[id] = max(ma[id * 2] , ma[id * 2 + 1]); 
}

int get(int s , int e , int id = 1 , int l = 0 , int r = n+1){
	if(s >= r || l >= e){
		return 0;
	}
	if(s <= l && r <= e){
		return ma[id];
	}

	int mid = (l + r) >> 1;
	return max(get(s , e , id * 2 , l , mid ) , get(s , e , id * 2 + 1 , mid , r ));
}

