LL bit[M];
inline int lowbit(int x)
{
	return x&(-x);
}
void upd(int p,LL v)
{
	for(;p<M;p+=lowbit(p))
		bit[p]=max(bit[p],v);
}
LL getmx(int p)
{
	LL mx=0;
	for(;p;p-=lowbit(p))
		mx=max(mx,bit[p]);
	return mx;
}

