template<class T, int MAX_N>class RMQ {
	const int N = 0, sqrtN = ceil(sqrt(MAX_N));
	int B = 0;
	vector<T> A, Min;

	void UpdateMin(int i) {
		int l = i * sqrtN, r = (i + 1) * sqrtN;
		Min[i] = *min_element(A.begin() + l, A.begin() + r);
	}

public:
	RMQ(int _N) :N(_N), B((_N + sqrtN - 1) / sqrtN) {
		A.resize(sqrtN * B);
		Min.resize(B);
	}
	void update(int i, T x) {
		A[i] = x;
		UpdateMin(i / sqrtN);
	}
	//[s, t)の最大値
	T find(int s, int t) {
		T ret = 0;
		for (int i = 0; i < B; i++) {
			int l = i * sqrtN, r = (i + 1) * sqrtN;
			if (r <= s || t <= l) {
				continue;
			} else if (s <= l && r <= t) {
				ret = max(ret, Min[i]);
			} else {
				for (int j = max(s, l); j < min(t, r); j++) {
					ret = max(ret, A[j]);
				}
			}
		}
		return ret;
	}
	void Print() {
		dump(A, Min);
	}
};

