typedef long long ll;

vector<ll> t;

void build_tree(int v, int l, int r) {
    if (l==r) t[v] = 0;
    else {
        int mid = (l+r)>>1;
        build_tree(2*v, l, mid);
        build_tree(2*v+1, mid+1, r);
        t[v] = max(t[2*v],t[2*v+1]);
    }
}

void update_tree(int v, int l, int r, int pos, ll x) {
    if (l==r) t[v] = x;
    else {
        int mid = (l+r)>>1;
        if (mid>=pos) update_tree(2*v, l, mid, pos, x);
        else update_tree(2*v+1, mid+1, r, pos, x);
        t[v] = max(t[2*v], t[2*v+1]);
    }
}

ll getmax(int v, int l, int r, int sl, int sr) {
    if (sl>sr) return 0ll;
    if (l==sl && sr==r) {
        return t[v];
    } else {
        int mid = (l+r)>>1;
        return max(getmax(2*v, l, mid, sl, min(sr, mid)), getmax(2*v+1, mid+1, r, max(sl, mid+1), sr));
    }
}

