    std::vector<node> stree;
    SegmentTree(){}
    SegmentTree(int size){
        stree.resize(4*size);
    }
    node merge(node a,node b){
        return node(max(a.val,b.val),0);
    }
    // root = 1;
    void propagate(int cur,int l,int r){
        if(stree[cur].lazy==0) return;
        stree[cur].val += stree[cur].lazy*(r-l+1); // r-l+1 quantidade de elementos
        if(l!=r){
            stree[2*cur].lazy += stree[cur].lazy;
            stree[2*cur+1].lazy += stree[cur].lazy;
        }
        stree[cur].lazy = 0;
    }
    void updaterange(int cur,int l,int r,int a,int b,int x){ // l r ->posiçoes atuais
        propagate(cur,l,r);
        if(r<a || l>b){
            return;
        }
        if(a <= l && r <= b){
            stree[cur].lazy += x;
            propagate(cur,l,r);
            return;
        }
        int m = (l+r)>>1;
        updaterange(2*cur,l,m,a,b,x);
        updaterange(2*cur+1,m+1,r,a,b,x);
        propagate(cur,l,r);
        stree[cur] = merge(stree[2*cur],stree[2*cur+1]);
        return;
    }
    node query(int cur,int l,int r,int a,int b){ // l r ->posiçoes atuais
        propagate(cur,l,r);
        if(r<a || l>b){
            return node(0,0);
        }
        if(a <= l && r <= b) return stree[cur];
        int m = (l+r)>>1;
        node x = query(2*cur,l,m,a,b);
        node y = query(2*cur+1,m+1,r,a,b);
        propagate(cur,l,r);
        return merge(x,y);
    }
};
