void update(ll indx, ll val, ll ogL, ll ogR, ll si = 1) {
  if ((indx < ogL) or (indx > ogR))
    return;

  if (ogL == ogR) {
    tr[si] = max(tr[si], val);
    return;
  }
  ll mid = (ogL + ogR) >> 1;
  update(indx, val, ogL, mid, si << 1);
  update(indx, val, mid + 1, ogR, (si << 1) | 1);

  tr[si] = max(tr[si << 1], tr[(si << 1) | 1]);
}

ll query(ll l, ll r, ll ogL, ll ogR, ll si = 1) {
  if (l > r)
    return 0;
  if ((r < ogL) or (l > ogR))
    return 0; // for min change it to inf

  if ((ogL >= l) && (ogR <= r)) {
    return tr[si];
  }

  ll mid = (ogL + ogR) >> 1;
  return max(query(l, r, ogL, mid, (si << 1)),
             query(l, r, mid + 1, ogR, (si << 1) | 1));
}

