void set_val(ll *bit,int i,ll val){
    i++;
    while(i<220000){
        bit[i]=max(bit[i],val);
        i+=i&-i;
    }
}
ll max_val(ll *bit, int i){
    i++;
    ll res=0;
    while(i){
        res=max(bit[i],res);
        i-=i&-i;
    }
    return res;
}
