constexpr int MAXN = 202020;
struct SegTree
{
	vector<ll> t;

	void set(int p , ll val){
		for(t[p += MAXN] = val ; p > 1 ; p /= 2){
			t[p / 2] = max(t[p] , t[p ^ 1]);
		}
	}

	ll query(int l , int r){
		ll res = 0;
		for(l += MAXN , r += MAXN ; l < r ; l /= 2 , r /= 2){
			if(l % 2){
				res = max(res , t[l]);
				++l;
			}
			if(r % 2){
				--r;
				res = max(res , t[r]);
			}
		}
		return res;
	}

	SegTree()
		: t (2 * MAXN , 0)
	{}
} dp;

