void solve()
{
    // START
    int n;
    cin>>n;
    int height[n+5];
    rep(i,n)cin>>height[i];
    int beauty[n+5];
    rep(i,n)cin>>beauty[i];
    ll dp[n+5][n+5];
    for(int i=0;i<n;i++){
        for(int j=0;j<n;j++)
            dp[i][j]=0;
    }
    for(ll i=0;i<n;i++)
        dp[i][i]=beauty[i]*1ll;
    for(ll i=0;i<n-1;i++){
        if(height[i+1]>=height[i])
            dp[i][i+1]=(1ll*beauty[i+1])+(1ll*beauty[i]);
        else
            dp[i][i+1]=max(beauty[i],beauty[i+1]);
    }
    for(ll gap=2;gap<n;gap++){
        for(ll i=0;i<n-gap;i++){
            int j=i+gap;
            dp[i][j]=0;
            for(int k=j-1;k>=i;k--){
                if(height[j]>height[k])
                    dp[i][j]=max(dp[i][j], (dp[i][k]+1ll*beauty[j]));
            }
        }
    }
    cout<<dp[0][n-1]<<endl;
    // END
}

