struct segtree{
  int n;
  vector<ll> dat;
  segtree(int n_){
    init(n_);
  }
  void init(int n_){
    n=1;
    while(n<n_) n*=2;
    dat.resize(2*n-1);
    for(int i=0;i<2*n-1;i++) dat[i]=0;
  }
  void update(int k,ll a){
    k+=n-1;
    dat[k]=a;
    while(k>0){
      k=(k-1)/2;
      dat[k]=max(dat[k*2+1],dat[k*2+2]);
