mat mul(mat& a, mat& b, int n) {
    mat c = {};

    for(int i : range(n)) {
        for(int j : range(n)) {
            for(int k : range(n)) {
                c[i][j] += a[i][k] * b[k][j] % MOD;
                if(c[i][j] >= MOD) c[i][j] -= MOD;
