void upd(int pos, ll val, int id = 1, int l = 0, int r = n - 1)
{
    if(l == r)
    {
        seg[id] = val;
        return;
    }
    int mid = (l + r) / 2;
    if(pos <= mid) upd(pos, val, id * 2, l, mid);
    else upd(pos, val, id * 2 + 1, mid + 1, r);
    seg[id] = max(seg[id * 2], seg[id * 2 + 1]);
}
ll query(int x, int y, int id = 1, int l = 0, int r = n - 1)
{
    if(r < x || l > y) return 0;
    if(l >= x && r <= y) return seg[id];
    int mid = (l + r) / 2;
    return max(query(x, y, id * 2, l, mid), query(x, y, id * 2 + 1, mid + 1, r));
}
