const int MOD = 1000000007;


LL solve(int i, int prevH, int N, const vector<int>& h, const vector<int>& a, vector<map<int, LL>>& dp)
{
    LL ret = 0;
    if (dp[i].find(prevH) == dp[i].end()) {
        if (i == N-1) {
            ret = (prevH < h[i] ? a[i] : 0); 
        } else {
            ret = (prevH < h[i] ? max(a[i]+solve(i+1, h[i], N, h, a, dp), solve(i+1, prevH, N, h, a, dp)) : solve(i+1, prevH, N, h, a, dp));
        }
        dp[i][prevH] = ret;
    } else {
        ret = dp[i][prevH];
    }
    return ret;
}

