class segment_tree
{
   public:
   vector<ll> arr,tree;
   segment_tree(vector<ll> a)
   {
      this->arr = a;
      ll n = a.size();
      ll height = 4*n;
      ll len = 2*height -1;
      tree.resize(len);
      build(0,n-1,0);
   }

   void build(ll l, ll r, ll node)
   {
      if(l==r)
      tree[node] = arr[l];
      else
      {
         ll mid = (l+r)/2;
         build(l,mid,2*node+1);
         build(mid+1,r,2*node+2);
         tree[node] = max(tree[2*node+1] , tree[2*node+2]);
      }
   }

   void updateutil(ll l, ll r,ll i, ll diff,ll node)
   {
      if(i<l || i>r)return;
      ll mid = (l+r)/2;
      tree[node] = max(tree[node],diff);
      if(l!=r){
         updateutil(l,mid,i,diff,2*node+1);
         updateutil(mid+1,r,i,diff,2*node+2);
      }
   }

   void update(ll i, ll x)
   {
      ll diff = x;
      updateutil(0,arr.size(),i,diff,0);
   }

   ll getq(ll tl,ll tr,ll l, ll r,ll node)
   {
      if(l<=tl && r>=tr) return tree[node];

      if(l>tr || r<tl) return 0;
      ll mid = (tr+tl)/2;
      return max(getq(tl,mid,l,r,2*node+1),getq(mid+1,tr,l,r,2*node+2));
   }

};

void solve()
{
   int n;
   cin>>n;
   vl h(n),b(n);
   f(i,0,n)
   cin>>h[i];
   f(i,0,n)cin>>b[i];
