   ll ans=0;
   f(i,0,n)
   {
      ll maxi = st.getq(0,n,0,h[i]-1,0);
      dp[h[i]] = maxi+b[i];
      st.update(h[i],dp[h[i]]);
      ans=max(ans,dp[h[i]]);
   }
