const int N = 2e5+5;
ll n;
vl a, h;
ll ans=0;
ll seg[4*N];
ll query(ll l, ll r, ll v, ll ql, ll qr){
    if(ql > r || qr < l){
        return 0;
    }
    if(ql <= l && qr >= r){
        return seg[v];
    }
    ll mid = (l+r)/2;
    return max(query(l, mid, 2*v, ql, qr), query(mid+1, r, 2*v+1, ql , qr));
}
void update(ll l, ll r, ll v, ll pos, ll val){
    if(l == r){
        seg[v]=max(seg[v], val);
        return;
    }
    ll mid = (l+r)/2;
    if(pos <= mid){
        update(l, mid, 2*v, pos, val);
    }
    else{
        update(mid+1, r, 2*v+1, pos, val);
    }
    seg[v] = max(seg[2*v], seg[2*v+1]);
}
