template <class T>
struct fenwick_tree {
	vector<T> x;
	fenwick_tree(int n) : x(n, 0) { }
	T mx(int j) {
		T S = 0;
		for (j; j >= 0; j = (j & (j + 1)) - 1) S = max(S, x[j]);
		return S;

	}
	void add(int k, T a) {
		for (; k < x.size(); k |= k + 1) x[k] = max(x[k], a);
	}
};
