namespace SOLVE {
	struct fenwick { // this fenwick tree keeps maximum prefix
		int maxn; // inclusive
		VLL A; // 1-indexed! 

		void build(int n) {
			maxn = n;
			A.resize(n + 1, 0);
		}

		void update(int x, ll v) {
			if (x > maxn) {
				return;
			}
			A[x] = max(A[x], v);
			int next = x + (x & -x);
			update(next, v);
		}

		ll query(int x) {
			if (x == 0) {
				return 0;
			}
			int next = x - (x & -x);
			return max(A[x], query(next));
		}
	};

	void main() {
		int n;
		cin >> n;
		VLL height(n);
		VLL beauty(n);
		fenwick tree;
		tree.build(n + 1); // maximum height is n+1

		REP(i, 0, n) {
			cin >> height[i];
		}
		REP(i, 0, n) {
			cin >> beauty[i];
		}

		for (int flower = 0; flower < n; flower++) {
			// choose the best beauty of a flower that has height less than current height

			// grab the maximum 
			ll biggest = tree.query(height[flower] - 1);
			// update the tree at that position
			tree.update(height[flower], biggest + beauty[flower]);
		}

		ll ans = tree.query(n + 1);

		cout << ans << endl;




	}
}


