LL bit[MAX_N];

void update(int idx, LL val, int n) {
    while(idx <= n) {
        bit[idx] = max(bit[idx], val);
        idx += idx & -idx;
    }
}

LL query(int idx) {
    LL res = 0;
    while(idx > 0) {
        res = max(res, bit[idx]);
        idx -= idx & -idx;
    }
    return res;
}

