void solve()
{
    ll hm = 0;
    REP (i, N) hm = max(hm, h[i]);
    SegmentTree st(hm+1);
    REP (i, N) {
        st.update(h[i], st.query(0, h[i]) +  a[i]);
    }
    cout << st.query(0, hm+1) << endl;
}

