  st_init();
  // update
  for (long i = N - 1; i >= 0; i--) {
    const long h = hs[i], a = as[i];
    const long dp = a + st_query(h + 1, N);
    // st_print();
    // printf("i = %ld, dps[i] = %ld\n", i, dp);
    st_update(h, dp);
  }
  printf("%ld\n", st_query(0, N));
}

