using T=ll;

class SST {
public:
    const T inf = 0;
    T m(T x, T y) { return max(x, y); }
    int d; T sum;
    SST* ch[2];
    SST(int D) : d(D) {
        sum = inf;
        ch[0] = nullptr;
        ch[1] = nullptr;
    }
    ~SST() {
        if (ch[0]) delete ch[0];
        if (ch[1]) delete ch[1];
    }
    void inc(const int& i, const T& v) {
        if (!d) { sum = m(sum, v); return; }
        bool cv = i & (1ll << (d - 1));
        if (!ch[cv]) ch[cv] = new SST(d - 1);
        ch[cv]->inc(i, v);
        sum = ch[cv]->sum; if(ch[1-cv]) sum = m(sum, ch[1-cv]->sum);
    }
    T prepsum(const int& i) {
        if (!d) return sum;
        T ans = inf;
        bool cv = i & (1ll << (d - 1));
        if (ch[cv]) ans = ch[cv]->prepsum(i);
        if (cv && ch[0]) ans = m(ans, ch[0]->sum);
        return ans;
    }
    T sufpsum(const int& i) {
        if (!d) return sum;
        T ans = inf;
        bool cv = i & (1ll << (d - 1));
        if (ch[cv]) ans = ch[cv]->sufpsum(i);
        if (!cv && ch[1]) ans = m(ans, ch[1]->sum);
        return ans;
    }
    T psum(const int& l, const int& r) {
        if (!d) return sum;
        bool cv1 = l & (1ll << (d - 1));
        bool cv2 = r & (1ll << (d - 1));
        if (cv1==cv2) {
            if(!ch[cv1]) return inf;
            return ch[cv1]->psum(l, r);
        }
        T ans = inf;
        if(ch[0]) ans = m(ans, ch[0]->sufpsum(l));
        if(ch[1]) ans = m(ans, ch[1]->prepsum(r));
        return ans;
    }
};

