template<typename T>
struct SegmentTree {
    int N;
    vector<T> node;

    SegmentTree(vector<T> &v) {
        int sz = v.size();
        N = 1; while (N < sz) N *= 2;
        node.assign(2*N,0);

        for (int i = 0; i < sz; i++) node[i+N] = v[i];
        for (int i = N-1; i > 0; i--) node[i] = max(node[i<<1|0],node[i<<1|1]);
    }

    void update(int x, T val) {
        x += N;

        node[x] = val;
        while (x > 1) {
            x >>= 1;
            node[x] = max(node[x<<1|0],node[x<<1|1]);
        }
    }

    T getmax(int l, int r) {
        T res = 0;
        l += N; r += N;
        while (l < r) {
            if (l & 1) res = max(res,node[l++]);
            l >>= 1;
            if (r & 1) res = max(res,node[--r]);
            r >>= 1; 
        }

        return res;
    }    
};

