class RangeMaximumQueryTree{
public:
  vector<long long> data;
  int size;
  int height; // the number of edges between the root and leaves
  long long maximum_util(int bidx, int eidx, int data_idx, int dbi, int dei){
    if((bidx <= dbi) && (dei <= eidx)){
      return data[data_idx];
    }

    if((eidx <= dbi) || (dei <= bidx)){
      return LLONG_MIN;
    }

    int dmi = (dbi + dei) / 2;
    return max(
               maximum_util(bidx, eidx, 2 * data_idx + 1, dbi, dmi),
               maximum_util(bidx, eidx, 2 * data_idx + 2, dmi, dei)
               );
  }
public:
  RangeMaximumQueryTree(int size){
    this->size = size;
    for(height = 0; (1 << height) < size; height++){
    }
    data = vector<long long>((1 << (height + 1)) - 1, LLONG_MIN);
  }
  const long long DEFAULT_VALUE = LLONG_MIN;
  void set(int idx, long long val){
    int leaf_idx = (1 << height) - 1 + idx;
    data[leaf_idx] = val;

    for(int node_idx = (leaf_idx - 1) / 2; node_idx > 0; node_idx = (node_idx - 1) / 2){
      data[node_idx] = max(data[2 * node_idx + 1], data[2 * node_idx + 2]);
    }
    data[0] = max(data[1], data[2]);
  }
  long long maximum(int begin, int end){
    return maximum_util(begin, end, 0, 0, 1 << height);
  }
};

