    return;
  }
  int m = (tree_l + tree_r)/2;
  if(m<valix)
  {
    update(m+1,tree_r,2*treeix+1,valix,value);
  }
  else
  {
    update(tree_l,m,2*treeix,valix,value);
  }
  ll l = tree[2*treeix];
  ll r = tree[2*treeix+1];
  tree[treeix] = max(l,r);
}


