struct lazy_max_seg_tree {
  std::vector<ll> tree, lazy;
  int n, height;

  lazy_max_seg_tree(std::vector<ll> v) {
    tree = std::vector<ll>(2*(n = v.size()));
    lazy = std::vector<ll>(n);
    height = sizeof(int) * 8 - __builtin_clz(n);

    // Fill leaves i.e. tree[n, 2n-1]
    for(int i = 0; i < n; i++)
      tree[n+i] = v[i];

    // Compute parents i.e. tree[0, n-1]
    for(int i = n-1; i > 0; i--)
      tree[i] = merge(tree[2*i], tree[2*i+1]);
  }

  void incr(int l, int r, ll val) {
    int l0 = (l += n);
    int r0 = (r += n+1);
    for(; l < r; l >>= 1, r >>= 1) {
      if(l&1) propagate(l++, val);
      if(r&1) propagate(--r, val);
    }
    updateParents(l0);
    updateParents(r0-1);
  }

  ll query(int l, int r) {
    l += n, r += n+1;
    push(l);
    push(r - 1);
    ll res = identifier();
    for(; l < r; l >>= 1, r >>= 1) {
      if(l&1) res = merge(res, tree[l++]);
      if(r&1) res = merge(res, tree[--r]);
    }
    return res;
  }

private:
  void propagate(int p, ll val) {
    tree[p] += val;
    if(p < n) lazy[p] += val;
  }

  void updateParents(int p) {
    while(p > 1)
      p >>= 1, tree[p] = merge(tree[2*p], tree[2*p+1]) + lazy[p];
  }

  void push(int p) {
    for (int s = height; s > 0; s--) {
      int i = p >> s;
      if(lazy[i] == 0) continue;
      propagate(2*i, lazy[i]);
      propagate(2*i+1, lazy[i]);
      lazy[i] = 0;
    }
  }

  ll merge(ll v1, ll v2) {
    return std::max(v1, v2);
  }

  ll identifier() {
    return -1e18;
  }

};


