	if(tl == l && tr == r) return t[cur];
	int tm = (tl+tr)>>1;
	if(r <= tm) return query(2*cur+1, tl, tm, l, r);
	else if(l > tm) return query(2*cur+2, tm+1, tr, l, r);
	else return max(query(2*cur+1, tl, tm, l, tm), query(2*cur+2, tm+1, tr, tm+1, r));
}

