	} else {
		if(pos<=(l+r)/2) upd(x*2,l,(l+r)/2,pos,val);
		else upd(x*2+1,(l+r)/2+1,r,pos,val);
		seg[x]=max(seg[x*2],seg[x*2+1]);
	}
} 
long long qry(int x, int l, int r, int ql, int qr) {
	if(l==ql && r==qr) {
		return seg[x];
