		if(qr<=(l+r)/2) return qry(x*2,l,(l+r)/2,ql,qr);
		if(ql>(l+r)/2) return qry(x*2+1,(l+r)/2+1,r,ql,qr);
		else return max(qry(x*2,l,(l+r)/2,ql,(l+r)/2),qry(x*2+1,(l+r)/2+1,r,(l+r)/2+1,qr));
