using namespace std;


struct Seg {
  int l, m, r;
  long long ma = 0;
  Seg* ch[2] = {0};
  void pull() {
    ma = max(ch[0]->ma, ch[1]->ma);
  }
  Seg(int l, int r) : l(l), r(r), m(l + r >> 1) {
    if (r - l > 1) {
      ch[0] = new Seg(l, m);
      ch[1] = new Seg(m, r);
    }
  }
  void mod(int x, long long v) {
    if (r - l == 1) ma = v;
    else {
      ch[x >= m]->mod(x, v);
      pull();
    }
  }
  long long rmq(int ql, int qr) {
    if (ql <= l and r <= qr) return ma;
    else {
      long long ans = 0;
      if (ql < m) ans = max(ans, ch[0]->rmq(ql, qr));
      if (m < qr) ans = max(ans, ch[1]->rmq(ql, qr));
      return ans;
    }
  }
};

