struct flower {
    ll height;
    ll beauty;
};

ll flowers(vector<flower> &v, int n) {
    vector<ll> dp(n + 1);
    map<ll, ll> meaningful;
    // Base Case
    dp[1] = v[1].beauty;
    meaningful[v[1].height] = dp[1];
    // Bottom Up Approach
    ll ans = dp[1];
    for(int i = 2; i <= n; i++) {
        dp[i] = v[i].beauty;
        auto it = meaningful.lower_bound(v[i].height + 1);
        if(it != meaningful.begin()) {
            it--;
            dp[i] += it->second;
        }
        meaningful[v[i].height] = dp[i];
        auto it = meaningful.upper_bound(v[i].height);
        while((it != meaningful.end()) && (it->second <= dp[i])) {
            auto temp = it;
            temp++;
            meaningful.erase(it);
            it = temp;
        }
        ans = max(ans, dp[i]);
    }
    return ans;
}

