    let construct_ST_util( let arr[], let n, let cs, let ce, let cp, let * st ){
        // base case
        if( cs == ce ) {
            st[ cp ] = arr[ cs ] ;      // here cs is same as ce
            return st[ cp ] ;          // here st[ cp ] is same as arr[ cs ]
        }
        let mid = get_mid( cs , ce ) ;  // to divide the interval into two parts and then recuring them
        st[ cp ] = max( construct_ST_util( arr , n , cs , mid , 2*cp+1 , st ) ,
                   construct_ST_util( arr, n , mid+1, ce , 2*cp+2, st ) );
        return st[ cp ] ;
    }
    let get_max_util( let qs , let qe ,  let cs , let ce , let cp ){
        if( cs >= qs && ce <= qe ){
            return st[ cp ] ;
        }
        if( cs > qe || ce < qs ){
            return 0 ;
        }
        let mid = get_mid( cs , ce ) ;
        return max( get_max_util( qs , qe , cs , mid , 2*cp + 1 ) , get_max_util( qs , qe , mid+1 , ce , 2*cp + 2 ) ) ;
    }
    let max_val( let qs , let qe ){
        return get_max_util( qs , qe , 0 , size-1 , 0 ) ;
    }
    let update_util( let new_value , let pos , let cs , let ce , let cp ){
        if( cs == ce && cs != pos ) return st[cp] ;
        if( cs == ce && cs == pos ){
            st[ cp ] = new_value ;
            return st[ cp ] ;
        }
        let mid = get_mid( cs , ce ) ;
        st[ cp ] = max( update_util( new_value , pos , cs , mid , 2*cp + 1 ) ,update_util( new_value , pos , mid+1 , ce , 2*cp + 2 ) );
        return st[ cp ] ;
    }
    void update( let pos , let new_value ){
        arr[ pos ] = new_value ;
        update_util( new_value , pos , 0 , size-1 , 0 ) ;
    }
};
