// array is 0 indexed 
// segment tree values start from index 1

void build(int node,int start,int end)
{
	if (start==end)
	{
		tree[node]=a[start];
		return ;
	}
	else 
	{
		int mid=(start+end)/2;
		build(2*node,start,mid);
		build(2*node+1,mid+1,end);
		tree[node]=max(tree[2*node],tree[2*node+1]);
	}
}

void update(int node,int start,int end,int idx,int val)
{
	int mid=(start+end)/2;
	if (start==end)
	{
		tree[node]=val;
		a[idx]=val;
		return;
	}
	else if (idx>mid)
	{
		update(2*node+1,mid+1,end,idx,val);
		tree[node]=max(tree[2*node],tree[2*node+1]);	
	}
	else 
	{
		update(2*node,start,mid,idx,val);
		tree[node]=max(tree[2*node],tree[2*node+1]);	
	}
}

int query(int node,int start,int end,int left,int right)
{
	if (left<=start and end<=right)
		return (tree[node]);
	else if (right<start or left>end)
		return -INFL;
	else
	{
		int mid=(start+end)/2;
		int ans1=query(2*node,start,mid,left,right);
		int ans2=query(2*node+1,mid+1,end,left,right);
		return (max(ans2,ans1));
	}
}


