    {
        tab[v]=max(tab[v*2], tab[v*2+1]);
        v/=2;
    }

    return;
}

long long m(long long b)
{
    long long w=0;
    long long a=MAX;
    b+=MAX-1;

    w=max(tab[a], tab[b]);

    while(a/2!=b/2)
    {

        if(a%2==0)
        {
            w=max(w, tab[a+1]);
        }

        if(b%2==1)
        {
            w=max(w, tab[b-1]);
        }

        a/=2;
        b/=2;

    }

    return w;
}


