template<class T>
class Segtree{
	unsigned int n;
	unsigned int size;
	vector<T> node;
	T val;
	function< T(T,T)> f;
public:
	Segtree(unsigned int a_n, T a_val, function< T(T,T)> a_f) :n(1),val(a_val),f(a_f){
		while(n<a_n)n<<=1;
		size = n*2-1;
		node.assign(size,val);
	}
	void set(int i, T x){
		node[i+n-1]=x;
	}
	T get(int i){
		return node[i+n-1];
	}
	void update(){
		for(int i=n-2;i>=0;i--){
			node[i] = f(node[i*2+1],node[i*2+2]);
		}
	}
	void update(int i, T x){
		i += n-1;
		node[i]=x;
		while(i>0){
			i = (i-1)/2;
			node[i] = f(node[i*2+1],node[i*2+2]);
		}
	}
	T query(int a,int b){
		return _query(a,b,0,0,n);
	}
	T _query(int a,int b,int i,int l,int r){
		if(r<=a || b<=l) return val;
		if(a<=l && r<=b) return node[i];
		else{
			T vl = _query(a,b,i*2+1,l,(l+r)/2);
			T vr = _query(a,b,i*2+2,(l+r)/2,r);
			return f(vl,vr);
		}
	}
};

