struct segment {
	vector<int>st;
	int n;
	void init(int nn) {
		n = nn;
		st.clear(); st.resize(4 * n, 0);
	}

	int query(int s, int e, int qs, int qe, int index) {
		if (s > qe or e < qs)
			return 0;
		if (s >= qs and e <= qe)
			return st[index];
		int mid = (s + e) / 2;
		int q1 = query(s, mid, qs, qe, 2 * index + 1);
		int q2 = query(mid + 1, e, qs, qe, 2 * index + 2);
		return max(q1 , q2);
	}
	void update(int s, int e, int index, int i, int val) {
		if (i < s or e < i)
			return ;
		if (s == e) {
			st[index] = val;
			return ;
		}
		int mid = (s + e) / 2;
		update(s, mid, 2 * index + 1, i, val);
		update(mid + 1, e, 2 * index + 2, i, val);
		st[index] = max(st[2 * index + 1] , st[2 * index + 2]);
	}
	int query(int l, int r) {
		return query(0, n - 1, l, r, 0);
	}
	void update(int index, int ele) {
		update(0, n - 1, 0, index, ele);
	}
} tree;
void solve() {
