typedef long long ll;

class StaticRMQ {
public:
  vector <ll> dat;
  int N;

  StaticRMQ(int n) {
    init(n);
  }

  void init(int n) {
    N = 1;

    while (N < n) N *= 2;

    for (int i = 0; i < 2 * N - 1; ++i) {
      dat.push_back(0);
    }
  }

  void update(int k, ll a) {
    k += N - 1;
    dat[k] = a;

    while (k > 0) {
      k = (k - 1) / 2;
      dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  ll find_max(int l, int r) {
    return query(l, r, 0, 0, N);
  }

private:

  ll query(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) return 0;

    if (a <= l && r <= b) {
      return dat[k];
    } else {
      ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
      ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);

      return max(vl, vr);
    }
  }
};

struct Flower {
  int h;
  int a;
  int idx;

  Flower(int a = -1, int h = -1, int idx = -1) {
    this->a = a;
    this->h = h;
    this->idx = idx;
  }

  bool operator<(const Flower &f) const {
    return h < f.h;
  }
};

int main() {
  int N;
  cin >> N;
  vector<int> H;
  vector<int> A;
  map<int, int> idx;

  int a, h;
  for (int i = 0; i < N; ++i) {
    cin >> h;
    H.push_back(h);
    idx[h] = i + 1;
  }

  for (int i = 0; i < N; ++i) {
    cin >> a;
    A.push_back(a);
  }

  ll dp[N + 1];
  vector<Flower> flowers;

  for (int i = 0; i < N; ++i) {
    int h = H[i];
    int a = A[i];

    flowers.push_back(Flower(a, h, i + 1));
  }

  sort(flowers.begin(), flowers.end());
  StaticRMQ rmq(N + 1);

  for (int i = 0; i < N; ++i) {
    Flower flower = flowers[i];

    ll v = flower.a + rmq.find_max(1, flower.idx);
    rmq.update(flower.idx, v);
  }

  cout << rmq.find_max(1, N + 1) << endl;

  return 0;
}

