ll f(ll s[], ll a[], int n, int l, int r){
    if(l==r)
        s[n]=a[l];
    else{
        int m=(l+r)/2;
        s[n]=max(f(s,a,n*2,l,m),f(s,a,n*2+1,m+1,r));
    }
    return s[n];
}

ll qy(ll s[], ll a[], int n, int l, int r, int x, int y){
    if(x>r or y<l)
        return 0;
    if(x<=l and y>=r)
        return s[n];
    int m=(l+r)/2;
    return max(qy(s,a,n*2,l,m,x,y),qy(s,a,n*2+1,m+1,r,x,y));
}

void u(ll s[], ll a[], int n, int l, int r, int i, ll v){
    if(l==r){
        s[n]=v;
        return ;
    }
    int m=(l+r)/2;
    if(i<=m)
        u(s,a,n*2,l,m,i,v);
    else
        u(s,a,n*2+1,m+1,r,i,v);
    s[n]=max(s[n*2],s[n*2+1]);
}

