void init(int i,int l,int r){
	 if(l==r){tr[i]=l;return;}
	 int m=l+(r-l)/2;
	 init(2*i+1,l,m);
	 init(2*i+2,m+1,r);
	 if(h[tr[2*i+1]]<h[tr[2*i+2]])tr[i]=tr[2*i+1];
	 else tr[i]=tr[2*i+2];
}
int qry(int i,int l,int r,int l1,int r1,int nn){
	if(l>r1||r<l1)return inf;
	if(l>=l1&&r<=r1&&h[tr[i]]>nn)return tr[i];
	if(l==r)return inf;
	int m=l+(r-l)/2;
	int lft=qry(2*i+1,l,m,l1,r1,nn);
	int rit=qry(2*i+2,m+1,r,l1,r1,nn);
	if(rit==inf)return lft;
	else if(lft==inf)return rit;
	if(min(h[lft],h[rit])<=nn)return inf;
	else if(h[lft]<=nn)return rit;
	else if(h[rit]<=nn)return lft;
	return (h[lft]<h[rit])?lft:rit;
}
ll rec(int i){
	ll x=0;
	for(int j:ed[i]){
		x=max(x,rec(j));
	}
	return dp[i]=v[i]+x;
}
