template <typename T>
struct sqrt_max {
    vector<T> buckets, data;
    const int ext_sq;
    sqrt_max(int n, int ext_sq = 500) : 
        ext_sq(ext_sq),
        data(n, 0),
        buckets(n / ext_sq + 1, 0) {}

    void insert(int pos, T val) {
        data[pos] = max(data[pos], val);
        int bucket_id = pos / ext_sq;
        buckets[bucket_id] = max(buckets[bucket_id], val);
    }

    T best(int pos) {
        T result = 0;
        int i = 0;
        for(int i = 0; (i + 1) * ext_sq <= pos ; i++)
            result = max(result, buckets[i]);
        int j = i * ext_sq;
        for(; j <= pos; j++)
            result = max(result, data[j]);
        return result;
    }
};

template <typename T>
struct seg_max {
    int n;
    vector<T> data;
    seg_max(int n) {
        int k = 1;
        while(k < n) k <<= 1;
        this->n = k;
        data.resize(2 * k, 0);
    }

    void insert(int pos, T val) {
        pos += n;
        while(pos > 0) {
            data[pos] = max(data[pos], val);
            pos /= 2;
        }
    }

    T best(int pos) {
        pos += n;
        T result = 0;
        while(pos > 0) {
            result = max(result, data[pos]);
            if(pos % 2 == 1)
                pos /= 2;
            else if(pos & (pos - 1))
                pos = (pos - 1) / 2;
            else
                break;
        }
        return result;
    }
};

