template <typename T>
struct BIT {
  int size;
  vector<T> tree;

  BIT(int sz) : size(sz), tree(sz + 1, T()) {}

  void update(int i, T v) {
    i++;
    while (i <= size) {
      tree[i] = tree[i] + v;
      i += i & (-i);
    }
  }

  // prefix sum up to index i
  T query(int i) {
    i++;
    T res = T();
    while (i > 0) {
      res = res + tree[i];
      i -= i & (-i);
    }
    return res;
  }
};

