//[a,b]の最小値を求める
//後ろの方の引数は計算の簡単のための引数
//kは節点番号，l.rはその節点が[l,r]に対応づいていることを表す
//従って外からはquery(a,b,0,0,n-1)として呼ぶ
LL query(int a,int b,LL k,int l,int r){
    //[a,b]と[l,r]が交差しなければINT_MAX
    if(r<a||b<l)return 1e12;
    //[a,b]が[l,r]を完全に含んでいればこの節点の値
    if(a<=l&&r<=b)return dat[k];
    else{
       //そうでなければ2つの子の最小値
       LL vl=query(a,b,k*2+1,l,(l+r)/2);
       LL vr=query(a,b,k*2+2,(l+r)/2+1,r);
       return min(vl,vr);
    }
}

