// dp[i] = maior soma de belezas se a ultima flor pega for a de altura i

void update(int node, int tl, int tr, int pos, long long val){
    if(tl == tr){
        tree[node] = val;
        return;
    }

    int mid = (tl + tr) >> 1;

    if(pos <= mid) update(2*node, tl, mid, pos, val);
    else update(2*node+1, mid+1, tr, pos, val);

    tree[node] = max(tree[2*node], tree[2*node+1]);
}

long long query(int node, int tl, int tr, int l, int r){
    if(tl > r or tr < l) return 0;
    if(tl >= l and tr <= r) return tree[node];

    int mid = (tl + tr) >> 1;

    return max(query(2*node, tl , mid, l, r), query(2*node+1, mid+1, tr, l, r));
}

