template<typename Monoid,typename Operator>
struct SegmentTree{
    private:
    typedef function<Monoid(Monoid,Monoid)> F;
    typedef function<Monoid(Monoid,Operator)> G;
    int n;
    F f;
    G g;
    Monoid id;
    vector<Monoid> dat;
    public:
    SegmentTree(int n_,F f,G g,Monoid id){
        this->f=f;
        this->g=g;
        this->id=id;
        init(n_);
    }
    void init(int n_){
        n=1;
        while(n<n_){
            n*=2;
        }
        dat.resize(2*n-1,id);
    }
    void build(int n_,vector<Monoid> v){
        rep(i,n_){
            dat[i+n-1]=v[i];
        }
        for (int i=n-2;i>=0;i--){
            dat[i]=f(dat[2*i+1],dat[2*i+2]);
        }
    }
    void update(int i,Operator a){
        i+=n-1;
        dat[i]=g(dat[i],a);
        while(i>0){
            i=(i-1)/2;
            dat[i]=f(dat[2*i+1],dat[2*i+2]);
        }
    }
    Monoid query(int a,int b,int k,int l,int r){
        if (r<=a||b<=l){
            return id;
        }
        if (a<=l&&r<=b){
            return dat[k];
        }
        Monoid vl=query(a,b,2*k+1,l,(l+r)/2);
        Monoid vr=query(a,b,2*k+2,(l+r)/2,r);
        return f(vl,vr);
    }
    Monoid query(int a,int b){
        return query(a,b,0,0,n);
    }
};

