                            ,[](ll a,ll b){return a+b;},0);
    rep(i,N){
        ll M=Seg.query(0,h[i]+1);
        Seg.update(h[i],M+a[i]);
    }
    ll ans=Seg.query(0,N);
    cout << ans << endl;
}

