template <class T>
struct segtree {
  // monoid f(X,X) -> X
  // 1. associative law f(f(a,b),c) = f(a,f(b, c))
  // 2. indentity element f(a, ie) = f(ie, a) = a
  // example) min, max, sum
 private:
  int n;
  vector<T> node;
  T IE;  // identity element of operation
  function<T(T, T)> operation;
  function<T(T, T)> update;
  /////////////////////////////////////////////////
  T query_sub(int a, int b, int k, int l, int r) {
    if (r <= a || b <= l) {
      return IE;
    } else if (a <= l && r <= b) {
      return node[k];
    } else {
      T vl = query_sub(a, b, 2 * k + 1, l, (l + r) / 2);
      T vr = query_sub(a, b, 2 * k + 2, (l + r) / 2, r);
      return operation(vl, vr);
    }
  }
  /////////////////////////////////////////////////
 public:
  segtree(size_t _n, T _IE, function<T(T, T)> _operation,
          function<T(T, T)> _update)
      : IE(_IE), operation(_operation), update(_update) {
    n = 1;
    while (n < _n) n *= 2;
    node = vector<T>(2 * n - 1, IE);
  }
  /////////////////////////////////////////////////
  void change(int i, T x) {
    i += n - 1;
    node[i] = update(node[i], x);
    while (i > 0) {
      i = (i - 1) / 2;
      node[i] = operation(node[i * 2 + 1], node[i * 2 + 2]);
    }
  }
  /////////////////////////////////////////////////
  T query(int a, int b) { return query_sub(a, b, 0, 0, n); }
  /////////////////////////////////////////////////
  T operator[](int i) { return node[i + n - 1]; }
};
////////////////////////////////////////////////
int main() {
  ////////////////////////////////////////////////
  cin.tie(nullptr);
  ios_base::sync_with_stdio(false);
  ////////////////////////////////////////////////
  int n;
  cin >> n;
  vecll h(n, 0), a(n, 0);
  REPe(e, h) cin >> e;
  REPe(e, a) cin >> e;
  auto f = [](ll a, ll b) -> ll { return max(a, b); };
  auto g = [](ll a, ll b) -> ll { return b; };
  segtree<ll> sgt(n + 1, 0LL, f, g);
  vecll dp(n, 0);
  // REP(i, n) { cout << sgt[i] << endl; }
  REP(i, n) {
    dp[i] = sgt.query(0LL, h[i]) + a[i];
    sgt.change(h[i], dp[i]);
  }
  ll ans = 0;
  REP(i, n) {
    ans = max(dp[i], ans);
    // cout << dp[i] << endl;
  }
  cout << ans << endl;
}

