void update(int idx, int lup, int rup, ll val, int l, int r) {
    if (lup <= l && r <= rup) {
        tree[idx] = val;
        return;
    }
    if (lup > r || l > rup)
        return;
    int mid = (l + r) / 2;
    update(2 * idx, lup, rup, val, l, mid);
    update(2 * idx + 1, lup, rup, val, mid + 1, r);
    tree[idx] = max(tree[2 * idx], tree[2 * idx + 1]);
