void update(ll index, ll start, ll end, ll x, ll val)
{
	if(start > x or end < x) return;

	if(start == end && start == x){
		seg[index] = val;
		return;
	}

	ll mid = (start+end)/2;
	update(index*2, start, mid, x, val);
	update(index*2+1, mid+1, end, x, val);

	seg[index] = max(seg[index*2] , seg[index*2+1]);
}
ll find(ll index, ll start, ll end, ll l, ll r)
{
	if(start > r or end < l) return 0;

	if(start >= l and end <= r) return seg[index];

	ll mid = (start+end)/2;
	ll lv = find(index*2, start, mid, l, r);
	ll rv = find(index*2+1, mid+1, end, l, r);
	return max(lv,rv);
}

