class BIT {//binary indexed tree, Fenwick treeとも
	int lg;
	std::vector<long long> bit;
public:
	BIT(int size) :bit(size + 1, 0) {
		lg = size;
		while (lg&lg - 1)lg &= lg - 1;
	}
	void insert(int i, long long x) {//i番目にx加える
		i++;//BIT添え字は1～ｎだから
		while (i < (int)bit.size()) {
			bit[i] = std::max(bit[i], x);
			i += i & -i;
		}
	}
	long long max(int a)const {
		a++;
		long long res = 0;
		while (0 < a) {
			res = std::max(res, bit[a]);
			a -= a & -a;
		}
		return res;
	}
};


