    up(nod*2+1,mid(l,r)+1,r,x,val);
    tree[nod]=max(tree[nod*2],tree[nod*2+1]);
}
int ck(int x,int y,int l,int r)
{
    if(x<=l&&r<=y)return 1;
    else if(y<l||r<x)return 3;
    else return 2;
}
long long q(int nod,int l,int r,int x,int y)
{
    int c=ck(x,y,l,r);
    if(c==1)return tree[nod];
    else if(c==3)return 0;
    else
    {
        long long s=q(nod*2,l,mid(l,r),x,y);
        long long ss=q(nod*2+1,mid(l,r)+1,r,x,y);
        return max(s,ss);
    }
}
