struct SegmentTree
{
private:
    int n;
    vector<ll> node;

public:
    SegmentTree(int sz)
    {
        n = 1;
        while (n < sz)
            n *= 2;
        node.resize(2 * n - 1, 0);
        for (int i = 0; i < sz; i++)
            node[i + n - 1] = 0;
        for (int i = n - 2; i >= 0; i--)
            node[i] = max(node[2 * i + 1], node[2 * i + 2]);
    }

    void update(int x, ll val)
    {
        x += (n - 1);
        node[x] = val;
        while (x > 0)
        {
            x = (x - 1) / 2;
            node[x] = max(node[2 * x + 1], node[2 * x + 2]);
        }
    }

    ll getmax(int a, int b, int k = 0, int l = 0, int r = -1)
    {
        if (r < 0)
            r = n;
        if (r <= a || b <= l)
            return 0;
        if (a <= l && r <= b)
            return node[k];

        ll vl = getmax(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = getmax(a, b, 2 * k + 2, (l + r) / 2, r);
        return max(vl, vr);
    }
};
