ll query(int index, int left, int right, int tar) {
    if (left > tar)
        return 0;
    if (right <= tar)
        return seg[index];
    int mid = (left + right) / 2;
    return max(query(2 * index, left, mid, tar), query(2 * index + 1, mid + 1, right, tar));
}
void update(int index, int left, int right, int pos, ll val) {
    if (left == right) {
        seg[index] = max(seg[index], val);
        return;
    }
    int mid
     = (left + right) / 2;
    if (pos <= mid)
        update(2 * index, left, mid, pos, val);
    else
        update(2 * index + 1, mid + 1, right, pos, val);
    seg[index] = max(seg[2 * index], seg[2 * index + 1]);
}
