void updateTree(int node,int l,int r,int height,int val){
	if(l==r){
		tree[node] = max(tree[node],val);
		return;
	}
	int mid=(l+r)/2;
	if(mid>=height)
		updateTree(2*node,l,mid,height,val);
	else
		updateTree(2*node+1,mid+1,r,height,val);

	tree[node] = max(tree[2*node],tree[2*node+1]);
}

int queryTree(int node,int l,int r,int ql,int qr){
	if(ql<=l && r<=qr)
		return tree[node];

	if(qr<l || ql>r)
		return 0;

	int mid = (l+r)/2;
	int left = queryTree(2*node,l,mid,ql,qr);
	int right = queryTree(2*node+1,mid+1,r,ql,qr);
	return max(left,right);
}


