#include <bits/stdc++.h>
using namespace std;
using LL = long long;

class LazySegmentTree{
private:
    int size_;
    vector<LL> v, lazy;
    void update(int a, int b, LL x, int k, int l, int r){
        push(k, l, r);
        if(r <= a || b <= l) return;
        if(a <= l && r <= b){
            lazy[k] = x;
            push(k, l, r);
        }else{
            update(a, b, x, k * 2,                l, (l + r) >> 1);
            update(a, b, x, k * 2 + 1, (l + r) >> 1,            r);
            v[k] = merge(v[k * 2], v[k * 2 + 1]);
        }
    }
    LL query(int a, int b, int k, int l, int r){
        push(k, l, r);
        if(r <= a || b <= l) return 0;
        if(a <= l && r <= b) return v[k];
        LL lc = query(a, b, k * 2,                l, (l + r) >> 1);
        LL rc = query(a, b, k * 2 + 1, (l + r) >> 1,            r);
        return merge(lc, rc);
    }

public:
    LazySegmentTree() : v(vector<LL>()), lazy(vector<LL>()) {};
    LazySegmentTree(int n){
        for(size_ = 1; size_ < n;) size_ <<= 1;
        v.resize(size_ * 4,0);
        lazy.resize(size_ * 4,0);
    }
    inline void push(int k, int l, int r){
        if(lazy[k] != 0){
            v[k] += lazy[k];
            if(r - l > 1){
                lazy[k * 2]     += lazy[k];
                lazy[k * 2 + 1] += lazy[k];
            }
            lazy[k] = 0;
        }
    }
    inline LL merge(LL x, LL y){
        return max(x, y);
    }
    inline void update(int l, int r, LL x){
        update(l, r, x, 1, 0, size_);
    }
    inline LL query(int l, int r){
        return query(l, r, 1, 0, size_);
    }
};

