void update(int l, int r, int x, ll v, int p){
    if(l > x || r < x)return;
    if(l == r){
        tree[p] = v;
    }else{
        int m = (l + r) >> 1;
        update(l, m, x, v, p << 1);
        update(m + 1, r, x, v, p << 1 | 1);
        tree[p] = max(tree[p << 1], tree[p << 1 | 1]);
    }
