ll count(int l, int r, int L, int R, int p){
    if(l > R || L > r)return 0;
    if(L <= l && R >= r)return tree[p];
    int m = (l + r) >> 1;
    return max(count(l, m, L, R, p << 1), count(m + 1, r, L, R, p << 1 | 1));
}
