vector<ll> s_tree;

void update(int tpos, int l, int r, int pos, ll val){
	if(l > r) return;
	if(l==r && l==pos){
		s_tree[tpos] = val;
		return;
	}
	int m = (l+r) >> 1;
	if(pos<=m)
		update(tpos*2,l,m,pos,val);
	else
		update(tpos*2+1,m+1,r,pos,val);	
	s_tree[tpos] = max(s_tree[tpos*2],s_tree[tpos*2+1]);
}
ll get_max(int tpos, int tl, int tr,int l, int r){
	if(tl > tr) return 0;
	if(tr < l || tl > r) return 0;
	if(tr <= r && tl >= l) return s_tree[tpos];
	int m = (tl+tr) >> 1;
	return max(get_max(tpos*2,tl,m,l,r),get_max(tpos*2+1,m+1,tr,l,r));
}


