	}
	if(r<st || ed<l)
		return 0;
	int mid = (st+ed)/2;
	ll ans1 = query(2*node,st,mid,l,r);
	ll ans2 = query(2*node+1,mid+1,ed,l,r);

	return max(ans1,ans2);
