int solve(int h[],int b[],int n)
{
    int dp[n];
    dp[0]=b[0];
    map<int,int> m;
    m[h[0]]=dp[0];
    int ans=b[0];
    for(int i=1;i<n;i++)
    {
        dp[i]=b[i];
        auto it=m.upper_bound(h[i]);
        if(it!=m.begin())
        {
            it--;
            dp[i]+=it->second;
        }
        m[h[i]]=dp[i];
        ans=max(ans,dp[i]);
        it=m.upper_bound(h[i]);
        while(it!=m.end()&&it->second<=dp[i])
        {
            auto temp=it;
            m.erase(it);
            it=temp;
            it++;
        }
    }
    return ans;
}
