using namespace std;

struct Flower
{
    int height;
    int beauty;
};

ll getBestOption(map<int,ll>& heightToBeauty, int height)
{
    auto it = heightToBeauty.lower_bound(height);
    if(it == heightToBeauty.begin())
        return 0;
    it--;
    return it->second;
}

void handleInsert(map<int,ll>& heightToBeauty, int height, ll beauty)
{
    heightToBeauty[height] = beauty;
    auto it = heightToBeauty.find(height);

    auto prev = it;
    auto next = it;
    prev--; next++;

    if(it != heightToBeauty.begin() && prev->second >= beauty)
    {
        heightToBeauty.erase(height);
        return;
    }

    while(next != heightToBeauty.end() && next->second <= it->second)
    {
            auto temp = next;
            temp++;
            heightToBeauty.erase(next->first);
            next = temp;
    }

}

ll solve(vector<Flower>& flowers)
{
    ll maxBeauty = flowers[0].beauty;
    map<int, ll> heightToBeauty;
    heightToBeauty[flowers[0].height] = flowers[0].beauty;

    for(int idx = 1; idx < flowers.size(); idx++)
    {
        ll beautyHere = flowers[idx].beauty + getBestOption(heightToBeauty,flowers[idx].height);
        maxBeauty = max(maxBeauty, beautyHere);
        handleInsert(heightToBeauty, flowers[idx].height, beautyHere);
    }

    return maxBeauty;
}

