const int maxn = 2e5 + 10;
int n;
int h[maxn], a[maxn];
long long bit[maxn];
long long dp[maxn];
long long val[maxn];


struct SegNode {
	int left, right;
	long long max;

	int mid() {
		return (left + right) >> 1;
	}
};

struct SegTree {

	SegNode tree[maxn*5];

	void pushUp(int idx) {
		tree[idx].max = max(tree[idx<<1].max, tree[idx<<1|1].max);
	}

	void build(int left, int right, int idx) {
		tree[idx].left = left;
		tree[idx].right = right;
		tree[idx].max = 0;
		if (left == right) {
			tree[idx].max = val[left];
			return ;
		}
		int mid = tree[idx].mid();
		build(left, mid, idx<<1);
		build(mid+1, right, idx<<1|1);
		pushUp(idx);
	}

	void update(int left, int right, int idx, long long value) {
		if (left == tree[idx].left && right == tree[idx].right) {
			tree[idx].max = value;
			return ;
		}
		int mid = tree[idx].mid();
		if (right <= mid)
			update(left, right, idx<<1, value);
		else if (left > mid)
			update(left, right, idx<<1|1, value);
		else {
			update(left, mid, idx<<1, value);
			update(mid+1, right, idx<<1|1, value);
		}
		pushUp(idx);
	}

	long long query(int left, int right, int idx) {
		if (tree[idx].left == left && tree[idx].right == right)
			return tree[idx].max;
		int mid = tree[idx].mid();
		if (right <= mid) 
			return query(left, right, idx<<1);
		else if (left > mid) 
			return query(left, right, idx<<1|1);
		return max(query(left, mid, idx<<1), query(mid+1, right, idx<<1|1));
	}

};
SegTree tree;

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i) {
        scanf("%d", &h[i]);
        val[i] = 0;
    }
    for (int i = 1; i <= n; ++i) {
        scanf("%d", &a[i]);
    }
    tree.build(1, n, 1);
    long long result = 0;
    for (int i = 1; i <= n; ++i) {
        dp[i] = a[i] + tree.query(1, max(1, h[i] - 1), 1);
        // printf("%d %lld %lld\n", h[i], tree.query(1, h[i], 1), dp[i]);
        tree.update(h[i], h[i], 1, dp[i]);
        result = max(result, dp[i]);
    }
    printf("%lld\n", result);
}

