class SegmentTree{
    int n;
    vector<ll> node;

    public:
    SegmentTree(vector<ll> v){
        int sz = v.size();
        n = 1;
        while(n < sz) n *= 2;
        node.resize(2*n-1);

        for(int i = 0; i < sz; i++)
            node[i+n-1] = v[i];
        for(int i = 0; i < n; i++)
            node[i] = max(node[2*i+1], node[2*i+2]);
    }

    void update(int x, ll val){
        x = x + n - 1;
        node[x] = val;

        while(x > 0){
            x = (x-1) / 2;
            node[x] = max(node[2*x+1], node[2*x+2]);
        }
    }

    //[a, b)
    ll getmax(int a, int b, int k=0, int left=0, int right=-1){
        if(right < 0)
            right = n;

        if(right <= a || b <= left)
            return 0;

        if(right <= b && a <= left)
            return node[k];

        ll lv = getmax(a, b, 2*k+1, left, (left+right)/2);
        ll rv = getmax(a, b, 2*k+2, (left+right)/2, right);
        return max(lv, rv);
    }

};

