using namespace std;

struct node {

	long long seg_st, seg_en, seg_mid;
	long long val;
	node *left, *right;

	node(long long st, long long en) {

		seg_st = st;
		seg_en = en;
		seg_mid = (st + en) / 2;
		val = 0;
		if (st == en) return;
		left = new node(st, seg_mid);
		right = new node(seg_mid+1, en);

	}

	void update(long long pos, long long to) {
		if (pos < seg_st || pos > seg_en) return;
		if (seg_st == seg_en) {
			val = to;
			return;
		}
		left->update(pos, to);
		right->update(pos, to);
		val = max(left->val, right->val);
	}

	long long query(long long le, long long ri) {
		if (le > seg_en) return INT_MIN;
		if (ri < seg_st) return INT_MIN;
		if (le <= seg_st && seg_en <= ri) return val;
		return max(left->query(le, ri), right->query(le, ri));
	}

} *root;

void init(long long x) {
	root = new node(0, x-1);
}

void update(long long pos, long long to) {
	root->update(pos, to);
}

long long query(long long a, long long b) {
	return root->query(a, b);
}

