using namespace std;

struct segment {
    int l,r;
    long long mx;
};

segment t[600006];
long long dp[200005];
int h[200005],a[200005];

void build(int l,int r,int idx) {
    t[idx] = {l,r,0};
    if (l == r)
        return;

    int mid;

    mid = (l + r) >> 1;

    build(l,mid,(idx << 1));
    build(mid + 1,r,(idx << 1) + 1);
}

void update(int pos,long long val,int idx) {
    if (pos == t[idx].l && pos == t[idx].r) {
        t[idx].mx = val;
        return;
    }

    int mid;

    mid = (t[idx].l + t[idx].r) >> 1;

    if (pos <= mid)
        update(pos,val,(idx << 1));
    else
        update(pos,val,(idx << 1) + 1);

    t[idx].mx = max(t[(idx << 1)].mx,t[(idx << 1) + 1].mx);
}

long long query(int l,int r,int idx) {
    if (l == t[idx].l && r == t[idx].r)
        return t[idx].mx;

    int mid;

    mid = (t[idx].l + t[idx].r) >> 1;

    if (r <= mid)
        return query(l,r,(idx << 1));
    else if (l > mid)
        return query(l,r,(idx << 1) + 1);
    else
        return max(query(l,mid,(idx << 1)),query(mid + 1,r,(idx << 1) + 1));
}

