typedef long long ll;

const int N = 200005;

int h[N], b[N]; ll tree[3 * N];

void update(int p, int l, int r, int i, ll v) {
  if (i > r || i < l) return;
  if (l >= i && r <= i) {
    tree[p] += v;
    //cout << "P: " << p << " " << tree[p] << endl;
    return;
  }
  int m = (l + r) >> 1;
  update(p * 2, l, m, i, v);
  update(p * 2 + 1, m + 1, r, i, v);
  tree[p] = max(tree[p * 2], tree[p * 2 + 1]);
}

ll query(int p, int l, int r, int i, int j) {
  if (i > r || j < l) return 0;
  if (l >= i && r <= j) return tree[p];
  int m = (l + r) >> 1;
  return max(query(p * 2, l, m, i, j), query(p * 2 + 1, m + 1, r, i, j));
}

