ull size;

ull get_idx(ull height,ull START,ull END)
{
  if(START==END)return START;
  ull MID = (START+END)/2;
  if(dp[MID].first<height)
  {
    return get_idx(height,MID+1,END);
  }
  else
  {
    return get_idx(height,START,MID);
  }
}

ull get_delete_size(ull beauty,ull START,ull END)
{
  if(START==END)
  {
    return dp[START].second<=beauty?1:0;
  }
  ull MID = (START+END)/2;
  if(dp[MID].second<=beauty)
  {
    return MID-START+1+get_delete_size(beauty,MID+1,END);
  }
  else
  {
    return get_delete_size(beauty,START,MID);
  }
}

void insert(pair<ull,ull> flower)
{
  ull idx = get_idx(flower.first,0,size);
  if(idx)
  {
    flower.second += dp[idx-1].second;
  }
  if(idx<size)
  {
    ull delete_size = get_delete_size(flower.second,idx,size);
    if(delete_size>1)
    {
      for(ull i=idx+1;i+delete_size<size;++i)
      {
        dp[i]=dp[i+delete_size-1];
      }
      size -= delete_size;
    }
    else if(delete_size==0)
    {
      for(ull i=size;i>idx;--i)
      {
        dp[i]=dp[i-1];
      }
    }
    else
    {
      --size;
    }
  }
  dp[idx]=flower;
  ++size;
}

