        tree[idx2] = val;
        return;
    }

    ll mid = (l + r) / 2;
    if (idx1 <= mid)
        update(l, mid, idx1, idx2 * 2, val);
    else
        update(mid + 1, r, idx1, idx2 * 2 + 1, val);

    tree[idx2] = max(tree[idx2 * 2], tree[idx2 * 2 + 1]);

}

ll query(ll l, ll r, ll idx, ll st, ll en) {
