    update(2*idx, l, mid, pos, val);
    update(2*idx+1, mid+1, r, pos, val);
    tree[idx]=max(tree[2*idx], tree[2*idx+1]);
}

int query(int idx, int l, int r, int x){
    if(l > r)
        return 0;
    if(x < l)
