struct BIT {
	vector<ll> bit;
	const int N;

	void upd(int idx, ll v) {
		for (int i = idx; i <= N; i += i & -i)
			chkmax(bit[i], v);
	}

	ll qry1(int idx) {
		ll ans = 0;
		for (int i = idx; i > 0; i -= i & -i)
			chkmax(ans, bit[i]);
		return ans;
	}

	BIT(int sz) : N(sz) {
		bit.resize(N + 1, 0);
	}
};
int main() {
	int n; R(n);
	vector<int> h(n); R(h);
	vector<ll> a(n); R(a);

	BIT bit(n);
	vector<ll> dp(n + 1, 0);
	for (int i = 0; i < n; i++) {
		ll v = bit.qry1(h[i] - 1);
		bit.upd(h[i], v + a[i]);
	}

	W(bit.qry1(n));

	return 0;
}

