ll mod=1e9+7;
const int nax=2e5+5; 

void self_mul(int &a, int b){
  a=(ll)a*b%mod; 
}
int add(int a, int b){
  return (a+b)%mod; 
}
ll tree[nax*4]; 
void update(int i, ll val, int p=1, int l=1, int r=nax){
  if(l>i || r<i) return; 
  else if(l==r){
    tree[p]=max(tree[p],val); 
  }
  else {
    int m=(l+r)>>1; 
    int c1=p<<1, c2=p<<1|1; 
    update(i,val,c1,l,m); 
    update(i,val,c2,m+1,r); 
    tree[p]=max(tree[c1],tree[c2]); 
  }
}
ll maxx(int i, int j, int p=1, int l=1, int r=nax){
  if(r<i || l>j) return 0; 
  else if(i<=l && r<=j) return tree[p]; 
  else {
    int m=(l+r)>>1; 
    int c1=p<<1, c2=p<<1|1; 
    ll a=maxx(i,j,c1,l,m); 
    ll b=maxx(i,j,c2,m+1,r); 
    return max(a,b); 
  }
}

