const int SIZE = 4e6 + 5;
vector<ll> tree, lazy;
vector<ll> a;
int defval = -1;

void build(int start, int end, int node){
    if(start > end)
        return;
    if(start == end){
        tree[node] = a[start];
        return;
    }
    int mid = start + (end - start) / 2;
    build(start, mid, 2 * node + 1);
    build(mid + 1, end, 2 * node + 2);

    tree[node] = max(tree[2 * node + 1], tree[2 * node + 2]);
}

void upd(int start, int end, int node, int idx, ll val){
    if(start > end || idx < start || idx > end)
        return;

    if(start == end){
        assert(idx == start);
        a[idx] += val;
        tree[node] += val;
        return;
    }

    int mid = start + (end - start) / 2;
    if(idx >= start && idx <= mid)
        upd(start, mid, 2 * node + 1, idx, val);
    else
        upd(mid + 1, end, 2 * node + 2, idx, val);

    tree[node] = max(tree[2 * node + 1], tree[2 * node + 2]);
}

ll query(int start, int end, int node, int left, int right){
    if(start > end || left > end || right < start)
        return defval;
    if(left <= start && end <= right){
        return tree[node];
    }

    int mid = start + (end - start) / 2;
    ll ans1 = query(start, mid, 2 * node + 1, left, right);
    ll ans2 = query(mid + 1, end, 2 * node + 2, left, right);
    ll ans = max(ans1, ans2);
    return ans;
}

void clr(int node){
    tree[node] += lazy[node];
    if(2 * node + 2 < lazy.size()){
        lazy[2 * node + 1] += lazy[node];
        lazy[2 * node + 2] += lazy[node];
    }
    lazy[node] = 0;
}

void updr(int start, int end, int node, int left, int right, int val){
    if(start > end || left > end || right < start)
        return;

    clr(node);
    if(start >= left && end <= right){
        tree[node] += val;
        if(2 * node + 2 < lazy.size()){ 
            lazy[2 * node + 1] += val;
            lazy[2 * node + 2] += val;
        }
        return;
    }

    int mid = start + (end - start) / 2;
    updr(start, mid, 2 * node + 1, left, right, val);
    updr(mid + 1, end, 2 * node + 2, left, right, val);
}

void solve(){
    ll n,i,j,k,l,p;
    cin >> n;
    a.resize(n + 1, 0);
    tree.resize(SIZE);
    build(0, n, 0);

    vector<ll> heights(n), val(n);
    for(auto &i : heights){
        cin >> i;
    }

    for(auto &i : val){
        cin >> i;
    }

    for(i = 0; i < n; i++){
        ll ans = query(0, n, 0, 0, heights[i] - 1);
        upd(0, n, 0, heights[i], val[i] + ans);
    }

    cout << query(0, n, 0, 0, n) << endc;
}

int32_t main(){
    init;
    int t = 1;
    // cin >> t;
    while(t--){
        solve();
    }
    return 0;
}

