void search(const ll N, const int pos, const vll& h, const vll& a, vll& dp){
  if(N-1==pos){
    dp[pos] = a[pos];
    return;
  }
  search(N, pos+1, h, a, dp);
  ll ans = a[pos];
  rep(i, pos+1, N){
    if(h[pos] >= h[i]) continue;
    ans = max(ans, dp[i]+a[pos]);
  }
  dp[pos] = ans;
  return;
}

