void upd(int v, int tl, int tr, int id, ll val) {
    if (tl == tr) {
        t[v] = val;
        return;
    }
    int tm = (tl + tr) / 2;
    if (id <= tm) upd(v * 2, tl, tm, id, val);
    else upd(v * 2 + 1, tm + 1, tr, id, val);
    t[v] = max(t[v * 2 + 1], t[v * 2]);
}

ll get(int v, int tl, int tr, int l, int r) {
    if (l <= tl && tr <= r) {
        return t[v];
    }
    if (l > tr || r < tl) {
        return 0;
    }
    int tm = (tl + tr) / 2;
    return max(get(v * 2, tl, tm, l, r), get(v * 2 + 1, tm + 1, tr, l, r));
}

