struct ST {
	LL maxv[4*MAXN];
	void set(int p, LL v, int l, int r, int idx) {
		if (p == l && p == r) {
			maxv[idx] = v;
			return;
		}
		int m = (l + r) >> 1;
		if (p <= m) this->set(p, v, l, m, idx << 1);
		else this->set(p, v, m + 1, r, idx << 1 | 1);
		maxv[idx] = max(maxv[idx << 1], maxv[idx << 1 | 1]);
	}
	LL query(int ql, int qr, int l, int r, int idx) {
		if (ql > r || qr < l) return 0;
		if (ql <= l && r <= qr) return maxv[idx];

		int m = (l + r) >> 1;
		LL q1 = query(ql, qr, l, m, idx << 1);
		LL q2 = query(ql, qr, m + 1, r, idx << 1 | 1);
		return max(q1, q2);
	}
