void build(vl&arr,int index,int l,int r){
	if(l>r) return;
	if(l==r){
		seg[index]=arr[l];
		no[index]=l;
		return;
	}
	ll mid=l+(r-l)/2;
	build(arr,2*index,l,mid);
	build(arr,2*index+1,mid+1,r);
	seg[index]=min(seg[2*index],seg[2*index+1]);
}
ll query(vvl&dp,int val,int index,int l,int r,int ql,int qr){
	if(ql>r || qr<l) return 0;
	if(l==r){
		if(seg[index]<val) return dp[no[index]][1];
		else return 0;
	}
	if(seg[index]<val){
		int mid=l+(r-l)/2;
		ll left=query(dp,val,2*index,l,mid,ql,qr);
		ll right=query(dp,val,2*index+1,mid+1,r,ql,qr);
		return max(left,right);
	}
}
