const int MOD = 1000 * 1000 * 1000 + 7;
const int N = 2*100000;
const int max_height = 2*pow(2, (int)ceil(log2(N))) -1;

ll tree[max_height];

void build(int index, int l, int r){
    if(l == r){
        tree[index] = 0;
    }
    else{
        int mid = (l+r)/2;

        build(2*index+1, l, mid);

        build(2*index+2, mid+1, r);

        tree[index] = 0;
    }
}

void update(int node, int l, int r, int index, ll val){
    if(l>index || r<index)
        return;

    if(l==r)
        tree[node] = val;   
    else{
        int mid = (l+r)/2;
        update(2*node+1, l, mid, index, val);
        update(2*node+2, mid+1, r, index, val);

        tree[node] = max(tree[2*node+1], tree[2*node+2]);
    }
}

ll query(int index, int start, int end, int l, int r){
    if(start>r || end<l)
        return 0;

    if(start >=l && end <= r)
        return tree[index];
    else
    {
        int mid = (start+end)/2;
        return max(query(2*index+1,start,mid,l,r), query(2*index+2,mid+1,end,l,r));
    }
}


