void modify(int x,int l,int r,int k,long long val)
{
	if(l==r)
	{
		s[x]=val;
		return;
	}
	int mid=(l+r)>>1;
	if(k<=mid) modify(x<<1,l,mid,k,val);
	else modify(x<<1|1,mid+1,r,k,val);
	s[x]=max(s[x<<1],s[x<<1|1]);
}

long long query(int x,int l,int r,int L,int R)
{
	if(l>=L&&R>=r) return s[x];
	int mid=(l+r)>>1;
	long long res=0;
	if(L<=mid) res=max(res,query(x<<1,l,mid,L,R));
	if(R>mid) res=max(res,query(x<<1|1,mid+1,r,L,R));
	return res;
}

