const int num = 1e6 + 1e4;
ll fen[num];

void update(int i,ll add)
{
    while(i<num)
    {
        fen[i] = max(fen[i],add);
        i += (i&(-i));
    }
}

ll sum(int i)
{
    ll s =0;
    while(i>0)
    {
        s = max(s,fen[i]);
        i -= (i&(-i));
    }
    return s;
}

int lowerbound(int k)
{
    int low = 0 , ans = 0 , prevsum = 0;
    for(int i=19;i>=0;i--)
    {
        if((low + (1<<i))<num && (fen[low + (1<<i)] + prevsum) < k)
        {
            ans = low + (1<<i);
            low = ans;
            prevsum += fen[low];
        }
    }
    return ans+1;
}

//SEGMENT TREE
ll tree[4*N+1];

void buildtree(int node,int start,int end)
{
    if(start == end)
        tree[node] = tree[start];
    else
    {
        int mid = (start+end)/2;
        buildtree(2*node,start,mid);
        buildtree(2*node + 1,mid+1,end);
        tree[node] = tree[2*node] + tree[2*node + 1];
    }
}

void update(int node,int start,int end,int index,ll value)
{
    if(start == end)
        tree[node] = max(tree[node],value);
    else
    {
        int mid = (start+end)/2;
        if(start <= index && index <= mid)
        {
            update(2*node,start,mid,index,value);
        }
        else
        {
            update(2*node + 1,mid+1,end,index,value);
        }
        tree[node] = max(tree[2*node],tree[2*node+1]);
    }
}

ll query(int node,int start,int end,int l,int r)
{
    if(r < start || end < l)
    {
        //completely outside range
        return 0;
    }
    if(l <= start && end <= r)
    {
        //completely inside
        return tree[node];
    }
    //partially inside
    int mid = (start + end)/2;
    ll p1 = query(2*node,start,mid,l,r);
    ll p2 = query(2*node + 1,mid+1,end,l,r);
    return max(p1,p2);
}

