void update(ll int i,ll int v,ll int s,ll int e,ll int index)
{
	if(i<s||i>e)
	{
		return ;
	}

	if(s==e && s==i)
	{
		tree[index]=v;
		return;
	}

	ll int mid=(s+e)/2;

	update(i,v,s,mid,2*index);
	update(i,v,mid+1,e,2*index+1);

	tree[index]=max(tree[2*index],tree[2*index+1]);
}

ll int query(ll int l,ll int r,ll int s,ll int e,ll int index)
{
    if(r<s||l>e)
    {
        return INT_MIN;
    }

    if(s>=l&&e<=r)
    {
        return tree[index];
    }

    ll int mid=(s+e)/2;

    return max(query(l,r,s,mid,2*index),query(l,r,mid+1,e,2*index+1));
}

