#define MAXN 200005
ll t[4*MAXN];

ll maxSeg(int v, int tl, int tr, int l, int r){
	if(l>r)
		return 0;
	if(l==tl and r==tr)
		return t[v];
	int tm = (tl + tr)/2;
	return max(maxSeg(v*2, tl, tm, l, min(r, tm)), maxSeg(v*2+1, tm+1, tr, max(l, tm+1), r));
}

void updateSeg(int v, int tl, int tr, int pos, ll new_val){
	if(tl==tr)
		t[v] = new_val;
	else{
		int tm = (tl+tr)/2;
		if(pos<=tm)
			updateSeg(v*2, tl, tm, pos, new_val);
		else
			updateSeg(v*2+1, tm+1, tr, pos, new_val);
		t[v] = max(t[v*2], t[v*2 + 1]);
	}
}

