bool cmp(node x,node y)
{
	return x.h<y.h;
}
ll t[800005],tag[800008],f[200005],ans;
void pushup(int x)
{
	t[x]=max(t[x+x],t[x+x+1]);
}
void pushdown(int x)
{
	t[x+x]=max(t[x+x],tag[x]);
	t[x+x+1]=max(t[x+x+1],tag[x]);
	tag[x+x]=max(tag[x+x],tag[x]);
	tag[x+x+1]=max(tag[x+x+1],tag[x]);
	tag[x]=0;
}
void build(int x,int l,int r)
{
	if(l==r)
	{
		t[x]=0;
		return;
	}
	int mid=(l+r)>>1;
	build(x+x,l,mid);
	build(x+x+1,mid+1,r);
	pushup(x);
}
void edit(int x,int l,int r,int L,int R,ll val)
{
	if(l>R||r<L) return;
	if(l>=L&&r<=R)
	{
		t[x]=max(t[x],val);
		tag[x]=max(tag[x],val);
		return;
	}
	int mid=(l+r)>>1;
	pushdown(x);
	edit(x+x,l,mid,L,R,val);
	edit(x+x+1,mid+1,r,L,R,val);
	pushup(x);
}
ll query(int x,int l,int r,int L,int R)
{
	if(l>R||r<L) return 0;
	if(l>=L&&r<=R)
	{
		return t[x];
	}
	int mid=(l+r)>>1;
	pushdown(x);
	pushup(x);
	return max(query(x+x,l,mid,L,R),query(x+x+1,mid+1,r,L,R));
}
