		int tm = (tl+tr)/2;
		if(pos <= tm){
			upd(2*v,tl,tm,val,pos);
		}else{
			upd(2*v+1,tm+1,tr,val,pos);
		}
		t[v] = max(t[2*v],t[2*v+1]);
	}
}
ll get(int v,int l,int r,int tl,int tr)
{
	if(tl == l && tr == r)return t[v];
	if(l > r)return -INF;
	int tm = (tl+tr)/2;
	return max(get(2*v,l,min(r,tm),tl,tm),
	           get(2*v+1,max(l,tm+1),r,tm+1,tr));
}
