using namespace std;

int num = 1;
vector<long long> dp;

void update(int i, long long x) {
  i += num - 1;
  dp.at(i) = x;
  while (i > 0) {
    i = (i - 1) / 2;
    dp.at(i) = max(dp.at(i*2 + 1), dp.at(i*2 + 2));
  }
}

long long query(int a, int b, int k, int l, int r) {
  if (r <= a || b <= l) return 0;
  if (a <= l && r <= b) return dp.at(k);
  else {
    long long c1 = query(a, b, 2*k+1, l, (l+r)/2);
    long long c2 = query(a, b, 2*k+2, (l+r)/2, r);
    return max(c1, c2);
  }
}

int main() {
  int N; cin >> N;
  vector<long long> H(N), A(N);
  for (int i = 0; i < N; i++) cin >> H.at(i);
  for (int i = 0; i < N; i++) cin >> A.at(i);
  num = 1;
  while (num <= N) num *= 2;
  // セグ木 dp[j] := 右端が高さ j となるような単調増加列を作るとき、
  // 実現可能な美しさの最大値
  dp = vector<long long>(2*num - 1, 0);
  long long ans = 0;
  for (int i = 0; i < N; i++) {
    long long score = query(0, H.at(i), 0, 0, num);
    if (query(H.at(i), H.at(i)+1, 0, 0, num) < score + A.at(i)) {
      update(H.at(i), score + A.at(i));
      ans = max(ans, score + A.at(i));
    }
  }
  cout << ans << endl;
}

