int h[N] , a[N] ;
ll dp[N] , seg[4*N] ; 

void update(int p , int s , int e   , int idx , ll val) {
	if (s==e) {
		 seg[p] = val ;
		 return ;
	}


	if (idx <= (s+e)/2 )
		update (p*2 , s , (s+e)/2 , idx , val) ;
	else 
		update (p*2+1  , (s+e)/2+1  , e , idx , val) ;


	seg[p] = max(seg[p*2],seg[p*2+1]) ;
}


ll get(int p  , int s , int e , int a , int b) {


	if (s > b ||  e<a)
		return 0;

	if (s>=a && e<=b){

		return seg[p] ; 
	}

	return max(get(p*2 , s , (s+e)/2 , a , b) ,  get(p*2+1 , (s+e)/2+1 , e , a , b)); 
}


