inline void solve()
{
	ll n, i, j, ans;
	cin >> n;

	ll h[n], a[n];
	map<ll, ll> m;

	for (i = 0; i < n; i++)
		cin >> h[i];

	for (i = 0; i < n; i++)
		cin >> a[i];

	vll dp(n);
	dp[0] = a[0];
	m[h[0]] = dp[0];
	ans = dp[0];

	for (i = 1; i < n; i++)
	{
		dp[i] = a[i];

		auto it = m.lower_bound(h[i] + 1);
		if (it != m.begin())
		{
			it--;
			dp[i] += it->second;
		}

		m[h[i]] = dp[i];

		it = m.upper_bound(h[i]);

		while (it != m.end() && it->second <= dp[i])
		{
			auto temp = it;
			temp++;
			m.erase(it);
			it = temp;
		}
		ans = max(ans, dp[i]);
	}

	cout << ans << endl;
}

