template<class T, T monoid>
class RMQ{
public:
  vector<T> dat;
  int _n;

  RMQ(int size) : _n{1}{
    while(size > _n) _n *= 2;
    dat.resize(2*_n-1, monoid);
  } 

  void update(int k, int a){
    k += _n-1;
    dat[k] = a;

    while(k > 0){
      k = (k-1) / 2;
      dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
  }

  T query(int a, int b){
    return _query(a, b, 0, 0, _n);
  }

  const T operator[](int i) const {
    assert(i >= 0 && i < _n);
    return dat[i + _n - 1];
  }
private:
  T _query(int a, int b, int k, int l, int r){
    if(r <= a || b <= l) {
      return monoid;
    }
    if(a <= l && r <= b) {
      return dat[k];
    }
    else {
      T v1 = _query(a, b, k * 2 + 1, l, (l + r) / 2);
      T v2 = _query(a, b, k * 2 + 2, (l + r) / 2, r);

      return max(v1, v2);
    }
  }
};

int main(){
  int n; cin >> n;
  int h[n], a[n];
  REP(i, n) cin >> h[i];
  REP(i, n) cin >> a[i];

  RMQ<ll, 0LL> rmq(n+1);
  REP(i, n){
    ll be = rmq.query(0, h[i]);
    rmq.update(h[i], be + a[i]);
  }

  cout << rmq.query(0, n+1) << endl;

  return 0;
}

