lli answer(vector<lli> h,vector<lli> a,int i,int n)
{
    if(dp[h[i]]!=-1) return dp[h[i]];
    dp[h[i]]=a[i];
    for(int j=i+1;j<n;j++)
    {
        if(h[j]>h[i])
        {
            dp[h[i]]=max(dp[h[i]],a[i]+answer(h,a,j,n));
        }
    }
    return dp[h[i]];
}
