struct Fenwick
{
	vector<long long> T;
	int size;

	Fenwick(int n)
	{
		size = n;
		T.resize(n + 1);
	}

	void add(int pos, long long val)
	{
		while(pos <= size)
		{
			T[pos] = max(T[pos], val);
			pos += pos & (-pos);
		}
	}

	long long get(int pos)
	{
		long long ret = 0;
		while(pos != 0)
		{
			ret = max(ret, T[pos]);
			pos -= pos & (-pos);
		}
		return ret;
	}
};

