struct segmentTree {
    const int NEUTRO = 0;
    long long st[400010];
    int n;

    long long action(long long x, long long y) {
        return max(x, y);
    }

    void update(int pos, long long value){
        for (st[pos += n] = value; pos > 1; pos >>= 1)
            st[pos >> 1] = action(st[pos], st[pos ^ 1]);
    }

    // interval[l,r)
    long long query(int l,int r){
        long long ans = NEUTRO;
        r++;
        for (l += n,r += n;l < r;l >>= 1,r >>= 1){
            if(l & 1) ans = action(ans, st[l++]);
            if(r & 1) ans = action(ans, st[--r]);
        }
        return ans;
    }
};

