#define int long long 

struct ftree {
  vector<int> bit;
  void update(int x, int val) {
    while (x < (int)bit.size()) {
      bit[x] = max(bit[x], val);
      x += x&-x;
    }
  }

  int query(int x) {
    int ret=0;
    while (x > 0) {
      ret = max(ret, bit[x]);
      x -= x&-x;
    }
    return ret;
  }
};

int32_t main() {
