typedef long long ll;
ll dat[800010];
ll u;
void seginit(ll n){
  for(int i=0;;i++){
    ll y=pow(2,i);
    if(y>=n){
      u=y;
      break;
    }
  }
  fill(dat,dat+2*u,0);
}
void add(ll n,ll x){
  ll i=u+n-1;
  dat[i]=x;
  while(i>0){
    i=(i-1)/2;
    dat[i]=max(dat[2*i+1],dat[2*i+2]);
  }
}
ll que(ll a,ll b,ll k,ll l,ll r){
  if(a>=r||b<=l)return 0;
  if(a<=l&&b>=r)return dat[k];
  else{
    ll m1=que(a,b,2*k+1,l,(l+r)/2);
    ll m2=que(a,b,2*k+2,(l+r)/2,r);
    return max(m1,m2);
  }
}
