ll query(int l, int r, int L, int R, int o){
	if (l>R||r<L) return 0;
	if (l>=L&&r<=R) return seg[o];
	int mid = (l+r)/2;
	ll ql = query(l, mid, L, R, o*2+1);
	ll qr = query(mid+1, r, L, R, o*2+2);
	return max(ql, qr);
}

void modify(int l, int r, int p, ll v, int o){
	if (l>p||r<p) return;
	if (l==r){
		if(l==p) seg[o]=v; return;
	}
	int mid = (l+r)/2;
	modify(l, mid, p, v, o*2+1);
	modify(mid+1, r, p, v, o*2+2);
	seg[o]=max(seg[o*2+1],seg[o*2+2]);
}

