using namespace std;
struct segment_tree {
  public:
    const long long uni = 0;
    int n, N;
    vector<long long> tr;
    segment_tree (int size) {
      n = size;
      N = 1;
      while (N < n) {
        N <<= 1;
      }
      tr.resize(2 * N, uni);
    }
    long long opr (long long x, long long y) {
      return max(x, y);
    }
    void update (int i, long long x) {
      i += N;
      tr[i] = x;
      i >>= 1;
      for (; i; i >>= 1) {
        tr[i] = opr(tr[2 * i], tr[2 * i + 1]);
      }
    }
    long long find (int l, int r) {
      return dfs(1, l, r, 0, N);
    }
    long long dfs (int k, int l, int r, int L, int R) {
      if (l <= L && R <= r) {
        return tr[k];
      } else if (r <= L || R <= l) {
        return uni;
      } else {
        int C = (L + R) >> 1;
        return opr(dfs(2 * k, l, r, L, C), dfs(2 * k + 1, l, r, C, R));
      }
    }
};
