llong get(int v, int tl, int tr, int L, int R){
    if(L <= tl && tr <= R){
        return t[v];
    }
    if(L > tr || tl > R){
        return 0;
    }
    int tm = (tl + tr) / 2;
    return max(get(v * 2, tl, tm, L, R), get(v * 2 + 1, tm + 1, tr, L, R));
}

void upd(llong v, llong tl, llong tr, llong ind, llong x){
    if(tl == tr){
        t[v] = x;
        return ;
    }
    int tm = (tl + tr) / 2;
    if(ind <= tm){
        upd(v * 2, tl, tm, ind, x);
    }else{
        upd(v * 2 + 1, tm + 1, tr, ind, x);
