struct RMQTree{
	// 0-indexed
	// for vertex n
	// par (n-1)/2
	// chi 2n+1,2n+2

	// index i
	// bottom vertex n+i-1

	int segn2; // imply actually vertex number
	vector<ll> data;

	RMQTree(int n){
		segn2=1;
		while(segn2<n) segn2*=2; //必要分2^Mを取る

		data.assign(segn2*2-1,0LL); // 2^31 - 1
	}

	// maximum in [a,b). l,r is given vertex k according the interval.
	ll query(int a,int b,int l=0,int r=-1,int k=0){

		if(r==-1) r=segn2; // when calling function at first
		if (r <= a || b <= l) return 0; //disjoint
		if (a <= l && r <= b) return data[k]; //include

		ll vl = query(a,b,l,(l+r)/2,k*2+1);
		ll vr = query(a,b,(l+r)/2,r,k*2+2);

		return max(vl,vr);
	}

	// i value |-> x (0-indexed)
	void update(int k,ll x){
		k += segn2 - 1;
		data[k]=x;

		while(k > 0){
			k=(k-1)/2; //move to par
			data[k]=max(data[k*2+1],data[k*2+2]); //refresh
		}

		return;
	}
};

