    T def;                          // 初期値かつ単位元
    function<T(T, T)> operation;    // 区間クエリで使う処理
    function<T(T, T)> update;       // 点更新で使う処理

    // 区間[a,b)の総和。ノードk=[l,r)に着目している。
    T _query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return def; // 交差しない
        if (a <= l && r <= b) return data[k]; // a,l,r,bの順で完全に含まれる
        else {
            T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子
            T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子
            return operation(c1, c2);
        }
    }

    public:
    // _n:必要サイズ, _def:初期値かつ単位元, _operation:クエリ関数,
    // _update:更新関数
    SegTree(size_t _n, T _def, function<T(T, T)> _operation,function<T(T, T)> _update): def(_def), operation(_operation), update(_update) {
        n = 1;
        while (n < _n) {n *= 2;}
        data = vector<T>(2 * n - 1, def);
    }

    // 場所i(0-indexed)の値をxで更新
    void change(int i, T x) {
        i += n - 1;
        data[i] = update(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    void setVec(vector<T> v) {
        for (int i = 0; i < v.size(); i++){
            change(i, v[i]);
        }
    }

    // [a, b)の区間クエリを実行
    T query(int a, int b) {
        return _query(a, b, 0, 0, n);
    }

    // 添字でアクセス
    T operator[](int i) {
        return data[i + n - 1];
    }
};

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);  

  int N;
  cin >> N;

  vector<ll> h(N);
  vector<ll> b(N);
  REP(i, N) cin >> h[i];
  REP(i, N) cin >> b[i];

  SegTree<ll> st(N + 5, 0, // ノード数、初期値(単位元)
                          [](long long a, long long b) { return max(a, b);}, //　更新処理
                          [](long long a, long long b) { return b; }); // 点更新
  REP(i, N){
    h[i]--;
    ll bi = st.query(0, h[i] + 1);
    st.change(h[i], bi + b[i]);
  }  
  cout << st.query(0, N + 1) << endl;

  return 0;
}

