const int nn=212345;
ll bit[nn+1];

ll minf(int i){++i; //閉区間
  ll s=0;
  while(i>0){
    s=max(s,bit[i]);
    i-=i&-i;
  }return s;
}
void upd(int i,ll val){++i; //より小さいのに更新される場合のみ
  while(i<=nn){
    bit[i]=max(bit[i],val);
    i+=i&-i;
  }
  return;
}

