void solve()
{
    ll n;
    cin >> n;
    vector<ll> a(n);
    vector<ll> h(n);
    for (int i = 0; i < n; ++i) {
        cin >> h[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    ll base=1;
    while (base <= n) {
        base *= 2;
    }
    vector<ll> tree(base*2);

    vector<ll> dp(n+1, 0); // dp[i] max possible beauty with last element of height i

    for (int i = 0; i < n; ++i) {
        // looking for max dp[i] for i=0...height

        ll best = 0;
        ll x = h[i]+base;
        while (x>1) {
            if (x%2==1) {
                best = max(best, tree[x-1]);
            }
            x /= 2;
        }
        dp[h[i]] = best + a[i];

        x = h[i]+base;
        while (x>0) {
                tree[x] = max(tree[x], dp[h[i]]);
            x /= 2;
        }
        /* for (int height = 0; height < h[i]; ++height) { */
        /*     dp[h[i]] = max(dp[h[i]], dp[height]+a[i]); */
        /* } */
    }

    dbg(dp);

    ll res = 0;
    for (int i = 0; i <= n; ++i) {
        res = max(res, dp[i]); 
    }

    cout << res << endl;
}

