long long f(vector<long long>&H,vector<long long>&A,long long i,long long last)
{
    if(i==H.size())
        return 0;
    if(last!=-1&&dp[i][last]!=-1)
        return dp[i][last];
    long long x=0,y;
    if(H[i]>last)
        x=A[i]+f(H,A,i+1,H[i]);
    y=f(H,A,i+1,last);
    if(last==-1)
        return max(x,y);
     dp[i][last]=max(x,y);
     return dp[i][last];
}

