ll seg[4*mx];
ll query(ll index,ll l,ll r,ll ql,ll qr){
	if(ql>r || qr<l) return INT_MIN;
	if(ql<=l && qr>=r) return seg[index];
	ll mid=l+(r-l)/2;
	ll left=query(2*index,l,mid,ql,qr);
	ll right=query(2*index+1,mid+1,r,ql,qr);
	return max(left,right);
}
void update(ll index,ll l,ll r,ll i,ll val){
	if(i<l || i>r) return;
	if(l==r){
		seg[index]=val;
		return;
	}
	ll mid=l+(r-l)/2;
	update(2*index,l,mid,i,val);
	update(2*index+1,mid+1,r,i,val);
	seg[index]=max(seg[2*index],seg[2*index+1]);
}
