void upd(ll v, ll tl, ll tr, ll pos, ll val) {
    if (tl == tr) {
        t[v] = max(t[v], val);
        return;
    }
    ll tm = (tl + tr)>>1;
    if (pos <= tm)
        upd(v * 2, tl, tm, pos, val);
    else
        upd(v * 2 + 1, tm + 1, tr, pos, val);
    t[v] = max(t[v * 2], t[v * 2  + 1]);
}


ll get(ll v, ll tl, ll tr, ll l, ll r) {
    if (r < tl || tr < l)
        return 0ll;
    ll tm = (tl + tr)>>1;
    if (l <= tm && tr <= r)
        return t[v];
    return max(get(v * 2, tl, tm, l, r), get(v * 2 + 1, tm + 1, tr, l, r));
}


