ll query(ll st, ll end, ll l, ll r, ll ind){
    ll m = (l+r)/2;
    if(l == st && r == end) return segtree[ind];
    if(st > m)  return query(st, end, m+1, r, 2*ind+2);
    else if(end <= m)   return query(st, end, l, m, 2*ind+1);
    return max(query(st,m,l,m,2*ind+1), query(m+1, end, m+1, r, 2*ind+2));
}

void update(ll height, ll val, ll l, ll r, ll ind){
    ll m = (l+r)/2;
    if(l == r && r == height){
        segtree[ind] = val;
        return ;
    }
    segtree[ind] = max(segtree[ind], val);
    if(height > m)  update(height, val, m+1, r, 2*ind+2);
    else    update(height, val, l, m, 2*ind+1);
}

