	if(start == end){
		if(x>tree[node]){
			tree[node] = x;
		}
		//cout << node << endl;
		return;
	}

	int mid = (start+end)/2;

	if( ind >= start && ind <= mid){
		update(2*node, start, mid, ind, x);
	}
	else{
		update(2*node+1, mid+1, end, ind, x);	
	}

	tree[node] = func(tree[2*node], tree[2*node+1]);
	//cout << node << endl;
	return;
}

