struct node{
    ll s,e,m,v; //global variables
    node *l, *r; //global pointers
    node(ll _s, ll _e){ //init
        s=_s;e=_e;m=(s+e)/2;
        if (s!=e){
            l=new node(s,m);
            r=new node(m+1,e);
            v=max(l->v, r->v);
        }else v=0; //starts off with 0 before any updates
    }

    ll query(ll x, ll y){
        if (s == x && e == y)return v; //leaf
        if (x > m)return(r->query(x, y)); //only part of right
        if (y <= m)return(l->query(x, y)); //only part of left
        return(max(l->query(x, m),r->query(m+1, y))); //in between nodes
    }
    void update(ll x, ll val){
        if (s == x && e == x){v = val;return;} //leaf node
        if (x > m)r->update(x, val); //update the right child
        else l->update(x, val); //update the left child
        v=max(l->v,r->v); //updates all above nodes when leaf is updated
    }
}*root;
