ll get(int v, int tl, int tr, int l, int r)
{
    if(l <= tl && tr <= r)return t[v];
    else if(tr < l || r < tl)return 0;
    else
    {
        int mid = (tl + tr) / 2;
        return max(get(v + v, tl, mid, l, r), get(v + v + 1, mid + 1, tr, l, r));
    }
}
void up(int v, int tl, int tr, int pos, ll val)
{
    if(tl == tr)t[v] = val;
    else
    {
        int mid = (tl + tr) / 2;
        if(pos <= mid)up(v + v, tl, mid, pos, val);
        else up(v + v + 1, mid + 1, tr, pos, val);
        t[v] = max(t[v + v], t[v + v + 1]);
    }
}
