int Max(int x, int ss, int se, int qs, int qe) {
    if (ss > qe || se < qs) return 0;
    if (ss >= qs && se <= qe) return st[x];

    int m = (ss+se)/2;
    return max(Max(2*x, ss, m, qs, qe),
               Max(2*x+1, m+1, se, qs, qe));
}

int Set(int x, int ss, int se, int q, int v) {
    if (ss > q || se < q) return st[x]; 
    if (ss == se) return st[x] = v;

    int m = (ss+se)/2;
    return st[x] = max(Set(2*x, ss, m, q, v),
                       Set(2*x+1, m+1, se, q, v));
}

