const int N = 1e5 + 5, MOD = 1e9 + 7, INF = 1e9 + 5;

struct SegmentTree {
    int n;
    vi a, t;

    void init(int x, vi y) {
        n = x;
        a = y;
        t.assign(4 * n, -INF);
        build(1, 0, n - 1);
    }

    int merge(int x, int y) { return max(x, y); }

    void build(int i, int l, int r) {
        if (l == r) {
            t[i] = a[l];
            return;
        }
        int mid = (l + r) / 2;
        build(lc(i), l, mid);
        build(rc(i), mid + 1, r);
        t[i] = merge(t[lc(i)], t[rc(i)]);
    }

    void modify(int i, int l, int r, int pos, int val) {
        if (l > pos || r < pos) return;
        if (l == pos && r == pos) {
            t[i] = val;
            return;
        }
        int mid = (l + r) / 2;
        modify(lc(i), l, mid, pos, val);
        modify(rc(i), mid + 1, r, pos, val);
        t[i] = merge(t[lc(i)], t[rc(i)]);
    }

    int query(int i, int l, int r, int ql, int qr) {
        if (l > qr || r < ql) return -INF;
        if (l >= ql && r <= qr) return t[i];
        int mid = (l + r) / 2;
        int resL = query(lc(i), l, mid, ql, qr);
        int resR = query(rc(i), mid + 1, r, ql, qr);
        return merge(resL, resR);
    }

    void modify(int p, int v) { modify(1, 0, n - 1, p, v); }

    int query(int l, int r) { return query(1, 0, n - 1, l, r); }
};

