const int N = 200010;

int n, h[N], where[N];
long long a[N], t[N + N];

void update (int p, long long v) {
  for (t[p += n] = v; p > 1; p >>= 1) {
    t[p >> 1] = max(t[p], t[p ^ 1]);
  }
}

long long query (int l, int r) {
  long long res = 0;
  for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
    if (l & 1) res = max(res, t[l++]);
    if (r & 1) res = max(res, t[--r]);
  }
  return res;
}

int main() {
  cin >> n;
  for (int i = 1; i <= n; ++i) {
    scanf("%d", h + i);
    where[h[i]] = i;
  }
  for (int i = 1; i <= n; ++i) {
    scanf("%lld", a + i);
  }
  long long ans = 0;
  for (int i = n; i > 0; --i) {
    int pos = where[i];
    long long cur = a[pos] + query(pos - 1, n);
    ans = max(ans, cur), update(pos - 1, cur);
  }
  cout << ans << endl;
  return 0;
}

