struct FenwickTree
{
    int n;
    vector<long long> FT;
    void init(int _n)
    {
        n = _n;
        FT.assign(n + 1, 0);
    }
    void Update(int x, long long val)
    {
        while (x <= n)
        {
            FT[x] = max(FT[x], val);
            x += (x & -x);
        }
    }
    long long Get(int x)
    {
        long long Resuft = 0;
        while (x > 0)
        {
            Resuft = max(Resuft, FT[x]);
            x -= (x & -x);
        }
        return Resuft;
    }
};

