template<class T>
class SegmentTree{
  using F=function<T(T,T)>;
private:
  ll n=1;
  F dot;
  T e;
  vector<T> node;
public:
  SegmentTree(const vector<T> &A,F dot,T e):dot(dot),e(e){
    while(n<A.size()) n<<=1;
    node.resize(2*n,e);
    rep(i,A.size()) node[n+i]=A[i];
    for(ll i=n-1;i>0;--i) node[i]=dot(node[2*i],node[2*i+1]);
  }
  void update(ll i,T c){
    node[i+=n]=c;
    while(i>>=1) node[i]=dot(node[2*i],node[2*i+1]);
  }
  T sum(ll l,ll r){
    T vl=e, vr=e;
    for(l+=n,r+=n;l<r;l>>=1,r>>=1){
      if(l%2==1) vl=dot(vl,node[l++]);
      if(r%2==1) vr=dot(node[--r],vr);
    }
    return dot(vl,vr);
  }
  ll bisect(ll l,ll r,T x,bool increase=true,ll i=1,ll a=0,ll b=-1){
    if(b==-1) b=n;
    if(increase){
      if(node[i]<=x||b<=l||r<=a) return -1;
      if(i>=n) return i-n;
      ll lv=bisect(l,r,x,increase,2*i,a,(a+b)/2);
      if(lv!=-1) return lv;
      return bisect(l,r,x,increase,2*i+1,(a+b)/2,b);
    } else {
      if(node[i]>=x||b<=l||r<=a) return -1;
      if(i>=n) return i-n;
      ll rv=bisect(l,r,x,increase,2*i+1,(a+b)/2,b);
      if(rv!=-1) return rv;
      return bisect(l,r,x,increase,2*i,a,(a+b)/2);
    }
  }
};

