int solve(int h[],int b[],int n)
{
    int dp[n];
    map<int,int> m;
    dp[0]=b[0];
    m[h[0]]=dp[0];
    int ans=dp[0];
    for(int i=1;i<n;i++)
    {
        dp[i]=b[i];
        auto it=m.lower_bound(h[i]);
        if(it!=m.begin())
        {
            it--;
            dp[i]+=it->second;
        }
        m[h[i]]=dp[i];
        it=m.upper_bound(h[i]);
        ans=max(ans,dp[i]);
        while(it!=m.end()&&it->second<=dp[i])
        {
            auto temp =it;
            temp++;
            m.erase(it);
            it=temp;
        }
    }
    return ans;
}
