const int INF = 1 << 17;

struct SegmentTree {
    vector<long long> dat;
    int n;


    SegmentTree(int i){
        n= 1;
        while(n < i){
            n *= 2;
        }
        dat.resize(2*n-1,INF);
    }

    void update(int k, long long a){
        k += n -1;
        dat[k] = a;
        while(k>0){
            k = (k-1)/2;
            dat[k] = min(dat[k*2+1],dat[k*2+2]);
        }
    }

    long long getVal(int k){
        k += n -1;
        return dat[k];
    }

    long long query(int a, int b){
        return queryRecursive(a,b,0,0,n);
    }

    private:
    long long queryRecursive(int a, int b,int k,int l,int r){
        if(r <= a || b <= l){
            return INF;
        }
        if(a<= l && r <= b){
            return dat[k];
        }
        long long vl = queryRecursive(a,b,k*2+1,l,(l+r)/2);
        long long vr = queryRecursive(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr);
    }
};


void solve(long long N, std::vector<long long> h, std::vector<long long> a){
    SegmentTree seg = SegmentTree(N);
    for(int i=0;i<N;i++){
        // cerr << "i=" << i << endl;
        long long minV = seg.query(0,h[i]);
        if(minV >0){
            seg.update(h[i], -a[i]);
            continue;
        }
        // cerr << "i=" << i << "h=" << h[i] <<"minV=" << minV << endl;
        seg.update(h[i], minV-a[i]);
    }
    long long ans =0;
    for(int i=0;i<N;i++){
        ans = max(ans,-seg.getVal(h[i]));
    }
    cout << ans << endl;
}

