	return tree[pos];

	if(qlow>high||qhigh<low)
	return INT_MIN;

	int mid=(low+high)/2;

	return max(rangemax(tree,qlow,qhigh,low,mid,2*pos+1),rangemax(tree,qlow,qhigh,mid+1,high,2*pos+2));


}


