class SegmentTree {

    int n;
    vector<LL> node;

public:

    SegmentTree(vector<LL> a) {
        int sz = a.size();
        n = 1;
        while (n < sz) n *= 2;
        node.resize(2 * n - 1, 0);
        for (int i = 0; i < sz; i++) node[i + n - 1] = a[i];
        for (int i = n - 2; i >= 0; i--) node[i] = max(node[i * 2 + 1], node[i * 2 + 2]);
    }

    void update(int index, LL x) {
        index += (n - 1);
        node[index] = x;
        while (index > 0) {
            index = (index - 1) / 2;
            node[index] = max(node[index * 2 + 1], node[index * 2 + 2]);
        }
    }

    LL getMax(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return 0;
        if (a <= l && r <= b) return node[k];
        LL vl = getMax(a, b, k * 2 + 1, l, (l + r) / 2);
        LL vr = getMax(a, b, k * 2 + 2, (l + r) / 2, r);
        return max(vl, vr);
    }

};

