class FenwickTree {
  public:
    FenwickTree(int size):
        m_data(size, 0) {}

    int size() const {
        return m_data.size();
    }

    void update(int position, int64_t value) {
        for (; position < size(); position += (position & -position))
            m_data[position] = max(m_data[position], value);
    }

    int64_t query(int position) const {
        int64_t best = 0;
        for (; position; position -= (position & -position))
            best = max(best, m_data[position]);
        return best;
    }

  private:
    vector<int64_t> m_data;
};

