int update(int ss, int se, int curr, int idx, int val)
{
    if(idx < ss || idx > se)
        return st[curr];
    if(ss == se)
    {
        st[curr] = val;
        return st[curr];
    }
    int mid = (ss + se) / 2;
    int left = update(ss, mid, (curr << 1), idx, val);
    int right = update(mid + 1, se, (curr << 1) | 1, idx, val);
    st[curr] = max(left, right);
    return st[curr];
}

int query(int ss, int se, int curr, int l, int r)
{
    if(r < ss || l > se)
        return -1;
    if(l <= ss && se <= r)
        return st[curr];
    int mid = (ss + se) / 2;
    int left = query(ss, mid, (curr << 1), l, r);
    int right = query(mid + 1, se, (curr << 1) | 1, l, r);
    return max(left, right);
}

