void update(int pos, ll value, int v, int tl, int tr) {
	if(tl==tr) {
		t[v] = value;
		return;
	} 
	int mid = tl + (tr-tl)/2;
	if(pos<=mid) {
		update(pos,value, v*2,tl,mid);
	} else {
		update(pos,value,v*2+1,mid+1,tr);
	}
	t[v] = max(t[v*2],t[v*2+1]);
}
int query(int v, int tl, int tr, int l, int r) {
	if(l>r) return 0;
	if(l==tl && r==tr) {
		return t[v];
