ll queryutil(ll left,ll right,ll l,ll r,ll node)
{

    if(left==l && right==r)
    {
        return tree[node];
    }
    else
    {
        if(left<=right)
        {
            ll mid=(l+r)/2;
            if(mid>=right)
            {
                return queryutil(left,right,l,mid,2*node+1);
            }
            if(left>mid)
            {
                 return queryutil(left,right,mid+1,r,2*node+2);
            }
            if(left<=mid && right>mid)
            {
                return max(queryutil(left,mid,l,mid,2*node+1),queryutil(mid+1,right,mid+1,r,2*node+2));//this line can be changed for minimum or maximum query

            }
        }
        else
            return 0;

    }
}
ll query(ll left,ll right)
{
    return queryutil(left-1,right-1,0,n-1,0);
}



