const int mod = 1e9+7; 
const int N = 2e5+1; 
int n;

vector<int> height(N),beauty(N);

vector<long long int> tree(4*N,0); 


void update(int node , int start, int end, int idx, long long int val)
{
    if(start == end)
    {

        tree[node] = val;

    }
    else
    {
        int mid = (start + end) / 2;
        if(start <= idx and idx <= mid)
        {
            // If idx is in the left child, recurse on the left child.
            update(2*node, start, mid, idx, val);
        }
        else
        {
            // if idx is in the right child, recurse on the right child.
            update(2*node+1, mid+1, end, idx, val);
        }

        // Internal node will have the sum of both of its children.
        tree[node] = max(tree[2*node],tree[2*node+1]);

    }
}


long long int query(int node, int start, int end, int l, int r)
{

    if(r < start or end < l)
    {
        // range represented by a node is completely outside the given range.
        return 0;

    }
    if(l <= start and end <= r)
    {
        // range represented by a node is completely inside the given range.
        return tree[node];

    }

    // range represented by a node is partially inside and partially outside the given range.
    int mid = (start + end) / 2;
    long long int p1 = query(2*node, start, mid, l, r);
    long long int p2 = query(2*node+1, mid+1, end, l, r);
    return max(p1,p2);

}

