typedef long long ll;

struct STree {
  int l, r;
  ll mx = 0;
  STree *left = 0;
  STree *right = 0;
  STree (int l, int r): l(l), r(r) {
    if (l == r) return;
    int m = (l + r) / 2;
    left = new STree(l, m);
    right = new STree(m + 1, r);
  }
  void update (const int pos, const ll val) {
    if (pos < l or r < pos) return;
    if (l == pos and pos == r) {
      mx = val;
      return;
    }
    left -> update(pos, val);
    right -> update(pos, val);
    mx = max(left -> mx, right -> mx);
  }
  ll getMax (const int L, const int R) {
    if (r < L or R < l) return 0;
    if (L <= l and r <= R) return mx;
    return max(left -> getMax(L, R), right -> getMax(L, R));
  } 
};

int main () {
  int n;
  cin >> n;
  vector <ll> h(n), a(n);
  for (int i = 0; i < n; i++) cin >> h[i];
  for (int i = 0; i < n; i++) cin >> a[i];
  vector <ll> dp(n + 1, 0);
  STree* tree = new STree(0, n);
  for (int i = 0; i < n; i++) {
    dp[h[i]] = max(dp[h[i]], a[i] + tree -> getMax(0, h[i] - 1));
    tree -> update(h[i], dp[h[i]]);
  }
  cout << tree -> mx << endl;
  return (0);
}

