struct node{
    node* l, *r;
    int val;
};

void Build(int l, int r, node *root){
    if(l == r){
        return;
    }
    node* L = new node{NULL,NULL,0};
    node* R = new node{NULL,NULL,0};
    root->l = L;
    root->r = R;
    int mid = (l+r) >> 1;
    Build(l, mid, root->l);
    Build(mid+1, r, root->r);
}

int Add(int l, int r, node *root, int val, int index){
    if(index < l || index > r) return root->val;
    if(index == l && index == r){
        root->val = val;
        return val;
    }
    int mid = (l+r)>>1;
    return root->val = max(Add(l,mid, root->l, val, index), Add(mid+1, r, root->r, val, index));
}

int getMax(int l, int r, node* root, int qL, int qR){
    if(qR < l || qL > r) return -INF;
    if(qR >= r && qL <= l) return root->val;
    int mid = (l+r)>>1;
    return max(getMax(l,mid, root->l, qL, qR), getMax(mid+1, r, root->r, qL, qR));
}

