void build(ll st,ll en,ll pos)
{
    if(st==en){
        sgt[pos]=0;
        return;
    }
    ll mid=(st+en)/2;
    build(st,mid,2*pos+1);
    build(mid+1,en,2*pos+2);
    sgt[pos]=max(sgt[2*pos+1],sgt[2*pos+2]);
}

void update(ll st,ll en,ll pos,ll idx,ll val)
{
    if(st==en){
        sgt[pos]=val;
        return;
    }
    ll mid=(st+en)/2;
    if(idx>=st&&idx<=mid){update(st,mid,2*pos+1,idx,val);}
    else{update(mid+1,en,2*pos+2,idx,val);}
    sgt[pos]=max(sgt[2*pos+1],sgt[2*pos+2]);
}

ll query(ll st,ll en,ll pos,ll l,ll r)
{
    if(st>r||en<l){return 0;}
    if(st>=l&&en<=r){return sgt[pos];}
    ll mid=(st+en)/2;
    return max(query(st,mid,2*pos+1,l,r),query(mid+1,en,2*pos+2,l,r));
}

