void update(int ss, int se, int i, int diff, int si)  
{  
    if (i < ss || i > se)  
        return; 
	if(ss==se) 
    tree[si] = tree[si] + diff;  
    else
    {  
        int mid = (ss+se)/2;  
        update( ss, mid, i, diff, 2*si + 1);  
        update( mid+1, se, i, diff, 2*si + 2);  
        tree[si]=max(tree[2*si+1],tree[2*si+2]);
    }  
}  
int query(int ss, int se, int qs, int qe, int si) 
{ 
	if (ss>se || ss>qe || se<qs) 
		return 0; 
	if (ss>=qs && se<=qe) 
		return tree[si]; 
	int mid = (ss + se)/2; 
	return max(query(ss, mid, qs, qe, 2*si+1) ,
		query(mid+1, se, qs, qe, 2*si+2)); 
}  
void segtree( int ss, int se, int si) 
{ 
	if (ss > se) 
		return ; 
	if (ss == se) 
	{ 
		tree[si] = a[ss]; 
		return; 
	} 
	int mid = (ss + se)/2; 
	segtree( ss, mid, si*2+1); 
	segtree( mid+1, se, si*2+2); 

	tree[si] = max(tree[si*2 + 1],tree[si*2 + 2]); 
} 
