ll max(ll a, ll b)
{
    if (a >= b) return(a);
    return(b);
}

void update(int node, int start, int end, int idx, ll v)
{
    if (start == end)
    {
        tree[node] = v;
        return;
    }
    int mid = (start + end) / 2;
    if (start <= idx && idx <= mid) update(2 * node, start, mid, idx, v);
    else update(2 * node + 1, mid + 1, end, idx, v);
    tree[node] = max(tree[2 * node], tree[2 * node + 1]);
}

ll query(int node, int start, int end, int l, int r)
{
    if (r < start || end < l) return(0);
    if (l <= start && end <= r) return(tree[node]);
    int mid = (start + end) / 2;
    ll p1 = query(2 * node, start, mid, l, r), p2 = query(2 * node + 1, mid + 1, end, l, r);
    return(max(p1, p2));
}

