ll query(int node, int l, int r, int a, int b){
    //cerr<<"l, r == "<<l<<' '<<r<<'\n';
    if(a<=l && r<=b){
        return tre[node];
    }

    ll ans = -1;

    int mid = (l+r)/2;
    if(a<=mid){
        ans = max(ans, query(2*node+1, l, mid, a, b));
    }

    if(b>mid){
        ans = max(ans, query(2*node+2, mid+1, r, a, b));
    }

    return ans;
}


void update(int node, int l, int r, int ind, ll val){
    //cerr<<"l, r == "<<l<<' '<<r<<'\n';
