    if(l==r){
        //cerr<<"upd l == "<<ind<<'\n';
        tre[node] = val;
        return;
    }

    int mid = (l+r)/2;
    if(ind<=mid){
        update(2*node+1, l, mid, ind, val);
    } else {
        update(2*node+2, mid+1, r, ind, val);
    }
    tre[node] = max(tre[2*node+1], tre[2*node+2]);
}

