vector<lli> dp(N*2, 0);

lli best(int l, int r, int idx = 0, int ll = 0, int rr = -1) {
    if (rr < 0) rr = N;
    // cout << ll << " " << rr << endl;
    if (rr <= l || r <= ll) return 0LL;

    lli res;
    if (l <= ll && rr <= r) return dp[idx];
    else res = max(best(l, r, idx*2+1, ll, (ll+rr)/2), best(l, r, idx*2+2, (ll+rr)/2, rr));

    // if (ll == 0 && rr == N) cout << "return : " << l << " " << r << " " << res << endl;
    return res;
}

void update(int idx, lli val) {
