void setValue(int v, int l, int r, int index, ll val) {
	if (l == r) {
		t[v] = val;
		return;
	}
	int mid = (l + r) / 2;
	if (index <= mid) setValue(2 * v, l, mid, index, val);
	else setValue(2 * v + 1, mid + 1, r, index, val);
	t[v] = max(t[2 * v], t[2 * v + 1]);
}

ll getValue(int v, int l, int r, int wl, int wr) {
	if (wl > wr) return 0;
	if (wl == l && wr == r) {
		return t[v];
	}
	int mid = (l + r) / 2;
	return max(getValue(2 * v, l, mid, wl, min(mid, wr)),
				getValue(2 * v + 1, mid + 1, r, max(mid + 1, wl), wr));
}

