template<class T>
class segment_tree_t {
public:
  segment_tree_t(int size) : size_(1), xp_(std::numeric_limits<T>::min()) {
    while (size_ < size)
      size_ *= 2;

    a_ = new T[size_ * 2];

    for (int i = 0, size = size_ * 2; i < size; i ++)
      a_[i] = xp_;
  };

  ~segment_tree_t() {
    delete[] a_;
  };

public:
  void update(int i, T x) {	// 0-index
    i += size_ - 1;

    a_[i] = x;

    while (i > 0) {
      i = (i - 1) / 2;

      a_[i] = std::max(a_[i * 2 + 1], a_[i * 2 + 2]);
    }
  };

  T query(int a, int b, int k = -1, int l = -1, int r = -1) const {	// [a, b)
    if (k < 0) {
      return query(a, b, 0, 0, size_);
    }
    else {
      if (r <= a || b <= l)
        return xp_;

      if (a <= l && r <= b) {
        return a_[k];
      }
      else {
        return std::max(query(a, b, k * 2 + 1, l, (l + r) / 2),
                        query(a, b, k * 2 + 2, (l + r) / 2, r));
      }
    }
  };

private:
  int size_;

  T* a_;

  T xp_;
};


