	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout << fixed << setprecision(15);
	ll n;
	cin >> n;
	vll h = vin(n), a = vin(n);
	add(h, -1LL);

	STmax<> st(n);	//花iに対する美しさを入れる

	vll res(n, -1);
	rep(i, n) st.update(i, -1);
	rep(i, n) {
		ll hei = h[i];
		ll best = st.largest(0, hei);
		if(best < 0) {
			res[hei] = a[i];
		} else {
			res[hei] = a[i] + best;
		}
		st.update(hei, res[hei]);
	}
	ll ans = 0;
	rep(i, n) { chmax(ans, res[i]); }
	cout << ans << endl;
}

