class SegmentTree{
public:

  int n;
  vector<ll> tree;

  SegmentTree(int size){
    n=1;
    while(n<size) n*=2;

    tree.resize(2*n-1,0);
  }

  SegmentTree(vector<int> v){
    int vSize=v.size();
    n=1;
    while(n<vSize) n*=2;

    tree.resize(2*n-1,0);

    for(int i=0;i<vSize;i++) tree[i+n-1]=v[i];
    for(int i=n-2;i>=0;i--) tree[i]=max(tree[2*i+1],tree[2*i+2]);
  }

  void update(int index,ll value){
    index+=n-1;

    tree[index]=value;
    while(index>0){
      index=(index-1)/2;
      tree[index]=max(tree[2*index+1],tree[2*index+2]);
    }
  }

  ll getMax(int a,int b,int k,int l,int r){
    if(r<0) r=n;

    if(r<=a||b<=l) return 0;
    else if(a<=l&&r<=b) return tree[k];
    else{
      ll lval=getMax(a,b,2*k+1,l,(l+r)/2);
      ll rval=getMax(a,b,2*k+2,(l+r)/2,r);
      return max(lval,rval);
    }
  }
};


