void update(int x, int l, int r, int z, long long int zz){
	if(l > z || r < z)return;
	if(l == r){
		st[x] = zz;
		return;
	}
	int mid = (l+r)/2;
	update(x*2, l, mid, z, zz);
	update(x*2+1, mid+1, r, z, zz);
	st[x] = max(st[x*2], st[x*2+1]);
