using namespace std;

const int N = 2e5 + 100;

int n;
int Beauty[N];
ll Seg[N << 2];

void Update (int idx, ll val, int Node = 1, int L = 1, int R = n)
{
    if (L == R) {
        Seg[Node] = max(Seg[Node], val);
        return;
    }

    int Mid = L + R >> 1;
    if (idx <= Mid)
        Update (idx, val, Node << 1, L, Mid);
    else
        Update (idx, val, Node << 1 | 1, Mid + 1, R);

    Seg[Node] = max(Seg[Node << 1], Seg[Node << 1 | 1]);
}

ll Query (int i, int j, int Node = 1, int L = 1, int R = n)
{
    if (i > R || j < L || i > j)    return 0;
    if (L >= i && R <= j)
        return Seg[Node];

    int Mid = L + R >> 1;
    ll Q1 = Query (i, j, Node << 1, L, Mid);
    ll Q2 = Query (i, j, Node << 1 | 1, Mid + 1, R);

    return max(Q1, Q2);
}


int main()
{
    scanf("%d", &n);

    vector <pair<ll, ll>> Arr;
    for (int i = 1; i <= n; i++) {
        int x;  scanf("%d", &x);
        Arr.push_back({x, i});
    }
    for (int i = 1; i <= n; i++)
        scanf("%d", Beauty + i);


    sort(Arr.begin(), Arr.end());

    for (auto flower : Arr) {
        int idx = flower.second;

        ll cur = Query(1, idx - 1);

        Update(idx, cur + Beauty[idx]);
    }

    printf("%lld\n", Query(1, n));
    return 0;
}

