struct segment{
    vector <ll> tree;
    int n;
    void resize(int _n){
        n = _n;
        tree.resize(4 * n);
    }
    void update(int l, int r, int node, int left, int right, ll val){
        if(l > r) return;
        if(l > right || r < left) return;
        if(l >= left && r <= right){
            tree[node] = val;
            return;
        }
        int mid = (l + r) >> 1;
        update(l, mid, node << 1, left, right, val);
        update(mid+1, r, node << 1 | 1, left, right, val);
        tree[node] = max(tree[node << 1], tree[node << 1 | 1]);
    }
    ll query(int l, int r, int node, int left, int right){
        if(l > r) return 0;
        if(l > right || r < left) return 0;
        if(l >= left && r <= right) return tree[node];
        int mid = (l + r) >> 1;
        return max(query(l, mid, node << 1, left, right), query(mid + 1, r, node << 1 | 1, left, right));
    }
};

