template<typename T>class BIT {
    public:
    int n;
    T init;
    vector<T> bit;

    BIT(int n, T init): n(n), init(init){
        bit.resize(n);
        fill(bit.begin(), bit.end(), (T)init);
    }

    void add(int idx, T x){
        for(int i=idx;i<=n;i+=i&-i) bit[i] = max(bit[i], x);
    }

    //bit[1]からbit[end]までのmax (閉区間)
    T get_max(int end){
        T ret = init;
        for(int i=end;i>=1;i-=i&-i) ret = max(ret, bit[i]);
        return ret;
    }
};


