   rep(i, n) {
	  cin >> t;h[t-1]=i;
   }
   rep(i, n)cin >> a[i];
   SegmentTree seg(VLL (n,0));
   for (int i = 0; i < n; i++)
   {
	  seg.update(h[i],seg.getmin(0,h[i])+a[h[i]]);
   }
   cout << seg.getmin(0, n)<<endl;
}

