void update(int node, int l, int r, int s, ll val) {
    if (s > r or s < l) return;

    if (l == r) {
        tree[node] = val;
        return ;
    }

    int m = (l+r)/2;
    update(2*node, l, m, s, val);
    update(2*node+1, m+1, r, s, val);

    tree[node] = max(tree[2*node] , tree[2*node+1]);

    return;
}

ll query(int node, int l, int r, int s, int e) {
    if (s>r or e<l) return LONG_LONG_MIN;

    if (l==r) return tree[node];

    int m = (l+r) /2;
    ll q1 = query(2*node, l, m, s, e);
    ll q2 = query(2*node+1, m+1, r, s, e);

    return max(q1, q2);
}

