template<typename T>
struct SegmentTree {  // For Range Maximum Query
  const T kInvalid;
  vector<T> data;
  int size = -1;

  SegmentTree(int N) : kInvalid(0) {
    size = 1;
    while (size < N) size *= 2;
    data.resize(2 * size - 1, kInvalid);
  }

  void Update(int k, T x) {
    k += size - 1;
    data[k] = x;

    while(k > 0) {
      k = (k - 1) / 2;
      data[k] = max(data[2 * k + 1], data[2 * k + 2]);
    }
  }

  // return value in [a, b]
  T Query(int a, int b) const { return Query(a, b + 1, 0, 0, size); }
  // return value in [a, b) by searching index k node which cover [l, r) region.
  T Query(int a, int b, int k, int l, int r) const {
    // l/r is out of bound.
    if (r <= a || b <= l) {
      return kInvalid;
    }

    // cover full range.
    if (a <= l && r <= b) {
      return data[k];
    }

    T left  = Query(a, b, 2 * k + 1, l, (l + r) /2);
    T right = Query(a, b, 2 * k + 2, (l + r) /2, r);
    return max(left, right);
  }
};

int main() {
  int N; cin >> N;
  vector<LL> h(N), a(N); cin >> h >> a;

  SegmentTree<LL> tree(N + 1);

  for (int i = 0; i < N; ++i) {
    LL vmax = tree.Query(0, h[i]);
    tree.Update(h[i], a[i] + vmax);
  }
  cout << tree.Query(0, N) << endl;
}

