template<class T>
struct MaxBIT {
    vector<T> x;
    MaxBIT(ll n) : x(n, 0) {}
    T get(ll i){
        ll s = 0;
        while(i > 0){
            s = max(s, x.at(i - 1));
            i -= i & (-i);
        }
        return s;
    }
    void set(ll i, T v){
        i += 1;
        while(i <= x.size()){
            x.at(i - 1) = max(x.at(i - 1), v);
            i += i & (-i);
        }
    }
};


