class flower
{
private:
	int n;
	unsigned long long retval = 0;
	vector<int> heights;
	vector<int> beauty;
	vector<bool> cuts;
	unsigned long long test_cut();
	bool valid_cut();
	void prune();
	void display();
public:
	flower();
};


flower::flower() {
	cin >> n;
	for (int i = 0; i < n; i++) {
		int h;
		cin >> h;
		heights.push_back(h);
	}
	for (int i = 0; i < n; i++) {
		int b;
		cin >> b;
		beauty.push_back(b);
	}
	cuts.resize(n, false);
	prune();
	display();
}


unsigned long long flower::test_cut() {
	unsigned long long sum = 0;
	for (int i = 0; i < n; i++) {
		if (!cuts[i]) {
			sum += beauty[i];
		}
	}
	return sum;
}

bool flower::valid_cut() {
	int h = 0;
	for (int i = 0; i < n; i++) {
		if (!cuts[i]) {
			if (heights[i] < h) {
				return false;
			}
			h = heights[i];
		}
	}
	return true;
}

void flower::prune() {
	if (valid_cut()) {
		retval = max(retval, test_cut());
		return;
	}
	if (test_cut() <= retval) {
		return;
	}
	for (int i = 0; i < n; i++) {
		if (!cuts[i]) {
			cuts[i] = true;
			prune();
			cuts[i] = false;
		}
	}
}
void flower::display() {
	cout << retval;
}

