typedef struct Node {
	ll val;
	ll l, r;
	struct Node *left, *right;

}node;
node *getNode(ll val, int l, int r) {
	node *tem = (node *)malloc(sizeof(node));
	tem->l = l; tem->r = r;
	tem->left = tem->right = NULL;
	tem->val = val;
	return tem;
}
node *build(ll val, int l, int r) {
	if(l == r) {
		return getNode(val, l, r);
	}
	node *root = getNode(val, l, r);
	root->left = build(val, l, (l + r) / 2);
	root->right = build(val, (l + r) / 2 + 1, r);
	return root;
}
void update(node *root, ll ind, ll change) {
	root->val = max(root->val, change);
	if(root->left == root->right)
		return;
	ll l = root->l, r = root->r;
	if(ind <= (l + r) / 2) {
		update(root->left, ind, change);
	}
	else {
		update(root->right, ind, change);
	}
}
ll getMax(node *root, int lf, int rf) {
	ll l = root->l, r = root->r;
	if(lf == l && rf == r)
		return root->val;
	if(rf <= (l + r) / 2) 
		return getMax(root->left, lf, rf);
	else if(lf >= (l + r) / 2 + 1) 
		return getMax(root->right, lf, rf);
	else 
		return max(getMax(root->left, lf, (l + r) / 2), getMax(root->right,(l + r) / 2 + 1 , rf));
}

