void upd(int v , int tl , int tr , int pos , int x){
	if(tl == tr){
		t[v] = x;
		return;
	}
	int tm = (tl + tr) >> 1;
	if(pos <= tm)	
		upd(v << 1 , tl , tm , pos , x);
	else
		upd(v << 1 |1 , tm + 1 , tr , pos , x);
	t[v] = max(t[v<<1] , t[v<<1|1]);
}
int get(int v , int tl, int tr , int l , int r){
	if( l > r)
		return 0;
	if(tl == l && tr == r)
		return t[v];
	int tm = (tl + tr) >> 1;
	return max(get(v << 1 , tl , tm , l , min(r , tm)) , get(v << 1 | 1 , tm + 1 , tr , max(tm + 1 , l) , r));
}

