i64 query (int ql, int qr, int l, int r, int node) {
  if (l > qr || r < ql) return 0;
  if (l >= ql && r <= qr) return seg[node];
  int mid = l + (r - l) / 2;
  return max (query (ql, qr, l, mid, 2 * node + 1), query (ql, qr, mid + 1, r, 2 * node + 2) );
}

void update (int idx, i64 delta, int l, int r, int node) {
  if (l > idx || r < idx) return;
  if (l == idx && r == idx) {
    seg[node] = max (seg[node], delta);
    return;
  }
  int mid = l + (r - l) / 2;
  update (idx, delta, l, mid, 2 * node + 1);
  update (idx, delta, mid + 1, r, 2 * node + 2);
  seg[node] = max (seg[2 * node + 1], seg[2 * node + 2]);
}


