   			 	c = (*it).second + b;
   			}


   			while(true) {
   				it = vals.lower_bound(a);
   				if(it == vals.end())
   					break;

   				if((*it).second<c || ((*it).second==c) && (*it).first>a)
   					vals.erase((*it).first);
   				else 
   					break; 
   			}
   			vals[a] = c;
   			maxi = max(maxi, c);
   		}
   	}

   	cout<<maxi<<endl;

	return 0;
}

