int query(int h) {
    int ret = BIT[h];
    //cout << "h: " << h << " ret: " << ret << " score[BIT[h]]: " << score[BIT[h]] << endl;
    while (h > 0) {
//		cout << h << " " << score[BIT[h]] << endl;
		if (score[BIT[h]] > score[ret]) ret = BIT[h];
		h -= h & (-h);
    }
    //cout << "returning " << ret << endl;
    return ret;
}

void update(int i, int curr) {
    int j = curr;
    while (j < n + 3) {
        if (score[BIT[j]] < score[i]) BIT[j] = i;
        if ((score[BIT[j]] == score[i]) && (h[i] < h[BIT[j]])) BIT[j] = i;
        j += j & (-j);
    }
}

