using namespace std;

using ll = long long;

template<typename Monoid>
class segment_tree {
    using T = typename Monoid::type;

public:
    segment_tree(std::vector<T> const& init)
        : sz(init.size()), n(expand(init.size()))
    {
        dat.assign(n*2, Monoid::id());
        std::copy(begin(init), end(init), begin(dat) + n);
        for(int i = n - 1; i >= 0; --i) {
            dat[i] = Monoid::op(dat[i * 2], dat[i * 2 + 1]);
        }
    }

    segment_tree(int const n_, T const& init = Monoid::id())
        : segment_tree(std::vector<T>(n_, init))
    {}

    void update(int p, T val) {
        assert(0 <= p && p < sz);
        dat[p += n] = val;
        while(p /= 2) {
            dat[p] = Monoid::op(dat[p * 2], dat[p * 2 + 1]);
        }
    }

    // [l, r)
    T query(int l, int r) const {
        assert(0 <= l && l <= r && r <= sz);
        l += n, r += n;
        T res1 = Monoid::id(), res2 = Monoid::id();
        while(l != r) {
            if(l & 1) res1 = Monoid::op(res1, dat[l++]);
            if(r & 1) res2 = Monoid::op(dat[--r], res2);
            l /= 2, r /= 2;
        }
        return Monoid::op(res1, res2);
    }

private:
    int expand(int n_) const {
        assert(n_ >= 1);
        return n_ == 1 ? n_ : expand((n_ + 1) / 2) * 2;
    }

private:
    const int sz, n;
    std::vector<T> dat;
};

struct RMQ {
    using type = ll;
    static type id() {
        return std::numeric_limits<type>::min() / 2;
    }
    static type op(type const& l, type const& r) {
        return std::max(l, r);
    }
};

int main() {
    int n; cin >> n;
    vector<int> h(n), a(n);
    for(int i = 0; i < n; ++i) {
        cin >> h[i];
    }
    for(int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    const int max_h = 1 << 18;
    segment_tree<RMQ> seg(max_h);
    seg.update(0, 0);
    for(int i = 0; i < n; ++i) {
        seg.update(h[i], seg.query(0, h[i]) + a[i]);
    }
    cout << seg.query(0, max_h) << endl;
}

