struct Drzefko{
    vector <long long> D;
    int wlk;
    Drzefko(int N){
        wlk = 1;
        while (wlk < N){
            wlk *= 2;
        }
        D.resize(wlk*2, 0);
    }
    void Dodaj(int poz, long long val){
        // cerr << "Dodaje na poz " << poz << " val " << val << "\n";
        poz += wlk;

        D[poz] = val;
        while(poz > 0){
            // cerr << poz << "\n";
            poz /= 2;
            D[poz] = max(D[poz*2], D[poz*2+1]);
        }
    }
    long long MaksZPrzedzialu(int lew, int praw, int lw, int pw, int poz){
        if (lew <= lw && praw >= pw){
            return D[poz];
        }
        else if (praw < lw || lew > pw){
            return 0;
        }
        else{
            return max( MaksZPrzedzialu(lew, praw, lw, (lw+pw)/2, poz*2), 
                        MaksZPrzedzialu(lew, praw, (lw+pw)/2+1, pw, poz*2+1));
        }
    }

    long long Przedzial(int lew, int praw){
        return MaksZPrzedzialu(lew, praw, 0, wlk-1, 1);
    }
};
