node query(int tree_l,int tree_r,int treeix,int q_l,int q_r)
{
  //cout<<"tree_range : "<<tree_l<<":"<<tree_r<<endl;
  if(q_l<=tree_l && q_r>=tree_r)
  {
    return tree[treeix];
  }
  else if(q_l>tree_r || q_r<tree_l)
  {
    node t;
    return t;
  }
  int m = (tree_l + tree_r)/2;
  node left = query(tree_l,m,2*treeix,q_l,q_r);
  node right = query(m+1,tree_r,2*treeix+1,q_l,q_r);
  node ans;
  if(left.timestamp < right.timestamp)
  {
    ans.data = left.data + right.data;
  }
  else
  {
    ans.data = max(left.data,right.data);
  }
  //cout<<"timestamp : "<<left.timestamp<<" "<<right.timestamp<<endl;
  //cout<<"for range "<<tree_l<<" "<<tree_r<<" : "<<ans.data<<endl;
  ans.timestamp = max(left.timestamp,right.timestamp);
  return ans;
}

void update(int tree_l,int tree_r,int treeix,int valix,int value,int time)
{
  //cout<<"tree_range : "<<tree_l<<":"<<tree_r<<endl;
  if(tree_l == tree_r)
  {
    tree[treeix].data = value;
    tree[treeix].timestamp = time;
    return;
  }
  int m = (tree_l + tree_r)/2;
  if(m<valix)
  {
    update(m+1,tree_r,2*treeix+1,valix,value,time);
  }
  else
  {
    update(tree_l,m,2*treeix,valix,value,time);
  }
  tree[treeix].timestamp = time;
  node l = tree[2*treeix];
  node r = tree[2*treeix+1];
  if(l.timestamp < r.timestamp)
  {
    tree[treeix].data = l.data + r.data;
  }
  else
  {
    tree[treeix].data = max(l.data,r.data);
  }
}


