class SegmentTree {
    long long n;
    vector<long long> dat;

    // i は接点の番号、l, rはその接点が[l, r)に対応していることを示す
    long long query_sub(long long a, long long b, long long i, long long l, long long r) {
        if (r <= a || b <= l) return 0;
        if (a <= l && r <= b)
            return dat[i];
        else {
            long long vl = query_sub(a, b, i * 2 + 1, l, (l + r) / 2);
            long long vr = query_sub(a, b, i * 2 + 2, (l + r) / 2, r);
            return max(vl, vr);
        }
    }

public:
    // 葉がn個のセグメント木
    // 実際の葉の数は完全二分木にしているので少し増える
    SegmentTree(long long n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat = vector<long long>(2 * n - 1, 0);
    }
    // i に x を入れる
    void update(long long i, long long x) {
        i += n - 1;
        dat[i] = x;
        while (i > 0) {
            i = (i - 1) / 2;
            dat[i] = max(dat[i * 2 + 1], dat[i * 2 + 2]);
        }
    }
    // [a, b) の最小値を求める
    long long query(long long a, long long b) { return query_sub(a, b, 0, 0, n); }
    // 配列にアクセス
    long long at(long long i) { return dat[i + n - 1]; }
};

