int getMid(int s, int e) 
{ 
    return s + (e - s) / 2; 
} 

int MaxUtil(int ss, int se, int l,int r, int node) 
{ 
    if (l <= ss && r >= se) 
        return tree[node]; 

    if (se < l || ss > r) 
        return -1; 

    int mid = getMid(ss, se); 

    return max(MaxUtil(ss, mid, l, r, 2 * node + 1), MaxUtil(mid + 1, se, l, r, 2 * node + 2)); 
} 


