ll query(ll index,ll start,ll end,ll l ,ll r,vector<ll>&segtree)
{
    //complete outside
    if(r<start || l>end) return LLONG_MIN;
    //complete inside
    if(l<=start && end<=r) return segtree[index];

    ll mid = (start+end)/2;
    ll left = query(2*index+1,start,mid,l,r,segtree);
    ll right = query(2*index+2,mid+1,end,l,r,segtree);
    return max(left,right);
}
void update(ll index,ll start,ll end,ll i ,ll newvalue,vector<ll>&segtree,vector<ll>&dp)
{
    //complete outside
    if(i<start || i>end) return ;
    if(start==end) dp[start] = segtree[index]=newvalue;
    else {
        ll mid = (start+end)/2;
        update(2*index+1,start,mid,i,newvalue,segtree,dp);
        update(2*index+2,mid+1,end,i,newvalue,segtree,dp);
        segtree[index] = max(segtree[2*index+1],segtree[2*index+2]);
    }
}

