    while (x > 1) {
        x /= 2;
        t[x] = max(t[2*x], t[2*x+1]);
    }
}
ll get_max(int x, int y) {
    x += M;
    y += M;
    ll res = max(t[x], t[y]);
    while (x/2 != y/2) {
        if (x%2 == 0) {
            res = max(res, t[x+1]);
        }
        if (y%2 == 1) {
            res = max(res, t[y-1]);
        }
        x /= 2;
        y /= 2;
    }
    return res;
}
