struct counter {
  const int magic = 1000;
  const int maxn = 1000 * 1000 + 100;

  vector<long long> range, sqrt_range;

  counter() : range(maxn),
              sqrt_range((maxn + magic - 1) / magic)
  {}

  void update(int at, long long by) {
    range[at] += by;
    sqrt_range[at / magic] = max(sqrt_range[at / magic], by);
  }

  long long query_max(int left, int right) {
    long long value = 0;

    for (int i = 0; i < sqrt_range.size(); ++i) {
      if (left / magic < i and i < right / magic) {
        value = max(value, sqrt_range[i]);
      }
    }

    for (int i = left; i <= right; ) {
      value = max(value, range[i]);

      i++;
      if (i % magic == 0) break;
    }

    for (int i = right; i >= left; ) {
      value = max(value, range[i]);

      if (i % magic == 0) break;
      i--;
    }

    return value;
  }
} counter;

