#define rep(i, a, b) for(int i = a; i < b; i++)
typedef long long ll;

const int MAX_N = 2e5+10;
const int def = 0;

//セグメント木を持つグローバル配列
ll n, dat[2 * MAX_N - 1];

//初期化
void init(ll n_){
    //簡単のため、要素数を2のべき乗に
    n = 1;
    while ( n < n_ ) n *= 2;

    //全ての値をINT_MAXに
    for(int i = 0; i < 2 * n - 1; i++) dat[i] = def;
}

//k番目の値(0-indexed)をaに変更
void update(ll k, ll a){
    //葉の節点
    k += n - 1;
    dat[k] = a;
    //登りながら更新
    while(k > 0){
        k = (k-1)/2;
        dat[k] = max(dat[k*2+1], dat[k*2+2]);
    }
}

// [a,b)の最小値を求める
// 後ろの方の引数は、計算の簡単のための引数
// kは節点の番号、1,rはその接点が[1,r)に対応づいていることを表す
// したがって、外からはquery(a, b, 0, 0, n)として呼ぶ
ll query(ll a, ll b, ll k = 0, ll l = 0, ll r = n){
    //[a,b)と[l,r)が交差しなければ、INT_MAX
    if( r <= a || b <= l) return def;

    //[a,b)が[l,r)を完全に含んでいれば、この節点の値
    if(a <= l && r <= b) return dat[k];
    else{
        //そうでなければ、２つの子が必要
        ll vl = query(a, b, k * 2 + 1, l, (l+r)/2);
        ll vr = query(a, b, k * 2 + 2, (l+r)/2, r);
        return max(vl,vr);
    }
}

int main(){
    ll N; cin >> N;
    vector<ll> h(N), a(N);
    rep(i, 0, N) cin >> h[i];
    rep(i, 0, N) cin >> a[i];

    init(N);
    rep(i, 0, N){
        update(h[i]-1, query(0, h[i]-1) + a[i]);
    }
    cout << query(0, N) << endl;
}

