        ll p=lower_bound(v.begin(),v.end(),h[i])-v.begin();

        if(p<v.size())
        {
            if(p==0)
            {
                dp[h[i]]=a[i];
                if(dp[h[i]]>=dp[v[p]]) v[p]=h[i];
                else{
                    v.push_front(h[i]);
                }
                continue;
            }
            dp[h[i]]=dp[v[p-1]]+a[i];
            if(dp[h[i]]>=dp[v[p]]) v[p]=h[i]; else
            {
                v[p-1]=h[i];
            }
        }
        else
        {
            if(!v.empty())dp[h[i]]=dp[v[p-1]]+a[i];
            else dp[h[i]]=a[i];
            v.push_back(h[i]);
        }
        //cout<<p<<" "<<dp[h[i]]<<"\n";
        //for(ll i=0;i<v.size();i++) cout<<v[i]<<" ";cout<<"\n";
    }
    ll sum=0;
    for(ll i=1;i<=n;i++) sum=max(sum,dp[i]);
    cout<<sum;

    return 0;
}

