ll
getValue(vector<ll> & seg, ll start, ll end) {
  if (start > end) return 0;

  ll ret = 0;
  while (1) {
    if (start > end) break;

    if (end % 2 == 0) {
      ret = max(ret, seg[end]);
      end--;
    }
    if (start % 2 == 1) {
      ret = max(ret, seg[start]);
      start++;
    }

    start /= 2;
    end /= 2;
  }

  return ret;
}

void
update(vector<ll> & seg, ll index, ll v) {
  ll i = index;
  seg[i] = v;
  while (1) {
    if (i == 0) break;

    i /= 2;
    seg[i] = max(seg[i*2], seg[i*2+1]);
  }
}

