void upd(int x, int l, int r, int p, long long v) {
    if(l == r) {
        assert(l == p);
        tree[x] = max(tree[x], v);
        return;
    }
    int m = ((l+r)/2);
    if(p <= m) upd((2*x), l, m, p, v);
    else upd((2*x+1), 1+m, r, p, v);
    tree[x] = max(tree[2*x], tree[2*x+1]);
}

long long query(int x, int l, int r, int p, int q) {
    if(r < p or q < l) return 0;
    if(p<=l and r<=q) return tree[x];
    int m = ((l+r)/2);
    return max(query((x<<1), l, m, p, q), query((x<<1)+1, 1+m, r, p, q));
}

