void update(ll nd, ll b, ll e, ll idx, ll val){
    if(b == e){

        tree[nd] = val;
    }
    else{
        ll mid = (b+e)/2;
        if(b <= idx && idx <= mid)
            update(2*nd,b,mid,idx,val);
        else
            update(2*nd+1,mid+1,e,idx,val);
        tree[nd] = max(tree[2*nd],tree[2*nd+1]);
    }
}
// rmq kortisi
ll query(ll nd, ll b, ll e, ll qb, ll qe){
    if(e < qb || qe < b)    return -inf;
    if(qb <= b && e <= qe)    return tree[nd];
    ll mid = (b+e)/2;
    return max(query(2*nd,b,mid,qb,qe),query(2*nd+1,mid+1,e,qb,qe));
}


