ll N;
ll tree[400010];
void updateTreeNode(ll p,ll value)
{
    ll i;
	tree[p+N] = value;
	p = p+N;
	for (i=p; i > 1; i >>= 1)
		tree[i>>1] =max(tree[i] , tree[i^1]);
}
ll query(ll l,ll r)
{
	ll res = 0;
	for (l += N, r += N; l < r; l >>= 1, r >>= 1)
	{
		if (l&1)
			res =max(res,tree[l++]);

		if (r&1)
			res =max(res,tree[--r]);
	}
	return res;
}
