int dp[N];

int dynamic(int pos, int prev_h)
{
    if (pos > n)
    {
        return 0;
    }
    if (dp[prev_h] != -1)
        return dp[prev_h];
    int ans = INT_MIN;
    if (h[pos] > prev_h)
    {
        ans = max(dynamic(pos + 1, prev_h), dynamic(pos + 1, h[pos]) + a[pos]);
    }
    else
    {
        ans = max(ans, dynamic(pos + 1, prev_h));
    }
    dp[prev_h] = ans;
    return ans;
}

