		int mid = l + (r - l) / 2;
		ll a = query(0, mid, v * 2 + 1, tl , tr);
        ll b = query(mid + 1, r, v * 2 + 2, tl, tr);
		return max(a, b);
	}
}

void update(int l, int r, int v, int index, ll value) {
	if(l == r) tree[v] = value;
	else {
		int mid = l + (r - l) / 2;
		if(index <= mid) {
			update(l, mid, v * 2 +1, index, value);		
		}
		else {
			update(mid + 1, r, v * 2 + 2, index, value);	
		}
		tree[v] = max(tree[v * 2 + 1], tree[v * 2 + 2]);
	}
}

