template<class T>
struct SegmentTree{
    private:
      using F=std::function<T(T,T)>;

      T n;
      T ide_ele;
      std::vector<T> seg;
      F fn;

    public:
      //要素数_n,単位元ide_ele,比較関数funで初期化
      SegmentTree(T _n,T ide_ele,F fun) : ide_ele(ide_ele), fn(fun){
          n = 1;
          while(n<_n) n *= 2;
          seg.assign(2*n-1,ide_ele);
      }

      //配列ide_val,単位元ide_val,比較関数funで初期化
      SegmentTree(std::vector<T> &ide_val,T ide_ele,F fun): ide_ele(ide_ele), fn(fun){
          n = 1;
          T _n = ide_val.size();
          while(n<_n) n *=2;
          seg.assign(2*n-1, ide_ele);
          for(T i = 0; i<_n; i++) seg[n+i-1] = ide_val[i];
          for(T i = n-2; i>=0; i++) seg[i] = fn(seg[2*i+1],seg[2*i+2]);
      }

      void update(T index,T x,bool flag=false){
          T k = index+n-1;
          if(flag) seg[k] +=x;
          else seg[k] = x;
          while(k>0){
              k = (k-1)/2;
              seg[k] = fn(seg[2*k+1],seg[2*k+2]);
          }
      }

      //[a,b)の区間でquery処理
      T query(T a,T b){
          if(a<0 || n<b) return ide_ele;
          T lval = ide_ele, rval = ide_ele;
          T l = a+n-1, r = b+n-1;
          for(;l<r;l=(l>>1),r=(r>>1)){
              if(!(r&1)){
                  r--;
                  rval = fn(seg[r],rval);
              }
              if(!(l&1)){
                  lval = fn(lval,seg[l]);
                  l++;
              }
          }
          return fn(lval,rval);
      }
};

