struct Tree {
    int l, r;
    ll mx;
}tree[maxn << 2];

void pushup(int i) {
    tree[i].mx = max(tree[i * 2].mx, tree[i * 2 + 1].mx);
}

void build(int i, int l, int r) {
    tree[i].l = l; tree[i].r = r;
    tree[i].mx = 0;
    if (l >= r) {
        return ;
    }
    int mid = (l + r) / 2;
    build(i * 2, l, mid); build(i * 2 + 1, mid + 1, r);
}

void update(int i, int pos, ll val) {
    if (tree[i].l == tree[i].r) {
        tree[i].mx = val; return ;
    }
    int mid = (tree[i].l + tree[i].r) / 2;
    if (mid >= pos) {
        update(i * 2, pos, val);
    } else {
        update(i * 2 + 1, pos, val);
    }
    pushup(i);
}

ll query(int i, int l, int r) {
    if (tree[i].l == l && tree[i].r == r) {
        return tree[i].mx;
    }
    int mid = (tree[i].l + tree[i].r) / 2;
    if (mid >= r) {
        return query(i * 2, l, r);
    } else if(l > mid) {
        return query(i * 2 + 1, l, r);
    } else {
        return max(query(i * 2, l, mid), query(i * 2 + 1, mid + 1, r));
    }
}

