struct SegmentTree{
        private:
        ll n;
        vector<ll> node;

        public:
        SegmentTree(vector<ll> v){
                ll sz = v.size();
                n = 1;
                while(n < sz) n *= 2;
                node.resize(2*n-1,0);
                for(ll i=0;i<sz;i++) node.at(i+n-1) = v.at(i);
                for(ll i=n-2;i>=0;i--) node.at(i) = max(node.at(2*i+1),node.at(2*i+2));
        }

        void update(ll x,ll val){
                x += n-1;
                node.at(x) = val;
                while(x > 0){
                        x = (x-1)/2;
                        node.at(x) = max(node.at(2*x+1),node.at(2*x+2));
                }
        }

        ll getmax(ll a,ll b,ll k=0,ll l=0,ll r=-1){
                if(r < 0) r = n;
                if(r <= a || b <= l) return 0;
                if(a <= l && r <= b) return node.at(k);
                ll vl = getmax(a,b,2*k+1,l,(l+r)/2);
                ll vr = getmax(a,b,2*k+2,(l+r)/2,r);
                return max(vl,vr);
        }
};

