void pushup(int id)
{
    tree[id].value = max(tree[2 * id].value, tree[2 * id + 1].value);
}
void createtree(int id, int s, int t)
{
    tree[id].lazy = 0;
    if (s == t)
        tree[id].value = 0;
    else
    {
        int mid = s + (t - s) / 2;
        createtree(2 * id, s, mid);
        createtree(2 * id + 1, mid + 1, t);
        pushup(id);
    }
}
void pushdown(int id, int s, int t)
{
    if (tree[id].lazy != 0)
    {
        int mid = s + (t - s) / 2;
        tree[2 * id].lazy += tree[id].lazy;
        tree[2 * id + 1].lazy += tree[id].lazy;
        tree[2 * id].value += tree[id].lazy;
        tree[2 * id + 1].value += tree[id].lazy;
        pushup(id);
        tree[id].lazy = 0;
    }
}
long long query(int id, int ns, int nt, int qs, int qt)
{
    if (qs > nt || qt < ns)
        return 0;
    if (qs <= ns && qt >= nt)
        return tree[id].value;
    pushdown(id, ns, nt);
    int mid = ns + (nt - ns) / 2;
    return max(query(2 * id, ns, mid, qs, qt), query(2 * id + 1, mid + 1, nt, qs, qt));
}
void singleupdate(int id, int ns, int nt, int index, long long value)
{
    if(ns == nt)
    {
        if(index == ns)
            tree[id].value += value;
        return;
    }
    int mid = ns + (nt - ns) / 2;
    if(index <= mid)
        singleupdate(2 * id, ns, mid, index, value);
    else
        singleupdate(2 * id + 1, mid + 1, nt, index, value);
    pushup(id);
}

