struct SegmentTree{
  ll n=1;
  vll node;

  SegmentTree(vll a){
    ll N=a.size();
    while(n<N)
      n*=2;

    node=vll(2*n-1, -LLINF);
    REP(i, a.size())
      node[n-1+i]=a[i];

    for(ll i=n-2; i>=0; i--)
      node[i]=max(node[2*i+1], node[2*i+2]);
  }


  void update(ll index, ll value){
    ll cur = index+n-1;
    node[cur] = value;
    while(cur>0){
      cur = (cur-1)/2;
      node[cur]=max(node[2*cur+1], node[2*cur+2]);
    }
  }

  ll find(ll qs, ll qe, ll index=0, ll l=0, ll r=-1){
    if(r<0)
      r=n;
    if(r<=qs || qe<= l)
      return -LLINF;
    else if(qs<=l && r<=qe)
      return node[index];

    ll vl = find(qs,qe,2*index+1,l,(l+r)/2);
    ll vr = find(qs,qe,2*index+2,(l+r)/2,r);
    return max(vl, vr);
  }
};


