ll update(int start, int end, int upos, ll val, int pos)
{
	if (upos < start or upos > end)
		return tree[pos];

	if (start == end)
		return tree[pos] = val;

	int mid = (start+end)/2;
	ll l = update(start, mid, upos, val, 2*pos + 1);
	ll r = update(mid+1, end, upos, val, 2*pos + 2);
	return tree[pos] = max(l, r);
}

ll query(int start, int end, int qstart, int pos)
{
	if (qstart > end)
		return 0;

	if (start >= qstart)
		return tree[pos];

	int mid = (start+end)/2;
	ll l = query(start, mid, qstart, 2*pos + 1);
	ll r = query(mid+1, end, qstart, 2*pos + 2);
	return max(l, r);
}

