int addNode()
{
	t.PB(0);
	L.PB(-1);
	R.PB(-1);
	return t.size() - 1;
}

void add(int v,int l,int r,int pos,LL val)
{
	if (l == r)
	{
		t[v] = val;
		return;
	}
	int m = (l + r) >> 1;
	if (L[v] == -1)
		L[v] = addNode();
	if (R[v] == -1)
		R[v] = addNode();
	if (pos <= m)
		add(L[v], l, m, pos, val);
	else
		add(R[v], m + 1, r, pos, val);
	t[v] = max(t[L[v]], t[R[v]]);
}

LL get(int v,int l,int r,int pos)
{
	if (l == r)
		return t[v];

	if (L[v] == -1)
		L[v] = addNode();
	if (R[v] == -1)
		R[v] = addNode();

	int m = (l + r) >> 1;
	if (pos <= m)
		return get(L[v], l, m, pos);
	else
		return max(t[L[v]], get(R[v], m + 1, r, pos));
}

