void update(int n, int k, ll a) {
    k += n - 1;
    dp[k] = a;

    while (k > 0) {
        k = (k - 1) / 2;
        if (dp[k] >= a) break;
        dp[k] = a;
    }
}

ll query(int a, int b, int k, int l, int r) {
    if (b <= l || r <= a) return 0;
    if (a <= l && r <= b) return dp[k];

    ll v1, v2;
    v1 = query(a, b, k * 2 + 1, l, (l + r) / 2);
    v2 = query(a, b, k * 2 + 2, (l + r) / 2, r);
    return max(v1, v2);
}

