class SegmentTree
{
  public:
  SegmentTree(int n)
  {
    this->n = n;
    vec_.resize(4 * n);

  }


  long long int query(int low, int high)
  {
    return query(low, high, 1, 0, n-1);
  }

  void add(int index, long long int value)
  {
    add(index, value, 1, 0, n-1);

  }

  void debug()
  {
    debug(1, 0, n-1);
  }


  private:
  vector<long long> vec_;
  int n;
  int left(int x) { return x * 2; }
  int right(int x) { return left(x) + 1;}
  long long int query(int ql, int qu, int current, int rl, int ru)
  {
    if (qu < rl or ql > ru)
      return 0;
    if (rl >= ql and ru <= qu)
       return vec_[current];
    if (rl == ru)
      return vec_[current];
    int mid = (rl + ru)/2;
    return max(query(ql, qu, left(current), rl, mid), query(ql,qu, right(current), mid + 1, ru));
  }

  void add(int index, long long  int val, int current, int rl, int ru)
  {
    if ( index > ru or index < rl)
      return;
    if (rl == index and ru == index)
    {
      vec_[current] = val;
      return;
    }
    vec_[current] = max(vec_[current], val);
    int mid = (rl + ru)/2;
    add(index, val, left(current), rl, mid);
    add(index, val, right(current), mid + 1, ru);
  }


  void debug(int current, int rl, int ru)
  {
    cout << "Range : " << rl <<'-' << ru << ':' << vec_[current] <<'\n';
    if (rl ==  ru) {
      return;
    }
    int mid = (rl + ru)/2;
    debug(left(current), rl, mid);
    debug(right(current), mid + 1, ru);
  }


};


