void push_up(int rt)
{
    tree[rt].val=max(tree[rt<<1].val,tree[rt<<1|1].val);
}
void build(int rt,int l,int r)
{
    tree[rt].l=l;
    tree[rt].r=r;
    if(l==r)
    {
        tree[rt].val=0;
        return ;
    }
    int mid=tree[rt].mid=((l+r)>>1);
    build(rt<<1,l,mid);
    build(rt<<1|1,mid+1,r);
    push_up(rt);
}
void update(int rt,int pos,ll val)
{
    if(tree[rt].l==tree[rt].r)
    {
        tree[rt].val=val;
        return ;
    }
    if(pos<=tree[rt].mid) update(rt<<1,pos,val);
    else update(rt<<1|1,pos,val);
    push_up(rt);
}
ll query(int rt,int l,int r)
{
    if(tree[rt].l>r||tree[rt].r<l) return -1;
    if(tree[rt].l>=l&&tree[rt].r<=r) return tree[rt].val;
    ll maxx=0;
    if(l<=tree[rt].mid) maxx=max(maxx,query(rt<<1,l,r));
    if(r>tree[rt].mid) maxx=max(maxx,query(rt<<1|1,l,r));
    return maxx;
}
