void update_tree( int leaf, long long value, int root_id, int left, int right) {
  // cout << ">>>" << leaf << " " << left << " " << right << endl;
  if (left > right) return;
  if (left == right && left == leaf) {
    st[root_id] = value;
  } else {
      int mid = (left + right) / 2;

      if (leaf <= mid) update_tree(leaf, value, root_id*2, left, mid);
      if (leaf > mid) update_tree(leaf, value, root_id*2+1, mid+1, right);

      if (st[root_id] < value) st[root_id] = value;
  }
}

long long query( int queryleft, int queryright, int left, int right, int root_id) {
    if ( left >= queryleft && right <= queryright) return st[root_id];

    if (  left > queryright ) return -1;
    if ( right < queryleft) return -1;

    int mid = (left + right)/2;
    // (left, mid)   and (mid+1, right) // vs. (ql, qr)
    long long qlres = query(queryleft, queryright, left, mid, root_id*2);
    long long qrres = query(queryleft, queryright, mid+1, right, root_id*2+1);

    return max(qlres, qrres);
}


