void build(int idx,int l,int r)
{
   if(l==r)
   {
      seg[idx] = 0;
      return;
   }

   int mid = (l+r)/2;
   build((2*idx)+1, l, mid);
   build((2*idx)+2, mid+1, r);
   seg[idx] = 0;
   return;
}


ll query(int idx,int l, int r, int a, int b)
{
   if(a>b)
      return 0;

   // subset
   if(a<=l && r<=b)
   {
      return seg[idx];
   }
   // no
   if(b<l || r<a)
   {
      return 0;
   }

   int mid = (l+r)/2;
   ll v1 = query((2*idx)+1, l, mid, a, b);
   ll v2 = query((2*idx)+2, mid+1, r, a, b);
   return max(v1, v2);

}

void update(int idx,int l,int r,int i,ll val)
{
   if(l==r)
   {
      seg[idx] = max(seg[idx], val);
      return;
   }

   int mid = (l+r)/2;
   if(i<=mid)
   {
      update((2*idx)+1, l, mid, i, val);
   }
   else
   {
      update((2*idx)+2, mid+1, r, i, val);
   }
   seg[idx] = max(seg[(2*idx)+1], seg[(2*idx)+2]);
   return;
}

