struct node{
    int s,e,m;
    ll v;
    node *l,*r;
    node(int S,int E){
        s=S;e=E;m=(s+e)/2;v=0;
        if(s!=e){
            l=new node(s,m);r=new node(m+1,e);
        }
    }
    void upd(int x,ll nv){
        if(s==e){v=max(v,nv);return;}
        if(x<=m)l->upd(x,nv);
        else r->upd(x,nv);
        v=max(l->v,r->v);
    }
    ll qry(int x){ //pref max
        if(x==e)return v;
        if(x<=m)return l->qry(x);
        return max(l->qry(m),r->qry(x));
    }
