template<typename T=int, typename E=int>
struct segment_tree{
  typedef function<T(T,T)> F;
  typedef function<T(T,E)> G;
  typedef function<E(E,E)> H;
  typedef function<E(E,int)> P;

  vector<T> data;
  vector<E> lazy;

  F f;
  G g;

  int n;

  T tid;

  H h;
  E eid;

  P p;

  // f is query monoid for merge. tid is f's identity element.
  // g is data updated function. g is often same as h.
  // h is lazy updated function. eid is h's identity element.
  // p is data updated function for ranged element from lazy. this is dependent on f.
  segment_tree(int size, F f, G g, T tid, H h=[](E a,E b){return b!=numeric_limits<E>::min()?a:b;}, E eid=0, P p=[](E a, int b){b=0;return a+b;}):f(f),g(g),tid(tid),h(h),eid(eid),p(p){
    n = 1;
    while(n<size) n<<=1;
    data.assign(2*n-1,tid), lazy.assign(2*n-1,eid);
  }
  segment_tree(vector<T> v, F f, G g, T tid, H h=[](E a,E b){return b!=numeric_limits<E>::min()?a:b;}, E eid=0, P p=[](E a, int b){b=0;return a+b;}):f(f),g(g),tid(tid),h(h),eid(eid),p(p){
    int size = v.size();
    n = 1;
    while(n<size) n<<=1;
    data.resize(2*n-1,tid);
    assign(v);
  }
  void assign(vector<T> v){
    assert((int)v.size()<=n);
    for(size_t i=0;i<v.size();++i) data[i+n-1] = v[i];
    for(int i=v.size();i<n;++i) data[i+n-1] = tid;
    for(int i=n-2;i>=0;--i) data[i] = f(data[2*i+1],data[2*i+2]);
    lazy.assign(2*n-1,eid);
  }
  inline void eval(int k, int len){
    if(lazy[k]!=eid){
      data[k] = g(data[k],p(lazy[k],len));
      // k has children.
      if(len > 1){
        lazy[2*k+1] = h(lazy[2*k+1],lazy[k]);
        lazy[2*k+2] = h(lazy[2*k+2],lazy[k]);
      }
      lazy[k] = eid;
    }
  }
  void update(int i, E x){
    i += n-1;
    data[i] = g(data[i],x);
    while(i>0){
      i = (i-1)/2;
      data[i] = f(data[2*i+1],data[2*i+2]);
    }
  }
  void update(int a,int b,E x){
    update(a,b,x,0,0,n);
  }
  void update(int a, int b, E x,int k, int l, int r){
    eval(k,r-l);

    // [l,r) out of [a,b)
    if(b<=l||r<=a) return;
    // [l,r) in [a,b)
    if(a<=l && r<=b){
      lazy[k] = h(lazy[k],x);
      eval(k,r-l);
    }else{
      update(a,b,x,2*k+1,l,(l+r)/2);
      update(a,b,x,2*k+2,(l+r)/2,r);
      data[k] = f(data[2*k+1],data[2*k+2]);
    }
  }
  T find(int i){
    return find(i,i+1,0,0,n);
  }
  // [a,b)
  T find(int a,int b){
    return find(a,b,0,0,n);
  }
  T find(int a,int b,int k,int l,int r){
    eval(k,r-l);

    // [l,r) out of [a,b)
    if(r<=a||b<=l) return tid;

    // [l,r) in [a,b)
    if(a<=l&&r<=b) return data[k];

    // else
    return f(find(a,b,2*k+1,l,(l+r)/2),find(a,b,2*k+2,(l+r)/2,r));
  }
};
