  map<D, int> mp;
  MapZ(const vector<D> &d) : dat(d) {
    sort(dat.begin(), dat.end());
    dat.erase(unique(dat.begin(), dat.end()), dat.end());
    for (int i = 0; i < dat.size(); ++i) mp[dat[i]] = i;
  }
  int operator()(const D &x) { return mp[x]; }
  int operator[](int x) { return dat[x]; }
  int size() { return dat.size(); }
};

