template<class T> struct SegTree{
  int n;
  vector<T> node;
  T initv;

  SegTree(int n_, T initv_){
    n = 1;
    while(n < n_) n *= 2;
    node.resize(n*2-1);
    initv = initv_;
    rep(i, n*2-1) node[i] = initv;
  }

  void update(int i, T val){
    i += n - 1;
    node[i] = val;
    while(i > 0) i = (i-1) / 2, node[i] = max(node[i*2+1], node[i*2+2]);
  }

  T getmax(int a, int b, int i, int l, int r){
    if(r<=a || b<=l) return initv;
    if(a<=l && r<=b) return node[i];
    T vl = getmax(a, b, i*2+1, l, (l+r)/2);
    T vr = getmax(a, b, i*2+2, (l+r)/2, r);
    return max(vl, vr);
  }
};

