typedef long long llt;

const int MaxN = 200000 + 5;

int N;
int H[MaxN]; llt W[MaxN];
llt dp[MaxN], Bit[MaxN];

void init() {
  scanf("%d", &N);
  for (int i = 1; i <= N; ++i) scanf("%d", &H[i]);
  for (int i = 1; i <= N; ++i) scanf("%lld", &W[i]);
}

inline int lowbit(int i) {
  return i & -i;
}

inline void update(int x, llt v) {
  for (int i = x; i <= N; i += lowbit(i))
    Bit[i] = max(Bit[i], v);
}

inline llt query(int x) {
  llt res = 0;
  for (int i = x; i > 0; i -= lowbit(i))
    res = max(res, Bit[i]);
  return res;
}

void solve() {
  for (int i = 1; i <= N; ++i) {
    dp[i] = query(H[i]) + W[i];
    update(H[i], dp[i]);
  }

  llt ans = 0;
  for (int i = 1; i <= N; ++i) ans = max(ans, dp[i]);
  cout << ans << endl;
}

int main() {
  init();
  solve();
  return 0;
}

