using ll = long long;

vector<ll> seg;

template<typename T>
void max_self(T& a, T b)
{
  a = max(a, b);
}

void calculate(int root)
{
  seg[root] = max(seg[root * 2], seg[root * 2 + 1]);
}

long long maxi(int l, int r, int x, int y, int root = 1)
{
  // full overlap
  if(x <= l and r <= y)
    return seg[root];

  // no overlap
  if(y < l or r < x)
    return 0;

  ll ans = 0;
  int mid = (l + r) / 2;
  max_self(ans, maxi(l, mid, x, y, root * 2));
  max_self(ans, maxi(mid + 1, r, x, y, root * 2 + 1));
  return ans; 
}

void update(int l, int r, int x, ll val, int root = 1)
{
  if(l == r)
  {
    seg[root] = val;
    return;
  }
  int mid = (l + r) / 2;
  if(x <= mid)
    update(l, mid, x, val, root * 2);
  else
    update(mid + 1, r, x, val, root * 2 + 1);
  calculate(root);  
}


