long long int st[800005];

long long int query(int node, int be, int en, int l, int r){
	if(be >= l && en <= r)return st[node];
	if(be > r || en < l)return 0;
	int mid = (be + en) >> 1;
	long long int p1 = query(2*node, be, mid, l, r);
	long long int p2 = query(2*node + 1, mid + 1, en, l, r);
	return max(p1, p2);
}

void update(int node, int be, int en, int pos, int value){
	if(be == en){
		st[node] = value;
		return;
	}
	int mid = (be + en) >> 1;
	if(pos <= mid)update(2*node, be, mid, pos, value);
	else update(2*node + 1, mid + 1, en, pos, value);
	st[node] = max(st[2*node], st[2*node + 1]);
	return;
}

