void build(int f)
{
    if(dp[f].l!=dp[f].r)
    {
        int mid=(dp[f].l+dp[f].r)/2;
        dp[2*f].l=dp[f].l;
        dp[2*f].r=mid;
        dp[2*f+1].l=mid+1;
        dp[2*f+1].r=dp[f].r;
        build(2*f);
        build(2*f+1);
    }
}

ll solve(int pos)
{
    int i=1;
    res=0;
    while(dp[i].l!=dp[i].r)
    {
        mid=(dp[i].l+dp[i].r)/2;
        if(dp[i].v+a[pos]>res)
            res=dp[i].v+a[pos];
        if(h[pos]<=mid)
            i=2*i;
        else
            i=2*i+1;
    }
    if(dp[i].v+a[pos]>res)
            res=dp[i].v+a[pos];
    i=1;
    while(dp[i].l!=dp[i].r)
    {
        if(dp[i].l==h[pos])
            dp[i].v=res;
        mid=(dp[i].l+dp[i].r)/2;
        if(h[pos]<=mid)
        {
            if(dp[2*i+1].v<res)
                dp[2*i+1].v=res;
            i=2*i;
        }
        else
            i=2*i+1;
    }
    dp[i].v=res;
}

