void update_tree(int cur,int s,int e,int pos,int val)
{
     if(s==e-1)
     {
          st[cur]=val;
          return;
     }
     if(pos<s || pos>=e)
          return;
     int c1=(cur<<1),c2=c1+1,m=(s+e)>>1;
     update_tree(c1,s,m,pos,val);
     update_tree(c2,m,e,pos,val);
     st[cur]=max(st[c1],st[c2]);
}

void query_tree(int cur,int s,int e,int l,int r)
{
     if(l>=e || r<=s)
     {
          qt[cur]=0;
          return;
     }
     if(s>=l && r>=e)
     {
          qt[cur]=st[cur];
          return;
     }
     int c1=2*cur,c2=c1+1,m=(s+e)>>1;
     query_tree(c1,s,m,l,r);
     query_tree(c2,m,e,l,r);
     qt[cur]=max(qt[c1],qt[c2]);
}

