ll dfs(int i, int H){
  if(dp[i][H]) return dp[i][H];
  // used[i][H] = true;
  if(i>=N) return dp[i][H] = 0;
  ll ret = 0;
  if(F[i].h<H){
    // 高さが単調増加になるように花を抜き去る
    ret = dfs(i+1,H);
  }
  else{
    // 花を抜き去る場合と抜き去らない場合で、残りの花の美しさの大きい方をとる。
    ret = max(F[i].a+dfs(i+1,F[i].h),dfs(i+1,H));
  }
  return dp[i][H] = ret;
}

