struct flower {
	int height, beauty;
};

int solve(flower arr[], int n) {

	vector<int> dp(n, 0);
	dp[0] = arr[0].beauty;
	map<int, int> m;
	m[arr[0].height] = dp[0];
	int ans = dp[0];
	for (int i = 1; i < n; i++) {
		dp[i] = arr[i].beauty;
		auto it = m.upper_bound(arr[i].height);
		if (it != m.begin()) {
			it--;
			dp[i] += it->second;
		}
		m[arr[i].height] = dp[i];

		it = m.upper_bound(arr[i].height);
		while (it != m.end() and it->second <= dp[i]) {
			auto temp = it;
			temp++;
			m.erase(it);
			it = temp;
		}
		ans = max(ans, dp[i]);
	}
	return ans;
}


