struct SegmentTree{
    VI A;
    ll N; // node num
    // 初期化
    SegmentTree(ll size){
        N = _powerOfTwo(size); //2べき
        // ll initial_value = (1LL<<31)-1LL;
        ll initial_value = -inf;
        A.resize(N * 2, initial_value); // 木なので2倍必要
    }
    void update(ll i, ll x){
        int index = N + i - 1; // 葉のインデックス
        A[index] = x;
        // 親にも反映
        while(index > 0){
            ll min0 = A[index];
            ll min1;
            if(index%2==0){
                min1 = A[index-1];
            }else{
                min1 = A[index+1];
            }

            ll parent = (index-1) / 2;
            // A[parent] = min(min0, min1);
            A[parent] = max(min0, min1);
            index = parent;
        }
    }
    bool is_power_of_two(ll v){
        return !(v & (v-1));
    }
    void DebugPrintTree(){
        // of << "tree" << endl;
        // FOR(i, 0, 2*N-1){
        //     if(i!=0 && is_power_of_two(i+1)){
        //         of << endl;
        //     }
        //     of << A[i] << ' ';
        // }
        // of << endl;
    }
    // 引数以上の2のべき乗 5=>8
    ll _powerOfTwo(int n){
        ll ret = 1;
        while(ret < n){
            ret *= 2;
        }
        return ret;
    }
    // 区間[a,b)の総和。ノードk = [l,r) に着目している
    ll _rangeMax(int a, int b, int k, int l, int r){
        //cout << "_rangeSum() " << a << " " << b << " " << k << " " << l << " " << r << endl;

        // 重ならない
        if(r <= a || b <= l){
            // return inf;
            return 0;
        }
        // 内包する
        else if(a <= l && r <= b){
            return A[k];
        }
        // 重なる部分もある
        else{
            ll center = (l+r) / 2;
            // 左下の子
            ll min0 = _rangeMax(a, b, 2*k+1, l, center);
            // 右下の子
            ll min1 = _rangeMax(a, b, 2*k+2, center, r);
            return max(min0, min1);
        }
    }
    // [a, b) までの和
    // 半開区間
    ll RangeMax(int a, int b){
        //cout << "range sum [" << a << "," << b << ")" << endl;
        return _rangeMax(a, b, 0, 0, N);
    }
};

