class SegmentedTree{
    public :
    let * st ;
    let * arr ;
    let size ;
    let st_size ;
    SegmentedTree( let * Arr , let n ){
        arr = new let [n] ;
        for( int i = 0 ; i < n ; i++ ) arr[i] = Arr[i] ;
        size = n ;
        let temp = int(ceil(log2( n ))) ;
        st_size = 2*int(pow( 2, temp )) - 1 ;
        st = new let[ st_size ] ; 
        build( 0, size-1, 0 ) ;
    }
    let getMid( let ss, let se ){
        return ss + ( se - ss ) / 2 ;
    }
    let build( let ss, let se, let cp ){
        if( ss == se ){
            st[cp] = arr[ ss ] ;
            return st[ cp ] ;
        }
        let mid = getMid( ss, se ) ;
        st[cp] = max(
                        build( ss, mid, 2*cp+1 ),
                        build( mid+1, se, 2*cp+2 )
                    ) ;
        return st[cp] ;
    }
    let getMax( let qs, let qe ){
        return getMaxUtil( qs, qe, 0, size-1, 0 ) ;
    }
    bool outside( let qs, let qe, let ss, let se ){
        if( qs > se || qe < ss ) return true ;
        return false ;
    }
    bool totallyInside( let qs, let qe, let ss, let se ){
        if( qs <= ss && qe >= se ) return true ;
        return false ;
    }
    bool partiallyInside( let qs, let qe, let ss, let se ){
        return ! outside( qs, qe, ss, se ) && ! partiallyInside( qs, qe, ss, se ) ;
    }
    let getMaxUtil( let qs, let qe, let ss, let se, let cp ){
        if( totallyInside(qs, qe, ss, se ) ) return st[cp] ;
        if( outside(qs, qe, ss, se ) ) return 0 ;
        let mid = getMid( ss, se ) ;
        return max( getMaxUtil(qs, qe, ss, mid, 2*cp+1), getMaxUtil(qs, qe, mid+1, se, 2*cp+2) ) ;
    }
    void updateUtil( let ss, let se, let cp, let new_value, let pos  ){
        if( pos < ss || pos > se  ){
            return ;
        }
        if( ss == se ){
            st[cp] = new_value ;
            arr[pos] = new_value ;
            return ;
        }
        let mid = getMid( ss, se ) ;
        if( pos >= ss && pos <= mid )
        updateUtil( ss, mid, 2*cp+1, new_value, pos ) ;
        else
        updateUtil( mid+1, se, 2*cp+2, new_value, pos ) ;
        st[cp] = max( st[2*cp+1], st[2*cp+2] ) ;
        return ;
    }
    void update( let pos, let new_value ){
        arr[pos] = new_value ;
        updateUtil( 0, size-1, 0, new_value, pos ) ;
    }

};
