typedef long long ll;
int N;
vector<int> H, A;
vector<ll> bit;

void input_init(void) {
	cin >> N;
	H.resize(N + 1);
	A.resize(N + 1);
	for (int i = 1; i <= N; ++i)
		cin >> H[i];
	for (int i = 1; i <= N; ++i)
		cin >> A[i];
	bit.resize(N + 1, (ll)0);
}

void add(int i, ll x) {
	while (i <= N) {
		bit[i] = max(bit[i], x);
		i += i & -i;
	}
}

ll query(int i) {
	ll s = (ll)0;
	while (i > 0) {
		s = max(s, bit[i]);
		i -= i & -i;
	}
	return s;
}

