vector<long long> segment;
int n,t,b[200001];

long long getmax(int a , int b , int curr , int l , int r){
    if(a > r || b < l){
        return 0;
    }
    if(a <= l && b >= r){
        return segment[curr];
    }
    int m = (l+r)/2;
    return max(getmax(a,b,2*curr,l,m),getmax(a,b,2*curr+1,m+1,r));
}

void update(int curr , long long val){
    curr += t;
    segment[curr] = val;
    curr /= 2;
    while(curr){
        segment[curr] = max(segment[2*curr],segment[2*curr+1]);
        curr /= 2;
    }
}

