	int c = (tl + tr) >> 1;
	if(pos > c) upd(2 * v + 2, c + 1, tr, x, pos);
	else upd(2 * v + 1, tl, c, x, pos);
	t[v] = max(t[2 * v + 1], t[2 * v + 2]);
