const int MAXN = (int)2e5 + 5;

int h[MAXN];
int a[MAXN];
long long bit[MAXN];

void add(long long val, int idx, int n) {
    while(idx <= n) {
        bit[idx] = max(bit[idx], val);
        idx += idx & -idx;
    }
    return;
}

long long query(int idx) {
    long long maxi = 0;
    while(idx > 0) {
        maxi = max(maxi, bit[idx]);
        idx -= idx & -idx;
    }
    return maxi;
}

long long solve(int n) {
    for (int i = 0; i < n; i++) {
        long long maxi = query(h[i]);
        add(maxi + a[i], h[i], n);
    }
    return query(n);
}

