ll N;
vector<ll> A, H, DP, tail, Max;

// DP : Nこめまで読んだ時のMax
// tail : DPの時の部分列の最大値
// Max : 部分列の末尾がNの時のAの合計のMax




int main() {
    cin >> N;
    A.resize(N);
    H.resize(N);
    for(int i = 0; i < N; i++) cin >> H[i];
    for(int i = 0; i < N; i++) cin >> A[i];
    DP.resize(N+1); tail.resize(N+1); Max.resize(N+1);
    for(int i = 0; i <= N; i++) DP[i] = -1; 
    DP[0] = 0, DP[1] = A[0];
    tail[1] = H[0];
    Max[H[0]] = A[0];
    for(int i = 2; i <= N; i++) {
        if(tail[i-1] < H[i-1]) { // 即決で使う
            DP[i] = DP[i-1] + A[i-1];
            tail[i] = H[i-1];
            Max[tail[i]] = DP[i];
        }
        else { // 使うか使わないかわからない
        // 今までのDPの値と、A[N]を使った場合の値を比べて決めたい
            ll comp1 = DP[i-1]; // 使わなかった場合
            ll comp2 = A[i-1] + Max[H[i-1]-1]; // 使った場合
            if(comp1 < comp2){ //使った場合
                DP[i] = comp2;
                tail[i] = H[i-1];
                Max[tail[i]] = DP[i];
            }
            else{
                DP[i] = DP[i-1];
                tail[i] = tail[i-1];
                Max[H[i-1]] = Max[H[i-1]-1]+A[i-1];

            }

        }
    }
    cout << DP[N] << endl;


}

