#define MAX_N 200010
#define SEG_SIZE (1<<21)

ll seg[2*SEG_SIZE-1];

void update(ll k, ll x){
    k += SEG_SIZE - 1;
    seg[k] = x;
    while(k){
        k = (k - 1)/2;
        seg[k] = max(seg[k*2+1], seg[k*2+2]);
    }
}

ll getMax(int a, int b, int k=0, int l=0, int r=SEG_SIZE){
    if(b <= l || r <= a) return 0;
    else if(a <= l && r <= b) return seg[k];
    else{
        ll lv = getMax(a,b,k*2+1,l,(l+r)/2);
        ll rv = getMax(a,b,k*2+2,(l+r)/2,r);

        return max(lv, rv);
    }
}

