    updateQuery(0,0,maxi,h[0],b[0]);
    fori(1,n)
    {
        ll c1 = checkQuery(0,0,maxi,0,h[i]-1);
        dp[i] = (ll)b[i] + c1;
        updateQuery(0,0,maxi,h[i],dp[i]);
        ans = max(ans,dp[i]);
    }
    cout<<ans<<endl;
