template <const int MAXN, class T> struct FenwickTreeMax {
    T BIT[MAXN], NEG_INF;
    FenwickTreeMax(T NEG_INF) : NEG_INF(NEG_INF) { fill(BIT, BIT + MAXN, NEG_INF); }
    void update(int i, T v) { for (; i < MAXN; i += i & -i) BIT[i] = max(BIT[i], v); }
    T rmq(int i) { T ret = NEG_INF; for (; i > 0; i -= i & -i) ret = max(ret, BIT[i]); return ret; }
};

