ll func(ll ind, ll prev, vector<vector<ll>>& dp){
	if(ind > n)
		return dp[ind][prev] = 0;

	if(dp[ind][prev] != -1)
		return dp[ind][prev];

	if(prev == 0){
		ll inc = bty[ind] + func(ind+1, ind, dp);
		ll not_inc = func(ind+1, prev, dp);
		return dp[ind][prev] = max(inc, not_inc);
	}

	if(ht[ind] > ht[prev]){
		ll inc = bty[ind] + func(ind+1, ind, dp);
		ll not_inc = func(ind+1, prev, dp);
		return dp[ind][prev] = max(inc, not_inc);
	}
	else{
		return dp[ind][prev] = func(ind+1, prev, dp);
	}
}

