const int N = 2e5 + 3;
const ll INF = 1e17;

ll dp[N], cost[N], h[N], tree[4 * N];

void build(int n) {
    for (int i = 0; i < 4 * n; ++i)
        tree[i] = -INF;
}

ll get_mx(int v, int tl, int tr, int l, int r) {
    if (l > r) return -INF;
    if (l == tl && r == tr)
        return tree[v];
    else {
        int tm = (tl + tr) / 2;
        return max(get_mx(2 * v, tl, tm, l, min(r, tm)), get_mx(2 * v + 1, tm + 1, tr, max(l, tm + 1), r));
    }
}

void update(int v, int tl, int tr, int pos, ll val) {
    if (tl == tr)
        tree[v] = val;
    else {
        int tm = (tl + tr) / 2;
        if (pos <= tm)
            update(2 * v, tl, tm, pos, val);
        else
            update(2 * v + 1, tm + 1, tr, pos, val);
        tree[v] = max(tree[2 * v], tree[2 * v + 1]);
    }
}

