// one-based numbering
template<class T> struct Fenwick {
    vector<T> bit; int N;
    Fenwick(int n) {
        N = n;
        bit.resize(n+1, 0);
    }
    void add(int a, T w) {
        for (int x = a; x <= N; x += x & -x) bit[x] = max(bit[x], w);
    }
    T max_range(int a) {
        T ret = 0;
        for (int x = a; x > 0; x -= x & -x) ret = max(ret, bit[x]);
        return ret;
    }
};

