    iota(idx.begin(), idx.end(), 0);
    sort(idx.begin(), idx.end(), [&h](ll i1, ll i2) {
        return h[i1] < h[i2];
    });

    ll N = 1;
    while (N < n) N *= 2;

    for (auto i : idx) {
        ll left_max = query(0, i, 0, 0, N);
        update(i + N - 1, a[i] + left_max);
    }

    cout << dp[0] << endl;

    return 0;
}

