const int MAXN = 200005;

struct BIT {
    long long a[MAXN];
    int n;

    static constexpr int lowbit(int x) {
        return x & -x;
    }

    void update(int pos, long long d) {
        for (int i = pos; i <= n; i += lowbit(i)) a[i] = std::max(a[i], d);
    }

    long long query(int pos) {
        long long res = 0;
        for (int i = pos; i; i -= lowbit(i)) res = std::max(res, a[i]);
        return res;
    }
} bit;

int a[MAXN], h[MAXN];

int main() {
    int n;
    scanf("%d", &n);

    for (int i = 0; i < n; i++) scanf("%d", &h[i]);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);

    bit.n = n;
    long long ans = 0;
    for (int i = 0; i < n; i++) {
        long long f = bit.query(h[i]) + a[i];
        ans = std::max(ans, f);
        bit.update(h[i], f);
    }

    printf("%lld\n", ans);

    return 0;
}

