	segtree<int> tree(N+1);
	tree.update(0, 0);
	REP(i, N) {
		int num = -tree.query(0, H[i]);
		tree.update(H[i], -(num+A[i]));
	}

	cout << -tree.query(0,N+1) << endl;
}

