struct SegmentTree {
    vector<ll> st;
    int n, neutro = 0;

    SegmentTree(vector<ll> &arr) {
        n = arr.size();
        st.assign(n << 2, 0);
        build(1, 0, n - 1, arr);
    }

    ll query(int i, int j) { return query(1, 0, n - 1, i, j); }
    void update(int i, int j, ll val) { update(1, 0, n - 1, i, j, val); }

    int left (int p) { return p << 1; }
    int right (int p) { return (p << 1) | 1; }

    void build(int p, int L, int R, vector<ll> &arr) {
        if (L == R) st[p] = arr[L];
        else {
            int m = (L+R)/2, l = left(p), r = right(p);
            build(l, L, m, arr);
            build(r, m+1, R, arr);
            st[p] = max(st[l], st[r]);
        }
    }
    ll query(int p, int L, int R, int i, int j) {
        if (i > R || j < L) return neutro;
        if (i <= L && j >= R) return st[p];
        int m = (L+R)/2, l = left(p), r = right(p);
        ll _l = query(l, L, m, i, j);
        ll _r = query(r, m+1, R, i, j);
        return max(_l, _r);
    }

    void update(int p, int L, int R, int i, int j, ll val) {
        if (i > R || j < L) return;
        if (i <= L && j >= R) st[p] = val;
        else {
            int m = (L+R)/2, l = left(p), r = right(p);
            update(l, L, m, i, j, val);
            update(r, m+1, R, i, j, val);
            st[p] = max(st[l], st[r]);
        }
    }
};


