void put(int i, int L, int R, int pos, ll x) {
    if (L == R)
        t[i] = x;
    else {
        int M = (L + R) / 2;
        if (pos <= M)
            put(2 * i + 1, L, M, pos, x);
        else
            put(2 * i + 2, M + 1, R, pos, x);
        t[i] = max(t[2 * i + 1], t[2 * i + 2]);
    }
}

ll rmq(int i, int L, int R, int l, int r) {
    if (l <= L && R <= r)
        return t[i];
    int M = (L + R) / 2;
    ll result = 0;
    if (l <= M)
        result = max(result, rmq(2 * i + 1, L, M, l, r));
    if (r > M)
        result = max(result, rmq(2 * i + 2, M + 1, R, l, r));
    return result;
}

