const int MAXM = 2e5+3;
const ll inf = 1e15;

int flowers[MAXM], beuity[MAXM],n;
int dp[MAXM];

int solve(int idx)
{
	if (idx > n)	return 0;
	if (dp[idx] != -1)	return dp[idx];
	int ret = 0;
	if (idx == 0){
		for (int i=1;i<=n;i++){
			ret = max(ret, beuity[i] + solve(i));
		}
	} else {
		for (int i=idx+1;i<=n;i++){
			if (flowers[i] > flowers[idx]){
				ret = max(ret, beuity[i]+solve(i));
			}
		}
	}
	return dp[idx] = ret;
}

