#include<bits/stdc++.h>
using namespace std;
vector<long long> tree(1e6,0);

long long getit(int ss,int se, int p, int l, int r){
    if(ss > se || ss > r || se < l)
        return (long long)0;
    if(l<= ss && se <= r)
        return tree[p];
    int mid = (ss+se)/2;
    return max(getit(ss,mid, 2*p, l, r), getit(mid+1,se, 2*p + 1,l,r));
}

void update(int ss,int se, int p, int l, int val){
    if(ss > se)
        return ;
    if(ss == se)
    {
        tree[p] += val;
        return;
    }
    int mid = (ss+se)/2;
    if(l > mid)
        update(mid+1,se, 2*p+1 , l, val);
    else update(ss, mid, 2*p, l, val);
    tree[p] = max(tree[2*p],tree[2*p+1]);
}

