int n;

void buildTree(int s=1,int e=n,int index=1){
    if(s>e){
        return;
    }
    if(s==e){
        tree[index]=dp[s];
        return;
    }
    int mid = (s+e)/2;
    buildTree(s,mid,2*index);
    buildTree(mid+1,e,2*index+1);
    // as it is a max tree so max is used
    tree[index] = max(tree[2*index],tree[2*index+1]);
    return;
}

ll query(int qs,int qe,int s=1,int e=n,int index=1){
    if(qe<s || qs>e || s>e){
        return MIN*1LL;
    }
    if(qs<=s && qe>=e){
        return tree[index];
    }
    int mid = (s+e)/2;
    ll q1 = query(qs,qe,s,mid,2*index);
    ll q2 = query(qs,qe,mid+1,e,2*index+1);
    return max(q1,q2);
}

//add value to elm at pos i in dp
void update(int i,ll value,int s=1,int e=n,int index=1){
    if(s>e || s>i || e<i){
        return;
    }
    if(s==e && s==i){
        tree[index]+=value;
        return;
    }
    int mid = (s+e)/2;
    update(i,value,s,mid,2*index);
    update(i,value,mid+1,e,2*index+1);
    tree[index] = max(tree[2*index],tree[2*index+1]);
}

