const ll INF = (ll)1e18L;
struct SegTree {
    std::vector<ll> data;
    SegTree(int n) : data(4 * n, -INF) { }
    void set(int v, int l, int r, int p, ll x) {
        if (p < l || p >= r) return;
        if (l + 1 == r) { data[v] = x; }
        else { 
            int m = (l + r) / 2;
            set(2*v+1,l,m,p,x);
            set(2*v+2,m,r,p,x);
            data[v] = std::max(data[2*v+1],data[2*v+2]);
        }
    }
    ll get(int v, int l, int r, int ql, int qr) {
        if (qr <= l || r <= ql) { return -INF; }
        if (ql <= l && r <= qr) { return data[v]; }
        int m = (l + r) / 2;
        return std::max(get(2*v+1,l,m,ql,qr),get(2*v+2,m,r,ql,qr));
    }
    void set(int p, ll x) { set(0,0,isz(data)/4,p,x); }
    ll get(int ql, int qr) { return get(0,0,isz(data)/4,ql,qr); }
};
