struct Segment{
  int n;
  vector<ll> tree;
  Segment(int _n){
    n = _n;
    tree.resize(n * 4);
  }

  void update(int in, ll v){
    update(1, 0, n - 1, in, v);
  }
  void update(int in, int l, int r, int i, ll v){
    if(l > i || r < i)return;
    if(l == r){
      tree[in] = v;
      return;
    }
    int m = (l + r) / 2;
    update(2 * in, l, m, i, v);
    update(2 * in + 1, m + 1, r, i, v);
    tree[in] = max(tree[2 * in], tree[2 * in + 1]);
  }
  ll query(int l, int r){
    return query(1, 0, n - 1, l, r);
  }
  ll query(int in, int l, int r, int s, int e){
    if(l > e || r < s)
      return -1;
    if(l >= s && r <= e)
      return tree[in];
    int m = (l + r) / 2;
    return max(query(2 * in, l, m, s, e), query(2 * in + 1, m + 1, r, s, e));
  }
};
