int get(int v , int tl , int tr , int l , int r)
{
	if(l > tr || tl > r)return 0;
	if(tl <= l && r <= tr)return t[v];

	int mid = l + r >> 1;

	return max( get(v + v , tl , tr , l , mid ) , get(v + v + 1 , tl , tr , mid+1 , r ) );
}

void upd(int v , int pos , int val , int l , int r)
{
	if(l == r){
		t[v] = val;
		return;
	}

	int mid = l + r >> 1;

	if(pos <= mid)
		upd(v + v , pos , val , l , mid);
	else
		upd(v + v + 1 , pos , val , mid+1 , r);
	t[v] = max(t[v + v] , t[v + v + 1]);
}


