struct SegmentTree {
    vi st;

    SegmentTree(ll n) {
        st.resize(4 * n, LLONG_MIN);
    }

    ll query(ll l, ll r, ll left, ll right, ll vertex = 1) {
        if (l > r) {
            return LLONG_MIN;
        }

        if (l == left && r == right) {
            return st[vertex];
        }

        ll mid = (left + right) / 2;
        return max(query(l, min(r, mid), left, mid, vertex * 2),
                   query(max(mid + 1, l), r, mid + 1, right, vertex * 2 + 1));
    }

    void update(ll ind, ll val, ll left, ll right, ll vertex = 1) {
        if (left == right) {
            st[vertex] = max(st[vertex], val);
            return;
        }

        ll mid = (left + right) / 2;
        if (ind <= mid) {
            update(ind, val, left, mid, vertex * 2);
        } else {
            update(ind, val, mid + 1, right, vertex * 2 + 1);
        }

        st[vertex] = max(st[vertex * 2], st[vertex * 2 + 1]);
    }
};

