#define lc (i << 1)
#define rc (i << 1 | 1)
void build(ll i, ll l, ll r) {
  tr[i].l = l; tr[i].r = r;
  if (l == r) return;
  ll md = (l + r) >> 1;
  build(lc, l, md); build(rc, md + 1, r);
}
ll ask(ll i, ll l, ll r) {
  if (tr[i].l >= l && tr[i].r <= r) return tr[i].val;
  if (tr[i].l > r || tr[i].r < l) return 0;
  return max(ask(lc, l, r), ask(rc, l, r));
}
void update(ll i, ll p, ll v) {
  if (tr[i].l == tr[i].r) {
    tr[i].val = v;
    return;
  }
  ll md = (tr[i].l + tr[i].r) >> 1;
  if (p <= md) update(lc, p, v);
  else update(rc, p, v);
  tr[i].val = max(tr[lc].val, tr[rc].val);
}

