int update(std::vector<long long int> &seg_tree, long long int N, long long int index, long long int value){

  // update the entry
  index += N-1;
  if(value > seg_tree[index]){
    seg_tree[index] = value;
  }

  // update the entries that represent range information
  while(index > 0){
    index = (index-1)/2;
    if(value <= seg_tree[index]){
      break;
    }
    else{
      seg_tree[index] = value;
    }
  }

  return 0;
}


// compute the query in the intersection of [left, right) and [L, R)
// [L, R) is for convenience in iteration. whole range is usually chosen when called in main function.
long long int query(std::vector<long long int> &seg_tree, long long int N, long long int left, long long int right, long long I, long long int L, long long int R){
  if(R <= left || right <= L){
    return 0;
  }
  if(left <= L && R <= right){
    return seg_tree[I];
  }
  else{
    long long int tmp1, tmp2;
    tmp1 = query(seg_tree, N, left, right,  2*I+1, L, (L+R)/2);
    tmp2 = query(seg_tree, N, left, right,  2*I+2, (L+R)/2, R);
    return std::max(tmp1, tmp2);
  }
}

