struct segmenttree{
    private:
    int n;
    vector<int> node;
    public:
    segmenttree(vector<int>v){
        int sz=v.size();
        n=1;while(n<sz)n*=2;
        node.resize(n*2-1,0);
        rep(i,0,sz)node[i+n-1]=v[i];
        for(int i=n-2;i>=0;i--)node[i]=max(node[2*i+1],node[2*i+2]);
    }
    void update(int x,int val){
        x+=n-1;
        node[x]=val;
        while(x>0){
            (x-=1)/=2;
            node[x]=max(node[2*x+1],node[2*x+2]);
        }
    }
    int getmax(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0)r=n;
        if(r<=a||b<=l)return -1;
        if(a<=l&&r<=b)return node[k];
        int vl=getmax(a,b,k*2+1,l,(l+r)/2);
        int vr=getmax(a,b,k*2+2,(l+r)/2,r);
        return max(vl,vr);
    }
};
