struct Bit {
    Bit(int n) : b(n+1) {};
    void upd(int pos, ll val) {
        for (int i = pos; i < (int)b.size(); i += i&-i) {
            b[i] = max(b[i], val);
        }
    }

    ll get(int pos) {
        ll res = 0;
        for (int i = pos; i > 0; i -= i&-i) {
            res = max(res, b[i]);
        }
        return res;
    }
private:
    vector<ll> b;
};

