    for (auto& i : h) cin >> i;
    for (auto& i : a) cin >> i;

    Bit bit(n);

    for (int i = 0; i < n; i++) {
        ll x = bit.get(h[i]) + a[i];
        bit.upd(h[i], x);
    }

    cout << bit.get(n) << "\n";
}

