struct SegmentTree {
    int n;
    vector<ll> node;

    SegmentTree(int _n, ll v = -1e18) {
        n = 1;
        while (n < _n)
            n *= 2;
        node.resize(2 * n - 1, v);
    }
    SegmentTree(vector<ll> a, ll v = -1e18) {
        n = 1;
        while (n < a.size())
            n *= 2;
        node.resize(2 * n - 1, v);
        for (int i = 0; i < a.size(); i++)
            node[i + n - 1] = a[i];
        for (int i = n - 2; i >= 0; i--)
            node[i] = max(node[2 * i + 1], node[2 * i + 2]);
    }

    void update(int k, ll v) {
        k += n - 1;
        node[k] = max(node[k], v);
        while (k > 0) {
            k = (k - 1) / 2;
            node[k] = max(node[2 * k + 1], node[2 * k + 2]);
        }
    }

    ll get(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l)
            return -1e18;
        if (a <= l && r <= b)
            return node[k];
        ll vl = get(a, b, 2 * k + 1, l, (l + r) / 2);
        ll vr = get(a, b, 2 * k + 2, (l + r) / 2, r);
        return max(vl, vr);
    }
    ll get(int a, int b) {
        return get(a, b, 0, 0, n);
    }
};

