void solve() {
    segtree T(n + 1);
    ll ans = 0;

    for (int i = 0; i < n; ++i) {
        ll res = T.get(0, h[i] - 1) + a[i];
        T.upd(h[i], res);
        ans = max(ans, res);
    }

    cout << ans << endl;
}

