ll powmod(ll x, ll y) 
{ 
    ll res = 1;  
    x = x % MOD;
    while (y > 0) 
    { 
        if (y & 1) 
          res = (res*x) % MOD; 
        y = y>>1; // y = y/2 
        x = (x*x) % MOD;   
    } 
    return res; 
} 
ll h[2*ee5],a[2*ee5];
ll seg[8*ee5];
void update(ll low,ll high,ll index,ll in,ll value){
  if(low>high or low>in or in>high)
    return;
  if(low==high){
    seg[index]=value;
    return;
  }
  int mid=(low+high)/2;
  update(low,mid,index*2+1,in,value);
  update(mid+1,high,index*2+2,in,value);
  seg[index]=max(seg[index*2+1],seg[index*2+2]);
}

ll query(ll low,ll high,ll index,ll in){
  if(low>high or high<in)
    return 0;
  if(low>=in)
    return seg[index];
  int mid=(low+high)/2;
  return max(query(low,mid,index*2+1,in),query(mid+1,high,index*2+2,in));
}


