        cin >> a[i];
    }

    // dp[i] := 区間 [0, i] における、花の美しさの総和の最大値
    SegmentTree<ll> dp(n + 5, [](ll a, ll b){return max(a, b);}, 0ll);
    for(int i = 0; i < n; ++i){
        // 更新前における区間 [0, pos[i]) の dp の最大値
        ll max_e = dp.query(0, pos[i]);
        dp.update(pos[i], max_e + a[pos[i]]);
    }
    cout << dp.query(0, n) << endl;
}

