long long query(int node,int s,int e,int l,int r)
{
    if(e < l or s > r)
        return 0;
    if(s >= l and e <= r)
        return tree[node];
    int mid = (s+e)>>1;
    return max(query(2*node,s,mid,l,r),query(2*node+1,mid+1,e,l,r));
}
void upd(int node,int s,int e,int v,long long x)
{
    if(s == e){
        tree[node] = x;
        return ;
    }
    int mid = (s+e)>>1;
    if(v <= mid){
        upd(2*node,s,mid,v,x);
    }
    else{
        upd(2*node+1,mid+1,e,v,x);
    }
    tree[node] = max(tree[2*node],tree[2*node+1]);
}
