typedef long long ll;
int n;
ll h[100003],v[100003],f[100003],tree[400003];
pair<ll,pair<ll,int> >a[100003];

void Update(int node,int start,int endd,int id,ll val)
{
    if(id<start||id>endd)
    {
        return;
    }
    if(start==endd)
    {
        tree[node]=val;
        return;
    }
    int mid=(start+endd)/2;
    Update(2*node,start,mid,id,val);
    Update(2*node+1,mid+1,endd,id,val);
    tree[node]=max(tree[2*node],tree[2*node+1]);
}

ll Maxx(int node,int start,int endd,int l,int r)
{
    if(r<start||l>endd)
    {
        return 0;
    }
    if(l<=start && endd<=r)
    {
        return tree[node];
    }
    int mid=(start+endd)/2;
    return max(Maxx(2*node,start,mid,l,r),Maxx(2*node+1,mid+1,endd,l,r));
}

int main()
{
    cin>>n;
    for(int i=1;i<=n;++i)
    {
        cin>>h[i];
    }
    for(int i=1;i<=n;++i)
    {
        cin>>v[i];
        a[i]={h[i],{v[i],-i}};
