int num;
long long tree[4 * MAXN];

void initTree() {
  num = 1;
  while (num < n) {
    num *= 2;
  }

  for (int i = 1; i < 2 * num; i++) {
    tree[i] = -INF;
  }
}

long long getMax(int l, int r) {
  l = num + l; r = num + r;
  long long res = -INF;

  while (l <= r) {
    if (l & 1) {
      res = max(res, tree[l]);
      l++;
    }
    if (r % 2 == 0) {
      res = max(res, tree[r]);
      r--;
    }
    l /= 2; r /= 2;
  }

  return res;
}

void update(int pos, long long val) {
  pos = num + pos;
  tree[pos] = val;
  pos /= 2;
  while (pos > 0) {
    tree[pos] = max(tree[pos * 2], tree[pos * 2 + 1]);
    pos /= 2;
  }
}

