        for(; x <= n; x += x & -x)
            merge(tree[x], z);
    }
    T query(int x){ // Queries index `x`
        T sum = defaultV;
        for(; x; x -= x & -x)
            merge(sum, tree[x]);
        return sum;
    }
    void reverseUpd(int x, T z) { upd(n - x + 1, z); }
    T reverseQuery(int x) { return query(n - x + 1); }
};

