ll query(ll node,ll tl,ll tr,ll l,ll r){
    if(l > r){
        return INT_MIN;
    }
    if(tr < l || tl > r){
        return INT_MIN;
    }
    if(l == tl && r == tr){
        return seg[node];
    }
    ll tm = (tl + tr)/2;
    ll left = query(2*node, tl, tm, l, r);
    ll right = query(2*node + 1, tm + 1, tr, l, r);
    return max(left,right);
}
void update(ll node,ll tl,ll tr,ll idx,ll val){
    if(tl == tr){
        ans[idx] += val;
        seg[node] += val;
        return;
