ll rmq(int l, int r){
	l += st_idx(); r += st_idx();
	ll ans = 0;
	while(l<=r){
		if(l%2 == 1)
			ans = max(ans, tree[l++]);
		if(r%2 == 0)
			ans = max(ans, tree[r--]);
		l/=2; r/=2;
	}
	return ans;
}

