  segtree(vec& v){
    ll K=v.size();
    N=1;
    while(N<K)N*=2;
    ll i;
    tree.resize(2*N-1);
    For(i,N-1,N-1+K){
      tree[i]=v[i-N+1];
    }
    For(i,N+K-1,2*N-1){
      tree[i]=0;
    }
    brep(i,N-1){
      tree[i]=max(tree[i*2+1],tree[i*2+2]);
    }
  }
  void input(ll i,ll a){
    i+=N-1;
    tree[i]=a;
    while(i){
      i=(i-1)/2;
      tree[i]=max(tree[i*2+1],tree[i*2+2]);
    }
  }
  ll res(ll a,ll b,ll k,ll l,ll r){
    if(r<0)r=N;
    if(r<=a||b<=l)return 0;
    if(a<=l&&r<=b)return tree[k];
    ll vl=res(a,b,2*k+1,l,(l+r)/2);
    ll vr=res(a,b,2*k+2,(l+r)/2,r);
    return max(vl,vr);
  }
  ll q(ll a,ll b){
    return res(a,b,0,0,-1);
  }
  void prt(){
    output(tree);
  }
};


