  forf(i,1,n+1)
  {
    int vl = My_tree.query(0,h[i]);
    My_tree.update(h[i],h[i],vl+a[i]);
    an = max(an,vl+a[i]);

  }

  //cout<<My_tree.query(0,5);
  cout<<an<<"\n";
}


