using namespace std;

ll a[MAXN], h[MAXN], n, ans = 0;
ll lo[4 * MAXN + 1], hi[4 * MAXN + 1], tree[4 * MAXN + 1], delta[4 * MAXN + 1];

void init(int i, int l, int r){
	lo[i] = l;
	hi[i] = r;
	if(l == r) return;
	int m = (l + r) / 2;
	init(2 * i, l, m);
	init(2 * i + 1, m + 1, r);
}

void prop(int i){
	delta[2 * i] += delta[i];
	delta[2 * i + 1] += delta[i];
	delta[i] = 0;
}

void update(int i){
	tree[i] = max(tree[2 * i] + delta[2 * i], tree[2 * i + 1] + delta[2 * i + 1]);
}

void inc(int i, int l, int r, ll val){
	if(r < lo[i] || hi[i] < l) return;
	if(hi[i] <= r && lo[i] >= l){
		delta[i] += val;
		return;
	}
	//partial cover case
	prop(i);
	inc(2 * i, l, r, val);
	inc(2 * i + 1, l, r, val);
	update(i);
}

ll query(int i, int l, int r){
	if(r < lo[i] || hi[i] < l) return 0;	//not in range
	if(hi[i] <= r && lo[i] >= l) return tree[i] + delta[i];	//completely in range
	prop(i);
	ll maxLeft = query(2 * i, l, r);
	ll maxRight = query(2 * i + 1, l, r);
	update(i);
	return max(maxLeft, maxRight);
}
int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
    cin >> n;
    init(1, 0, n);
    for(int i = 0; i < n; i++){
    	cin >> h[i];
    }
    for(int i = 0; i < n; i++){
    	cin >> a[i];
    	inc(1, h[i], h[i], a[i] + query(1, 0, h[i]));
    	ans = max(ans, query(1, 0, h[i]));
    }
    cout << ans;
}

