void update(int l,int r,int v,int pos,int val)
{
	if(l>r)
		return;
	if(l==r)
	{
		if(seg[v]<val)
		{
		  seg[v] = val;
		  mai[l] = val;
		}
		  return;
	}
	int mid = (l + r)/2;
	if(pos<=mid)
		update(l,mid,v<<1,pos,val);
	else
		update(mid+1,r,v<<1|1,pos,val);
	seg[v] = max(seg[v<<1],seg[v<<1|1]);
	return;
}

int query(int l,int r,int v,int s,int e)
{
	if(l>r)
		return 0;
	if(r<s||e<l)
		return 0;
	if(s<=l&&r<=e)
		return seg[v];
	int mid = (l+r)/2;
	return max(query(l,mid,v<<1,s,e),query(mid+1,r,v<<1|1,s,e));
}

