	if(s[k].l==s[k].r){
		s[k].val=x;
		return;
	}
	int mid=(s[k].l+s[k].r)>>1;
	if(ind<=mid)	modify(k<<1,ind,x);
	else			modify(k<<1|1,ind,x);
	s[k].val=max(s[k<<1].val,s[k<<1|1].val);
}
