	if(l<=s[k].l&&s[k].r<=r){
		return s[k].val;
	}
	int mid=(s[k].l+s[k].r)>>1;
	if(r<=mid)			return query(k<<1,l,r);
	else if(l>mid)		return query(k<<1|1,l,r);
	else				return max(query(k<<1,l,mid),
						query(k<<1|1,mid+1,r));
}
