	while (noeud > 0)
	{
		noeud /= 2;
		arbre[noeud] = max(arbre[noeud * 2] , arbre[noeud * 2 + 1]);
	}
}

int trouverMax(int gauche , int droite)
{
	gauche+= MAXN , droite += MAXN;
	int maxi = 0;
	while (gauche<= droite)
	{
		if (gauche % 2 == 1)
		{
			maxi = max(maxi , arbre[gauche]);
			gauche++;
		}
		if (droite % 2 == 0)
		{
			maxi = max(maxi , arbre[droite]);
			droite--;
		}
		gauche/=2;
		droite/=2;
	}
	return maxi;
}

