class SegTree
{
    int n;
    vector<ll> node;

    public:
        SegTree(vector<ll> a) 
        {
            int sz = a.size();
            n = 1;
            while (n < sz) n*= 2; //nはsz以上の2の累乗とすると
            node.resize(2 * n - 1, 0);//node数は2*n-1  最下位ノードは[n - 1]から
        }

        void update(int index, ll x)
        {
            index += (n - 1); 
            node[index] = x; //ノード更新
            while(index > 0)
            {
                index = (index - 1) / 2; //親ノードへのアクセス
                node[index] = max(node[index * 2 + 1], node[index * 2 + 2]); //ノードの最大値更新
            }
        }
        /*
        区間[a, b] における最大値の取得
        */
        ll getMax(int a, int b, int k = 0, int l = 0, int r = -1)
        {
            if (r < 0) r = n - 1;
            if (r < a || b < l) return 0;
            if (a <= l && r <= b) return node[k];
            ll vl = getMax(a, b, k * 2 + 1, l, (l + r) / 2);
            ll vr = getMax(a, b, k * 2 + 2, (l + r) / 2  +  1, r);
            return max(vl, vr);
        }
};


