#define int long long

int n,h[200005],a[200005],gt,res,f[1000006];

void update(int id,int l,int r,int vt)
{
    if(l==vt&&r==vt)
    {
        f[id]=gt;
    }
    else if(l>vt||r<vt) return;
    else
    {
        int m=(l+r)/2;
        update(id*2,l,m,vt);
        update(id*2+1,m+1,r,vt);
        f[id]=max(f[id*2],f[id*2+1]);
    }
}

int get(int id,int l,int r,int vt)
{
    if(r<=vt) return f[id];
    else if(l>vt) return -1e15;
    else
    {
        int m=(l+r)/2;
        return max(get(id*2,l,m,vt),get(id*2+1,m+1,r,vt));
    }
}

main()
{
    cin>>n;
    for(int i=1;i<=n;i++) cin>>h[i];
    for(int i=1;i<=n;i++) cin>>a[i];
    for(int i=1;i<=n;i++)
    {
        gt=get(1,1,n,h[i])+a[i];
        update(1,1,n,h[i]);
        res=max(res,gt);
    }
    cout<<res;
}

