const int MAXN=2*1e5+1000;
int H[MAXN];
long long int V[MAXN];

set<int> altezze;
long long int sol[MAXN];
int N;
int mappa[MAXN];
int main(){
	cin>>N;
	for(int i=0;i<N;i++)
		cin>>H[i];
	for(int i=0;i<N;i++){
		cin>>V[i];
		mappa[H[i]]=i;
		sol[i]=V[i];
	}
	altezze.insert(H[0]);
	set<int>::iterator it;

	for(int i=1;i<N;i++){
		it=altezze.upper_bound(H[i]);
		if(it!=altezze.begin()){
			it--;
			sol[i]+=sol[mappa[*(it)]];
		}

		altezze.insert(H[i]);

		it = altezze.find(H[i]);
		it++;
		while(it!=altezze.end() && sol[mappa[*(it)]]<=sol[i]){
			set<int>::iterator tmp = it;
			it++;
			altezze.erase(tmp);
		}
	}
	long long int risultato = 0;
	for(int i=0;i<N;i++)
		risultato = max(risultato, sol[i]);
	cout<<risultato;
}

