class SegmentTree{
public:
    int n;
    vector<ll> node;

    SegmentTree(vector<ll> v){
        int sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, 0);
        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = max(node[2*i+1], node[2*i+2]);
    }

    void update(int x, ll val){
        x += (n - 1);
        node[x] = val;
        while(0 < x){
            x = (x - 1) / 2;
            node[x] = max(node[2*x+1], node[2*x+2]);
        }
    }

    ll getmax(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        if(r <= a || b <= l) return 0;
        if(a <= l && r <= b) return node[k];

        ll vl = getmax(a, b, 2*k+1, l, (l+r)/2);
        ll vr = getmax(a, b, 2*k+2, (l+r)/2, r);

        return max(vl, vr);
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n; cin>>n;
    vector<ll> h(n), a(n);
    for(int i=0; i<n; i++) cin>>h[i], h[i]--;
    for(int i=0; i<n; i++) cin>>a[i];

    SegmentTree seg(vector<ll>(n, 0));
    vector<ll> dp(n+1, 0);
    for(int i=0; i<n; i++){
        ll ma = seg.getmax(0, h[i]);
        dp[i+1] = ma + a[i];
        seg.update(h[i], dp[i+1]);
    }

    cout << seg.getmax(0, n) << endl;

    return 0;
}

