    if(l==r)
    {
        tree[node]=max(tree[node],(long long)x);
        return;
    }
    int ln=node*2,mid=(l+r)/2;
    up(ln,l,mid,i,x);
    up(ln+1,mid+1,r,i,x);
    tree[node]=max(tree[ln],tree[ln+1]);
    return ;
}


ll qry(int node,int l,int r,int i)
{
    if(l>i)
        return 0ll;
    if(r<=l)
        return tree[node];
    int ln=node*2,mid=(l+r)/2;
    return max(qry(ln,l,mid,i),qry(ln+1,mid+1,r,i));
}

