struct segmentTree
{
    long tree[N << 2];
    void update(int id, int l, int r, int x, long w)
    {
        if (x < l || r < x) return;
        if (l == r) {tree[id] = w; return;}
        update(lc, l, mid, x, w), update(rc, mid + 1, r, x, w);
        tree[id] = max(tree[lc], tree[rc]);
