void Add(int id,int l,int r,int pos,LL v)
{
	if (l==r&&l==pos) {T[id]=std::max(T[id],v); return;}
	int mid=(l+r)>>1;
	if (pos<=mid) Add(id<<1,l,mid,pos,v);
	else Add(id<<1|1,mid+1,r,pos,v);
	T[id]=std::max(T[id<<1],T[id<<1|1]);
}
