void update_tree(int node,int idx,long long int val,int b,int e){
	if(idx<b||e<idx)
	return;
	if(b==idx&&b==e){
		tree[node]=val;
		return;
	}
	int m=b+(e-b)/2;
	update_tree(2*node+1,idx,val,b,m);
	update_tree(2*node+2,idx,val,m+1,e);
	tree[node]=max(tree[2*node+1],tree[2*node+2]);
}
long long int query(int node,int l,int r,int b,int e){
	if(r<b||e<l)
	return 0;
	if(l<=b&&e<=r)
	return tree[node];
	int m=b+(e-b)/2;
	long long int m1=query(2*node+1,l,r,b,m);
	long long int m2=query(2*node+2,l,r,m+1,e);
	return max(m1,m2);
}
