long long dp[N];
long long segtree[N << 2];

long long idx;
long long val;

void update(int P , int L , int R){
     if(R < idx || L > idx){
        return;
     } else if(L == R) {
        segtree[P] = val;
     } else {
        int mid = (L + R) >> 1;
        update( (P << 1) | 0 , L , mid + 0);
        update( (P << 1) | 1 , mid + 1 , R);
        segtree[P] = max(segtree[P << 1] , segtree[P << 1 | 1]);
     }
}

long long s , e;

long long query(int P , int L , int R){
    if(s <= L && R <= e){
        return segtree[P];
    } else if(L > e || s > R){
        return 0;
    } else {
        int mid = (L + R) >> 1;
        long long a = query( (P << 1) | 0 , L , mid + 0);
        long long b = query( (P << 1) | 1 , mid + 1 , R);
        return max(a , b);
    }
}


