#define mid (l+r)/2
#define ll long long

using namespace std;
const int N=2e5+55;
ll tree[N*4];
int h[N];
ll a[N];

void update(int l , int r , int node , int ind , ll val)
{
    if(l==r)
    {
        tree[node]=val;
        return ;
    }
    if(ind<=mid)
        update(l,mid,node*2,ind,val);
    else
        update(mid+1,r,node*2+1,ind,val);
    tree[node]=max(tree[node*2],tree[node*2+1]);
}

ll query(int l , int r , int node , int x , int y)
{
    if(l>y||r<x)
        return 0;
    if(x<=l&&r<=y)
        return tree[node];
    return max(query(l,mid,node*2,x,y),query(mid+1,r,node*2+1,x,y));
}

