struct BIT {
    vll bit;
    int n;

    BIT(int n) : n(n) {
        bit.assign(n + 1, 0);
    }

    inline void update(int i, int del) {
        while (i <= n) {
            bit[i] += del;
            i += i & (-i);
        }
    }

    inline ll read(int i) {
        ll res = 0;
        while (i > 0) {
            res += bit[i];
            i -= i & (-i);
        }
        return res;
    }
};

