struct Fenwick_tree{
    ll t[MAXN];

    Fenwick_tree(){
        memset(t,0,sizeof t);
    }

    void upd(int pos,ll val){
        for(;pos < MAXN;pos = (pos|(pos+1))){
            t[pos] = max(t[pos],val);
        }
    }
    ll get(int r){
        ll res = 0;
        for(;r>=0; r=(r&(r+1))-1){
            res = max(res, t[r]);
        }
        return res;
    }
