    }
    int mid = (start+end)/2;
    return max(query(node*2 , start , mid , l , r),query(2*node+1,mid+1,end,l,r));
}
void update( int node , int start , int end , int pos , ll val ){
    if(start==end && start == pos){
            seg_tree[node] = val ;
            return ;
    }
    int mid = (start+end)/2;
    if(pos<=mid){
        update(2*node , start , mid , pos , val);
    }
    else{
        update(2*node+1,mid+1,end,pos,val);
    }
    seg_tree[node] = max( seg_tree[node*2] , seg_tree[node*2+1]);
}
