  //    cout<<"k"<<value[k]<<endl;
          return value[k]; // ノード k の担当範囲がクエリ区間 [a, b)
      // に完全に含まれる
    }

    else {
        ll c1 = query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子に値を聞く
