void update(int node,int ss,int se,int i,ll val){
	if(ss == se){
		st[node] = val;
		return;
	}
	if( i > se or i < ss)return;
	int mid = (ss+se)/2;
	update(node*2+1,ss,mid,i,val);
	update(node*2+2,mid+1,se,i,val);
	st[node] = max(st[node*2+1] , st[node*2+2]);
}
ll get(int node,int ss,int se,int qs,int qe){
	if(qs > se or qe < ss)return 0;
	if(qs <= ss and se <= qe)return st[node];
	int mid = (ss+se)/2;
	return max(get(node*2+1,ss,mid,qs,qe) , get(node*2+2,mid+1,se,qs,qe));
}

