    for(int i = 0; i < n; ++i){
        cin >> beauts[i];
    }

    BIT tree(n);
    for(int i = 0; i < n; ++i){
        int height = heights[i];
        long long int beaut = beauts[i];

        long long int max_yet = tree.max1(height);

        tree.update(height, max_yet + beaut);
    }

    cout << tree.max_tree_value() << "\n";
}

