struct segTree{
  int n;
  VLL nodes;
  void init(int _n){
    n = 1;
    while(n < _n) n*=2;
    nodes.resize(2*n-1,0);
  }

  void update(int i, ll x){
    i += n-1;
    nodes[i] = x;
    while(i > 0){
      i = (i-1)/2;
      nodes[i] = max(nodes[i*2+1], nodes[i*2+2]);
    }
  }

  ll getmax(int x, int y, int k = 0, int l = 0, int r = -1){
    if(r < 0) r = n;
    if(r <= x || y <= l) return 0;
    if(x <= l && r <= y) return nodes[k];
    ll vl = getmax(x,y,k*2+1,l,(r+l)/2);
    ll vr = getmax(x,y,k*2+2,(r+l)/2,r);
    return max(vl,vr);
  }
};

