void modify(ll v, ll vl, ll vr, ll pos, ll val){
    if(vl == vr){
        t[v] = val;
        return;
    }
    ll vm = (vl + vr) >> 1;
    if(pos <= vm){
        modify(v*2+1, vl, vm, pos, val);
    }else{
        modify(v*2+2, vm+1, vr, pos, val);
    }
    t[v] = max(t[v*2+1], t[v*2+2]);
}

ll query(ll v, ll vl, ll vr, ll l, ll r){
    if(l > vr || r < vl){
        return -INF;
    }
    if(l <= vl && vr <= r){
        return t[v];
    }
    ll vm = (vl + vr) >> 1;
    ll q1 = query(v*2+1, vl, vm, l, r);
    ll q2 = query(v*2+2, vm+1, vr, l, r);
    return max(q1, q2);
}

