typedef long long ll;
ll tree[800005], a[200005], h[200005], dp[200005];

ll build(int ind, int s, int e) {
    if(s==e) {
        tree[ind] = 0;
        dp[s] = 0;
        return tree[ind];
    }

    int mid = (s+e)/2;

    tree[ind] = max(build(2*ind, s, mid), build(2*ind+1, mid+1, e));
    return tree[ind];
}

ll get(int idx, int s, int e, int l, int r) {
    if(l>e || r<s) return INT_MIN;

    if(l<=s&&e<=r)
        return tree[idx];

    int mid = (s+e)/2;

    return max(get(2*idx,s,mid,l,r), get(2*idx+1,mid+1,e,l,r));
}

void update(int idx, int s, int e,int pos, ll val) {
    if(s==e) {
        dp[pos] = val;
        tree[idx] = val;
        return ;
    }

    int mid = (s+e)/2;

    if(pos>=s&&pos<=mid)
        update(2*idx, s, mid, pos, val);
    else
        update(2*idx+1, mid+1, e, pos, val);

    tree[idx] = max(tree[2*idx], tree[2*idx+1]);
}

