class SEGTREE
{
private:
    vector<ll> dat;
public:
    int n;
    int init(int n_);
    void update(int k, ll a);
    ll query(int a, int b, int k, int l, int r);
};

int SEGTREE::init(int n_) {
    n = 1;
    while (n <= n_) n *= 2;
    dat = vector<ll>(2*n,0);
    return n;
    //for (int i = 0;i < 2*n-1;++i) dat[i] = INT_MAX;
}

void SEGTREE::update(int k,ll a) {
    k += n-1;
    dat[k] = a;
    while (k > 0) {
        k = (k-1)/2;
        dat[k] = max(dat[k*2+1],dat[k*2+2]);
    }
}

ll SEGTREE::query(int a,int b,int k,int l,int r) {
    if (r <= a || b <= l) return -1;
    if (a <= l && r <= b) return dat[k];
    else {
        ll vl = query(a,b,k*2+1,l,(l+r)/2);
        ll vr = query(a,b,k*2+2,(l+r)/2,r);
        return max(vl,vr);
    }
}

