ll i,n,b,ans,r;
ll a[N],st[4 * N];
void update(ll i,ll p,ll v,ll l,ll r)
{
    if(l == r){
        st[i] = v;
        return;
    }
    ll m = (l + r) / 2;
    if(p <= m)
        update(2 * i,p,v,l,m);
    else
        update(2 * i + 1,p,v,m + 1,r);
    st[i] = max(st[2 * i],st[2 * i + 1]);
}
ll query(ll i,ll s,ll e,ll l,ll r)
{
    if(e < l || s > r) return 0;
    if(s <= l && r <= e)
        return st[i];
    ll m = (l + r) / 2;
    return max(query(2 * i,s,e,l,m),query(2 * i + 1,s,e,m + 1,r));
}
