    else if(l>ir || r<il)
        return 0;
    else
    {
        ll mid = (l+r)/2;
        return max(getMax(l,mid,il,ir,2*i+1),getMax(mid+1,r,il,ir,2*i+2));
    }
}

void updateMax(ll l, ll r, ll i, ll diff, ll index)
{
    if(i<l || i>r)
