    if(r<=a||b<=l)return -INF;
    if(a<=l&&r<=b)return dat[k];
    else{
      return max(subquery(a,b,k*2+1,l,(l+r)/2),subquery(a,b,k*2+2,(l+r)/2,r));
    }
  }

  ll query(int a,int b){
    return subquery(a,b,0,0,size);
  }
};

