template <class T>
struct Fenwick {
    Fenwick() = default;
    Fenwick(int n) : tree(n + 1) {}

    void Add(unsigned int i, const T& d) {
        for (i++; i < tree.size(); i += i & (-i)) {
            tree[i] = tree[i] + d;
        }
    }

    T Prefix(unsigned int i) {
        T result{};
        for (i++; i > 0; i -= i & (-i)) {
            result = result + tree[i];
        }
        return result;
    }

   private:
    vector<T> tree;
};

struct Elem {
	ll val = {};
	Elem operator+(Elem r) const {
		return {max(val, r.val)};
	}
};



