ll Query(ll a, ll b)
{
    a+=MAX;
    b+=MAX;
    ll odp=max(tree[a], tree[b]);
    if(b%2==1) odp=max(odp, tree[b-1]);
    if(a%2==0) odp=max(odp, tree[a+1]);
    while(a/2 != b/2)
