	node(lli n=0):n(n){}
	node operator +(const node &x)const{
		return n<x.n?x:node(n);
	}
};

struct ST{
	#define mid (l+r)/2
	#define left(u) u+1
	#define right(u) (u + ((mid - l + 1) << 1))
	vector<node>st;
	ST(int n):st(2*n){}
	void update(int u, int l, int r, int w, lli v){
		if(l==r){
			st[u].n=v;
			return;
		}
		if(w<=mid)update(left(u),l,mid,w,v);
		else update(right(u),mid+1,r,w,v);
		st[u]=st[left(u)]+st[right(u)];
	}
	node query(int u, int l, int r, int ll, int rr){
		if(l>r or ll>r or rr<l)return node();
		if(l>=ll and r<=rr)return st[u];
		return query(left(u),l,mid,ll,rr)+query(right(u),mid+1,r,ll,rr);
	}
};

