ll rangeQuery(int low, int high, int qlow, int qhigh, int pos) {
    if(qlow <= low && qhigh >= high) {
        return seg[pos];
    }
    if(qlow > high || qhigh < low) {
        return INT_MIN;
    }
    int mid = (low + high) / 2;
    return MAX(rangeQuery(low, mid, qlow, qhigh, 2 * pos + 1),
               rangeQuery(mid + 1, high, qlow, qhigh, 2 * pos + 2));
}
void updateSegmentTree(int index, ll delta, int low, int high, int pos) {
    if(index < low || index > high) {
        return;
    }
    if(low == high) {
        seg[pos] += delta; /* delta = change added */
        return;
    }
    int mid = (low + high) / 2;
    updateSegmentTree(index, delta, low, mid, 2 * pos + 1);
    updateSegmentTree(index, delta, mid + 1, high, 2 * pos + 2);
    seg[pos] = MAX(seg[2 * pos + 1], seg[2 * pos + 2]);
}
