	if (r < 0) return 0LL;
	if (l <= x && r >= y) {
		return st[k];
	}
	else {
		int m = x + (y - x) / 2;
		if (r <= m) return query(l, r, x, m, 2*k+1);
		else if (l > m) return query(l, r, m+1, y, 2*k+2);
		else return max(query(l, m, x, m, 2*k+1), query(m+1, r, m+1, y, 2*k+2));
	}
}

