template<class T>
struct SegmentTree {
private:
    int n;
    vector<T> node;
	T ininum; // 初期値。区間sumなら0、区間minならINFなど
	function<T(T,T)> f; // sum,minなどの演算を設定

public:
    SegmentTree(vector<T> v, T ininum, function<T(T,T)> f) {
    	this->ininum = ininum;
    	this->f = f;

        int sz = v.size();
        n = 1; while(n < sz) n *= 2;
        node.resize(2*n-1, 0);
        for(int i=0; i<sz; i++) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; i--) node[i] = f(node[2*i+1], node[2*i+2]);
    }

    void update(int x, T val) {
        x += (n - 1);
        node[x] = val;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = f(node[2*x+1], node[2*x+2]);
        }
    }

    ll get(int a, int b, int k=0, int l=0, int r=-1) {
        if(r < 0) r = n;
        if(r <= a || b <= l) return ininum;
        if(a <= l && r <= b) return node[k];

        ll vl = get(a, b, 2*k+1, l, (l+r)/2);
        ll vr = get(a, b, 2*k+2, (l+r)/2, r);
        return f(vl, vr);
    }
};

