struct segment_tree {
  using T = i64;
  T ope(const T& a, const T& b) {
    return max(a, b);
  }
  T ide() { return -1e18; }

  i64 n;
  vector<i64> node;

  segment_tree(vector<i64> init) {
    n = 1;
    while(n < init.size()) n *= 2;
    node.resize(2 * n);
    rep(i, 0, init.size()) node[i + n] = init[i];
    for(int i = n - 1; i >= 1;i--) node[i] = ope(node[i * 2], node[i * 2 + 1]);
  }

  void update(i64 i, i64 x) {
    i += n;
    node[i] = x;
    while(i > 1) {
      i = i / 2;
      node[i] = ope(node[i * 2], node[i * 2 + 1]);
    }
  }

  T get(i64 l, i64 r) {
    T lx = ide();
    T rx = ide();
    l += n;
    r += n;
    while(l < r) {
      if(l & 1) { lx = ope(lx, node[l]); }
      if(!(r & 1)) { rx = ope(node[r], rx); }
      l = (l + 1) >> 1;
      r = (r - 1) >> 1;
    }
    if(l == r) { lx = ope(lx, node[l]); }
    return ope(lx, rx);
  }
};

