class Fenwick {
public:
	int N;
	Fenwick(int M) {
		N = M;
		V.resize(N + 1);
	}
	vector<long long int> V;

	long long int query(int k) {
		long long int ret=0;
		while (k > 0) {
			ret = max(ret, V[k]);
			k -= RSOne(k);
		}
		return ret;
	}

    void  update(int j, long long int val) {
		while (j<=N) {
			V[j] = max(V[j], val);
			j += RSOne(j);
	   }
	}

};

