void upd(int node,int l,int r,int k,ll val){
	if(l == r){
		tree[node] = val;
		return;
	}
	if(k <= (l+r)/2) 
		upd(node*2,l,(l+r)/2,k,val);
	else 
		upd(node*2+1,(l+r)/2+1,r,k,val);
	tree[node] = max(tree[node*2],tree[node*2+1]);
}
ll query(int node,int l,int r,int s,int e){
	if(s <= l && e >= r)
		return tree[node];
	if(s <= (l+r)/2 && e >= (l+r)/2+1){
		return max(query(node*2,l,(l+r)/2,s,e),query(node*2+1,(l+r)/2+1,r,s,e));
	}
	if(s <= (l+r)/2) 
		return query(node*2,l,(l+r)/2,s,e);
	return query(node*2+1,(l+r)/2+1,r,s,e);
}
