	for (int i = base - 1; i > 0; --i)      
		tree[i] = max(tree[i<<1] , tree[i<<1 | 1]);     
} 

// function to update a tree node 
void update(int p, ll value)  
{  
	// set value at position p 
	tree[p+base] = value; 
	p = p+base; 

	// move upward and update parents 
	for (int i=p; i > 1; i >>= 1) 
		tree[i>>1] = max(tree[i] , tree[i^1]); 
} 

