template <typename T>
struct BinaryIndexedTree {
  vector<T> data;  // 1-indexed

  BinaryIndexedTree(size_t size) { data.assign(size + 1, 0); }

  T Sum(size_t k) {  // 0-indexed
    T ret = T(0);
    for (++k; k > 0; k -= (k & (-k))) {
      ChMax(ret, data[k]);
    }
    return ret;
  }

  void Add(size_t k, const T x) {  // 0-indexed
    for (++k; k < data.size(); k += (k & -k)) ChMax(data[k], x);
  }
};

