void up(ll node,ll l,ll r,ll i,ll x)
{
    if(l>i||r<i)
        return;
    if(l==r)
    {
        tree[node]=max(tree[node],x);
        return;
    }
    ll ln=node*2,mid=(l+r)/2;
    up(ln,l,mid,i,x);
    up(ln+1,mid+1,r,i,x);
    tree[node]=max(tree[ln],tree[ln+1]);
    return ;
}


ll qry(ll node,ll l,ll r,ll i)
{
    if(l>i)
        return 0;
    if(r<=l)
        return tree[node];
    ll ln=node*2,mid=(l+r)/2;
    return max(qry(ln,l,mid,i),qry(ln+1,mid+1,r,i));
}

