    int64 res = 0;

    vector<int> H(N), A(N);
    for (auto & v : H)
        cin >> v;
    for (auto & v : A)
        cin >> v;

    for (int i = 0; i < N; i++) {
        int h = H[i], a = A[i];
        auto bst = tree.get(h - 1) + a;
        res = max(res, bst);
        tree.modify(h, bst);
    }

    cout << res << "\n";

    return 0;
}

