void sinit(int x,int l,int r) {
	if(l==r) {
		sval[x]=0;
	} else {
		int m=l+(r-l)/2;
		sinit(2*x+1,l,m); sinit(2*x+2,m+1,r);
		sval[x]=max(sval[2*x+1],sval[2*x+2]);
	}
}
void supd(int x,int l,int r,int IDX,ll VAL) {
	if(l==r) {
		sval[x]=VAL;
	} else {
		int m=l+(r-l)/2;
		if(IDX<=m) supd(2*x+1,l,m,IDX,VAL); else supd(2*x+2,m+1,r,IDX,VAL);
		sval[x]=max(sval[2*x+1],sval[2*x+2]);
	}
}
ll sget(int x,int l,int r,int L,int R) {
	if(L<=l&&r<=R) {
		return sval[x];
	} else {
		ll ret=LLONG_MIN; int m=l+(r-l)/2;
		if(L<=m) ret=max(ret,sget(2*x+1,l,m,L,R));
		if(m+1<=R) ret=max(ret,sget(2*x+2,m+1,r,L,R));
		return ret;
	}
}

