void update(int p, int l, int r, int x, ll y) {
	if (l == r) {
		st[p] = y;
		return;
	}
	int mid = (l + r) >> 1;
	if (x <= mid) update(p << 1, l, mid, x, y);
	else update(p << 1 | 1, mid + 1, r, x, y);
	st[p] = max(st[p << 1], st[p << 1 | 1]);
	return;
}

ll query(int p, int l, int r, int x, int y) {
	if (l > y || r < x) return 0;
	if (l >= x && r <= y) return st[p];
	int mid = (l + r) >> 1;
	return max(query(p << 1, l, mid, x, y), query(p << 1 | 1, mid + 1, r, x, y));
}

