void update(int node, int l, int r, int p, long long x) {
	if(l == r) {
		sg[node] = max(sg[node], x);
		return;
	}
	if(p > r || p < l) return;
	int mid = (l + r) / 2;
	update(2*node, l, mid, p, x);
	update(2*node+1, mid+1, r, p, x);
	sg[node] = sg[2*node] + sg[2*node+1];
}

long long range_max(int node, int l, int r, int a, int b) {
	if(l == r) {
		return sg[node];
	}
	if(a > r || b < l) return -1;
	int mid = (l + r) / 2;
	long long q1 = range_max(2*node, l, mid, a, b);
	long long q2 = range_max(2*node+1, mid+1, r, a, b);
	return max(q1, q2);
}

