#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
const LL MAX = 1e5+5;
LL a[MAX] , b[MAX] , dp[MAX];
LL ST[4*MAX + 5];

LL query(LL start , LL end , LL node , LL s , LL e)
{
        if(e < start || s > end || start > end) return 0;
        if(s <= start && e >= end)
        {
                return ST[node];
        }
        LL mid = (start + end)/2;
        return max(query(start,mid,2*node,s,e) , query(mid+1,end,2*node+1,s,e));
}

void update(LL start , LL end , LL node , LL pos , LL val)
{
        if(pos < start || pos > end || start > end) return;
        if(start == end)
        {
                ST[node] = val;
                return;
        }
        LL mid = (start + end)/2;
        if(pos >= start && pos <= mid)
                update(start,mid,2*node,pos,val);
        else
                update(mid+1,end,2*node+1,pos,val);
        ST[node] = max(ST[2*node] , ST[2*node+1]);
}

int main()
{
        ios_base::sync_with_stdio(false);
        cin.tie(NULL);
        cout.tie(NULL);
        memset(ST , 0 ,sizeof(ST));
        LL n;
        cin >> n;
        for(int i = 1 ; i <= n ; i++)
        {
                cin >> a[i];
        }
        for(int i = 1 ; i <= n ; i++)
        {
                cin >> b[i];
        }
        for(int i = 1 ; i <= n ; i++)
        {
                LL x = query(1,n,1,1,a[i]);
                dp[i] = x + b[i];
                update(1,n,1,a[i] , dp[i]);
        }
        LL ans = 0;
        for(int i = 1 ; i <= n ; i++)
        {
                //cout << dp[i] << " ";
                ans = max(ans , dp[i]);
        }
        cout << ans << endl;
        return 0;
}

