ll query(ll l ,ll r ,ll s , ll e ,ll idx)
{
	if(s>r || e< l)
		return 0;
	if(l<=s && e<=r)
	{
		return tree[idx];
	}
	ll mid = (s+e)/2;
	return max(query(l,r,s,mid,2*idx),query(l,r,mid+1,e,2*idx+1));
}

void update(ll s, ll e , ll idx , ll node , ll val)
{
	ll mid = (s+e)/2;
	if(idx<s || idx>e)
		return ;
	if(s == e)
	{
		tree[node] = val;
		return ;
	}
	update(s,mid,idx,2*node,val);
	update(mid+1,e,idx,2*node+1,val);
	tree[node]=max(tree[2*node],tree[2*node+1]);

}

