class SegmentTree
{
	public:
	int N;
	vector<lint> tree;

	SegmentTree(int size,lint init)
	{
		N=1;
		while(N<size)N*=2;

		tree.resize(2*N-1);
		for(auto&& i:tree)
			i=init;
	}

	void update(int i,lint value)
	{
		tree[i+N-1]=value;

		i=i+N-1;
		while(i>0)
		{
			i=(i-1)/2;
			tree[i]=max(tree[2*i+1],tree[2*i+2]);
		}
	}

	lint getMax(int tl,int tr,int l=0,int r=-1,int i=0)
	{
		if(r<0)
			r=N;

		if(tr<=l || r<=tl)
			return 0;

		if(tl<=l && r<=tr)
			return tree[i];

		lint retl=getMax(tl,tr,l,(l+r)/2,2*i+1);
		lint retr=getMax(tl,tr,(l+r)/2,r,2*i+2);

		return max(retl,retr);
	}
};

