const int sqrtN = 512;

struct SqrtDecomposition{
    int N, K;
    vector<int> data;
    vector<int> bucketmax;
    SqrtDecomposition(int n) : N(n){

        //切り上げ(K := バケット数, sqrtN := バケットサイズ)
        K = (N + sqrtN - 1) / sqrtN;
        data.assign(K * sqrtN, 0);
        bucketmax.assign(K, 0);
    }

    void update(int x, int y){
        int k = x / sqrtN;
        int maxVal = data[x] = y;
        int sum = 0;
        for (int i = k * sqrtN; i < (k + 1) * sqrtN; ++i) {
            maxVal = max(maxVal, data[i]);
        }

        bucketmax[k] = maxVal;
    }

    //[x, y)
    int find(int x, int y){

        int maxVal = 0;

        for(int k = 0; k < K; k++){

            int l = k * sqrtN;
            int r = (k + 1) * sqrtN;
            if(r <= x || y <= l) continue;

            if(x <= l && r <= y) maxVal = max(maxVal, bucketmax[k]);
            else{
                for(int i = max(x, l); i < min(y, r); i++){
                    maxVal = max(maxVal, data[i]);
                }
            }
        }

        return maxVal;
    }


};

