ll maxSumIS(ll arr[], ll n)
{
    ll newindex = 0, max_sum;

    map<ll, ll> uniqueArr;

    for (ll i = 0; i < n; i++)
    {
        uniqueArr[arr[i]] = 0;
    }

    for (map<ll, ll>::iterator it = uniqueArr.begin();
         it != uniqueArr.end(); it++)
    {

        newindex++;

        uniqueArr[it->first] = newindex;
    }

    ll *BITree = new ll[newindex + 1];

    for (ll i = 0; i <= newindex; i++)
    {
        BITree[i] = 0;
    }

    for (ll i = 0; i < n; i++)
    {
        max_sum = getSum(BITree, uniqueArr[arr[i]] - 1);

        updateBIT(BITree, newindex,
                  uniqueArr[arr[i]], max_sum + b[i]);
    }

    return getSum(BITree, newindex);
}

