void setValue(int i, int l, int r, int pos, ll val)
{
	if (l == r)
		t[i] = max(t[i], val);
	else
	{
		int mid = (l + r) / 2;
		if (pos <= mid)
			setValue(2 * i + 1, l, mid, pos, val);
		else
			setValue(2 * i + 2, mid + 1, r, pos, val);
		t[i] = max(t[2 * i + 1], t[2 * i + 2]);
	}
}

ll maxOnRange(int i, int l, int r, int lx, int rx)
{
	if (l == lx && r == rx)
		return t[i];
	else
	{
		int mid = (l + r) / 2;
		ll result = -INF;
		if (lx <= mid)
			result = max(result, maxOnRange(2 * i + 1, l, mid, lx, min(rx, mid)));
		if (rx > mid)
			result = max(result, maxOnRange(2 * i + 2, mid + 1, r, max(lx, mid + 1), rx));
		return result;
	}
}

