using namespace std;

template <typename T>
class Max_seg_tree {
    vector<T> seg;
    int n;

    // create
    T create(int node, int l, int r, const vector<T>& v) {
        if (l == r)
            seg[node] = v[l];
        else {
            int mid = (l + r) / 2;
            seg[node] = max(create(2 * node + 1, l, mid, v), create(2 * node + 2, mid + 1, r, v));
        }
        return seg[node];
    }

   public:
    // constructor
    Max_seg_tree(const vector<T>& v) {
        n = (int)v.size();
        seg.resize(4 * n);
        create(0, 0, n - 1, v);
    }

    // update element
    T update(int ind, T val, int node = 0, int l = 0, int r = -1) {
        if (r == -1) r += n;

        if (l == r && l == ind)
            seg[node] = val;
        else if (l <= ind && ind <= r) {
            int mid = (l + r) / 2;
            if (ind <= mid)
                update(ind, val, 2 * node + 1, l, mid);
            else
                update(ind, val, 2 * node + 2, mid + 1, r);

            seg[node] = max(seg[2 * node + 1], seg[2 * node + 2]);
        }
        return seg[node];
    }

    // range query
    T query(int l, int r, int node = 0, int tl = 0, int tr = -1) {
        if (tr == -1) tr += n;

        if (tl == tr)
            return seg[node];
        else {
            int mid = (tl + tr) / 2;
            if (r <= mid)
                return query(l, r, 2 * node + 1, tl, mid);
            else if (l > mid)
                return query(l, r, 2 * node + 2, mid + 1, tr);
            else
                return max(query(l, mid, 2 * node + 1, tl, mid), query(mid + 1, r, 2 * node + 2, mid + 1, tr));
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ll n;
    cin >> n;
    vector<int> h(n);
    vector<ll> a(n, 0);
    Max_seg_tree<ll> seg(a);

    for (int i = 0; i < n; i++) {
        cin >> h[i];
        h[i]--;
    }
    for (int i = 0; i < n; i++) cin >> a[i];

    ll ans = 0;

    for (int i = n - 1; i >= 0; i--) {
        ll temp = 0;
        if (h[i] + 1 <= n - 1) temp = seg.query(h[i] + 1, n - 1);
        temp += a[i];
        // cout << temp << endl;
        seg.update(h[i], temp);
        ans = max(ans, temp);
    }
    cout << ans;

    return 0;
}

