{	// 降順は演算子>, 昇順は演算子<, if順の優先でソートされる
	return l.h < r.h;
};

int main(void)
{
	ll N; cin >> N;
	vt<ll> h; InputVT(N, h);
	vt<ll> a; InputVT(N, a);

	vt<Nyaa> f;
	rep(i, 0, N) f.push_back({ h[i], a[i], i });
	sort(all(f), NyaaSort);

	DS_SegmentTree<ll> tree(N);
	each(i, e, f)
	{
		ll test = tree.GetMax(0, e.i);
		tree.Add(e.i, test + e.a);
	}

	cout << tree.GetMax(0, N);
	return 0;
}

