ll get(int node, int start, int end, int from, int to) {
	if (end < from || start > to)
		return 0;
	if (start >= from && end <= to)
		return seg[node];
	int mid = (start + end) >> 1;
	return max(get(node << 1, start, mid, from, to),
			get((node << 1) | 1, mid + 1, end, from, to));
}

void update(int node, int start, int end, int at, ll value) {
	if (at < start || at > end)
		return;
	if (start == end) {
		seg[node] = max(seg[node], value);
		return;
	}
	int mid = (start + end) >> 1;
	update(node << 1, start, mid, at, value);
	update((node << 1) | 1, mid + 1, end, at, value);
	seg[node] = max(seg[node << 1], seg[(node << 1) | 1]);
}

