    {   
        return seg[ind];
    }
    else
    {
        ll tm = (tl+tr)/2;
        return max(ret_tree(2*ind,tl,tm,l,min(tm,r)),ret_tree(2*ind+1,tm+1,tr,max(tm+1,l),r));
    }
}

