//RECURSIVE SOLUTION
ll rec(ll x){
    if(x==n-1) return dp[x]=b[x];
    if(dp[x]!=-1) return dp[x];
    ll p=INT_MIN;
    for(int i=x+1;i<n;i++){
        if(a[i]>a[x]){
            p=max(p,rec(i));
        }
    }
    dp[x]=p+b[x];
    return dp[x];
}

