struct SegmentTree {
    int N;
    vector<ll> node;
    const ll INF = LLINF;

    void init(int siz){
        N = 1;
        while (N < siz) N *= 2;
        node.resize(2*N-1, 0);
    }
    void build(vector<ll> &dat){
        for(int i=0; i<dat.size(); i++){
            node[i+N-1] = dat[i];
        }
        for(int i=N-2; i>=0; i--){
            node[i] = max(node[2*i+1], node[2*i+2]);
        }
    }
    void update(int k, ll x) {
        k += N - 1;
        node[k] = x;
        while (k > 0) {
            k = (k-1)/2;
            node[k] = max(node[k*2+1], node[k*2+2]);
        }
    }
    ll getMax(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return -INF;
        if (a <= l && r <= b) return node[k];
        ll vl = getMax(a, b, k*2+1, l, (l+r)/2);
        ll vr = getMax(a, b, k*2+2, (l+r)/2, r);
        return max(vl, vr);
    }
    ll getMax(int a, int b) {return getMax(a, b, 0, 0, N);}
};

