const ll mod = 1e9+7;
ll query(ll s , ll e , ll node , ll h){
    if(e <= h)return tree[node];
    ll mid = (s + e) / 2;
    if(h <= mid)return query(s , mid , node * 2 , h);
    return max( query(s , mid , node * 2 , h) , query(mid + 1 , e , node * 2 + 1 , h));
}
void update(ll s , ll e , ll node , ll h , ll val){
    if(s == e){
        tree[node] = val;
        return;
    }
    ll mid = (s + e);
    mid /= 2;
    if(s <= h && h <= mid)update(s , mid , node * 2 , h , val);
    else update(s , mid , node * 2 + 1 , h , val);
    tree[node] = max(tree[node * 2] , tree[node * 2 + 1]);
}
