// one-index based bit tree.
template <class T>
struct Bit {
    vector<T> x;
    Bit(int n) : x(n + 1) {}

    void add(int k, T a) {
        for (; k < sz(x); k += (k & -k)) {
            x[k] = max(x[k], a);
        }
    }

    // query [1...k]
    T query(int k) {
        T s = 0;
        for (; k > 0; k -= (k & -k)) {
            s = max(s, x[k]);
        }
        return s;
    }
};


void solve() {
    int n; cin >> n;
    vi h(n), a(n);
    fori (i, 0, n) {
