    }

    Bit<ll> bit(n);
    vl dp(n);
    fori (i, 0, n) {
        // Query maximum value in range [1...h[i]], if we found one,
        // there must have h[i] > h[j] (j < i) satisfied.
        dp[i] += bit.query(h[i]) + a[i];
        bit.add(h[i], dp[i]);
    }

    // trace(h, a, dp);
    output(bit.query(n));
}

