   s.clear();

   for (vector<string>::const_iterator p = v.begin();
        p != v.end(); ++p) {
      s += *p;
      if (p != v.end() - 1)
        s += c;
   }
}


int h[2*(int)1e5];
ll b[2*(int)1e5];
ll dp[2*(int)1e5+1];
int n;
ll solve() {
    dp[0] = b[0];
    ll res = dp[0];
    rep(i, 1, n) {
        rep(j, 0, i) {
            if(h[i] > h[j]) {
                dp[i] = max(dp[j], dp[i]);
            }
        }
        dp[i] += b[i];
        res = MAX(res, dp[i]);
    }
    return res;
}

