typedef long long int in;

in tree[800005],dp[200005];

void update(in node,in s,in e,in ind,in val)
{
    if(s==e)
    {
        tree[node]=val;
    }
    else
    {
        in m=(s+e)/2;

        if(s<=ind && ind<=m)
        update(2*node,s,m,ind,val);
        else
        update(2*node+1,m+1,e,ind,val);

        tree[node]=max(tree[2*node],tree[2*node+1]);
    }
}

in query(in node,in s,in e,in l,in r)
{
    if(r<s||e<l)
    return 0;

    if(l<=s&&e<=r) 
    return tree[node];

    in m=(s+e)/2;

    in max1=query(2*node,s,m,l,r);
    in max2=query(2*node+1,m+1,e,l,r);

    in maxi=max(max1,max2);

    return maxi;
}

