class SegmentTree {
private:
  int siz;
  vector<long long> dat;

  public:
  SegmentTree(vector<long long> v) {
    siz = 1;
    while(siz < (int) v.size()) siz <<= 1;
    dat.resize(2 * siz - 1, -LLONG_MAX);
    for(int idx = 0; idx < (int) v.size(); idx++) {
      dat[idx + siz - 1] = v[idx];
    }
    for(int idx = siz - 2; idx >= 0; idx--) {
      dat[idx] = max(dat[2 * idx + 1], dat[2 * idx + 2]);
    }
  }

  void update(int idx, long long val) {
    idx += (siz - 1);
    dat[idx] = val;
    while(idx > 0) {
      idx = (idx - 1) / 2;
      dat[idx] = max(dat[2 * idx + 1], dat[2 * idx + 2]);
    }
  }
  //[a, b)
  long long get(int a, int b, int idx = 0, int l = 0, int r = -1) {
    if(r < 0) r = siz;
    if(r <= a || b <= l) return -LLONG_MAX;
    if(a <= l && r <= b) return dat[idx];
    long long val1 = get(a, b, 2 * idx + 1, l, (l + r) / 2);
    long long val2 = get(a, b, 2 * idx + 2, (l + r) / 2, r);
    return max(val1, val2);
  }
};
