	ll n;
	cin >> n;
	vector<ll> H(n), B(n);

	ll base = n;

	vector<ll> dp(n + 1);
	vector<ll> tree(4 * base + 1);

	for (auto &a : H){
		cin >> a;
	}
	for (auto &a : B){
		cin >> a;
	}

	for (ll flower = 0; flower < n; ++flower){
		ll h = H[flower];
		ll b = B[flower];

		ll best = 0;

		ll l = base + 1;
		ll r = base + h;

		while (l <= r){
			if (l & 1){
				best = max(best, tree[l]);
				l++;
			}
			if ((r & 1) == 0){
				best = max(best, tree[r]);
				r--;
			}
			l /= 2;
			r /= 2;
		}

		dp[h] = best + b;
		tree[base + h] = best + b;

		for (ll index = (base + h) / 2; index >= 1; index /= 2){
			tree[index] = max(tree[2 * index], tree[2 * index + 1]);
		}
	}
	ll best = 0;
	for (ll x : dp){
		best = max(best, x);
	}
	cout << best << endl;
}

