void change(const int &p,const ll &v,const int &l,const int &r,const int &k){
	if (l==p && r==p){
		tr[k]=v;
		re;
	}
	int mid=(l+r)>>1;
	if (p<=mid) change(p,v,lson);
	if (p>mid) change(p,v,rson);
	tr[k]=max(tr[k<<1],tr[k<<1|1]);
}

ll query(const int &L,const int &R,const int &l,const int &r,const int &k){
	if (L>R) re 0;
	if (l>=L && r<=R) re tr[k];
	int mid=(l+r)>>1;
	ll ret=0;
	if (L<=mid) cmax(ret,query(L,R,lson));
	if (R>mid) cmax(ret,query(L,R,rson));
	re ret;
}

