lli answer(vector<lli> h,vector<lli> a,int i,int n,vector<lli> dp)
{
    if(dp[i]!=-1) return dp[i];
    dp[i]=a[i];
    for(int j=i+1;j<n;j++)
    {
        if(h[j]>h[i])
        {
            dp[i]=max(dp[i],a[i]+answer(h,a,j,n,dp));
        }
    }
    return dp[i];
}
