vector<int> a;

size_t solution(int i, int prev)
{ 
  if (i == N) return 0;
  if (i == N-1) return a[i];
  size_t ans = 0;
  for (int j = i+1; j < N; ++j)
  { 
    if  (h[j] < prev)
    { 
      continue;
    }
    else if (h[j] > h[i])
    { 
      ans = max(a[i] + solution(j, h[j]), ans);
    }
    else
    { 
      ans = max(solution(j, prev), ans);
    }
  }
  return ans;
}

