//Globals
class segment_tree{
private:
    vec<ll> seg_tree;
    vec<ll> lazy_val;
    ll n;
    //Build seg tree
    void build_tree(ll index, ll start, ll end, vec<ll> arr){
        if(start==end){
            seg_tree[index] = arr[start];
        } 
        else if(start>end){
            return;
        } else {
            ll mid = (start+end)/2LL;
            build_tree(2LL*index,start,mid,arr);
            build_tree(2LL*index+1LL,mid+1,end,arr);
            seg_tree[index] = max(seg_tree[2LL*index],seg_tree[2LL*index+1LL]);
        }
    }
    ll query_tree(ll index, ll start, ll end, ll qstart, ll qend){
        if (lazy_val[index]!=0LL){
                seg_tree[index] += lazy_val[index];
                if(start!=end){
                    lazy_val[2LL*index] += lazy_val[index];
                    lazy_val[2LL*index+1LL] += lazy_val[index];
                }
                lazy_val[index] = 0LL;
        }
        //Qurey is totally out of current range
        if(qend<start or qstart>end){
            return 0LL;
        }
        //Query encloses current range
        else if(qstart<=start and qend >= end){
            return seg_tree[index];
        }
        //If some part of range coincides
        else{
            ll mid = (start+end)/2LL;
            ll left = query_tree(2LL*index,start,mid,qstart,qend);
            ll right = query_tree(2LL*index+1LL,mid+1,end,qstart,qend);
            seg_tree[index] = max(left,right);
            return seg_tree[index];
        }
    }
    void lazy_upadte(ll index, ll start, ll end, ll qstart, ll qend, ll delta){
        if(lazy_val[index]!=0LL){
            seg_tree[index] += lazy_val[index];
            if(start!=end){
                lazy_val[2LL*index] += lazy_val[index];
                lazy_val[2LL*index+1LL] += lazy_val[index];
            }
            lazy_val[index] = 0LL;
        }
        if(qend<start or qstart>end){
            return;
        }
        else if (qstart<=start  and  qend>=end){
            seg_tree[index] += (end-start+1)*delta;
            if(start!=end){
                lazy_val[2LL*index]+=delta;
                lazy_val[2LL*index+1LL]+=delta;
            }
            return;
        } else {
            ll mid = (start+end)/2;
            lazy_upadte(2LL*index,start,mid,qstart,qend,delta);
            lazy_upadte(2LL*index+1LL,mid+1,end,qstart,qend,delta);
            seg_tree[index] = max(seg_tree[2LL*index],seg_tree[2LL*index+1LL]);
        }
    }
public:
    //Init
    segment_tree(ll sz){
        n = sz;
        seg_tree.resize(2LL*n+3LL);
        lazy_val.resize(2LL*n+3LL);
    }
    //Range/Point Query
    ll query(ll start, ll end){
        return query_tree(1LL,0LL,n-1LL,start,end);
    }
    void update(ll start, ll end, ll delta){
        lazy_upadte(1LL,0LL,n-1LL,start,end,delta);
    }
};
