/**
 *  @brief Iterative segment tree: single update, range query
*/
struct segTree {
    int N;
    using S = int64_t;
    vector<S> val;
    segTree(int _n) : N(_n) {
        // initialize array
        val.resize(2 * N, 0);
    }
    S combine(S l, S r) {
        return max(l, r);
    }
    void update(int i, S d) {
        // this is assignment update
        for (val[i += N] = d; i >>= 1;) {
            val[i] = combine(val[i << 1], val[i << 1 | 1]);
        }
    }
    S query(int l, int r) {
        // query sum of range [l, r)
        S rl = 0, rr = 0;
        for (l += N, r += N; l < r; l /= 2, r /= 2) {
            if (l & 1)
                rl = combine(rl, val[l++]);
            if (r & 1)
                rr = combine(rr, val[--r]);
        }
        return combine(rl, rr);
    }
};

