struct segtree{
    int n;
    vector<long long> d;
    segtree(int mx){
        n = 1;
        while(n < mx) n <<= 1;
        d = vector<long long>(n << 1);
    }
    long long query(int a, int b, int i = 1, int l = 0, int r = -1){
        if(r == -1) r = n;
        if(a <= l && r <= b) return d[i];
        long long res = 0;
        int c = (l + r) >> 1;
        if(a < c) res = max(res, query(a, b, i << 1, l, c));
        if(c < b) res = max(res, query(a, b, i << 1 | 1, c, r));
        return res;
    }
    void update(int i, long long x){
        i += n;
        while(i){
            d[i] = max(d[i], x);
            i >>= 1;
        }
    }
};

