class SegmentTree {
public:
    vector<ll> Max;
    int N;
    SegmentTree(int n) {
        N = 1;
        while (N < n) N *= 2;
        Max.resize(2 * N - 1, 0);
    }
    ll get(int a, int b, int l, int r, int x) {
        if (b <= l || r <= a) return 0;
        if (a <= l && r <= b) return Max[x];
        int mid = (l + r) / 2;
        return max(get(a, b, l, mid, 2 * x + 1), get(a, b, mid, r, 2 * x + 2));
    }
    ll get(int a, int b) {
        return get(a, b, 0, N, 0);
    }
    void update(int p, ll x) {
        p += N - 1;
        Max[p] = x;
        while (p > 0) {
            p = (p - 1) / 2;
            Max[p] = max(Max[2 * p + 1], Max[2 * p + 2]);
        }
    }
};

