class node{
public:
    ll val;
    int lb, rb;
    node *left, *right;
    node(int levo, int desno){
        lb = levo;
        rb = desno;
        if(levo == desno){
            val = 0;
        }
        else{
            int mid = (levo + desno) >> 1;
            left = new node(levo, mid);
            right = new node(mid + 1, desno);
            val = max(left->val, right->val);
        }
    }
    void update(int _node, ll new_val){
        if(lb == rb){
            val = new_val;
            return;
        }
        if(_node >= right -> lb){
            right -> update(_node, new_val);
        }
        else{
            left -> update(_node, new_val);
        }
        val = max(left->val, right->val);
    }
    ll query(int i, int j){
        if(i <= lb and rb <= j) return val;
        /// i j l r i j
        if(j < lb or rb < i) return -inf;
        return max(left->query(i, j), right->query(i, j));
    }
};
