struct segtree
{
    vector<ll> t;
    int n;
    segtree(int _n) : n(_n)
    {
        t.assign(4 * n, 0);
    }

    void update(int node, int l, int r, int p, ll v)
    {
        if(p < l || p > r) return;

        if(l == r)
        {
            t[node] = v;
            return;
        }

        int mid = (l + r) / 2;
        update(2 * node, l, mid, p, v);
        update(2 * node + 1, mid + 1, r, p, v);
        t[node] = max(t[2 * node], t[2 * node + 1]);
    }

    ll query(int node, int l, int r, int ql, int qr)
    {
        if(qr < l || ql > r) return 0;

        if(l >= ql && qr >= r)
            return t[node];

        int mid = (l + r) / 2;
        ll a = query(2 * node, l, mid, ql, qr);
        ll b = query(2 * node + 1, mid + 1, r, ql, qr);
        return max(a, b);
    }
};

