ll query(ll l, ll r, ll v, ll tl, ll tr) {
	if(tl > r || tr < l) {
		return 0;
	}
    else if(tr >= r and tl <= l) {
		return tree[v];
	}
	else {
		ll mid = l + (r - l) / 2;
		ll a = query(l, mid, v * 2 + 1, tl , tr);
        ll b = query(mid + 1, r, v * 2 + 2, tl, tr);
		return max(a, b);
	}
}

void update(ll l, ll r, ll v, ll index, ll value) {
	if(l == r) tree[v] = value;
	else {
		ll mid = l + (r - l) / 2;
		if(index <= mid) {
			update(l, mid, v * 2 +1, index, value);		
		}
		else {
			update(mid + 1, r, v * 2 + 2, index, value);	
		}
		tree[v] = max(tree[v * 2 + 1], tree[v * 2 + 2]);
	}
}

