void ragetreeupd(int idx, int l, int r, int i, ll v) {
  if(l == r) {
    ragetree[idx] = v;
  }
  else {
    int m = (l+r)/2;
    if(i <= m) ragetreeupd(2*idx, l, m, i, v);
    else ragetreeupd(2*idx+1, m+1, r, i, v);
    ragetree[idx] = max(ragetree[2*idx], ragetree[2*idx+1]);
  }
}
void ragetreeupd(int idx, ll val) {
  ragetreeupd(1, 0, n-1, idx, val);
}
ll ragetreequery(int idx, int l, int r, int lhs, int rhs) {
  if(l >= lhs && r <= rhs) return ragetree[idx];
  ll ret = 0;
  int m = (l+r)/2;
  if(m >= lhs) ret = max(ret, ragetreequery(2*idx, l, m, lhs, rhs));
  if(m+1 <= rhs) ret = max(ret, ragetreequery(2*idx+1, m+1, r, lhs, rhs));
  return ret;
}
ll ragetreequery(int lhs, int rhs) {
  if(lhs > rhs) return 0;
  return ragetreequery(1, 0, n-1, lhs, rhs);
}

