lli T[4*2*100001];
lli S[4*2*100001];
lli E[4*2*100001];

void build(lli node,lli l,lli r)
{
    S[node] = l;
    E[node] = r;
    if(l == r)
    {
        T[node] = 0;
        return;
    }
    lli m = l + (r-l)/2;
    build(2*node,l,m);
    build(2*node+1,m+1,r);
    T[node] = max(T[2*node] , T[2*node+1]);
    return;
}

void update(lli node,lli x,lli i)
{
    if(S[node] == E[node])
    {
        T[node] = x;
        return;
    }
    if(i <= E[2*node])
        update(2*node,x,i);
    else
        update(2*node+1,x,i);
    T[node] = max(T[node*2] , T[2*node+1]);
}

lli get(lli node , lli l,lli r)
{
    if(r < S[node] || E[node] < l)
        return LLONG_MIN;
    if(l<=S[node] && E[node] <= r)
    {
        return T[node];
    }
    lli ret = LLONG_MIN;
    ret = max(ret , get(node*2,l,r));
    ret = max(ret , get(2*node+1,l,r));
    return ret;
}

