ll seg[4*2*100000];
void update(int node, int left, int right, int pos, ll val)
{
    if(pos<left || pos>right) return;
    if(left==right)
    {
        seg[node]=val;
        return;
    }
    int mid=(left+right)/2;
    update(node*2, left, mid, pos, val);
    update((node*2)+1, mid+1, right, pos, val);
    seg[node]=max(seg[node*2], seg[(node*2)+1]);
}
ll query(int node, int left, int right, int i, int j)
{
    if(i>right || j<left) return 0;
    if(i<=left && j>=right) return seg[node];
    int mid=(left+right)/2;
    ll p1=query(node*2, left, mid, i, j);
    ll p2=query((node*2)+1, mid+1, right, i, j);
    return max(p1, p2);
}
