#define SZ      (sz * 2 - 1)
#define LF(i)   (i + sz - 1)
#define PA(k)   ((k - 1) / 2)
#define LC(k)   (k * 2 + 1)
#define RC(k)   (k * 2 + 2)
#define M(l,r)  ((l + r) / 2)

const int ST_SIZE = 1 << 19;    // N_MAX * 2 - 1

int sz;
ll dat[ST_SIZE];

void rmq_init(int n) {
  sz = 1;
  while (sz < n) sz <<= 1;
  REP(i, SZ) dat[i] = 0;
}

void update(int i, ll a) {
  int k = LF(i);
  dat[k] = a;
  while (k > 0) {
    k = PA(k);
    dat[k] = max(dat[LC(k)], dat[RC(k)]);
  }
}

ll query_sub(int a, int b, int k, int l, int r) {
  if (r <= a || b <= l) return 0;
  if (a <= l && r <= b) return dat[k];
  else {
    ll vl = query_sub(a, b, LC(k), l, M(l, r));
    ll vr = query_sub(a, b, RC(k), M(l, r), r);
    return max(vl, vr);
  }
}

ll query(int a, int b) {
  return query_sub(a, b, 0, 0, sz);
}

