template<class V, int NV> struct SegTree {
	V comp(V& l, V& r) { return max(l, r); }

	vector<V> val;
	SegTree() {
		val = vector<V>(NV * 2, 0);
	}
	V get(int x, int y, int l = 0, int r = NV, int k = 1) {
		if (r <= x || y <= l) {
			return 0;
		}
		if (x <= l && r <= y) {
			return val[k];
		}
		auto a = get(x, y, l, (l + r) / 2, k * 2);
		auto b = get(x, y, (l + r) / 2, r, k * 2 + 1);
		return comp(a, b); 
	}

	void update(int i, V v) {
		i += NV;
		val[i] = v;
		while (i > 1) {
			i >>= 1;
			val[i] = comp(val[i * 2], val[i * 2 + 1]);
		}
	}
	void add(int i, V v) {
		update(i, val[i + NV] + v);
	}
	V operator[](int x) {
		return get(x, x + 1);
	}
};

