template<typename T> class SegmentTree
{
 public:
    using Func=function<T(T,T)>;
    int sz;
    vector<T> data;
    Func func;
    T e;

    SegmentTree(int n,Func func,T e):func(func),e(e){
        sz=1;
        while(sz<n) sz*=2;
        data.assign(2*sz-1,e);
    }
    void update(int k,T x){
        k+=sz-1; data[k]=x;
        while(k>0){
            k=(k-1)/2;
            data[k]=func(data[2*k+1],data[2*k+2]);
        }
    }
    T get(int l,int r){
        // [l,r)
        T resL=e,resR=e;
        for(l+=sz-1,r+=sz-1;l<r;l/=2,r/=2){
            if((l&1)==0) resL=func(resL,data[l]);
            if((r&1)==0) resR=func(resR,data[--r]);
        }
        return func(resL,resR);
    }
    T operator[](int k){ return data[k+sz-1]; }
};

