typedef long long ll;
typedef vector<ll> vll;
class ST {
	private:
		vll st;
		int n;
		int lf(int n) {return n<<1;}
		int rt(int n) {return 1+(n<<1);}
		void up(int p, int L, int R, int i, ll v) {
			if(L > i || R < i) {return;}
			if(L == R) {st[p] += v;return;}
			int M = (L+R)/2;
			up(lf(p),L,M,i,v);
			up(rt(p),M+1,R,i,v);
			st[p] = max(st[lf(p)],st[rt(p)]);
		}
		ll rq(int p, int L, int R, int i, int j) {
			if(L > j || R < i) {return 0;}
			if(L >= i && R <= j) {return st[p];}
			int M = (L+R)/2;
			ll sa = rq(lf(p),L,M,i,j);
			ll sb = rq(rt(p),M+1,R,i,j);
			//printf("%lld %d %d\n",sa,L,M);
			//printf("%lld %d %d\n",sb,M+1,R);
			return max(sa,sb);
		}
	public:
		ST(int sz) {
			n = sz;
			st.assign(4*n,0);
		}
		void up(int i, ll v) {
			up(1,0,n-1,i,v);
		}
		ll rq(int i, int j) {return rq(1,0,n-1,i,j);}

};
