		for(ll i = 0; i < 4*n; i++)	tree[i] = queryBase;
		build(1, 0, n-1, arr);
	}
	T build(ll i, ll l, ll r, T *arr){
		if(l == r)	return tree[i] = arr[l];
		return tree[i] = segOp(build(i<<1, l, (l+r)>>1, arr), build(i<<1|1, ((l+r)>>1)+1, r, arr));
	}
	T update(ll i, const T &value, ll p = 1, ll l = 0, ll r = -1){
		if(r == -1)	r = n-1;
		if(l == r)	return tree[p] = value;
		ll m = (l+r)>>1;
		if(i <= m)	update(i, value, p<<1, l, m);	else update(i, value, p<<1|1, m+1, r);
		return tree[p] = segOp(tree[p<<1], tree[p<<1|1]);
	}
	T query(ll l, ll r, ll p = 1, ll tl = 0, ll tr = -1){
		if(tr == -1)	tr = n-1;
		if(l > r)	return queryBase;	// Overflow
		if(l == tl && r == tr)	return tree[p];	// Complete overlap
		ll m = (tl+tr)>>1;
		return segOp(query(l, min(m, r), p<<1, tl, m), query(max(l, m+1), r, p<<1|1, m+1, tr));
	}
};
template <typename T> T SegTree<T>::segOp(const T &left, const T &right){
	return max(left, right);
}

