void update(int l , int r , int pos , int index , long long val)
{
	if(l > r) return;
	else if(l == r)
	{
		tree[pos] = val;
		return ;
	}
	int mid = l + (r - l)/2;
	if(index <= mid) update(l , mid , 2*pos+1 , index , val);
	else update(mid + 1 , r , 2*pos+2 , index , val);
	tree[pos] = max(tree[2*pos+1] , tree[2*pos+2]);
	// cerr <<l << " "<< r << " "<< pos << " "<< tree[pos] << endl;
	return ;
}
long long query(int ql , int qr , int l , int r , int pos)
{
	if(l > r || qr < l || ql > r) return 0;
	else if (ql <= l && qr >= r) return tree[pos];
	int mid = l + (r - l)/2;
	return max(query(ql , qr , l , mid , 2*pos+1) , query(ql , qr, mid + 1 , r , 2*pos+2));
}

