template<class T>
class SegmentTreeMax{
    int n = 0;
    std::vector<T> dat;
public:
    SegmentTreeMax(){}
    SegmentTreeMax(int m, T fill = -INF){
        int i = 1;
        while(i < m) i *= 2;
        n = i;
        dat.resize(2*i - 1);
        for(int j(0), j_len(2*i-1); j < j_len; ++j)
            dat[j] = fill;
    }

    void update(int k, T a){
        k += n - 1;
        int moto = dat[k];
        dat[k] = a;
        while(k){
            k = (k - 1) / 2;
            dat[k] = std::max(dat[2*k+1], dat[2*k+2]);
        }
    }

    T getMax(int a, int b, int k=0, int l=0, int r=-1){
        //[a, b[であることに注意
        if(r < 0) r = n;
        if(r <= a || b <= l) return -INF;
        if(a <= l && r <= b) return dat[k];

        T vl(getMax(a, b, 2*k+1, l, (l+r)/2));
        T vr(getMax(a, b, 2*k+2, (l+r)/2, r));
        return std::max(vl, vr);
    }

    T getvalue(int k){
        return dat[k+n-1];
    }
};


