template <typename T>
struct sqrt_max : vector<T> {
    vector<T> buckets, data;
    const int ext_sq;
    sqrt_max(int n, int ext_sq = 500) : 
        ext_sq(ext_sq),
        data(n, 0),
        buckets(n / ext_sq + 1, 0) {}

    void insert(int pos, T val) {
        data[pos] = max(data[pos], val);
        int bucket_id = pos / ext_sq;
        buckets[bucket_id] = max(buckets[bucket_id], val);
    }

    T best(int pos) {
        T result = 0;
        int i = 0;
        for(int i = 0; (i + 1) * ext_sq <= pos ; i++)
            result = max(result, buckets[i]);
        int j = i * ext_sq;
        for(; j <= pos; j++)
            result = max(result, data[j]);
        return result;
    }
};

