ll n, dp[100001], st[500000];

ll find(ll i, ll l, ll r, ll ql, ll qr) {
    if (ql > r || qr < l) return 0;

    if (l >= ql && r <= qr) {
        return st[i];
    }

    return max(find(2 * i, l, (l + r) / 2, ql, qr), find(2 * i + 1, (l + r) / 2 + 1, r, ql, qr));
}

void update(ll i, ll l, ll r, ll qi, ll val) {
    if (qi < l || qi > r) {
        return;
    }

    if (l == r && l == qi) {
        st[i] = val;
        return;
    }

    update(2 * i, l, (l + r) / 2, qi, val);
    update(2 * i + 1, (l + r) / 2 + 1, r, qi, val);

    st[i] = max(st[2 * i], st[2 * i + 1]);
}

