template<class T>
struct segment_tree {
    int n;
    vector<T> dat;
    segment_tree(int n_) {init(n_);}

    void init(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat.resize(2*n-1);
        rep(i,2*n-1) dat[i] = 0;
    }

    //kをaに変更
    void update(int k, T a) {
        k += n-1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = max(dat[k*2+1],dat[k*2+2]);
        }
    }

    //[a,b)のquery,kは節点番号
    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return 0;
        if (a <= l && r <= b) return dat[k];
        else {
            T vl = query(a,b,k*2+1,l,(l+r)/2);
            T vr = query(a,b,2*k+2,(l+r)/2,r);
            return max(vl,vr);
        }
    }

    T get(int a) {
        a += n-1;
        return dat[a];
    }

    void debug(int a, int b) {
        a += n-1; b += n-1;
        for (int i = a; i <= b; i++) {
            cout << dat[i] << " ";
        }
        cout << endl;
    }
};

int main() {
    int n; cin >> n;
    vint h(n), a(n);
    rep(i,n) cin >> h[i];
    rep(i,n) cin >> a[i];
    segment_tree<ll> seg(n+1);
    rep(i,n) {
        ll value = seg.query(0,h[i],0,0,16);
        if (seg.get(h[i]) < value+a[i]) seg.update(h[i],value+a[i]);
    }
    cout << seg.query(0,n+1) << endl;
}

