struct flower{
    int hi;
    int bty;
};

ll solve(vector<flower>& v,int n){
    vi dp(n+1);
    dp[0] = 0;
    dp[1] = v[1].bty;
    map<ll,ll> indices;
    indices[v[1].hi] = dp[1];
    ll ans = dp[1];
    loop(i,2,n+1){
        dp[i] = v[i].bty;
        auto it = indices.lower_bound(v[i].hi + 1);
        if(it != indices.begin()){
            it--;
            dp[i] += it->second ;
        }
        indices[v[i].hi] = dp[i] ;
        auto it2 = indices.upper_bound(v[i].hi);
        while(it2 != indices.end() && it2->second <= dp[i]){
            auto temp = it2;
            temp++;
            indices.erase(it2);
            it2 = temp;
        }
        ans = max(ans,dp[i]);
    }
    return ans;
}

void solution(){
