template<class node>
struct SegT{
#define mid ((l+r)>>1)
	int n;
	node *t;
	SegT(int n):n(n){t=new node[4*n+10];}
	inline node combine(node a,node b){
		return max(a,b);
	}
	void build(int id,int l,int r){
		if(l==r){
			t[id]=0;
			return;
		}
		build(id<<1,l,mid);
		build(id<<1|1,mid+1,r);
		t[id]=combine(t[id<<1],t[id<<1|1]);
	}
	void update(int id,int l,int r,int pos,lli val){
		if(pos<l||pos>r)return;
		if(l==r){
			remax(t[id],val);return;
		}
		update(id<<1,l,mid,pos,val);
		update(id<<1|1,mid+1,r,pos,val);
		t[id]=combine(t[id<<1],t[id<<1|1]);
	}	
	node query(int id,int l,int r,int lq,int rq){
		if(l>r||lq>r||l>rq)return node(0);
		if(lq<=l&&r<=rq)return t[id];
		return combine(query(id<<1,l,mid,lq,rq),query(id<<1|1,mid+1,r,lq,rq));
	}
#undef mid
};


