/*

	Segment Tree
		- utilizada para consultar e atualizar valores em llervalos de v[0..n).
		- operações: 
			- build - O(n lg n).
			- search - O(lg n) - consulta o valor mínimo contido no llervalo [0..n-1].
			- add - O(lg n) - atualiza o valor de v(i).

			- soma (nulo = 0), mínimo (nulo = inf), etc.

*/

void build_segment_tree(vector<ll> & v, vector<ll> & st, ll nulo) {
	ll n = v.size();
	ll k = 1;

	while (pow(2, k) < n) k++;
	ll ns = pow(2,k);
	st.resize(2*ns);

	for(ll i=ns; i<2*ns; i++) {
		if (i - ns < n) st[i] = v[i-ns];
		else st[i] = nulo;
	}

	ll start = ns;
	ll delta = 2*ns;
	for(ll pot=k; pot>=0; pot--) {
		ll sz = pow(2,pot);
		for(ll i=start; i<delta; i+=2) {
			st[i/2] = max(st[i], st[i+1]);
		}
		delta = start;
		start /= 2;
	}

}

ll search(ll i, ll j, vector<ll> & st) {
	ll n = st.size() / 2;
	i += n;
	j += n;
	bool i_last = false;
	bool j_last = false;
	ll t = 0;
	while (i <= j) {
		if (!i_last and (i % 2 == 1 or j_last)) {
			t = max(t, st[i]);
			i++;
		}
		if (!j_last and (j % 2 == 0 or i_last)) {
			t = max(t, st[j]);
			j--;
		}
		if (!i_last and i % 2 == 1) {
			i_last = true;
		}
		if (!j_last and j % 2 == 0) {
			j_last = true;
		}
		i = i / 2;
		j = j / 2;
	}
	return t;
}

void add(ll x, ll i, vector<ll> & st) {
	ll n = st.size() / 2;
	i += n;
	st[i] += x;
	ll t = st[i];
	while (i >= 1) {
		st[i] = max(st[i], t);
		i /= 2;
	}
}

void show(vector<ll> & st) {
	cout << st.size() << ": ";
	for(ll i=0; i<st.size(); i++) {
		cout << st[i] << " ";
	}
	cout << endl;
}

int main() {

	ll n;
	cin >> n;
	vector<ll> h(n), a(n), dp(n+1, 0); 
	vector<ll> st;
	build_segment_tree(dp, st, 0);

	for(ll i=0; i<n; i++) {
	 cin >> h[i];
	}
	for(ll i=0; i<n; i++) {
	 cin >> a[i];
	}

	for(ll i=0; i<n; i++) {
		dp[h[i]] = max(dp[h[i]], search(0, h[i]-1, st) + a[i]);
		add(dp[h[i]], h[i], st);
	}

	ll ans = 0;
	for(ll i=0; i<=n; i++) {
		ans = max(ans, dp[i]);
	}
	cout << ans << endl;
}

