vector<vector<size_t>> dp;

size_t solution(int i, int prev)
{ 
  if (i == N) return 0;
  if (i == N-1) return a[i];
  size_t ans = 0;
  for (int j = i+1; j < N; ++j)
  { 
    if  (h[j] < prev)
    { 
      continue;
    }
    else if (h[j] > h[i])
    { 
      if (dp[j][h[j]] == 0)
      { 
        dp[j][h[j]] = solution(j, h[j]);
      }
      ans = max(a[i] + dp[j][h[j]], ans);
    }  
    else
    { 
      if (dp[j][prev] == 0)
      {
        dp[j][prev] = solution(j, prev);
      }
      ans = max(dp[j][prev], ans);
    }
  }
  return ans;
}

