inline void pushUp(int k){
	t[k].val = max(t[k<<1].val, t[k<<1|1].val);
}
void build(int l, int r, int k)
{
	t[k].l = l; t[k].r = r; t[k].val = 0;
	if(l == r) return ;
	int mid = l+r>>1;
	build(l, mid, k<<1);
	build(mid+1, r, k<<1|1);
	pushUp(k);
}
void update(int x, ll v, int k)
{
	if(t[k].l == x && t[k].r == x){
		t[k].val = max(t[k].val, v);
		return ;
	}
	int mid = t[k].l+t[k].r>>1;
	if(x <= mid) update(x, v, k<<1);
	else update(x, v, k<<1|1);
	pushUp(k);
}
ll query(int x, int y, int k)
{
	if(t[k].l >= x && t[k].r <= y) return t[k].val;
	int mid = t[k].l+t[k].r>>1;
	ll res = 0;
	if(x <= mid) res = max(res, query(x, y, k<<1));
	if(y >= mid+1) res = max(res, query(x, y, k<<1|1));
	return res;
}

