void update(int pos,long int diff,int ind,int l,int r)
{
	if(l == r)
	{
		seg[pos] = diff;
		return;
	}
	int mid = l + (r-l)/2;
	if(ind <= mid && ind >= l)
	update(2*pos+1,diff,ind,l,mid);
	else
	update(2*pos+2,diff,ind,mid+1,r);
	seg[pos] = max(seg[2*pos+1],seg[2*pos+2]);
	return;

}
long int query(int pos,int l,int r,int start,int end)
{	
	if(l >= start && r <= end)
	return seg[pos];
	if(l > end || r < start)
	return 0;
	int mid = l + (r-l)/2;
	return max(query(2*pos+1,l,mid,start,end),query(2*pos+2,mid + 1,r,start,end));
}

