ll extended_gcd(ll a, ll b, ll &x, ll &y) {
	if(a==0) {
		x = 0;
		y = 1;
		return b;
	}

	ll x1,y1;
	ll gcd = extended_gcd(b%a,a,x1,y1);

	x = y1 - (b/a)*x1;
	y = x1;

	return gcd;
}

ll solve(vector<vector<ll>> &dp, vector<vector<ll>> &adj, ll idx, ll mask) {

	ll n = adj.size();
	if(mask==0)
		return 1;

	if(dp[idx][mask]!=-1)
		return dp[idx][mask];

	ll res = 0;

	for(ll i=0;i<n;i++) {
		if((mask & (1<<i)) != 0 && adj[idx][i]) {
			res = (res + solve(dp,adj,idx-1,mask^(1<<i)))%N;
		}
	}

	dp[idx][mask] = (res+N)%N;
	return dp[idx][mask];
}

