void update(ll index,ll low,ll high,ll x,ll val){
	if(low == high){
		seg[index] = val;
		return ;
	}
	ll mid = (low+high)/2;
	if(x <= mid)
		update(2*index+1,low,mid,x,val);
	else
		update(2*index+2,mid+1,high,x,val);
	seg[index] = max(seg[2*index+1],seg[2*index+2]);

}
ll query(ll index, ll low,ll high,ll l, ll r){
	if(r<low or l>high)
		return 0;
	if(l<=low and r>=high)
		return seg[index];
	ll mid = (low+high)/2;
	ll p1=query(2*index+1,low,mid,l,r);
	ll p2=query(2*index+2,mid+1,high,l,r);
	return max(p1,p2);
}
