long long query(int index,int lb,int rb,int lq,int rq)
{
	if((lb==lq&&rb==rq)||lb==rb)
		return t[index];
	int mid=(lb+rb)/2;
	long long maxn=0;
	if(rq<=mid)
		maxn=max(maxn,query(index*2,lb,mid,lq,mid));
	else if(lq>mid)
		maxn=max(maxn,query(index*2+1,mid+1,rb,mid+1,rq));
	else
	{
		maxn=max(maxn,query(index*2,lb,mid,lq,mid));
		maxn=max(maxn,query(index*2+1,mid+1,rb,mid+1,rq));
	}
	return maxn;
}
void update(int index,int lb,int rb,int id,long long value)
{
	if(lb==rb&&index==id)
		t[index]=max(t[index],value);
	int mid=(lb+rb)/2;
	if(id<=mid)
	{
		update(index*2,lb,mid,id,value);
		t[index]=max(t[index],t[index*2]);
	}
	else
	{
		update(index*2+1,mid+1,rb,id,value);
		t[index]=max(t[index],t[index*2+1]);
	}
}
