typedef long long LL;
const int MAX_N = 1<<17;
//セグメント木を持つグローバル配列
LL n,dat[2*MAX_N-1];
//初期化
void init(int n_){
   //簡単のために要素数を2のべき乗に
   n=1;
   while(n<n_)n*=2;
   //全ての値をINT_MAXに
   for(int i=0;i<2*n-1;i++)dat[i]=1e12;
}

//k番目の値(0-index)をaに変更
void update(int k,LL a){
   //葉の節点
   k+=n-1;
   dat[k]=a;
   //登りながら更新
   while(k>0){
      k=(k-1)/2;
      dat[k]=min(dat[k*2+1],dat[k*2+2]);
   }
}

//[a,b]の最小値を求める
//後ろの方の引数は計算の簡単のための引数
//kは節点番号，l.rはその節点が[l,r]に対応づいていることを表す
//従って外からはquery(a,b,0,0,n-1)として呼ぶ
LL query(int a,int b,LL k,int l,int r){
    //[a,b]と[l,r]が交差しなければINT_MAX
    if(r<a||b<l)return 1e12;
    //[a,b]が[l,r]を完全に含んでいればこの節点の値
    if(a<=l&&r<=b)return dat[k];
    else{
       //そうでなければ2つの子の最小値
       LL vl=query(a,b,k*2+1,l,(l+r)/2);
       LL vr=query(a,b,k*2+2,(l+r)/2+1,r);
       return min(vl,vr);
    }
}

