template<class Monoid> 
class SegmentTree {
private:
  using Func = function<Monoid(Monoid, Monoid)>;
  const Func f;
  const Monoid unity;
  int siz;
  vector<Monoid> dat;

public:
  SegmentTree(int _n, const Func _f, const Monoid &_unity) : f(_f), unity(_unity) { init(_n);}
  void init(int _n) {
    siz = 1;
    while (siz < _n) siz <<= 1;
    dat.assign(siz * 2, unity);
  }

  void set(int idx, const Monoid &val) { dat[siz + idx] = val;}

  void build() {
    for (int idx = siz - 1; idx > 0; idx--) {
      dat[idx] = f(dat[idx * 2], dat[idx * 2 + 1]);
    }
  }

  void update(int idx, const Monoid &val) {
    idx += siz;
    dat[idx] = val;
    while (idx >>= 1) {
      dat[idx] = f(dat[idx * 2], dat[idx * 2 + 1]);
    }
  }

  Monoid get(int left, int right) {
    Monoid val_left = unity, val_right = unity;
    for (int l = left + siz, r = right + siz; l < r; l >>= 1, r >>= 1) {
      if (l & 1) val_left = f(val_left, dat[l++]);
      if (r & 1) val_right = f(val_right, dat[--r]);
    }
    return f(val_left, val_right);
  }

  inline Monoid operator[] (int idx) {return dat[idx + siz];}

  void print() {
    for (int i = 0; i < siz; i++) {
      cout << (*this)[i];
      if (i != siz - 1) cout << ", ";
    }
    cout << endl;
  }
};

