class FenwickTree
{
    long long A[NMAX];

private:
    static inline int UB (int X)
    {
        return (X & (-X));
    }

public:
    inline void Update (int pos, long long val)
    {
        for(int i = pos; i <= N; i += UB(i))
            A[i] = max(A[i], val);

        return;
    }

    inline long long Query (int pos)
    {
        long long r = 0;

        for(int i = pos; i >= 1; i -= UB(i))
            r = max(r, A[i]);

        return r;
    }
} A;

