#include <functional>
template <typename T>
struct SegTree{
  int n;
  vector<T> node;
  T maxval;
  function<T(T,T)> fn;

public:
  SegTree(const vector<T> &v, T maxval0, function<T(T,T)> fn0){
    n=1;
    while((1<<(n-1))<v.size()) n++;
    maxval=maxval0;
    fn=fn0;
    node.resize((1<<n)-1,maxval);
    for(int i=0;i<v.size();i++){
      node[(1<<(n-1))-1+i]=v[i];
    }
    for(int i=(1<<(n-1))-2;0<=i;i--){
      node[i]=fn(node[2*i+1], node[2*i+2]);
    }
  }

  T query(int a, int b){
    int l=(1<<(n-1))-1+a;
    int r=(1<<(n-1))-1+b;

    int m=0; 
    T ans=maxval;
    while(true){
      if(r<=(l+1)*(1<<m)-1){
        break;
      }else if(((l&1)==0) && ((l+2)*(1<<m)-1<=r)){
        ans=fn(ans,node[l]);
        ++l;
      }else if((l+3)*(1<<m)-1<=r){
        l/=2; ++m;
      }else if((l+2)*(1<<m)-1<=r){
        ans=fn(ans,node[l]);
        ++l;
      }else{
        l=l*2+1; --m;
      }
    }
    return ans;
  }

  T get(int p){
    return node[(1<<(n-1))-1+p];
  }

  int update(int p, T val){
    int cur=(1<<(n-1))-1+p;
    node[cur]=val;
    for(int i=0;i<n-1;i++){
      cur=(cur-1)/2;
      node[cur]=fn(node[2*cur+1],node[2*cur+2]);
    }
    return 0;
  }

};

int main(){
  int N;
  cin >> N;
  vector<ll> r(N,0);
  SegTree<ll> st(r,0,[](ll l, ll r){return max(l,r);});
  vector<int> h(N);

  for(int i=0;i<N;i++){
    cin >> h[i]; h[i]--;
  }

