        if (l <= start and end <= r) return Seg[node];
        int mid = (start + end) / 2;
        ll p1 = query(2 * node, start, mid, l, r);
        ll p2 = query(2 * node + 1, mid + 1, end, l, r);

        return max(p1 , p2);
    }

