void update_beauty(int now, int lo, int hi, int idx, ll val) {
    if(lo == hi) {
        dp[lo] = max(dp[lo], val);
        node[now] = max(node[now], val);
        return;
    }

    int mid = (lo + hi) / 2;

    if(idx <= mid) update_beauty(now*2, lo, mid, idx, val);
    else update_beauty(now*2+1, mid+1, hi, idx, val);

    node[now] = max(node[now*2], node[now*2+1]);
}

ll find_mx_beauty(int now, int lo, int hi, int l, int r) {
    if(l > r) return 0;
    if(lo == l && hi == r) return node[now];

    int mid = (lo + hi) / 2;
    if(r <= mid) return find_mx_beauty(now*2, lo, mid, l, r);
    else if(l > mid) return find_mx_beauty(now*2+1, mid+1, hi, l, r);
    else{
        return max(find_mx_beauty(now*2, lo, mid, l, mid), find_mx_beauty(now*2+1, mid+1, hi, mid+1, r));
    }
}

