ll tree[4 * N];

void upd(int in, int l, int r, int idx, ll v){
  if(l == r){
    tree[in] = v;
    return;
  }
  if(l > idx || r < idx)
    return;
  int m = (l + r) / 2;
  upd(2 * in, l, m, idx, v);
  upd(2 * in + 1, m + 1, r, idx, v);
  tree[in] = max(tree[2 * in], tree[2 * in + 1]);
}

ll get(int in, int l, int r, int s, int e){
  if(l > e || r < s)
    return 0;
  if(l >= s && r <= e)
    return tree[in];
  int m = (l + r) / 2;
  return max(get(2 * in, l, m, s, e),
             get(2 * in + 1, m + 1, r, s, e));
}
