struct RangeMaximumQuery
{
    using type = ll;
    static type id() { return 0; }
    static type op(const type &l, const type &r) { return max(l, r); }
};

// segment tree
template <typename M>
class segment_tree
{
    using T = typename M::type;
    const int n;
    vector<T> data;
    int size(int n)
    {
        int res;
        for (res = 1; res < n; res <<= 1)
            ;
        return res;
    }

  public:
    segment_tree(int n_) : n(size(n_)), data(n * 2, M::id()) {}
    segment_tree(int n_, T val) : n(size(n_)), data(n * 2, val) {}
    void init(const vector<T> &data_)
    {
        for (int i = 0; i < (int)data_.size(); i++)
            data[i + n] = data_[i];
        for (int i = n - 1; i >= 0; i--)
            data[i] = M::op(data[i * 2], data[i * 2 + 1]);
    }
    void update(int p, T val)
    {
        p += n;
        data[p] = val;
        while (p >>= 1)
            data[p] = M::op(data[p * 2], data[p * 2 + 1]);
    }
    void add(int p, T val)
    {
        p += n;
        data[p] += val;
        while (p >>= 1)
            data[p] = M::op(data[p * 2], data[p * 2 + 1]);
    }
    T find(int l, int r)
    {
        l += n;
        r += n + 1;
        T res1 = M::id(), res2 = M::id();
        while (l < r)
        {
            if (l & 1)
                res1 = M::op(res1, data[l++]);
            if (r & 1)
                res2 = M::op(data[--r], res2);
            l >>= 1;
            r >>= 1;
        }
        return M::op(res1, res2);
    }
};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N;
    cin >> N;
    segment_tree<RangeMaximumQuery> dp(N + 1);
    ll res = 0;
    vector<ll> h(N), a(N);
    for(int i=0;i<N;i++) cin>>h[i];
    for(int i=0;i<N;i++) cin>>a[i];
    for (int i = 0; i < N; i++)
    {
        ll ma = dp.find(0, h[i]);
        res = max(res, ma + a[i]);
        dp.add(h[i], ma + a[i]);
    }
    cout << res << endl;
}

