		h = sizeof(int)*8-__builtin_clz(sz);
		n = 1<<h;
		t = vector<ll>(n<<1, 0);
	}
	void change(int l, int r, ll v) {
		for(l+=n,r+=n;l<r;l/=2,r/=2) {
			if(l%2) {t[l] = max(t[l], v); ++l;}
			if(r%2) {--r; t[r] = max(t[r], v);}
		}
	}
	ll query(int x) {
		ll v = 0;
		for(x+=n;x>0;x/=2) {
			v = max(v, t[x]);
		}
		return v;
	}
};

