void update(int id, int l, int r, int pos, ll val) {
  if (l == pos && r == pos) {
    seg[id] = val;
    return;
  }
  int mid = (l + r) >> 1;
  if (pos <= mid) update(id * 2, l, mid, pos, val);
  else update(id * 2 + 1, mid + 1, r, pos, val);
  seg[id] = max(seg[id*2], seg[id*2+1]);
}
