vll lazy(4*MAXN),tree(4*MAXN);
vll s(4*MAXN),e(4*MAXN),arr(MAXN+1,0);

ll calculate(int node){
	return max(tree[node],lazy[node]);
}

void lazyPropagation(int node){
	amax(lazy[2*node],lazy[node]);
	amax(lazy[2*node+1],lazy[node]);
    lazy[node] = 0;
}

void build(int node,int l,int r){
	s[node]=l;
	e[node]=r;
	if(l==r){
		tree[node]=0;
		return;
	}
	int mid=(l+r)/2;
	build(2*node,l,mid);
	build(2*node+1,mid+1,r);
	tree[node]=max(tree[2*node],tree[2*node+1]);
	return;
}

void update(int node,int l,int r,ll x){
	if(s[node]>r || e[node]<l)
	return;
	if(l<=s[node] && e[node]<=r){
		amax(lazy[node],x);
		return;
	}
	lazyPropagation(node);
	update(2*node,l,r,x);
	update(2*node+1,l,r,x);
	tree[node]=max(calculate(2*node),calculate(2*node+1));
}

ll query(int node,int l,int r){
	if(s[node]>r || e[node]<l)
	return 0ll;
	if(l<=s[node] && e[node]<=r){
		return calculate(node);
	}
	lazyPropagation(node);
	ll left=query(2*node,l,r);
	ll right=query(2*node+1,l,r);
	tree[node]=max(calculate(2*node),calculate(2*node+1));
	return max(left,right);
}

