using namespace std;

template<class T>
struct SegmentTree {
private:
    int n;
    T def;
    vector<T> node;
public:
    SegmentTree(int sz, T _def) {
        def = _def;
        n = 1;
        while (n < sz) n *= 2;
        node.resize(2 * n - 1, def);
    }
    void update(int x, T val) {
        x += n - 1;
        node[x] = val;
        while (x > 0) {
            x = (x - 1) / 2;
            node[x] = max(node[2 * x + 1], node[2 * x + 2]);
        }
    }
    T getmax(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return def;
        if (a <= l && r <= b) return node[k];
        T vl = getmax(a, b, 2 * k + 1, l, (l + r) / 2);
        T vr = getmax(a, b, 2 * k + 2, (l + r) / 2, r);
        return max(vl, vr);
    }
};

int main() {
    int N; cin >> N;
    vector<int> H(N), A(N);
    for(int i = 0; i < N; ++i) cin >> H[i];
    for(int i = 0; i < N; ++i) cin >> A[i];
    SegmentTree<long long> dp(N + 1, 0);
    for(int i = 0; i < N; ++i) {
        long long a = dp.getmax(0, H[i]) + A[i];
        long long b = dp.getmax(H[i], H[i]);
        dp.update(H[i], max(a, b));
    }
    cout << dp.getmax(0, N + 1) << endl;
    return 0;
}

