void buildtree(ll a[],ll node,ll left,ll right)
{
    if(left==right)
    {
        tree[node]=a[left];
    }
    else
    {
        ll mid=(left+right)/2;
        buildtree(a,2*node+1,left,mid);
        buildtree(a,2*node+2,mid+1,right);
        tree[node]=max(tree[2*node+1],tree[2*node+2]);//this tree is for the sum in the given range query , this line can be modified according to the need for
