void update(int p , int l , int r , int dx , ll val){
    if(l == r){
            st[p] = max(st[p] , val);
            return;
    }

    int mid = l + ((r - l) >> 1);

    if(dx <= mid) update(p << 1     , l       , mid , dx , val);
    else          update(p << 1 | 1 , mid + 1 , r   , dx , val);

    st[p] = max(st[p << 1] , st[p << 1 | 1]);
}

ll query(int p , int l , int r , int S , int E){
    if(l >= S && r <= E) return st[p];
    if(l > E || r < S)   return     0;

    int mid = l + ((r - l) >> 1);

    return max(query(p << 1 , l , mid , S , E) , query(p << 1 | 1 , mid + 1 , r , S , E));
}

