    for(int i = 1 ; i <= n ; i ++) {

            ll curr = a[i] + query(1 , 1 , N-1 , 1 , h[i]);

            ans = max(ans , curr);
            update(1 , 1 , N-1 , h[i] , curr);
    }

    printf("%lld\n" , ans);

}

