void a1(int v, int tl, int tr, int pos, LL add)
{
	if (tl == tr)
		t[v] += add;
	else
	{
		int tm = (tl + tr) >> 1;
		if (pos <= tm)
			a1(v + v, tl, tm, pos, add);
		else
			a1(v + v + 1, tm + 1, tr, pos, add);
		t[v] = max(t[v + v], t[v + v + 1]);
	}
}

LL get(int v, int tl, int tr, int l, int r)
{
	if (l == tl && r == tr)
		return t[v];
	if (l > r || tl > tr)
		return 0;
	int tm = (tl + tr) >> 1;
	return max(get(v + v, tl, tm, l, min(tm, r)), get(v + v + 1, tm + 1, tr, max(tm + 1, l), r));
}

