    vll h(n), a(n);
    REP(i, n) cin >> h[i];
    REP(i, n) cin >> a[i];
    SegmentTree<ll> seg(n+1, 0LL, 
                        [](ll a, ll b){return max(a, b);},
                        [](ll a, ll b){return b;});
    REP(i, n) {
        ll tmp = seg.query(0, h[i]);
        seg.change(h[i], tmp+a[i]);
    }
    cout << seg.query(0, n+1) << '\n';
    return 0;
}

