    int N;
    vector<lli> ft;

    void init(int n){
        N = n;
        ft.assign(n + 1, 0);
    }

    void updateMax(int idx, lli val){
        while(idx <= N)	{
            ft[idx] = max(ft[idx], val);
            idx += idx & -idx;
        }
    }

    lli prefMax(lli idx){
        lli ans = 0;

        while(idx > 0)	{
            ans = max(ans, ft[idx]);
            idx -= idx & -idx;
        }

        return ans;
    }

};



