template <typename T>
struct SegmentTree
{

    T n;
    const ll MIN_N = 0; 

    vector<T> dat;
    vector<T> segAdd;

    T init(T n_)
    {
        n = 1;
        while (n <= n_)//等号を修正
            n *= 2;
        dat.assign(2 * n - 1, MIN_N);
        segAdd.assign(2*n-1,0);
        return n;
    } //このreturnはFindmnの第五引数用

    void add(int a, int b, int x, int k = 0, int l = 0, int r = 200010)
    {
        if (r <= a || b <= l)
            return; //もし交差しない区間であれば終える.

        if (a <= l && r <= b)
        {                   //もし今みている区間[l, r)が[a, b)に完全に内包されていれば
            segAdd[k] += x; //区間[l, r)にkを加算する.
            return;
        }

        add(a, b, x, k * 2 + 1, l, (l + r) / 2); //子の区間に(必要があれば)xを加算する.
        add(a, b, x, k * 2 + 2, (l + r) / 2, r); //〃

        //親の区間の最小値は, 子の区間の最小値 + 自分に一様に加算されている値 である.一様に加算される値は更新しなくて良い.
        dat[k] = max(dat[k * 2 + 1] + segAdd[k * 2 + 1], dat[k * 2 + 2] + segAdd[k * 2 + 2]);
    }

    void update(T k, T a)
    { //k番目(0-indexed)をaに変更
        k += n - 1;
        dat.at(k) = a;

        while (k > 0)
        {
            k = (k - 1) / 2;
            dat.at(k) = max(dat.at(2 * k + 1), dat.at(2 * k + 2));
        }
    }

    //[a,b)の最小値 kはノード番号 [l,r)はkに対応する区間
    //Findmn(a,b,0,0,initの値)で呼ぶ
    T Findmx(T a, T b, T k, T l, T r)
    {
        if (r <= a || b <= l)
            return MIN_N;

        if (a <= l && r <= b)
        {
            return dat.at(k);
        }
        else
        {
            T mnL = Findmx(a, b, (2 * k) + 1, l, (l + r) / 2);
            T mnR = Findmx(a, b, (2 * k) + 2, (l + r) / 2, r);
            return max(mnL, mnR);
        }
    }
};

