void build(ll l, ll r, ll in, vector<ll> &v, vector<ll> &tree) {
    if (l > r) {
        return;
    }
    if (l == r) {
        tree[in] = v[l];
        return;
    }
    ll mid = (l + r) >> 1ll;
    build(l, mid, 2 * in + 1, v, tree);
    build(mid + 1, r, 2 * in + 2, v, tree);
    tree[in] = max(tree[2 * in + 1], tree[2 * in + 2]);
}

ll query(ll l, ll r, ll ql, ll qr, ll in, vector<ll> &tree) {
    if (l > qr || r < ql || l > r) {
        return -INF;
    }
    if (l >= ql && r <= qr) {
        return tree[in];
    }
    ll mid = (l + r) >> 1ll;
    ll left = query(l, mid, ql, qr, 2 * in + 1, tree);
    ll right = query(mid + 1, r, ql, qr, 2 * in + 2, tree);
    ll ans = max(left, right);
    return ans;
}

void update(ll l, ll r, ll index, ll in, vector<ll> &tree, vector<ll> &v) {
    if (l > r) {
        return;
    } else if (index < l || index > r) {
        return;
    } else if (l == r) {
        tree[in] = v[index];
        return;
    }
    ll mid = (l + r) >> 1;
    update(l, mid, index, 2 * in + 1, tree, v);
    update(mid + 1, r, index, 2 * in + 2, tree, v);
    tree[in] = max(tree[2 * in + 1], tree[2 * in + 2]);
}

