ll stmax(int ti, int l, int r, int ql, int qr) {
    if (l >= ql && r <= qr) {
        return st[ti];
    } else if (l > qr || r < ql) {
        return 0;
    } else {
        return max(stmax(ti * 2, l, (l + r) / 2, ql, qr),
                   stmax(ti * 2 + 1, (l + r) / 2 + 1, r, ql, qr));
