void stup(int ti, int l, int r, int pos, ll val) {
    if (pos < l || pos > r)
        return;
    st[ti] = max(st[ti], val);
    if (l != r) {
        stup(ti * 2, l, (l + r) / 2, pos, val);
        stup(ti * 2 + 1, (l + r) / 2 + 1, r, pos, val);
    }
}

