void build(ll v, ll tl, ll tr)
{
    if(tl == tr)
        t[v] = 0;
    else
    {
        ll tm = (tl+tr)/2;
        build(2*v, tl, tm);
        build(2*v+1, tm+1, tr);
        t[v] = min(t[2*v], t[2*v+1]);
    }
}

ll qu(ll v, ll tl, ll tr, ll l, ll r)
{
    if(l > r) return 0;
    if(l == tl && r == tr) return t[v];

    ll tm = (tl+tr)/2;
    return max(qu(2*v, tl, tm, l, min(tm,r)),
                qu(2*v+1, tm+1, tr, max(l,tm+1), r));
}

void up(ll v, ll tl, ll tr, ll pos, ll val)
{
    if(tl > pos || tr < pos) return;
    if(tl == tr){
        t[v] = val;
        return;
    }

    ll tm = (tl+tr)/2;
    up(2*v, tl, tm, pos, val);
    up(2*v+1, tm+1, tr, pos, val);
    t[v] = max(t[2*v], t[2*v+1]);
}

