long long int* segTree;

long long int max_query(long long int qs, long long int qe, long long int si, long long int ei, long long int index)
{
   if(ei < qs || si > qe) return 0;

   if(si >= qs && ei <= qe)
   {
      return segTree[index];
   }

   long long int mid = (si + ei) >> 1;

   long long int a = max_query(qs, qe, si, mid, (index<<1)+1 );
   long long int b = max_query(qs, qe, mid + 1, ei, (index<<1)+2 );
   return max(a, b);
}

void max_self(long long int& a, long long int b)
{
  a = max(a, b);
}

void update(long long int bui, long long int si, long long int ei, long long int index, long long int val)
{
   if(ei < bui || si > bui) return ;

   if(si == ei)
   {
      max_self(segTree[index], val);
      return;
   }

   long long int mid = (si + ei) >> 1;

   update(bui, si, mid, (index<<1)+1, val );
   update(bui, mid + 1, ei, (index<<1)+2, val );
   segTree[index] = max(segTree[(index<<1)+1], segTree[(index<<1)+2]);
}


