void updatetree(ll* tree,int s,int e,int ind,int i,ll val)
{
    // cout << i << " " << s << " " << e << " " << ind << " " << i << endl;
    if(s==e){
        tree[ind] = max(val,tree[ind]);
        return;
    }

    int mid = s + (e-s)/2;

    if(mid >= i){
        updatetree(tree,s,mid,2*ind,i,val);
    }

    else{
        updatetree(tree,mid+1,e,2*ind+1,i,val);
    }

    tree[ind] = max(tree[2*ind],tree[2*ind+1]);
}

ll query(ll* tree,int s,int e,int x,int y,int ind)
{
    if(x > y) return 0;
    if(x <= s && y >= e) return tree[ind];
    if(s > y || x > e) return 0;
    int mid = s + (e-s)/2;
    ll leftval = query(tree,s,mid,x,y,2*ind);
    ll rightval = query(tree,mid+1,e,x,y,2*ind+1);
    return max(leftval,rightval);
}

