#include <bits/stdc++.h>
using namespace std;
using ll = long long;

class segment_tree
{
	using T = ll;
	static const T id = 0;
	T op(T a, T b) const {
		return max(a, b);
	}

	int expand(int x) {
		int res;
		for (res = 1; res < x; res <<= 1);
		return res;
	}
	const int n;
	vector<T> dat;
public:
	segment_tree(int n_)
		: n(expand(n_)), dat(n + n, id) {}
	void update(int p, T val) {
		dat[p += n] = val;
		while (p >>= 1) dat[p] = op(dat[p << 1], dat[(p << 1) | 1]);
	}
	T find(int l, int r) const {
		T res1 = id, res2 = id;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) res1 = op(res1, dat[l++]);
			if (r & 1) res2 = op(dat[--r], res2);
		}
		return op(res1, res2);
	}
};

int main()
{
	int N;
	cin >> N;
	vector<int> h(N);
	for (int i = 0; i < N; i++) {
		cin >> h[i]; --h[i];
	}
	vector<ll> a(N);
	for (int i = 0; i < N; i++) {
		cin >> a[i];
	}
	segment_tree dp(N);
	for (int i = 0; i < N; i++) {
		dp.update(h[i], dp.find(0, h[i]) + a[i]);
	}
	cout << dp.find(0, N) << endl;
	return 0;
}

