long long int seg[4*N+10000];

void build(int id,int st,int end)
{
	if(st == end)
	{
		seg[id] = 0;
		return ;
	}
	int mid = (st+end)/2;
	build(2*id,st,mid);
	build(2*id+1,mid+1,end);
	seg[id] = 0;
}

void update(int id,int st,int end,int k,long long int val)
{
	if(st == end && st == k)
	{
		seg[id] = max(val,seg[id]);
	}
	else
	{
		int mid = (st+end)/2;
		if(k<=mid)
		{
			update(2*id,st,mid,k,val);
		}
		else
		{

			update(2*id+1,mid+1,end,k,val);
		}
		seg[id] = max(seg[2*id],seg[2*id+1]);
	}
}

long long int query(int id,int st,int end,int l,int r)
{
	if(l > end || r < st)
	{
		return 0;
	}

	if(l <= st && end <= r)
	{
		return seg[id];
	}

	int mid = (st+end)/2;
	long long int lm = query(2*id,st,mid,l,r);
	long long int rm = query(2*id+1,mid+1,end,l,r);
	return max(lm,rm);
}
