func dfs(u, parent int) (int, int) {
	w,b := 1,0 // -> children are white or it is black
	for _, e := range mat[u] {
		if e != parent {
			wc, bc := dfs(e, u)
			tmp := w
			w = mulMOD(bc,w)
			b = (mulMOD(tmp, wc) + mulMOD(b, bc+wc))%MOD
		}
	}
	return w, (w+b)%MOD
}

