void update(vector<ll>& st,int root,int s, int e, int i, ll val){
	int mid = (s+e)/2;
	if( s < e ){
		if (i >= s &&  i <= mid){
			update(st,2*root+1,s,mid,i,val);
		}
		else{
			update(st,2*root+2,mid+1,e,i,val);
		}
		st[root] = max(st[2*root+1],st[2*root+2]);
	}
	else{
		st[root] = val;
	}
}

ll query(vector<ll>& st,int root, int s, int e, int i, int j){//i ,j are query paarmenter, s&ee are tree param
	if(i > e or j < s){ return -INF;}
	if(i == s && j == e){
		return st[root];
	}
	int mid = (s+e)/2;
	if(j <= mid){  //i-j lies on left side
		return query(st,2*root+1,s,mid,i,j);
	}
	else if(s > mid){ //i-j lies on right side
		return query(st,2*root+2,mid+1,e,i,j);
	}
	else{
		return max(query(st,2*root+1,s,mid,i,mid),query(st,2*root+2,mid+1,e,mid+1,j));
	}
}



