template<typename T>
struct SegmentTreeMax{
    int n;

    //represent tree as array
    //parent of k: (k-1)/2,child of k : 2*k+1,2*k+2
    vector<T> node;

    public:
    SegmentTreeMax(vector<T> a){
        int n_ = a.size();
        //round to power of 2
        n=1;
        while(n<n_)n*=2;
        //initialize tree
        node.resize(2*n-1, 0);

        //fill data into tree
        for(int i=0; i<n_; i++)node[n-1+i] = a[i];
        for(int i=n-2;i>=0;i--)node[i]=max(node[2*i+1],node[2*i+2]);

    }
    //return minimum value in[a,b).
    T getmax(int a,int b,int k=0,int l=0,int r=-1){
        if(r<0)r=n;
        if(r<=a||b<=l)return 0;
        if(a<=l&&r<=b)return node[k];
        T vl = getmax(a,b,2*k+1,l,(l+r)/2);
        T vr = getmax(a,b,2*k+2,(l+r)/2,r);
        return max(vl,vr);
    }
    //x番目をvalに更新
    void update(int x, T val){
        //最下段のノードにアクセスする
        x+=(n-1);

        //最下段のノードを更新したら、あとは親に上って更新していく
        node[x]=val;
        while(x > 0){
            x = (x-1)/2;
            node[x] = max(node[2*x+1],node[2*x+2]);
        }

    }

};


