    rep(i, n) { cin >> a_s[i]; }

    seg_tree<mon> dp(n);
    rep(i, n) {
        auto a = dp.query({0, h_s[i]});
        auto b = dp.at(h_s[i]);
        dp.set(h_s[i], mon::op(b, a + a_s[i]));
    }

    cout << dp.query({0, dp.n}) << '\n';

    return 0;
}

