// 0-indexed, 半開
template <typename T> struct BIT {
  private:
    int n;
    vector<T> dat;

  public:
    BIT(int n) : n(n) { dat.assign(n + 1, 0); }
    void update(int k, T a) {
        for(k++; k <= n; k += k & -k)
            chmax(dat[k], a);
    }
    // [0,a)
    T query(int a) {
        T ret = 0;
        for(; a > 0; a -= a & -a)
            chmax(ret, dat[a]);
        return ret;
    }
};

