//segment tree
struct SegTree{
	VL seg;
	int segsize;
	void Revise(int id, LL x){
		seg[id] = x;
		while(id){
			id = (id - 1) / 2;
			seg[id] = max(seg[id * 2 + 1], seg[id * 2 + 2]);
		}
	}
	LL RMaxQ(int l, int r, int nl, int nr, int id){//[i, j)のRMaxQを求める
		if(nl >= r || nr <= l) return 0;//まったくかぶらない
		if(l<=nl&&nr<=r) return seg[id];//完全に入っている
		int mid = (nl + nr) / 2, chi = id * 2 + 1;
		return max(RMaxQ(l, r, nl, mid, chi), RMaxQ(l, r, mid, nr, chi + 1));
	}
	void sizedef(int n){//セグ木の初期化
		segsize = 1;
		while(n > segsize) segsize = (segsize << 1);
		for(int i=0; i< segsize * 2 - 1; i++) seg.push_back(0);
	}
};

