struct segTree {
	int n;
	vector<ll> t;
	segTree(int n) : n(n), t(2 * n, 0) {}
	void upd(int v, ll x) {
		t[v += n] = x;
		for (v >>= 1; v; v >>= 1) {
			t[v] = max(t[v << 1], t[v << 1 | 1]);
		}
	}
	ll get(int l, int r) {
		ll ret = 0;
		for (l += n, r += n; l <= r; l = (l + 1) >> 1, r = (r - 1) >> 1) {
			if (l & 1) {
				ret = max(ret, t[l]);
			}
			if (!(r & 1)) {
				ret = max(ret, t[r]);
			}
		}
		return ret;
	}
};

