struct segtree
{
    int size;
    vector<long long> values;

    void init(int n)
    {
        size = 1;

        while(size<=n)
        {
            size *= 2;
        }

        values.assign(2*size, 0LL);
    }

    void set(int i, ll v, int x, int lx, int rx)
    {
        if(rx-lx ==1)
        {
            values[x] = v;
            return;
        }

        int m = (lx+rx)/2;

        if(i<m)
        {
            set(i, v, 2*x + 1, lx, m);
        }
        else
        {
            set(i, v, 2*x + 2, m, rx);
        }

        values[x] = max(values[2*x +1],  values[2*x + 2]);
    }

    void set(int i, ll v)
    {
        set(i, v, 0, 0, size);
    }

    long long maxi(int l, int r, int x, int lx, int rx)
    {
        if( lx >= r || rx <= l) return 0;
        if( lx >= l && rx <= r) return values[x];

        int m = (lx + rx)/2;

        long long s1 = maxi(l, r, 2*x + 1, lx, m);
        long long s2 = maxi(l, r, 2*x + 2, m, rx);
        return max(s1, s2);
    }

    long long maxi(int l, int r)
    {
        return maxi(l, r, 0, 0, size);
    }

};

