const int INF=1e9;
class BinaryIndexcedTree
{
// 1-indexed
public:
    vector<int> data;
    BinaryIndexcedTree(int N):data(N+1,-INF){}
    void updata(int i,int x){
        for(;i<data.size();i+=i&-i) chmax(data[i],x);
    }
    int query(int i){
        int res=-INF;
        for(;i>0;i-=i&-i) chmax(res,data[i]);
        return res;
    }
};

