typedef long long int ll;
ll seg[700005];
ll query(ll ql,ll qr, ll l, ll r, ll ind){
	if(ql<=l && qr>=r){
		return seg[ind];
	}
	if(l>qr || ql>r){
		return 0;
	}
	ll m=(l+r)/2;
	return max(query(ql,qr,l,m,2*ind+1),query(ql,qr,m+1,r,2*ind+2));
}
ll update(ll ind, ll val, ll l, ll r, ll ti){
	if(ind<l || ind>r){
		return 0;
	}
	if(l==r){
		return seg[ti]=val;
	}
	ll m=(l+r)/2;
	return seg[ti]=max(update(ind,val,l,m,2*ti+1),update(ind,val,m+1,r,2*ti+2));
}
