vector<long long> st;

void update_tree( int pos, long long value, int root, int tleft, int tright) {
  if (pos < tleft || pos > tright || tleft > tright) return;

  if (tleft == tright) {
    st[root] = value;
    return;
  } 

  int mid = (tleft + tright) / 2;

  update_tree(pos, value, root*2, tleft, mid);
  update_tree(pos, value, root*2+1, mid+1, tright);

  st[root] = max(st[root], value);
}

long long query( int qleft, int qright, int root, int tleft, int tright) {
    if (  qleft > qright ) return -1;
    if ( tleft == qleft && tright == qright) return st[root];

    int mid = (tleft + tright)/2;

    return max(
      query(qleft, min(qright, mid), root*2, tleft, mid),
      query(max(mid+1, qleft), qright, root*2+1, mid+1, tright)
    );
}


