void modify(int index,ll value){
	int p=n+index;
	tree[p]=value;
	p/=2;
	while(p>0){
		tree[p]=max(tree[2*p],tree[2*p+1]);
		p/=2;
	}
}

ll query(int l,int r){
	ll res=0;
	l+=n,r+=n;
	while(l<=r){
		if(l%2==1)res=max(res,tree[l++]);
		if(r%2==0)res=max(tree[r--],res);
		l/=2;
		r/=2;
	}
	return res;
}

