ll modexp(ll x, ll ex) {
    ll ans = 1ll;
    while (ex > 0) {
        if (ex & 1ll) ans = (ans * x) % mod;
        ex >>= 1ll;
        x = (x * x) % mod;
    }
    return ans;
}
template <typename T>
class fenwick{
    public:
     vector<T> BIT;
     int N;
     void init(int size){ 
         BIT.resize(size + 1);
         fill(BIT.begin() , BIT.end() , 0);
         N = size + 1;
     }
     void modify(int x , T val){ 
           while(x < N){
               BIT[x] = max(BIT[x] , val);
               x += (x & (-x));
           }
     }
     T get(T x){
          T mx = 0;
          while(x > 0){
              mx = max(mx , BIT[x]);
              x -= (x & (-x));
          }
          return mx;
     }
};
