void update(int node,int start,int end,int index,ll num){
	int mid=(start+end)/2;
	if(start==end){
		tree[node]+=num;
		return ;
	}
	if(start<=index&&index<=mid){
		update(2*node,start,mid,index,num);
	}
	if(index>mid&&index<=end){
		update(2*node+1,mid+1,end,index,num);
	}
	tree[node]=max(tree[2*node],tree[2*node+1]);
}
ll query(int node,int start,int end,int l,int r){
	int mid=(start+end)/2;
	if(start>=l&&end<=r)return tree[node];
	if(start>r||end<l){
		return 0;
	}
	ll L=query(2*node,start,mid,l,r);
	ll R=query(2*node+1,mid+1,end,l,r);
	return max(L,R);
}

