vi h(2*1e5+1), a(2*1e5+1);
struct SegmentTree
{
  int n;
  vector<Node> v;
  SegmentTree(int size)
  {
    n=4*size+1;
    v.resize(n);
  }
  Node combine(Node v1, Node v2){
    Node ans;
    ans.hn=max(v1.hn, v2.hn);
    ans.an=max(v1.an, v2.an);
    return ans;
  }
  void build(int ipos,int fpos,int pos=1)
  {
    if(ipos>fpos)
    return ;
    if(ipos==fpos){
      v[pos].an=a[ipos];
      v[pos].hn=h[ipos];
    }
    else
    {
    int mid=(ipos+fpos)/2;
    build(ipos,mid,pos*2);
    build(mid+1,fpos,pos*2+1);
    v[pos]=combine(v[2*pos], v[2*pos+1]);
    }
  }
  void update(int index,ll val,int ipos,int fpos,int pos=1)
  {
    if(ipos>fpos)
    return ;
    if(ipos==fpos)
    v[pos].an+=val;
    else
    {
      v[pos].an+=val;
      int mid=(ipos+fpos)/2;
      if(mid>=index)
      update(index,val,ipos,mid,pos*2);
      else
      update(index,val,mid+1,fpos,pos*2+1);
      v[pos]=combine(v[2*pos], v[2*pos+1]);
    }
  }
  int get_max(int l,int r,int ipos,int fpos, int hval, int pos=1)
  {
    if(l>fpos or r<ipos or fpos<ipos)return 0;
    if(l<=ipos and r>=fpos and v[pos].hn<hval) return v[pos].an;
    int mid=(ipos+fpos)/2;
    return max(get_max(l, r, ipos, mid, hval, pos*2), get_max(l, r, mid+1, fpos, hval, pos*2+1));
  }
};
