lli get_max(int idx , int lo , int hi , int l , int r)
{

    if(hi<l || lo>r)return 0;

    if(l<=lo && hi<=r)return tree[idx];

    int mid = (lo+hi)/2;

    int x = get_max(idx*2,lo,mid,l,r);
    int y = get_max(idx*2+1,1+mid,hi,l,r);

    return max(x,y);
}

void update(int idx , int lo , int hi ,int pos)
{
    if(hi<pos || lo>pos)return;

    if(lo == hi){
        tree[idx] = dp[pos];
        return ;
    }

    int mid = (lo+hi)/2;

    update(idx*2,lo,mid,pos);
    update(idx*2+1,1+mid,hi,pos);

    tree[idx] = max(tree[idx*2] , tree[idx*2 +1]);
}

