template <typename T>
class ST{
public:
  int n;
  vector <T> seg;
  vector <T> laz;
  ST(int x):n(4*x){
    seg.resize(n);
    build(1,x,1);
  }
  ST(int x,int is_laz):n(4*x){
    seg.resize(n);
    laz.resize(n);
    build(1,x,1);
  }
  void ini(T &tt){
  	tt=0;
    //Initialize the data to return at base cases;
  }
  T make_data(int st){
    T dt;
   	dt=dp[st];
    return dt;
  }
  T combine_data(T le,T ri){
    T par;
    par=max(le,ri);
    return par;
  }
  void build(int st,int en,int pos){
    if(st==en){
      seg[pos]=make_data(st);
      return;
    }
    int mid=(st+en)/2;
    build(st,mid,2*pos);
    build(mid+1,en,2*pos+1);
    seg[pos]=combine_data(seg[2*pos],seg[2*pos+1]);
  }
  void update(int st,int en,int ind,int val,int pos){
    if(st==en)
    {

      seg[pos]=val;
      return;
    }
    int mid=(st+en)/2;
    if(st<=ind && ind<=mid)
    update(st,mid,ind,val,2*pos);
	else
    update(mid+1,en,ind,val,2*pos+1);
    seg[pos]=combine_data(seg[2*pos],seg[2*pos+1]);
  }
  T query(int st,int en,int qst,int qen,int pos){
    if(en<qst || qen<st)
    {
      T dt;
      ini(dt);
      return dt;
    }
    if(qst<=st && en<=qen)
    {
      return seg[pos];
    }
    int mid=(st+en)/2;
    return combine_data( query(st,mid,qst,qen,2*pos) , query(mid+1,en,qst,qen,2*pos+1) );
  }
};
