std::vector<size_t> read_vector(size_t len) {
    std::vector<size_t> result;
    size_t temp = 0;
    for (size_t i = 0; i < len; ++i) {
        std::cin >> temp;
        result.push_back(temp);
    }
    return result;
}

size_t flowers(std::vector<size_t> & heights, std::vector<size_t> & values) {
    std::map<size_t, size_t> best_seqs;

    for (size_t curr_flower = 0; curr_flower < heights.size(); ++curr_flower) {
        size_t current_height = heights[curr_flower];

        auto lb = best_seqs.lower_bound(current_height);

        size_t curr_val;
        if (lb != best_seqs.begin() && best_seqs.size() > 0) {
            --lb;
            curr_val = values[curr_flower] + (*lb).second;
        } else {
            curr_val = values[curr_flower];
        }

//        std::cout << current_height << " h " << (*lb).first << " " << curr_val << std::endl;

        best_seqs[current_height] = curr_val;

        auto ub = best_seqs.upper_bound(current_height);
        std::vector<size_t> keys_to_remove;
        while (ub != best_seqs.end()) { 
            if ((*ub).second <= curr_val) {
                keys_to_remove.push_back((*ub).first);
            } else {
                break;
            }
            ++ub;
        }

        for (size_t k : keys_to_remove) {
            best_seqs.erase(k);
        }
    }

    auto e = best_seqs.end();
    --e;

    return (*e).second;
}

int main(int argc, char** argv) {
    size_t flowers_number = 0;
    std::cin >> flowers_number;    
    std::vector<size_t> heights = read_vector(flowers_number);
    std::vector<size_t> values = read_vector(flowers_number);

    std::cout << flowers(heights, values);
    return 0;
}

