class SegmentTree {
private:
    int n;
    std::vector<long long> node;
    int def;
public:
    SegmentTree(std::vector<int> v, int d) : def(d){
        int sz = v.size();
        n = 1; while(n <= sz) n *= 2;
        node.resize(2*n, def);
        for(int i = 0; i < sz; i++){
            node[i+n] = v[i];
        }
        for(int i = n-1; i > 0; i--){
            node[i] = std::max(node[2*i], node[2*i+1]);
        }
    }
    void update(int i, long long val){
        node[i+n] = val;
        for(int j = (i+n)/2; j > 0; j/=2){
            node[j] = std::max(node[2*j], node[2*j+1]);
        }
    }
    long long getmax(int a, int b, int k = 1, int l = 0, int r = -1){
        if(r < 0) r = n;
        if(b <= l || r <= a) return def;
        if(a <= l && r <= b) return node[k];
        long long vl = getmax(a, b, 2*k, l, (l+r)/2);
        long long vr = getmax(a, b, 2*k+1, (l+r)/2, r);
        return std::max(vl, vr);
    }
};


