void upd(int v, int tl, int tr, int pos, int val){
	if (tl == tr){
		t[v] = val;
		return;
	}
	int tm = (tl + tr) >> 1;
	if (pos <= tm)
		upd(v * 2, tl, tm, pos, val);
	else
		upd(v * 2 + 1, tm + 1, tr, pos, val);
	t[v] = max(t[v * 2], t[v * 2 + 1]);
}

int get(int v, int tl, int tr, int l, int r){
	if (tr < l || r < tl)
		return 0;
	if (tl >= l && tr <= r)
		return t[v];
	int tm = (tl + tr) >> 1;
	int x = get(v * 2, tl, tm, l, r);
	int y = get(v * 2 + 1, tm + 1, tr, l, r);
	return max(x, y);
}

