const int N = 2e5 + 5;

long long segTree[4*N];
long long upd;
int n;

inline void update(int l, int r, int node, int index){
  if(l > r) return ;
  if(index < l || index > r) return ;
  if(l == r && l == index){
    segTree[node] = upd;
    return ;
  }
  int left = node<<1, right = left|1, mid = l+r>>1;
  update(l, mid, left, index);
  update(mid + 1, r, right, index);
  segTree[node] = max(segTree[left], segTree[right]);
}

inline long long query(int l, int r, int node, int lq, int rq){
  if(l > r) return LLONG_MIN;
  if(l > rq || lq > r) return LLONG_MIN;
  if(l >= lq && r <= rq) return segTree[node];
  int left = node<<1, right = left|1, mid = l+r>>1;
  long long lres = query(l, mid, left, lq, rq);
  long long rres = query(mid + 1, r, right, lq, rq);
  return max(lres, rres);
}

