vector<int> heights;
vector<int> values;

long long int choose()
{
    int size = heights.size();
    map<int, int> candidates;

    vector<long long int> records(size);

    for(int interval = 0; interval < size; interval++){

        map<int,int>::iterator it = candidates.lower_bound(heights[interval]);
        if(it != candidates.begin()) 
        {
            it--;
            records[interval] = records[it->second]+values[interval];
            it++;
        }
        else
            records[interval] = values[interval];

        while((it != candidates.end()) && (records[it->second] <= records[interval]))
        {
            it = candidates.erase(it);
        }

        candidates[heights[interval]] = interval; 
    }

    return records[size-1];
}

