vector<ll> dp, bit;

ll count( ll i) {
	i++;
	int s = 0;
	while (i > 0) {
		if (bit[i] > s) {
			s = bit[i];
		}
		i -= i&(-i);
	}
	return s;
}

void update(int n, ll i, ll v) {
	i++;
	while (i < n) {
		if (bit[i] < v) {
			bit[i] = v;
		}
		i += i&(-i);
	}
}


