ll query(int ss,int se,int qs,int qe,int si) {

    if(ss > se || ss > qe || qs > se) return 0;

    if(ss >= qs && qe >= se) {
        return tree[si];
    }

    int mid = ss + (se - ss)/2;

    return max(query(ss,mid,qs,qe,2*si+1),query(mid+1,se,qs,qe,2*si+2));

}

void update(int ss,int se,int id,ll val,int si) {

    if(ss > se) return;

    if(ss == se && ss == id) {
        tree[si] = max(tree[si],val);
        return;
    }

    int mid = ss + (se - ss)/2;
    if(mid >= id) update(ss,mid,id,val,2*si+1);
    else update(mid+1,se,id,val,2*si+2);

    tree[si] = max(tree[2*si+1],tree[2*si+2]);
}

