template <typename T>
struct SegmentTree {
    int n;
    T* t;
    T zero_val;

    inline T operation(T a, T b)
    {
        return max(a, b);
    }
    void setup(int n_, T zero_val_)
    {
        n = n_;
        zero_val = zero_val_;
        t = new T[2*n];
        memset(t, 0, 2*n*sizeof(T));
    }
    void build()
    {
        for (int i = n-1; i > 0; --i) {
            t[i] = operation(t[2*i], t[2*i+1]);
        }
    }
    void update(int p, T v)
    {
        t[p+n] = v;
        for (int i = p+n; i > 1; i /= 2) {
            t[i/2] = operation(t[i], t[i^1]);
        }
    }
    T query(int l, int r)
    {
        T res = zero_val;
        ++r; // make range inclusive
        for (l += n, r += n; l < r; l /= 2, r /= 2) {
            if (l&1) res = operation(res, t[l++]);
            if (r&1) res = operation(res, t[--r]);
        }
        return res;
    }
};

