using namespace std;

const int N = 6e5+5;
int tree[N];

void build(ll node, ll l, ll r)
{
	if(l==r)
	{
		tree[node] = 0;
	}
	else
	{
		ll m = (l+r)/2;
		build(2*node, l, m);
		build(2*node+1, m+1, r);
		tree[node] = max(tree[2*node], tree[2*node+1]);
	}
}

ll query(ll node, ll l, ll r, ll st, ll en)
{
	if(st > en)
		return 0;
	if(r<st||l>en)
		return 0;

	else if(st<=l && r<=en)
		return tree[node];

	else
	{
		ll m = (l+r)/2;
		ll p1 = query(2*node, l, m, st, en);
		ll p2 = query(2*node+1, m+1, r, st, en);
		return max(p1, p2);
	}
}

void update(ll node, ll l, ll r, ll ind, ll x)
{
	if(l==r)
		tree[node] = x;

	else
	{
		ll m = (l+r)/2;
		if(ind<=m)
			update(2*node, l, m, ind, x);
		else
			update(2*node+1, m+1, r, ind, x);
		tree[node] = max(tree[2*node] , tree[2*node+1]);
	}
}


