inline void maintain(int k) { d[k] = std::max(d[k << 1], d[k << 1 | 1]); }

inline void modify(int k, long long v) {
  d[k += M] = v;
  for (k >>= 1; k; k >>= 1) maintain(k);
}

inline long long query(int s, int t) {
  if (s > t) return 0;
  long long ret = 0;
  for (s += M - 1, t += M + 1; s ^ t ^ 1; s >>= 1, t >>= 1) {
    if (~s & 1) ret = std::max(ret, d[s ^ 1]);
    if (t & 1) ret = std::max(ret, d[t ^ 1]);
  }
  return ret;
}

