	BIT(int n_) {
		n = n_;
		bit.resize(n+1, 0);
	}
	void add(int x, T v) {
		for (int i = x+1; i <= n; i += i & -i) {
			chmax(bit[i], v);
		}
	}
	T get(int x) {
		T res = 0;
		for (int i = x+1; i; i -= i & -i) {
			chmax(res, bit[i]);
		}
		return res;
	}
};


