ll tree[4*200003],a[200003],h[200003],dp[200003];

void build(int node,int start,int end){
	if(start == end){
		tree[node] = 0;
	}
	else{
		int m = (start+end)/2;
		build(2*node,start,m);
		build(2*node+1,m+1,end);
		tree[node] = max(tree[node*2],tree[node*2+1]);
	}
}

void update(int node,int start,int end,int idx,ll val){
	if(start == end){
		tree[node] = max(val,tree[node]);
	}
	else{
		int m = (start+end)/2;
		if(idx>=start && idx<=m)
		{
			update(2*node,start,m,idx,val);
		}
		else{
			update(2*node+1,m+1,end,idx,val);
		}
		tree[node] = max(tree[node*2],tree[node*2+1]);
	}
}

ll query(int node,int l,int r,int start,int end){
	if(r<start || l>end){
		return 0;
	}
	if(l<=start && r>=end){
		return tree[node];
	}

	int m = (start+end)/2;
	return max(query(2*node,l,r,start,m),query(2*node+1,l,r,m+1,end));

}
