#define ll long long

long long solve(vector<int> h, vector<int> b) {
	int n = h.size();
	ll ans = b[0];
	map<ll, ll> m;
	m[h[0]] = b[0];

	for (int i = 1; i < n; i++) {
		ll bt = (long long)b[i];
		auto it = m.lower_bound(h[i] + 1);
		if (it != m.begin()) {
			it--;
			bt += it->second;
		}
		m[h[i]] = bt;
		it = m.upper_bound(h[i]);
		while (it != m.end() && it->second < bt) {
			auto temp = it;
			temp++;
			m.erase(it);
			it = temp;
		}
		ans = max(ans, bt);
	}
	return ans;
}

