long long seg[800000];

void update(long long val, int id, int l, int r, int index) {
    if(l > id or r < id) {
        return;
    }

    if(l == r) {
        seg[index] = val;
        return;
    }
    update(val, id, l, (l + r)/2, 2*index);
    update(val, id, (l + r)/2 + 1, r, 2*index + 1);

    seg[index] = max(seg[2*index], seg[2*index + 1]);
}

long long get(int L, int R, int l, int r, int index) {
    if(l > R or r < L) {
        return 0;
    }

    if(l >= L and r <= R) {
        return seg[index];
    }

    int mid = (l + r) /2;
    long long a = get(L, R, l, mid, 2*index);
    long long b = get(L, R, mid + 1, r, 2*index + 1);

    return max(a, b);
}


