void update(int ind,int ss,int se,int pos,ll val){

    if(ss==se){
        tree[ind]=val;
        dp[pos]=val;
        return;
    }
    int mid=getMid(ss,se);
    if(pos<=mid) update(2*ind,ss,mid,pos,val);
    else update(2*ind+1,mid+1,se,pos,val);

    tree[ind]=max(tree[2*ind],tree[2*ind+1]);
}

