	vector<ll> dp(n + 1, 0);
	for (int i = 0; i < n; i++) {
		ll maxW = st.query(0, h[i]);
		dp[h[i]] = maxW + a[i];
		st.update(h[i], dp[h[i]]);
	}

	cout << *max_element(dp.begin(), dp.end()) << '\n';
}

