void bld(node* a1,ll l,ll r){
    a1->l1=l,a1->r1=r;
    if(l==r){
        a1->a=0;
        return;
    }
    a1->lf=nnd(0);
    a1->rt=nnd(0);
    bld(a1->lf,l,(l+r)/2);
    bld(a1->rt,(l+r)/2+1,r);
}
ll sst(node* a1,ll l,ll r){
    if(a1->l1==l&&a1->r1==r)
        return a1->a;
    ll m=(a1->l1+a1->r1)/2;
    if(m>=r)
        return sst(a1->lf,l,r);
    if(m<l)
        return sst(a1->rt,l,r);
    return max(sst(a1->lf,l,m),sst(a1->rt,m+1,r));
}
void upt(node* a1,ll r,ll u){
    if(a1->l1==r&&r==a1->r1){
        a1->a=u;
        return;
    }
    ll m=(a1->l1+a1->r1)/2;
    if(m>=r){
        upt(a1->lf,r,u);
        a1->a=max(a1->lf->a,a1->rt->a);
        return;
    }
    if(m<r){
        upt(a1->rt,r,u);
        a1->a=max(a1->lf->a,a1->rt->a);
        return;
    }
}
