struct node {
    node *l, *r;
    ll mx;
    node() {
        l = r = 0;
        mx = 0;
    }
};

void upd(node *root, int l, int r, int x, ll v) {
    if(l == r) {
        root->mx = max(root->mx, v);
        return;
    }
    int m = (l + r) >> 1;
    if(l <= x && x <= m) {
        upd(root->l, l, m, x, v);
    } else if(m + 1 <= x && x <= r) {
        upd(root->r, m + 1, r, x, v);
    }
    root->mx = max(root->l->mx, root->r->mx);
}

void make(node *root, int l, int r) {
    if(l == r) {
        return;
    }
    int m = (l + r) >> 1;
    root->l = new node();
    root->r = new node();
    make(root->l, l, m);
    make(root->r, m + 1, r);
}

ll get(node *root, int l, int r, int gl, int gr) {
    if(l == gl && r == gr) {
        return root->mx;
    }
    int m = (l + r) >> 1;
    ll ans = 0;
    if(gr >= l && gl <= m) {
        ans = max(ans, get(root->l, l, m, max(l, gl), min(gr, m)));
    }
    if(gr >= m + 1 && gl <= r) {
        ans = max(ans, get(root->r, m + 1, r, max(m + 1, gl), min(gr, r)));
    }
    return ans;
}

