class RMQ{
public:
	ve<int> A,st;int n;

	RMQ(int givenSize){
		n=givenSize;
		A.resize(n);
		st.resize(4*n);
	}

	void update(int x,int val){
		update(x,-val,0,n-1,1);
	}

	void update(int x,int val,int l,int r,int id){
		if(l>x||r<x) return;
		if(l==r){
			st[id]=l;
			A[l]=val;return;
		}
		update(x,val,l,(l+r)/2,id*2);
		update(x,val,(l+r)/2+1,r,id*2+1);
		if(A[st[id*2]] < A[st[id*2+1]])
			st[id]=st[id*2];
		else
			st[id]=st[id*2+1];
	}

	int query(int x,int y){
		return -A[query(x,y,0,n-1,1)];
	}

	int query(int x,int y,int l,int r,int id){
		if(l>y||r<x) return -1;
		if(x<=l && r<=y) return st[id];
		int lind=query(x,y,l,(l+r)/2,id*2);
		int rind=query(x,y,(l+r)/2+1,r,id*2+1);
		if(lind==-1) return rind;
		if(rind==-1) return lind;
		if(A[lind]<A[rind]) return lind;
		else return rind;
	}
};

