ll update(int TAR,ll VAL,int x = 1,int l = 0,int r = N+1)
{
    if( TAR < l || r < TAR )
        return T[x];
    if( l == r )
    {
        if( TAR == l )
            return T[x] = VAL;
        return T[x];
    }
    int mid = l+r>>1;
    int x1 = x<<1, x2 = x<<1 |1;
    ll c1 = update(TAR,VAL,x1,l,mid);
    ll c2 = update(TAR,VAL,x2,mid+1,r);
    return T[x] = max(c1,c2);
}

ll query(int TAR,int x = 1,int l = 0,int r = N+1)
{
    if( l >= TAR )
        return 0;
    if( r < TAR )
        return T[x];
    int mid = l+r>>1;
    int x1 = x<<1, x2 = x<<1 |1;
    ll c1 = query(TAR,x1,l,mid);
    ll c2 = query(TAR,x2,mid+1,r);
    return max(c1,c2);
}

