ll f(ll l, ll nex_h){
    if(l<0) return 0;
    if(dp[l]>0) return dp[l];

    ll res = 0;
    if(h[l]>nex_h){
        res = f(l-1, nex_h);
    }else{
        res = max(f(l-1,nex_h), f(l-1, h[l])+a[l]);
    }
    return dp[l] = res;
}

