ll getMaxBeauty(vector<int> heights, vector<ll> beauties, int n) {
	ll res=0;
	int maxHeight = 2*(int)(1e5);//*max_element(heights.begin(),heights.end());
	vector<vector<ll>> dp(maxHeight+1,vector<ll>(n+1,0));
	for(int i=1;i<=maxHeight;i++) {
		for(int j=1;j<=n;j++) {
			dp[i][j]=max(dp[i-1][j],dp[i][j-1]);
			if(heights[j-1]<=i && heights[j-1]>i-1) {
				dp[i][j]=max(dp[i][j],dp[i-1][j-1]+beauties[j-1]);
			}
			//cout<<dp[i][j]<<" ";
		}
		//cout<<endl;
	}
	res=dp[maxHeight][n];
	return res;
}

