template<typename T>
struct SegmentTree {
    int n;
    std::vector<T> val;

    SegmentTree(int size) {
        for (n = 1; n < size; ) n <<= 1;
        val.assign(2 * n + 1, 0);
    }

    inline T op(const T &v1, const T &v2) const { return v1 <= v2 ? v2 : v1; }

    void update(int idx, T v) {
        idx += n - 1;
        val[idx] = v;
        while (0 < idx) {
            idx = (idx - 1) >> 1;
            val[idx] = op(val[2 * idx + 1], val[2 * idx + 2]);
        }
    }
    T find(int l, int r) {
        T res = 0;
        l += n - 1; r += n - 1;
        while (l < r) {
            if (!(l & 1)) res = op(res, val[l]);
            if (!(r & 1)) res = op(res, val[r - 1]);
            l >>= 1;
            r = (r - 1) >> 1;
        }
        return res;
    }
};

