template<class Monoid>
class SegmentTree {

public:
    /**
     * @param N size
     * @param e identity element
     * @param operation operation to merge `data`
     * @param updater operation to update `data`
     */
    SegmentTree(size_t N, Monoid e, function<Monoid(Monoid, Monoid)> operation,
                function<Monoid(Monoid, Monoid)> updater)
            : e(e), operation(operation), updater(move(updater)) {
        n = 1;
        while (n < N) {
            n *= 2;
        }
        data = vector<Monoid>(2 * n - 1, e);
        for (int i = n - 2; i >= 0; i--) {
            data[i] = operation(data[2 * i + 1], data[2 * i + 2]);
        }
    }

    /**
     * iの値をxに更新 ( 0-indexed )
     */
    void update(int i, Monoid x) {
        i += n - 1;
        data[i] = updater(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    /**
     * [a, b)の区間でクエリを実行
     */
    Monoid query(int a, int b) {
        return query(a, b, 0, 0, n);
    }

    /**
     * 添字でアクセス( 0-indexed )
     */
    Monoid operator[](int i) {
        return data[i + n - 1];
    }

private:
    int n;
    vector<Monoid> data;
    Monoid e;
    function<Monoid(Monoid, Monoid)> operation;
    function<Monoid(Monoid, Monoid)> updater;

    Monoid query(int a, int b, int k, int l, int r) {
        // 交差しない
        if (r <= a || b <= l) return e;
        // 区間 [a, b) に l, r が含まれる
        if (a <= l && r <= b) return data[k];
        // 左の子
        Monoid c1 = query(a, b, 2 * k + 1, l, (l + r) / 2);
        // 右の子
        Monoid c2 = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return operation(c1, c2);
    }
};

void solve() {
    ll N;
    cin >> N;
    vector<ll> H(N), A(N);
    rep(i, N) cin >> H[i];
    rep(i, N) cin >> A[i];
    SegmentTree<ll> segmentTree(N + 1, 0, [](ll a, ll b) {
        return max(a, b);
    }, [](ll a, ll b){
        return a + b;
    });
    rep(i, N) {
        ll h = H[i];
        ll a = A[i];
        ll v = segmentTree.query(0, h);
        segmentTree.update(h, v + a);
    }
    cout << segmentTree.query(0, N + 1)<< '\n';
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);
    solve();
    return 0;
}

#include<bits/stdc++.h>
#define ll long long
#define MAX 200005
using namespace std;

int n;
ll dp[MAX*4];
ll height[MAX];
ll beauty[MAX];

void build(int idx, int left, int right) {
    if (left==right) {dp[idx]=beauty[left]; return;}

    int mid=(left+right)/2;
    build(idx*2,left,mid);
    build(idx*2+1,mid+1,right);
    dp[idx]=max(dp[idx*2],dp[idx*2+1]);
}

void update(int idx, int left, int right, int a, ll val) {
    if (left>a || right<a) {return;}
    if (left==right) {dp[idx]=val; return;}

    int mid=(left+right)/2;
    update(idx*2,left,mid,a,val);
    update(idx*2+1,mid+1,right,a,val);
    dp[idx]=max(dp[idx*2],dp[idx*2+1]);
}

ll query(int idx, int left, int right, int a, int b) {
    if (left>=a && right<=b) {return dp[idx];}
    if (left>b || right<a) {return 0;}

    int mid=(left+right)/2;
    return max(query(idx*2,left,mid,a,b),query(idx*2+1,mid+1,right,a,b));
}

