long long int dp[500005] = {0};
long long int tree[2000005] = {0};
void build(long long int node, long long int start, long long int endi)
{
    if(start == endi)
    {
        // Leaf node will have a single element
        tree[node] = dp[start];
    }
    else
    {
        int mid = (start + endi) / 2;
        // Recurse on the left child
        build(2*node, start, mid);
        // Recurse on the right child
        build(2*node+1, mid+1, endi);
        // Internal node will have the sum of both of its children
        tree[node] = max(tree[2*node] , tree[2*node+1]);
    }
}
void update(long long int node, long long int start, long long int endi, long long int idx, long long int val)
{
    if(start == endi)
    {
        /// Leaf node
        dp[idx] = val;
        tree[node] = val;
    }
    else
    {
        int mid = (start + endi) / 2;
        if(start <= idx and idx <= mid)
        {
            /// If idx is in the left child, recurse on the left child
            update(2*node, start, mid, idx, val);
        }
        else
        {
            /// if idx is in the right child, recurse on the right child
            update(2*node+1, mid+1, endi, idx, val);
        }
        /// Internal node will have the sum of both of its children
        tree[node] = max(tree[2*node], tree[2*node+1]);
    }
}
long long int query(long long int node, long long int start, long long int endi, long long int l, long long int r)
{
    if(r < start or endi < l)
    {
        /// range represented by a node is completely outside the given range
        return 0;
    }
    if(l <= start and endi <= r)
    {
        /// range represented by a node is completely inside the given range
        return tree[node];
    }
    /// range represented by a node is partially inside and partially outside the given range
    long long int mid = (start + endi) / 2;
    long long int p1 = query(2*node, start, mid, l, r);
    long long int p2 = query(2*node+1, mid+1, endi, l, r);
    return max(p1 , p2) ;
}
