template <typename T>
class Max_seg_tree {
    vector<T> seg;
    int n;

    // create
    void create(int node, int l, int r, const vector<T>& v) {
        if (l == r)
            seg[node] = v[l];
        else {
            int mid = (l + r) / 2;
            create(node << 1, l, mid, v);
            create(node << 1 | 1, mid + 1, r, v);
            seg[node] = max(seg[node << 1], seg[node << 1 | 1]);
        }
    }

   public:
    // constructor
    Max_seg_tree(const vector<T>& v) {
        n = (int)v.size();
        seg.resize(4 * n);
        create(1, 0, n - 1, v);
    }

    // update element
    void update(int ind, T val, int node = 1, int l = 0, int r = -1) {
        if (r == -1) r += n;

        if (l == r && l == ind)
            seg[node] = val;
        else if (l <= ind && ind <= r) {
            int mid = (l + r) / 2;
            if (ind <= mid)
                update(ind, val, node << 1, l, mid);
            else
                update(ind, val, node << 1 | 1, mid + 1, r);

            seg[node] = max(seg[node << 1], seg[node << 1 | 1]);
        }
    }

    // range query
    T query(int l, int r, int node = 1, int tl = 0, int tr = -1) {
        if (tr == -1) tr += n;

        if (l == tl && r == tr)
            return seg[node];
        else {
            int mid = (tl + tr) / 2;
            if (r <= mid)
                return query(l, r, node << 1, tl, mid);
            else if (l > mid)
                return query(l, r, node << 1 | 1, mid + 1, tr);
            else
                return max(query(l, mid, node << 1, tl, mid), query(mid + 1, r, node << 1 | 1, mid + 1, tr));
        }
    }
};

