class SegmentTree {
private:
	int num;
	vector<int> dat;

	// TODO: Change the operator and the identity element.
	static const int INI = 0;
	int op(int a, int b) {
		return max(a, b);
	}

public:
	SegmentTree(int n_) {
		num = 1;
		while (num < n_) num *= 2;
		dat = vector<int>(2 * num, INI);
	}

	// Update the k-th value (0-indexed) to a.
	void update(int k, int a) {
		k += num - 1;
		dat[k] = a;
		while (k > 0) {
			k = (k - 1) / 2;
			dat[k] = op(dat[2 * k + 1], dat[2 * k + 2]);
		}
	}

	// Get the value of the range [a, b).
	// k: The index of the node.
	// [left, right): The range corresponds to the k-th node.
	// Call like getval(a, b).
	int getval(int a, int b, int k = 0, int left = 0, int right = -1) {
		if (right < 0) right = num;
		if (right <= a || b <= left) return INI;
		if (a <= left && right <= b) return dat[k];
		int vleft = getval(a, b, 2 * k + 1, left, left + (right - left) / 2);
		int vright = getval(a, b, 2 * k + 2, left + (right - left) / 2, right);
		return op(vleft, vright);
	}
};



