void update(int nd,int s,int e,int idx,int val){
	if(s == e){
		tr[nd] = max(tr[nd], val);
		return;
	}
	int m = (s + e) >> 1;
	if(idx <= m)
		update(nd << 1, s, m, idx, val);
	else
		update(nd << 1 | 1, m + 1, e, idx, val);
	tr[nd] = max(tr[nd << 1], tr[nd << 1 | 1]);
}
int query(int nd,int s,int e,int l,int r){
	if(s > r || e < l) return 0;
	if(l <= s && e <= r) return tr[nd];
	int m = (s + e) >> 1;
	return max(query(nd << 1, s, m, l, r), query(nd << 1 | 1, m + 1, e, l, r));
}
