void solve()
{   
    int n;
    cin>>n;
    vector<int> h(n);
    vector<ll> a(n);
    for(auto &it : h)
        cin>>it;
    for(auto &it : a)
        cin>>it;
    int base=1;
    while(base<=n)
        base*=2;
    stree.resize(2*base,0);
    //cout<<base;
    for(int i=0;i<n;i++){
        //find the max height in [0,h[i])
        int r=h[i]+base;
        ll best=0;
        while(r>0){
            if(r%2)
                best=max(best,(ll)stree[--r]);
            r/=2;
        }
        dp[h[i]]=best+a[i];
        //update segment tree with dp[h[i]];
        r=h[i]+base;
        stree[r]=dp[h[i]];
        r/=2;
        while(r>0){
            stree[r]=max(stree[2*r],stree[2*r+1]);
            r/=2;
        }
    }
    ll ans=0;
    for(int i=0;i<2000001;i++){
        ans=max(ans,dp[i]);
    }
    cout<<ans;
}
