        return seg[pos];
    int mid=(low+high)/2;
    return max(rmq(low,mid,2*pos+1,x,y), rmq(mid+1,high,2*pos+2,x,y));
}

void update(int low,int high,ll val,int pla,int pos)
{
    if(low==high)
    {
        seg[pos]=val;
        return ;
