    int mid=(low+high)/2;
    if(pla<=mid)
    {
        update(low,mid,val,pla,2*pos+1);
        seg[pos]=max(seg[2*pos+1], seg[2*pos+2]);
    }
    else
    {
        update(mid+1,high,val,pla,2*pos+2);
        seg[pos]=max(seg[2*pos+1], seg[2*pos+2]);
    }
}


