    }

    REP(i, N + 1)
    {
        REP(j, N + 1)
        {
            dp[i][j] = -1;
        }
    }

    REP(i, N + 1)
    {
        dp[i][0] = 0;
    }
    REP(j, N + 1)
    {
        dp[0][j] = 0;
    }

    FOR(n, 1, N + 1)
    {
        int nidx = n - 1;
        FOR(h, 1, (max_h + 1) + 1)
        {
            if (h < H[nidx])
            {
                dp[h][n] = dp[h][n - 1];
            }
            else
            {
                dp[h][n] = max(
                    dp[H[nidx] - 1][n - 1] + A[nidx], dp[h][n - 1]);
            }

            auto c = ", ";
            // cout << h << c << n << c << dp[h][n] << endl;
        }
    }

    LL ans = 0;
    FOR(h, 0, (max_h + 1) + 1)
    {
        ans = max(ans, dp[h][N]);
    }

    cout << ans << endl;
}

