ll st[N*4];
ll get(int node, int ql, int qr, int l, int r) {
    if (r < ql || qr < l) return 0;
    if (ql <= l && r <= qr) return st[node];
    else {
        ll max1 = get(node*2, ql, qr, l, (l+r)/2);
        ll max2 = get(node*2+1, ql, qr, (l+r)/2+1, r);
        return max(max1, max2);
    }
}

void update(int node, int ql, int qr, int l, int r, ll x) {
    if (r < ql || qr < l) return;
    if (l == r) st[node] = x;
    else {
        update(node*2, ql, qr, l, (l+r)/2, x);
        update(node*2+1, ql, qr, (l+r)/2+1, r, x);
        st[node] = max(st[node*2], st[node*2+1]);
    }
}

