ll tree[1000000];
void build(ll node, ll l ,ll r){
    if(r-l<2){
        tree[node] = 0;
        return;
    }
    ll mid = (l+r)/2;
    build(2*node,l,mid);
    build(2*node+1,mid,r);
    tree[node]=0;
}
void update(ll node, ll l, ll r, ll x, ll val){
    if(x>=r or x < l) return ;
    if(r-l<2){
        tree[node]+=val;
        return;
    }
    ll mid = (l+r)/2;
    if(x<mid){
        update(2*node,l,mid,x,val);
    }else{
        update(2*node+1,mid,r,x,val);
    }
    tree[node] = max(tree[2*node] , tree[2*node+1]);
}

ll query(ll node, ll l, ll r, ll x, ll y){
    if(x>=r or y<=l) return 0;
    if(x<=l and y>=r) return tree[node];
    ll mid = (l+r)/2;
    return max(query(2*node,l,mid,x,y) , query(2*node+1,mid,r,x,y));
}

