vector<int> st;

void update(int node, int l, int r, int i, int val)
{
	if(l>r or l>i or r<i)
		return;

	if(l==r and l==i)
	{
		st[node] = val;
		return;
	}

	int mid = (l+r)/2;
	update(2*node+1, l, mid, i, val);
	update(2*node+2, mid+1, r, i, val);

	st[node] = max(st[2*node+1], st[2*node+2]);
}

int query(int node, int l, int r, int i, int j)
{
	if(l>r or l>j or r<i)
		return 0;

	if(i<=l and r<=j)
		return st[node];

	int mid = (l+r)/2;

	int q1 = query(2*node+1, l, mid, i, j);
	int q2 = query(2*node+2, mid+1, r, i, j);

	return max(q1,q2);
}

