struct FenwickTreeMax {
    long long bit[123456];
    int n;
    const long long INF = (int)1e9;

    FenwickTreeMax(int n) {
        this->n = n;
	for(int i = 0; i < n+10; i++) bit[i] = 0;
    }

    long long getmax(int r) {
        long long ret = -INF;
        for (; r >= 0; r = (r & (r + 1)) - 1)
            ret = max(ret, bit[r]);
        return ret;
    }

    void update(int idx, long long val) {
        for (; idx < n; idx = idx | (idx + 1))
            bit[idx] = max(bit[idx], val);
    }
};

int main() {
