	}

	for(int i = 0; i < n; i++) cin >> a[i];
	FenwickTreeMax ft(n+10);

	dp[0][0] = 0;
	dp[0][1] = a[0];
	ft.update(h[0],dp[0][1]);

	for(int i = 1; i < n; i++) {
		dp[i][0] = max(dp[i-1][0], dp[i-1][1]);
		dp[i][1] = ft.getmax(h[i]) + a[i];
		ft.update(h[i],dp[i][1]);
	}

