#define L ((cur) << 1)
#define R ((cur) << 1 | 1)

void pushup(int cur)
{
    tr[cur] = max(tr[cur], max(tr[L], tr[R]));
}

void update(int pos, ll val, int l, int r, int cur)
{
    if (l == r)
    {
        tr[cur] = max(val, tr[cur]);
        return;
    }

    int m = (l + r) >> 1;

    if (pos < m)
        update(pos, val, l, m, L);
    else
        update(pos, val, m + 1, r, R);

    pushup(cur);
}

ll query(int pos, int l, int r, int cur)
{
    if (1 <= l && r <= pos)
        return tr[cur];

    int m = (l + r) >> 1;

    ll ans = 0;

    if (1 <= m)
        smax(ans, query(pos, l, m, L));
    if (pos > m)
        smax(ans, query(pos, m + 1, r, R));

    return ans;
}

