vector<ll> seg;
int n;

// create
ll create(int node, int l, int r, const vector<ll>& v) {
    if (l == r)
        seg[node] = v[l];
    else {
        int mid = (l + r) / 2;
        seg[node] = max(create(2 * node + 1, l, mid, v), create(2 * node + 2, mid + 1, r, v));
    }
    return seg[node];
}

// update element
ll update(int ind, ll val, int node = 0, int l = 0, int r = -1) {
    if (r == -1) r += n;

    if (l == r && l == ind)
        seg[node] = val;
    else if (l <= ind && ind <= r) {
        int mid = (l + r) / 2;
        if (ind <= mid)
            update(ind, val, 2 * node + 1, l, mid);
        else
            update(ind, val, 2 * node + 2, mid + 1, r);

        seg[node] = max(seg[2 * node + 1], seg[2 * node + 2]);
    }
    return seg[node];
}

// range query
ll query(int l, int r, int node = 0, int tl = 0, int tr = -1) {
    if (tr == -1) tr += n;

    if (tl == tr)
        return seg[node];
    else {
        int mid = (tl + tr) / 2;
        if (r <= mid)
            return query(l, r, 2 * node + 1, tl, mid);
        else if (l > mid)
            return query(l, r, 2 * node + 2, mid + 1, tr);
        else
            return max(query(l, mid, 2 * node + 1, tl, mid), query(mid + 1, r, 2 * node + 2, mid + 1, tr));
    }
}

