void build_tree(ll node,ll start,ll end){
	ans[node].l=start;
	ans[node].r=end;
    if(start==end){
        ans[node].v=0;
        ans[node].w=INF;
        return ;
    }
    ll left_node=2*node;
    ll right_node=2*node+1;
    ll mid=(start+end)>>1;
    build_tree(left_node,start,mid);
    build_tree(right_node,mid+1,end);
    ans[node].v=max(ans[left_node].v,ans[right_node].v);
    ans[node].w=max(ans[left_node].w,ans[right_node].w);
}

void update(ll node,ll p,ll w,ll v){
    if(ans[node].l==ans[node].r){
        ans[node].v=v;
        ans[node].w=w;
        return ;
    }
    ll mid=(ans[node].l+ans[node].r)>>1;
    ll left_node=2*node;
    ll right_node=2*node+1;
    if(p<=mid){
        update(left_node,p,w,v);
    }
    else{
        update(right_node,p,w,v);
    }
    ans[node].v=max(ans[left_node].v,ans[right_node].v);
    ans[node].w=max(ans[left_node].w,ans[right_node].w);
}
ll query(ll node,ll l,ll r,ll w){
    if(r<ans[node].l||l>ans[node].r){
        return 0;
    }
    else if(ans[node].l>=l&&ans[node].r<=r&&ans[node].w<w){
        return ans[node].v;
    }
    ll mid=(ans[node].l+ans[node].r)>>1;    
    ll left_node=2*node;
    ll right_node=2*node+1;
    ll sum_left=query(left_node,l,r,w);
    ll sum_right=query(right_node,l,r,w);
    return max(sum_left,sum_right);
}

