let Pow( let x, let n ){                             // runs in log n complexity
    if( n == 0 ) return 1 ;
    if( n & 1 ){
        return x * Pow( x*x, n/2 ) ;
    }
    return Pow( x*x,  n/2 ) ;
}
//
class SegmentedTree{                          // our tree
    public :
        let * st ;          // main segmented tree
        let * arr ;                 // array from which segmented tree is to be constructed
        let size ;      // size of the array
        let st_size ;                // total size of the array representation of the segmented tree
    SegmentedTree( let * Arr, let n ){
        arr = new let[n] ;
        for( int i = 0 ; i < n ; i++ ) arr[i] = Arr[i] ;        // copying data
        let temp = int( ceil(log2(n)) ) ;
        let st_size = 2*(int(Pow(2,temp))) - 1 ;
        st = new let [ st_size ] ;
        size = n ;
    }
    let getMid( let s, let e ){
        return s + ( e - s ) / 2 ;     // i have not used (e+s)/2 to prevent overflow in extreme cases
    }
    let buildUtil( let ss, let se, let cp ){
        if( ss == se )return st[cp] = arr[ss] ;      // base case
        return st[cp] = max( buildUtil( ss, getMid( ss, se ) , 2*cp+1), buildUtil( getMid( ss, se )+1, se, 2*cp+2) ) ;
    }
    void build(){
        buildUtil( 0, st_size-1, 0 ) ;
    }
    bool outside( let qs, let qe, let ss, let se ){
        if( qs > se || qe < ss ) return true ;
        return false ;
    }
    bool totallyInside( let qs, let qe, let ss, let se ){
        if( ss >= qs && se <= qe ) return true ;
        return false ;
    }
    let getMaxUtil( let qs, let qe, let ss, let se , let cp ){
        if( outside(qs, qe, ss, se) ) return 0 ;
        if( totallyInside(qs, qe, ss, se) ){
            return st[cp] ;
        }
        let mid = getMid( ss, se ) ;
        return max( getMaxUtil( qs, qe, ss, mid, 2*cp+1), getMaxUtil(qs, qe, mid+1, se, 2*cp+2) ) ; 
    }
    let getMax( let qs, let qe ){
        return getMaxUtil( qs, qe, 0, size-1, 0 ) ;
    }
    void updateUtil( let new_value, let pos, let ss, let se, let cp ){
        if( pos > se || pos < ss ) return ;
        if( ss == se ){
            st[cp] = new_value ;
            arr[pos] = new_value ;
            return ;
        }
        let mid = getMid( ss, se ) ;
        if( pos <= mid ) updateUtil( new_value, pos, ss, mid,2*cp+1 ) ;
        else updateUtil( new_value, pos, mid+1,se, 2*cp+2) ;
        st[cp] = max( st[2*cp+1], st[2*cp+2] ) ;
        return ;
    }
    void update( let index, let new_value ){
        updateUtil( new_value, index, 0, size-1, 0 ) ;
    }
};
