const ll inf=1LL<<60;

struct SegmentTree{
private:
    int n; // セグ木の葉の数, つまり２冪になっており,　全体の要素数は2*n-1
    vector<ll> node;

public:
    SegmentTree(vector<ll> v){
        int sz = (int)v.size();
        n = 1; while(n < sz) n*= 2;
        node.resize(2*n-1, 0);
        for(int i=0; i<sz; ++i) node[i+n-1] = v[i];
        for(int i=n-2; i>=0; --i) node[i] = max(node[2*i+1], node[2*i+2]);
    }

    // k番目(0-indexed)をvalに変更
    void update(int x, int val){
        x += (n-1);
        node[x] = val;
        while(x > 0){
            x = (x-1)/2;
            node[x] = max(node[2*x+1], node[2*x+2]);
        }
    }

    // [a,b)の最小値を求める
    // kは接点の番号、l、rはその接点が[l, r)に対応していることを表す
    // 外からはgetmin(a, b, 0, 0, n)と呼ぶ
    ll getmax(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0) r = n;
        // [a, b)と[l, r)が交差していなければinfを返す
        if(r <= a || b <= l) return 0;
        // [a,b) ⊃ [l, r)ならば、この接点の値
        if(a <= l && r <= b) return node[k];
        // そうでなければ二つの子の最小値
        int vl = getmax(a, b, k*2+1, l, (l+r)/2);
        int vr = getmax(a, b, k*2+2, (l+r)/2, r);
        return max(vl, vr);
    }
};

int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n; cin >> n;
    vector<ll> h(n), a(n);
    rep(i, n) cin >> h[i];
    rep(i, n) cin >> a[i];

    SegmentTree seg(vector<ll>(n+1, 0));

    rep(i, n){
        ll tmp=seg.getmax(0, h[i]);
        seg.update(h[i], tmp+a[i]);
    }
    cout << seg.getmax(0, n+1) << endl;

    return 0;
}

