	index+=SIZE;
	tree[index] = max(tree[index], val);
	while(index)	
		index>>=1, tree[index] = max(tree[2*index], tree[2*index+1]);

}

ll query(int left, int right) {
	left += SIZE, right += SIZE;	
	ll R = max(tree[left], tree[right]);	
	while(left>>1 != right>>1) {
		if (left%2==0)
			R = max(R, tree[left+1]);
		if (right%2==1)
			R = max(R, tree[right-1]);
	left>>=1, right>>=1;
	}
	return R; 
}

