class QFlowers {
public:
    template< typename Monoid >
    struct SegmentTree {
        using F = function< Monoid(Monoid, Monoid) >;

        int sz;
        vector< Monoid > seg;

        const F f;
        const Monoid M1;

        SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
            sz = 1;
            while(sz < n) sz <<= 1;
            seg.assign(2 * sz, M1);
        }

        void set(int k, const Monoid &x) {
            seg[k + sz] = x;
        }

        void build() {
            for(int k = sz - 1; k > 0; k--) {
                seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
            }
        }

        void update(int k, const Monoid &x) {
            k += sz;
            seg[k] = x;
            while(k >>= 1) {
                seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
            }
        }

        Monoid query(int a, int b) {
            Monoid L = M1, R = M1;
            for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
                if(a & 1) L = f(L, seg[a++]);
                if(b & 1) R = f(seg[--b], R);
            }
            return f(L, R);
        }

        Monoid operator[](const int &k) const {
            return seg[k + sz];
        }
    };
void solve(std::istream& cin, std::ostream& cout, std::ostream& cerr) {
    int N;
    cin >> N;
    SegmentTree<int> rmq(N, [](int a, int b){return max(a,b);}, 0);
    VI h(N), a(N);
    REP(i,N)cin >> h[i];
    REP(i,N)cin >> a[i];
    REP(i,N){
        rmq.update(h[i]-1, rmq.query(0, h[i]-1) + a[i] );
    }
    print(rmq.query(0, N));

}


};


