vector<int> mx(tree_size, -2e18);

struct tree {
    int mx;
    tree* l;
    tree* r;
    tree() {
        mx = -2e18;
        l = r = nullptr;
    }
};

tree* rt = new tree;

tree* get_l(tree* v) {
    if (!v->l) {
        v->l = new tree;
    }
    return v->l;
}

tree* get_r(tree* v) {
    if (!v->r) {
        v->r = new tree;
    }
    return v->r;
}

int get_max(tree* v, int l, int r, int L, int R) { // l , r - границы L,R запрос
    // если не перес
    // полуинтервал
    if(R <= l || L >= r)
        return -2e18;
    if(L <= l && r <= R)
        return v->mx;
    int m = (r + l)/2;
    return max(
                get_max(get_l(v), l, m, L, R),
                get_max(get_r(v), m, r, L, R)
              );
}

void relax(tree* v, int l, int r, int i, int x) {
    v->mx = max(v->mx, x);
    if (r-l==1)
        return;
    int m = (l + r)/2;
    if(i < m)
        relax(get_l(v), l, m, i, x);
    else
        relax(get_r(v), m, r, i, x);
}

