void update(lli in,lli l,lli r,lli ind,lli val){
    if(l==r && l==ind){
        seg[in]=val;
        return;
    }
    lli mid=(l+r)/2;
    if(ind<=mid)
    update(2*in,l,mid,ind,val);
    else
    update(2*in+1,mid+1,r,ind,val);

    seg[in]=max(seg[2*in] , seg[2*in+1]);
}

lli func(lli in,lli lt,lli rt,lli l,lli r){
    if(lt>rt) return 0;
    if(l==lt && r==rt) return seg[in];
    lli mid=(l+r)/2;
    if(rt<=mid) return func(2*in , lt,rt,l,mid);
    else if(lt>mid) return func(2*in+1,lt,rt,mid+1,r);
    else{
        return max(func(2*in,lt,mid,l,mid) , func(2*in+1,mid+1,rt,mid+1,r));
    }
}

