ll N;
vl t;

void build(vl arr, ll v, ll tl, ll tr) {
    if (tl == tr) {
        t[v] = arr[tl];
    } else {
        ll tm = (tl + tr) / 2;
        build(arr, v*2, tl, tm);
        build(arr, v*2+1, tm+1, tr);
        t[v] = max(t[v*2], t[v*2+1]);
    }
}

ll maxRecurse(ll v, ll tl, ll tr, ll l, ll r) {
  //cout << tl << ' ' << tr << ' ' << l << ' ' << r << endl;
    if (l > r)
        return 0;
    if (l == tl && r == tr) {
        return t[v];
    }
    ll tm = (tl + tr) / 2;
    return max(maxRecurse(v*2, tl, tm, l, min(r, tm)), maxRecurse(v*2+1, tm+1, tr, max(l, tm+1), r));
}

void updateRecurse(ll v, ll tl, ll tr, ll pos, ll new_val) {
    if (tl == tr) {
        t[v] = new_val;
    } else {
        ll tm = (tl + tr) / 2;
        if (pos <= tm) updateRecurse(v*2, tl, tm, pos, new_val);
        else updateRecurse(v*2+1, tm+1, tr, pos, new_val);
        t[v] = max(t[v*2], t[v*2+1]);
    }
}


ll getMax(ll l, ll r){
  return maxRecurse(1, 0, N-1, l , r);
}

void update(ll pos, ll new_val){
  updateRecurse(1, 0, N-1, pos, new_val);
}

