#define int long long

int tree[1000100];

void upd(int v, int tl, int tr, int pos, int val) {
    if (tl == tr)tree[v] = val;
    else {
        int tm = (tl + tr) / 2;
        if (pos <= tm)upd(2 * v, tl, tm, pos, val);
        else upd(2 * v + 1, tm + 1, tr, pos, val);
        tree[v] = max(tree[2 * v], tree[2 * v + 1]);
    }
}

int search(int v, int tl, int tr, int l, int r) {
    if (tl >= l && tr <= r)return tree[v];
    if (l > r || tl > tr || tr < l || tl > r)return 0;
    int tm = (tl + tr) / 2;
    return max(search(2 * v, tl, tm, l, min(tm, r)), search(2 * v + 1, tm + 1, tr, min(tm + 1, l), r));
}

