#define L(p) 2*p+1
#define R(p) 2*p+2

struct seg_tree
{
    vector<int> jt ;
    int n;
    seg_tree(int n) : n(n)
    {
        jt.resize( 4*n );
    }
    int fun( int a,int b )
    {
        return max(a,b); // whetever u want
    }
    void build(int l , int h , int p )
    {
        if(l == h)
        {
            cin >> jt[p];
            return;
        }
        int m = (l+h)>>1;
        build(l , m , L(p));
        build(m+1 , h , R(p));
        jt[p] = fun(jt[L(p)],jt[R(p)]);
        return;
    }
    void update(int l ,int h , int p, int q,int v) // point-update
    {
        if( l==h )
        {
            jt[p] = v;
            return ;
        }
        int m = (l + h )>> 1;
        if( m>=q ) update( l , m , L(p) ,q , v);
        else        update(m+1 , h , R(p) , q , v);

	    jt[p] = fun(jt[L(p)],jt[R(p)]);
	    return;
    }
    int query(int l,int h, int p, int ql ,int qh) // range_query
    {
        if(l > qh || h < ql)
            return 0;
        else if(l >= ql && h <= qh)
            return jt[p] ;
        int m = (l + h )>> 1;
        int p1 = query( l , m , L(p) ,ql ,qh);
        int p2 = query(m+1 , h , R(p) , ql ,qh);
        return fun(p1,p2);
    }
    void up( int p, int v)
    {
        update( 1,n,0,p,v );
        return ;
    }
    int qr( int ql,int qh )
    {
       return query( 1,n,0,ql,qh ); 
    }
};

