const int N = 2e5 + 1;
ll tree[4 * N];
ll H[N] , A[N];

void update(ll node , ll s , ll e , ll i , ll v){
	if(s == e){
		tree[node] = v;
	}else{
		ll m = s + e >> 1;
		if(i <= m) update(node << 1 , s , m , i , v);
		else update(node << 1 | 1 , m + 1 , e , i , v);
		tree[node] = max(tree[node<<1] , tree[node<<1 | 1]);
	}
}

ll query(ll node , ll s , ll e , ll l , ll r){
	if(s > r || e < l) return 0;
	if(s >= l && e <= r) return tree[node];
	ll m = s + e >> 1;
	return max(query(node << 1 , s , m , l , r) , query(node << 1 | 1 , m + 1 , e , l , r));
}

