void chTree(int node, ll v) {
    node += Base;
    Tree[node] = v;
    while (node /= 2) {
        Tree[node] = max(Tree[2 * node], Tree[2 * node + 1]);
    }
}

ll read(int node, int lo, int hi, int l, int r) {
    if (r < lo or hi < l) {
        return 0;
    }
    if (l <= lo and hi <= r) {
        return Tree[node];
    }

    int mid = (lo + hi) / 2;
    return max(read(2 * node, lo, mid, l, r), read(2 * node + 1, mid + 1, hi, l, r));
}

