template<class T>
class ST {
	struct N {
		N *ln,*rn;
		int l,r;
		T v;
	};

	N *root;
	vector<T> *data;
	bool hasData;

	T Q(int li, int ri, N *n) {
		if (ri <= n->l || n->r <= li) return INT_MIN;
		if (li <= n->l && n->r <= ri) return n->v;
		T l = Q(li, ri, n->ln);
		T r = Q(li, ri, n->rn);
		return max(l, r);
	}

	void U(int e, T v, N *n) {
		if (e < n->l || n->r <= e) return;
		if (n->r - n->l == 1) {
			n->v = v;
			return;
		}
		U(e, v, n->ln);
		U(e, v, n->rn);
		T l = n->ln->v;
		T r = n->rn->v;
		n->v = max(l, r);
	}

	void B(N *n) {
		if (n->r - n->l == 1) {
			n->v = 0;
			return;
		}
		n->ln = new N;
		n->rn = new N;
		n->ln->l = n->l;
		n->ln->r = n->rn->l = (n->r + n->l) / 2;
		n->rn->r = n->r;
		B(n->ln);
		B(n->rn);
	}

public:
	T Q(int l, int r) {
		return Q(l, r, root);
	}

	void U(int e, T v) {
		U(e, v, root);
	}

	ST(vector<T> &v) {
		hasData = 1;
		data = &v;
		root = new N;
		root->l = 0;
		root->r = v.size();
		B(root);
	}

	ST(int siz){
		hasData = 0;
		root = new N;
		root->l = 0;
		root->r = siz;
		B(root);
	}
};

