std::string join(const vector<string> &v, const char *delim = 0)
{
	std::string s;
	if (!v.empty())
	{
		s += v[0];
		for (decltype(v.size()) i = 1, c = v.size(); i < c; ++i)
		{
			if (delim)
				s += delim;
			s += v[i];
		}
	}
	return s;
}

