using namespace std;

const int M = 1e5;

using ll = long long;

vector<ll> tree(2*(M+1), 0);

void update(int i, long long v){
	tree[i+M+1] = v;
	i = i+M+1;
	for(int k = i/2; k >= 1; k /= 2){
		tree[k] = max(tree[2*k], tree[2*k+1]);	
	}
}

void max_self(ll& a, ll b){
	a = max(a, b);	
}

ll Query(int a, int b){
	ll r = 0;
	a += (M+1);
	b += (M+1);
	while(a <= b){
		if(a%2 == 1) max_self(r, tree[a++]);
		if(b%2 == 0) max_self(r, tree[b--]);
		a /= 2; b /= 2; 	
	}
	return r;
}

int main(){
	int n;
	cin >> n;
	vector<int> h(n);
	vector<int> b(n);
	int N = 0;
	for(int i = 0; i < n; i++){
		cin >> h[i];
		N = max(N, h[i]);
	}
	for(int i = 0; i < n; i++){
		cin >> b[i];	
	}
	//segment tree
	vector<ll> dp(M+1, 0);
	for(int i = 0; i < n; i++){
		dp[h[i]] = Query(1, h[i]);
		dp[h[i]] += b[i];
		update(h[i], dp[h[i]]);
	}
	ll ans = 0;
	for(int i = 1; i <= N; i++){
		if(dp[i] > ans){
			ans = dp[i];
		}
	}
	cout << ans << endl;
	return 0;
}

