ll ans = 0;
ll height[200005];
ll value[200005];

ll go(int n)
{
    ll dp[n+1];
    memset(dp,0,sizeof(dp));

    for(int i=1;i<=n;i++)
        dp[i] = value[i];

    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<i;j++)
        {
            if(height[j] < height[i])
            {
                dp[i] = max(dp[i],dp[j]+value[i]);
            }
        }
    }

    for(int i=1;i<=n;i++)
        ans = max(ans,dp[i]);

    return ans;
}

