const int mod=1e9+7;
long long querry(int nod,int st,int dr)
{
    if(dr<=a[i])
        return tree[nod];
    else {
        long long mij=(st+dr)>>1,x=0,y=0;
        x=querry(2*nod,st,mij);
        if(mij<a[i])
            y=querry(2*nod+1,mij+1,dr);
        return max(x,y);
    }
}
void update(int nod,int st,int dr)
{
    if(st==dr)tree[nod]=x;
    else {
     int mij=(st+dr)>>1;
     if(mij>=a[i])
     update(2*nod,st,mij);
     if(mij<a[i])
        update(2*nod+1,mij+1,dr);
     if(nod<=n)
        tree[nod]=max(tree[2*nod],tree[2*nod+1]);
    }
}
