typedef long long LL;

struct SegmentTree {
 public:
  SegmentTree(int n) {
    num_ = 1;
    while (num_ < n) num_ *= 2;
    data_.assign(2*num_-1, 0);
  }

  void Update(int i,  LL v) {
    i += num_ - 1;
    data_[i] = v;
    while (i > 0) {
      i = (i-1)/2;
      data_[i] = std::max(data_[2*i+1],  data_[2*i+2]);
    }
  }

  LL Query() { return data_[0]; }
  LL Query(int a, int b) { return Query(a, b, 0, 0, num_); }
  LL Query(int a, int b, int i,  int l,  int r) {
    if (r <= a || b <= l) return 0;
    if (a <= l && r <= b) return data_[i];

    LL left = Query(a, b, 2*i+1, l, (l+r)/2);
    LL right = Query(a, b, 2*i+2, (l+r)/2, r);
    return std::max(left, right);
  }

 private:
  std::vector<LL> data_;
  int num_;
};

int main() {
  int N; std::cin >> N;
  std::vector<int> h(N), a(N);
  for (int i = 0; i < N; ++i) std::cin >> h[i];
  for (int i = 0; i < N; ++i) std::cin >> a[i];

  SegmentTree tree(N+1);

  for (int i = 0; i < N; ++i) {
    LL max_value = tree.Query(0, h[i]);
    tree.Update(h[i], a[i] + max_value);
  }

  std::cout << tree.Query() << std::endl;
}

