            else
               m[hgt[i]] = m[*it] + bty[i];
            ans = max(ans, m[hgt[i]]);
            s.insert(hgt[i]);
            auto ut = s.lower_bound(hgt[i]);
            auto st = ++ut, et = s.end();
            vector <int> temp;
            for (auto at = st; at != s.end(); at++) {
               if (at == s.end())
                  break;
               if (m[*at] <= m[hgt[i]]) {
                  temp.push_back(*at);
               } else {
