ll n;
Node seg[4*size_1d];

void merge(int ti){
    if(seg[ti*2 + 1].x >= seg[ti*2 + 2].x)
        seg[ti] = seg[ti*2 + 1];
    else seg[ti] = seg[ti*2 + 2];
}
Node check(Node t1, Node t2){
    if(t1.x >= t2.x) return t1;
    return t2;
}
void build(ll ti,ll l,ll r,std::vector<ll> &v){
    if(l==r){
        seg[ti] = v[l];
        return;
    }
    ll mid = (l+r)/2;
    build(2*ti + 1,l,mid,v);
    build(2*ti + 2,mid+1,r,v);
    merge(ti);
    return;
}
Node query(ll ti,ll l,ll r,ll left,ll right){
    if(l>right || r<left) return Node(0);
    if(l>=left && r<=right) return seg[ti];
    ll mid = (l+r)/2;
    Node t1 = query(2*ti + 1,l,mid,left,right);
    Node t2 = query(2*ti + 2,mid+1,r,left,right);
    return check(t1,t2);
}
void update(ll ti,ll l,ll r,ll index,Node x){
    if(l==r){
        seg[ti]=x;
        return;
    }
    ll mid = (l+r)/2;
    if(index<=mid) update(2*ti + 1,l,mid,index,x);
    else update(2*ti+2,mid+1,r,index,x);
    merge(ti);
    return ;
}
