class Tree
{
public:
	LL M;
	Tree(){
		M = 0;
	}
	Tree(int x){
		x = M;
	}
};



int sizeOfSegmentTree(int n)
{
	int x = (int)(ceil(log2(n))); 
	return (2*(int)pow(2,x) - 1);  // 2*(next power of two)-1
}


void build(int node, int start, int end, Tree *T, int A[])
{
	if(start == end)
		T[node].M = A[start];
	else
	{
		int leftChild = 2*node+1;
		int rightChild = 2*node+2;
		int mid = (start+end)/2;
		//compute the values in the left and right subtrees
		build(leftChild, start, mid, T, A);
		build(rightChild, mid+1, end, T, A);
		//search for the Prodimum value in the first and 
		//second half of the interval
		T[node].M = max(T[leftChild].M, T[rightChild].M);
	}
} 

void updateRange(int node, int start, int end, int l, int r, LL val, Tree *T)
{
	if(start > end || start > r || end < l) // Current segment is not within range [l, r]
		return;



	int leftChild  = 2*node+1;
	int rightChild = 2*node+2; 


	if(start >= l && end <= r)
	{
		// Segment is fully within range
		T[node].M += val;
		return;
	}

	int mid = (start+end)/2;
	updateRange(leftChild, start, mid, l, r, val, T);        // Updating left child
	updateRange(rightChild, mid+1, end, l, r, val, T);   // Updating right child


	T[node].M = max(T[leftChild].M, T[rightChild].M);
}

LL queryRange(int node, int start, int end, int l, int r, Tree *T)
{
	int leftChild  = 2*node+1;
	int rightChild = 2*node+2; 
	if(start > end || start > r || end < l) // Out of range
		return 0;   


	if(start >= l && end <= r)             // Current segment is totally within range [l, r]
		return T[node].M;

	int mid = (start + end) / 2;
	LL p1 = queryRange(leftChild, start, mid, l, r, T);         // Query left child
	LL p2 = queryRange(rightChild, mid + 1, end, l, r, T); // Query right child
	return max(p1,p2);
}


