template <class T> struct Array {
    struct node {
        ll childl, childr;
        T data;
        node(ll l, ll r, T t) : childl(l), childr(r), data(t) {}
    };
    ll n, depth;
    vector<ll> versions;
    vector<ll> prev_versions;
    vector<node> nodes;
    Array(ll n = 1 << 20, T val = T()) : n(n), depth(0) {
        while (n /= 2) depth++;
        init(val);
    }
    void init(T val) {
        versions.push_back(0);
        prev_versions.push_back(0);
        rep(i, 2 * n - 1) {
            if (i < n - 1) {
                nodes.push_back(node(2 * i + 1, 2 * i + 2, T()));
            } else {
                nodes.push_back(node(0, 0, val));
            }
        }
    }
    void set(ll index, ll val, ll version = -1) {
        ll id, par = nodes.size(), left = 0, right = n;
        if (version == -1) {
            id = versions.back();
            version = versions.size() - 1;
        } else {
            id = versions[version];
        }
        versions.push_back(par);
        prev_versions.push_back(version);
        if (right == -1) right = n;
        rep(i, depth) {
            ll mid = (left + right) / 2;
            if (index < mid) {
                nodes.push_back(node(par + i + 1, nodes[id].childr, T()));
                id = nodes[id].childl;
                right = mid;
            } else {
                nodes.push_back(node(nodes[id].childl, par + i + 1, T()));
                id = nodes[id].childr;
                left = mid;
            }
        }
        nodes.push_back(node(0, 0, val));
    }
    T get(ll index, ll version = -1) {
        ll id, left = 0, right = n;
        if (version == -1) {
            id = versions.back();
        } else {
            id = versions[version];
        }
        rep(i, depth) {
            ll mid = (left + right) / 2;
            if (index < mid) {
                id = nodes[id].childl;
                right = mid;
            } else {
                id = nodes[id].childr;
                left = mid;
            }
        }
        return nodes[id].data;
    }
    ll latest() { return versions.size() - 1; }
};

struct BipartiteGraph {
    ll V;
    vector<vector<ll>> G;
    vector<ll> match;
    vector<bool> used;
    BipartiteGraph(ll N) : V(N), G(N), match(N), used(N) {}
    void addEdge(ll i, ll j) {
        G[i].push_back(j);
        G[j].push_back(i);
    }
    bool dfs(ll now) {
        used[now] = true;
        rep(i, G[now].size()) {
            ll next = G[now][i], w = match[next];
            if (w == -1 || (!used[w] && dfs(w))) {
                match[now] = next, match[next] = now;
                return true;
            }
        }
        return false;
    }
    ll matching() {
        ll res = 0;
        fill(all(match), -1);
        rep(i, V) {
            if (match[i] == -1) {
                fill(all(used), false);
                if (dfs(i)) res++;
            }
        }
        return res;
    }
};

template <typename T = ll> struct Dijkstra {
    ll V;
    using P = pair<ll, ll>;
    vector<vector<P>> G;
    vector<T> dist;
    vector<bool> used;
    Dijkstra(ll v) : V(v), G(v), dist(v), used(v) {}
    void setDist(ll a, ll b, ll d) { G[a].push_back(P(d, b)); }
    void culc(ll s = 0) {
        priority_queue<P, vector<P>, greater<P>> Q;
        Q.push(P(0, s));
        fill_n(dist.begin(), V, INF);
        fill_n(used.begin(), V, false);
        while (!Q.empty()) {
            T d;
            ll t;
            tie(d, t) = Q.top(), Q.pop();
            if (used[t]) continue;
            used[t] = true, dist[t] = d;
            for (P e : G[t]) {
                if (dist[e.second] <= d + e.first) continue;
                Q.push(P(d + e.first, e.second));
            }
        }
    }
};

struct BIT {
    vector<ll> data;

    BIT() {}
    BIT(ll N) : data(N + 1) {
        fill(data.begin(), data.end(), 0);
        data[0] = N;
    }

    void add(ll pos, ll val) {
        while (pos <= data[0]) {
            data[pos] = ::max(data[pos], val);
            pos += pos & -pos;
        }
    }
    ll sum(ll pos) {
        if (pos <= 0) return 0;
        ll res = 0;
        while (pos > 0) {
            res = ::max(res, data[pos]);
            pos -= pos & -pos;
        }
        return res;
    }

    ll lower_bound(ll val) {
        if (val <= 0) return 0;
        ll index = 0;
        for (ll d = 1 << ll(log2(data[0])); d > 0; d /= 2) {
            if (index + d <= data[0] && data[index + d] < val) {
                val -= data[index + d];
                index += d;
            }
        }
        return index;
    }
};

