void update(int l, int r, int id, int x)
{
    int m = (l+r)/2;
    if(x < l || x >= r) return;
    if(x == l && x == r-1){
        seg[id] = dp[x];
        return;
    }

        update(l, m, left(id), x);
        update(m,r, right(id), x);
        seg[id] = max(seg[left(id)] , seg[right(id)]);

}

int solve(int l, int r, int id, int x, int y)
{
    int m = (l+r)/2;
    if(x <= l && r <= y){
        return seg[id];
    }
    if(r <= x || l >= y){
        return 0;
    }
    return max(solve(l, m, left(id), x, y), solve(m, r, right(id), x, y));
}

