struct Fenwick {
    int n;
    long long node[N];
    void update(int u, long long val)
    {
        for (; u <= n; u += u & -u)
            node[u] = max(node[u], val);
    }
    long long query(int u)
    {
        long long max_pref = 0;
        for (; u > 0; u -= u & -u)
