int query(int l, int r, int i, int qs, int qe)
{
    if (l > r)
        return -inf;
    if (qs > r or qe < l)
        return -inf;
    if (qs <= l and qe >= r)
        return st[i];
    int m = (l + r) / 2;
    return max(query(l, m, 2 * i + 1, qs, qe), query(m + 1, r, 2 * i + 2, qs, qe));
}

void update(int l, int r, int i, int index, int val)
{
    if (l > r)
        return;
    if (index > r or index < l)
        return;
    if (l == r)
    {
        st[i] = val;
        return;
    }
    int m = (l + r) / 2;
    update(l, m, 2 * i + 1, index, val);
    update(m + 1, r, 2 * i + 2, index, val);
    st[i] = max(st[2 * i + 1], st[2 * i + 2]);
}

