const int DEPTH = 18;
struct SegTree {
	int d[1 << (DEPTH + 1)];
	SegTree() {
		int i;
		rep(i, (1 << (DEPTH + 1))) d[i] = 0;
	}
	void update(int pos, int x) {
		pos += (1 << DEPTH) - 1;
		d[pos] = x;
		while (pos > 0) {
			pos = (pos - 1) / 2;
			d[pos] = max(d[pos * 2 + 1], d[pos * 2 + 2]);
		}
	}
	//[l, r)
	int getMax(int l, int r, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) return 0;
		if (l <= a && b <= r) return d[id];
		int u = getMax(l, r, a, a + (b - a) / 2, id * 2 + 1);
		int v = getMax(l, r, a + (b - a) / 2, b, id * 2 + 2);
		return max(u, v);
	}
};

