#define ls(x) x<<1
#define rs(x) x<<1|1
using namespace std;
const int MAXN=200010;
long long a[MAXN],dp[MAXN],ans;
int n,h[MAXN];

struct node{
	int l,r,data;
} tree[MAXN<<2];

void build(int p,int lb,int ub){
	tree[p].l=lb,tree[p].r=ub;
	if(lb==ub) { tree[p].data=h[lb]; return; }
	int mid=lb+ub>>1;
	build(ls(p),lb,mid);
	build(rs(p),mid+1,ub);
	tree[p].data=min(tree[ls(p)].data,tree[rs(p)].data);
}

long long query(int p,int lb,int ub,int x){
	if(tree[p].data>x) return 0;
	if(tree[p].l>ub||tree[p].r<lb) return 0;
	if(tree[p].l==tree[p].r) return dp[tree[p].l];
	int mid=tree[p].l+tree[p].r>>1;
	long long res=0;
	if(lb<=mid) res=query(ls(p),lb,ub,x);
	if(mid<ub) res=max(res,query(rs(p),lb,ub,x));
	return res;
} 

