ii hae(int a, int b)
{
    ii r = 0;
    for (a += N, b += N; a <= b; a /= 2, b /= 2) {
        if (a & 1) r = max(r, p[a++]);
        if (~b & 1) r = max(r, p[b--]);
    }
    return r;
}
void muuta(int k, ii x)
{
    k += N;
    p[k] = max(p[k], x);
    for (k /= 2; k; k /= 2) {
        p[k] = max(p[k * 2], p[k * 2 + 1]);
    }
}
