        segIndex = ((segIndex + 1) >> 1) - 1; // parent
        if (maxes[segIndex] >= value) break;
        maxes[segIndex] = value;
      }
    }
    else {
      if (index < mp[segIndex]) {
        SetValue(value, index, childs[segIndex].first);
      }
      else {
        SetValue(value, index, childs[segIndex].second);
      }
    }
