int const maxi = 4*200005;
ll t[maxi];
vector<ll> dp(200005);

void build(int idx , int l ,int r){
	if(l==r){
		t[idx] = dp[l]; 
		return;
	}
	int mid = (l+r)>>1;

	build(2*idx+1 , l , mid);
	build(2*idx+2 , mid+1 ,r);

	t[idx] = max(t[2*idx+1], t[2*idx+2]);
}

void update(int v, int l , int r, int idx , ll val){
	if(l==r && idx==l){
		t[v] = dp[idx];
		return;
	}
	int mid = (l+r)>>1;
	if(idx<=mid) update(2*v+1, l,mid , idx , val);
	else update(2*v+2 , mid+1, r , idx,val);
	t[v] = max(t[2*v+1] , t[2*v+2]);

}

ll query(int v, int l, int r , int ql , int qh){
	if(r<ql || l > qh) return -1e18;
	if(l==ql && r==qh)return t[v];
	int mid = (l+r) >> 1;
	return max(query(2*v+1, l, mid, ql , min(mid, qh)) , query(2*v+2 , mid+1 , r , max(mid+1,ql) , qh));
}

