template<class C = long long>
class segtree{
   vector<C> dat;
   ll N;
public:
    explicit segtree(long long n) :N(n), dat() {
       int  k = 1;
       while(k < N) k*=2;
       dat.resize(k*2, 0);
       N = k;
    }

    void update(int k, C a){
        k += N - 1;
        dat[k] = a;
        while(k > 0){
            k = (k-1) / 2;
            dat[k] = max(dat[k*2+1], dat[k*2+2]);
        }
    }

    C query(int a, int b, int k, int l, int r){
        if(r <= a or b <= l) return -INF;
        if(a <= l and r <= b) return dat[k];

        C v1 = query(a, b, 2*k+1, l, (l+r)/2);
        C v2 = query(a, b, 2*k+2, (l+r)/2, r);

        return max(v1, v2);
    }

    C maximum(int l, int r){
        return query(l, r, 0, 0, N);
    }

};


