struct segment_tree
{
    int n;
    vector<long long> a, tree;
    segment_tree(vector<long long>& a)
    {
        n = a.size();
        this -> a = a;
        tree.resize(4 * n);
        build(0, 0, n - 1);
    }
    void build(int node, int l, int r)
    {
        if(l == r)
            tree[node] = a[l] = a[r];
        else
        {
            int mid = (l + r) / 2;
            build(2 * node + 1, l, mid);
            build(2 * node + 2, mid + 1, r);
            tree[node] = max(tree[2 * node + 1], tree[2 * node + 2]);
        }
    }
    void update(int node, int l, int r, int i, long long x)
    {
        if(l == r)
        {
            a[l] = a[r] = x;
            tree[node] = a[l] = a[r];
        }
        else
        {
            int mid = (l + r) / 2;
            if(i >= l && i <= mid)
                update(2 * node + 1, l, mid, i, x);
            else
                update(2 * node + 2, mid + 1, r, i, x);
            tree[node] = max(tree[2 * node + 1], tree[2 * node + 2]);
        }
    }
    long long query(int node, int l, int r, int s, int e)
    {
        if(l == s && r == e)
            return tree[node];
        else
        {
            int mid = (s + e) / 2;
            if(r <= mid)
                return query(2 * node + 1, l, r, s, mid);
            else if(l > mid)
                return query(2 * node + 2, l, r, mid + 1, e);
            else 
                return max(query(2 * node + 1, l, mid, s, mid), query(2 * node + 2, mid + 1, r, mid + 1, e));
        }
    }
};

