struct prefix_max_fenwick_tree {
    int tree_n;
    vector<long long> tree;

    prefix_max_fenwick_tree(int n = 0) {
        if (n > 0)
            init(n);
    }

    void init(int n) {
        tree_n = n;
        tree.assign(tree_n + 1, 0);
    }

    // index is in [0, tree_n).
    void update(int index, long long value) {
        for (int i = index + 1; i <= tree_n; i += i & -i)
            maximize(tree[i], value);
    }

    // Returns the max of the range [0, count).
    long long query(int count) const {
        long long result = 0;

        for (int i = count; i > 0; i -= i & -i)
            maximize(result, tree[i]);

        return result;
    }
};


