        }
        int m = (l+r)/2;
        return dat[k] = segfunc(add(a,b,x,2*k+1,l,m),add(a,b,x,2*k+2,m,r))+sum[k];
    }
    LL query(int a, int b) { return query(a,b,0,0,N); }
    LL query(int a, int b, int k, int l, int r) {
        if(b <= l || r <= a) return seg_unit;
        if(a <= l && r <= b) return dat[k];
        int m = (l+r)/2;
        return segfunc(query(a,b,2*k+1,l,m),query(a,b,2*k+2,m,r))+sum[k];
    }
};



