using namespace std;

template <typename T> class SegTree{
 /* Segment木                                                                              */
 /* [0,n)の計n個の要素を格納し、ある区間[l,r)の値を取得するための構造。                    */
 /* 更新処理、値の取得共にlog(n)                                                           */
 /* これが使えるための条件は、区間A,Bの値を用いて区間A+Bの値がcombineにより計算できること。*/
 /* 便宜的にoperator+を実装したくらすならば格納可能としている。例はBoxを参照のこと。       */
 private:
  vector<T> data;
  long long size; // 入力として与えられる要素数でなくそれ以上の最大の2の累乗を実際のサイズ歳て保持する
 public:
  T combine(T a, T b){
   //cout << "combine: "; a.print();
   //cout << "combine: "; b.print();
   return a+b;
  }
  SegTree(long long n, T def){
     size = 1;
     while(size < n) size*=2;
     data=vector<T>(size*2-1, def);
     for(int i=0; i<n; i++) setValue(i, def);
  }

  T getValue(int l){
    return getValue(l, l+1);
  }
  T getValue(int l, int r){
    // return sum in [l,r-1] or [l,r)
    return getValue_(0, l, r, 0, size);
  }
  T getValue_(int ind, int l, int r, int lb, int rb){
    //cout << ind << ", "<< l << ", " << r <<", "<<lb <<", "<< rb<<endl;
    if(l<=lb && rb<=r) return data[ind];
    int mid = (lb+rb)/2;
    if(r <= mid) return getValue_(ind*2+1, l, r, lb, mid);
    if(mid <= l) return getValue_(ind*2+2, l, r, mid, rb);
    return combine(getValue_(ind*2+1, l, r, lb, mid),
                   getValue_(ind*2+2, l, r, mid, rb));
  }
  void setValue(int i, T value){
    // add x to i
    int internal_index = size-1+i;
    data[internal_index]=value;
    while( internal_index != 0 ){
      internal_index=(internal_index-1)/2;
      data[internal_index]=combine(data[internal_index*2+1], data[internal_index*2+2]);
      //cout << "set: "<< internal_index << endl;
      //data[internal_index].print();
    }
    return;
  }
};
class Box{
  public:
  long long a;
  Box(long long a_):a(a_){};
  const Box operator+(const Box& B) const{
   return Box(max(a, B.a));
  }
  void print(){
   cout << a<<endl;
  }
};

