int H[100005], R[100005], A[100005];
ll tree[400005];

ll max(ll a, ll b)
{
    if (a >= b) return(a);
    return(b);
}

void update(int node, int start, int end, int idx, ll v)
{
    if (idx < start || end < idx) return;
    if (start == end)
    {
        tree[node] = v;
        return;
    }
    int mid = (start + end) / 2;
    update(2 * node, start, mid, idx, v);
    update(2 * node + 1, mid + 1, end, idx, v);
    tree[node] = max(tree[2 * node], tree[2 * node + 1]);
}

ll query(int node, int start, int end, int l, int r)
{
    if (r < start || end < l) return(0);
    if (start == end) return(tree[node]);
    int mid = (start + end) / 2;
    ll p1 = query(2 * node, start, mid, l, r), p2 = query(2 * node + 1, mid + 1, end, l, r);
    return(max(p1, p2));
}

