// セグメントツリー
class SegmentTree {
private:
    Int n;
    vector<Int> node;
    Int ident = 0;
    Int f(Int x, Int y) {
        return max(x, y);
    }
public:
    SegmentTree(vector<Int> v) {
        Int v_size = v.size();
        n = 1;
        while (n < v_size) {
            n *= 2;
        }
        node.resize(2 * n, ident);
        for (Int i = 0; i < v_size; i++) {
            node[n + i] = v[i];
        }
        for (Int i = n - 1; i >= 1; i--) {
            node[i] = f(node[i * 2], node[i * 2 + 1]);
        }
    }
    void update(Int x, Int val) {
        x += n;
        node[x] = val;
        while (x > 1) {
            x /= 2;
            node[x] = f(node[x * 2], node[x * 2 + 1]);
        }
    }
    // [a, b) での答え
    Int query(Int a, Int b, Int k = 1, Int l = 0, Int r = -1) {
        //cout << l << " " << r << endl;
        if (r < 0) {
            r = n;
        }
        if (r <= a or b <= l) {
            return ident;
        }
        if (a <= l and r <= b) {
            return node[k];
        }
        Int vl = query(a, b, 2 * k, l, (l + r) / 2);
        Int vr = query(a, b, 2 * k + 1, (l + r) / 2, r);
        return f(vl, vr);
    }
};

