struct segment_tree{

	vector<ll> st;

	segment_tree(int n) : st(4 * n){ }

	void update(int node, int b, int e, int p, ll v){
		if(b == e)
			st[node] = v;
		else{
			int m = (b + e) >> 1;
			int l = node << 1;
			int r = l | 1;
			if(p <= m)
				update(l, b, m, p, v);
			else
				update(r, m + 1, e, p, v);

			st[node] = max(st[l], st[r]);
		}
	}

	ll query(int node, int b, int e, int i, int j){
		if(b >= i && e <= j)
			return st[node];
		if(b > j || e < i)
			return 0;
		int m = (b + e) >> 1;
		int l = node << 1;
		int r = l | 1;

		ll L = query(l, b, m, i, j);
		ll R = query(r, m + 1, e, i, j);

		return max(L, R);
 	}

};

