struct SegTree {
	std::vector<int64_t> data;
	int n;
	SegTree (int n_) {
		for (n = 1; n < n_; n <<= 1);
		data.resize(n << 1);
	}
	void assign(int i, int64_t val) {
		for (data[i += n] = val; i >>= 1; ) data[i] = std::max(data[i << 1], data[i << 1 | 1]);
	}
	int64_t max(int l, int r) {
		int64_t res = 0;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (r & 1) res = std::max(res, data[--r]);
			if (l & 1) res = std::max(res, data[l++]);
		}
		return res;
	}
	int64_t operator [] (int i) { return data[i + n]; }
};
