using namespace std;
using ll = long long;

struct bit {
 vector<ll> vec;
 bit(size_t size) : vec(size+1) {}
 void set(size_t index, ll val) {
   auto i = index+1;
   while (i < vec.size()) {
     vec[i] = max(vec[i], val);
     i += i&(-i);
   }
 }
 ll get(size_t index) const {
   auto i = index+1;
   ll res = vec[i];
   i -= i&(-i);
   while (i > 0) {
     res = max(res, vec[i]);
     i -= i&(-i);
   }
   return res;
 }
};

