void treeupdate(int idx, int L, int R, int ii, ll upd)
{
	if(L == R)
	{
		tree[idx] = upd;
		return;
	}
	int le = 2*idx + 1, ri = le + 1, mid = (L + R) / 2;
	if(ii <= mid)
		treeupdate(le, L, mid, ii, upd);
	else treeupdate(ri, mid + 1, R, ii, upd);
	//
	tree[idx] = max(tree[le], tree[ri]);
}
