ll treemax(int idx, int L, int R, int QL, int QR)
{
	if(L >= QL && R <= QR)
	{
		return tree[idx];
	}
	if(L > QR || R < QL)
		return 0;
	int le = 2*idx + 1, ri = le + 1, mid = (L + R) / 2;
	ll a1 = treemax(le, L, mid, QL, QR);
	ll a2 = treemax(ri, mid + 1, R, QL, QR);
	//
	return max(a1, a2);
}
