void update(int pos, ll value, int node = 1, int start = 1, int end = MAXN){
  int mid = (start+end)/2;
  if(start == end) tree[node] = value;
  else{
    if(start <= pos && pos <= mid) update(pos, value, 2*node, start, mid);
    else update(pos, value, 2*node+1, mid+1, end);
    tree[node] = op(tree[2*node], tree[2*node+1]);
