const int MOD = 1e9 + 7;
const int INF = 0x3f3f3f3f;
const LL LLINF = 0x3f3f3f3f3f3f3f3f;
const int MAX_N = 200005;

LL dat[MAX_N * 4];

struct SegTree {
    int lg(int n) { return 31 - __builtin_clz(n); }

    int N;
    SegTree(int n): N(1) {
        while(N < n) {
            N <<= 1;
        }
    }

    void update(int a, LL val, int l = 0, int r = -1, int k = 1) {
        r = (r == -1) ? N : r;

        if(a < l or r <= a) {
            return;
        }
        if(l == r - 1) {
            dat[k] = val;
            return;
        }
        int mid = l + (r - l) / 2;
        update(a, val, l, mid, k << 1);
        update(a, val, mid, r, k << 1 | 1);
        dat[k] = max(dat[k << 1], dat[k << 1 | 1]);
    }

    LL query(int a, int b, int l = 0, int r = -1, int k = 1) {
        r = (r == -1) ? N : r;

        if(b <= l or r <= a) {
            return 0;
        }
        if(a <= l and r <= b) {
            return dat[k];
        }
        int mid = l + (r - l) / 2;
        LL vl = query(a, b, l, mid, k << 1);
        LL vr = query(a, b, mid, r, k << 1 | 1);
        return max(vl, vr);
    }
};


struct Solution {
    Solution(int) {
        int N;
        read(N);
        vector<int> a(N), h(N);
        for(int i : range(N)) {
            read(h[i]);
