        for(int i : range(N)) {
            read(a[i]);
        }
        LL ans = 0;
        auto st = SegTree(N + 1);
        for(int i : range(N)) {
            LL mx = st.query(0, h[i]);
            ans = max(ans, mx + a[i]);
            st.update(h[i], mx + a[i]);
        }
        print(ans);
    }
};

