void built(int start,int end,int index)
{
	if(start==end)
	{
		tree[index]=0;
		return;
	}
	int mid=(start+end)/2;
	built(start,mid,2*index);
	built(mid+1,end,2*index+1);
	tree[2*index]=0;
	tree[2*index+1]=0;
}
ll query(int start,int end,int index,int l,int r)
{
//	cout<<start<<" "<<end<<endl;
	if(start>r || end<l)return 0LL;
	if(start>=l && end<=r)return tree[index];
	int mid=(start+end)/2;
	return max(query(start,mid,2*index,l,r),query(mid+1,end,2*index+1,l,r));
}
void update(int start,int end,int index,int f,ll val)
{
	if(start==end)
	{
		tree[index]=val;
		return;
	}
	int mid=(start+end)/2;
	if(mid>=f)update(start,mid,2*index,f,val);
	else update(mid+1,end,2*index+1,f,val);
	tree[index]=max(tree[2*index],tree[2*index+1]);
}
