        tree[node]+=val;
    }
    else
    {
        in m=(s+e)/2;

        if(s<=ind&&ind<=m)
        update(2*node,s,m,ind,val);
        else
        update(2*node+1,m+1,e,ind,val);

        tree[node]=max(tree[2*node],tree[2*node+1]);
