pair<int, long long> tree[4 * maxn];

void update(int in, int l, int r, int h, const pair<int, long long> &val) {
	tree[in] = max(tree[in], val);
	if(l==r) {
		return;
	}
	int mid = (l+r)/2;
	if(h<=mid) {
		update(2*in, l, mid, h, val);
	} else {
		update(2*in+1, mid+1, r, h, val);
	}
}

pair<int, long long> query(int in, int l, int r, int ql, int qr) {
	if(ql<=l && r<=qr) {
		return tree[in];
	}
	int mid = (l+r)/2;
	if(qr<=mid) {
		return query(2*in, l, mid, ql, qr);
	}
	if(ql>mid) {
		return query(2*in+1, mid+1, r, ql, qr);
	}
	return max(
		query(2*in, l, mid, ql, qr),
		query(2*in+1, mid+1, r, ql, qr)
	);
}

