int lowbit(int x) {
    return x & (-x);
}

void update(int x, long long v) {
    bit[x] = v;
    for (int i = 1; i < lowbit(x); i <<= 1) {
        bit[x] = max(bit[x], bit[x - i]);
    }
}

long long query(int l, int r) {
    long long ans = 0;
    while (l <= r) {
        ans = max(bit[r--], ans);
        while (r - lowbit(r) >= l) {
            ans = max(ans, bit[r]);
            r -= lowbit(r);
        }
    }
    return ans;
}

