    while(x>1){
        if(x%2 == 1){
            max_self(best, tree[x-1]);
        }
        x /=2;
    }
    dp[h[k]] = best + a[k];
    for(int i=base+h[k]; i>= 1; i /=2){
        max_self(tree[i], dp[h[k]]);
