// DP + セグメントツリー（RMQ）の問題
// DPテーブルは、「左からi本目までの花を考慮したときに、i番目の花を必ず残す場合の価値の最大値」
// 自分より左にあって、かつ高さが自分より低いものの中から最大値を選ぶ必要がある。それと自分自身の価値を足し合わせたものがDPテーブルの値になる。
// 高さhが低い順にDPテーブルを埋めていけば良い。DPテーブルの初期値を0にすることで、高さが注目している要素より大きいものは無視できるようになる。
ll dp[400004];

void update(ll i, ll x) {
    dp[i] = x;
    while (i > 0) {
        i = (i - 1) / 2;
        dp[i] = max(dp[i*2+1], dp[i*2+2]);
    }
}

// [a, b) の区間に対するクエリについて
// ノード k （区間 [l, r) 担当）が答える
ll query(ll a, ll b, ll k, ll l, ll r) {
    if (r <= a || b <= l) return 0; // 区間がかぶらない場合単位元を返す
    if (a <= l && r <= b) return dp[k]; // 区間が完全に被っている場合
    else {
        ll c1 = query(a, b, 2 * k + 1, l, (l + r) / 2);
        ll c2 = query(a, b, 2 * k + 2, (l + r) / 2, r);
        return max(c1, c2);
    }
}

