	if(toUpdate <= mid) update(2*index,l,mid,toUpdate,v);
	else update(2*index+1,mid+1,r,toUpdate,v);
	seg[index] = max(seg[2*index] ,seg[2*index+1]);
}
ll query(int index,int l,int r,int L,int R){
	if(R < l || L > r) return 0;
	if(l>=L && r<= R) return seg[index];
	return max(query(2*index,l,(l+r)>>1,L,R)
	,query(2*index +1 , ((l+r)>>1) +1 ,r,L,R));
}

