void update(int i, long long v){
	tree[i+M+1] = v;
	i = i+M+1;
	for(int k = i/2; k >= 1; k /= 2){
		tree[k] = max(tree[2*k], tree[2*k+1]);	
	}
}

void max_self(ll& a, ll b){
	a = max(a, b);	
}

ll Query(int a, int b){
	ll r = 0;
	a += (M+1);
	b += (M+1);
	while(a <= b){
		if(a%2 == 1) max_self(r, tree[a++]);
		if(b%2 == 0) max_self(r, tree[b--]);
		a /= 2; b /= 2; 	
	}
	return r;
}

