long long int maximum(int a,int b,int curr,long long int z)
{
	if(a > z) return 0;
	if(b <= z) return dp[curr];
	if(b > a) 
	{
		int mid = (a + b)/2;
		int x = maximum(a , mid , 2*curr + 1 , z); 
		int y = maximum(mid + 1, b , 2*curr + 2 , z);
		return max(x,y);
	}
	return 0;
}

void update(int curr,int a,int b,long long int z,int i)
{
	// cout<<a<<" "<<b<<" "<<i<<endl;
	if(a > i - 1 or b < i - 1){ return ;}
	dp[curr] = max(z,dp[curr]);
	if(b > a)
	{
		update(2*curr + 1 , a, (a + b)/2 , z,i);
		update(2*curr + 2, (a + b)/2 + 1, b,z,i);
	}
}

void fn(int i)
{
	long long int z = maximum(0 ,n - 1, 0 , h[i] - 1) + a[i];
	update(0,0,n - 1,z,h[i]);
