class SegmentTree {
  public:
    explicit SegmentTree(int n) : n_(n), v_(4 * n + 1, 0) {}

    ll query(int b, int e) {
      return query_aux(1, 1, n_, b, e);
    }

    void update(int ind, ll value) {
      update_aux(1, 1, n_, ind, value);
    }

  private:
    ll query_aux(int node, int lo, int hi, int b, int e) {
      if (e < lo || b > hi) return 0;
      if (b <= lo && hi <= e) return v_[node];

      int med = (lo + hi) / 2;
      return max(query_aux(2 * node, lo, med, b, e),
                 query_aux(2 * node + 1, med + 1, hi, b, e));
    }

    void update_aux(int node, int lo, int hi, int ind, ll value) {
      if (ind < lo || ind > hi) return;
      if (lo == hi) {
        v_[node] = value;
        return;
      }

      int med = (lo + hi) / 2;
      update_aux(2 * node, lo, med, ind, value);
      update_aux(2 * node + 1, med + 1, hi, ind, value);
      v_[node] = max(v_[2 * node], v_[2 * node + 1]);
    }

    int n_;
    vector<ll> v_;
};

