void upd(ll v,ll l,ll r,ll pos,ll val){
    if(pos<l or pos>r) return;
    if(l==r and l==pos){
        tree[v]+=val;
        return;
    }
    ll mid=(l+r)>>1;
    upd(2*v,l,mid,pos,val);
    upd(2*v+1,mid+1,r,pos,val);
    tree[v]=max(tree[2*v],tree[2*v+1]);
}
ll rec(ll v,ll l,ll r,ll ql,ll qr){
