void update(int l, int r, int ai, int i, lli val){
	if(l > ai or r < ai) return;
	if(l == r and l == ai){
		max_self(st[i], val);
		return;
	}
	update(l, mid, ai, i*2, val);
	update(mid+1, r, ai, i*2+1, val);
	st[i] = max(st[i*2], st[i*2+1]);
}

// always prefix
lli query(int l, int r, int ar, int i){
	if(l > ar) return 0;
	if(r <= ar) return st[i];
	return max(query(l, mid, ar, i*2), query(mid+1, r, ar, i*2+1));
}

