ll recur(int pos, ll height) {
    ll &ret = dp[height];
    if(ret != -1)
        return ret;

    int nxtPos;
    while(pos != -1) {
        int nxtPos = nxtBigger[pos];
        if(nxtPos == -1) break;
        ret = max(ret, (ll)recur(nxtPos, h[nxtPos])+a[nxtPos]);
        pos = nxtPos;
    }

    return ret;
}


