class SegmentTree {
public:
	int N;
	vector<ll> maximum, delta;

	SegmentTree() {}

	SegmentTree(int N) {
		this->N = N;
		maximum = vector<ll>(4 * N + 1);
	}

	void update(int l, int r, ll val) {update(1, 0, N - 1, l, r, val);} //inclusive range

	ll query(int l, int r) {return query(1, 0, N - 1, l, r);} //inclusive range

	void pull(int i) {
		maximum[i] = max(maximum[2 * i], maximum[2 * i + 1]);
	}

	void update(int i, int lo, int hi, int l, int r, ll val) {
		if (r < lo || hi < l) return;
		if (l <= lo && hi <= r) {
			maximum[i] = max(maximum[i], val);
			return;
		}

		int m = (lo + hi) / 2;
		update(2 * i, lo, m, l, r, val);
		update(2 * i + 1, m + 1, hi, l, r, val);

		pull(i);
	}

	ll query(int i, int lo, int hi, int l, int r) {
		if (r < lo || hi < l) return 0;
		if (l <= lo && hi <= r) {
			return maximum[i];
		}

		int m = (lo + hi) / 2;
		ll maxLeft = query(2 * i, lo, m, l, r);
		ll maxRight = query(2 * i + 1, m + 1, hi, l, r);

		pull(i);

		return max(maxLeft, maxRight);
	}
};

