  scanf("%d",&n);
  for ( i = 0; i < n; i++ ) scanf("%d",&H[i]);
  for ( i = 0; i < n; i++ ) scanf("%d",&V[i]);

  N = init(n);

  printf("%ld\n",flower(n,N));

  return 0;
}

