typedef long long int int64;

#define MAX(a,b) ((a)>(b)?(a):(b))

void update(int64 *bit,int index,int64 v){
  int n=bit[0];
  for(int i=index;i<=n;i+=i&-i) bit[i]=MAX(bit[i],v);
}

int64 getMax(int64 *bit,int index){
  int64 res=0;
  for(int i=index;i>0;i-=i&-i) res=MAX(res,bit[i]);
  return res;
}

