ll seg[1151151],seg_t=1;
void segmake(ll n, ll a[n]){
    while(seg_t<n) seg_t*=2;
    ll t=seg_t;
    rep(i,0,t) seg[t-1+i]=i<n?a[i]:-INF;
    while(t/=2) rep(i,0,t) seg[t+i-1]=max2(seg[2*(t+i)],seg[2*(t+i)-1]); 
}
