ll (*seg_ope[3])(ll,ll);
ll (*seg_def[3])(void);

ll seg[3][351551],seg_size=1;

ll seg_def_max(){ return -INF; }
ll seg_def_min(){ return INF; }
ll seg_def_sum(){ return 0; }
ll seg_def_gcd(){ return 0; }

ll seg_ope_max(ll a, ll b){ return max2(a,b); }
ll seg_ope_min(ll a, ll b){ return min2(a,b); }
ll seg_ope_sum(ll a, ll b){ return a+b; }
ll seg_ope_gcd(ll a, ll b){ return gcd(a,b); }


void seg_make(int seg_num, int n, ll a[]){
    while(seg_size<n) seg_size*=2;
    ll t=seg_size;
    rep(i,0,t){
        if(i<n) seg[seg_num][t-1+i]=a[i]; 
        else    seg[seg_num][t-1+i]=seg_def[0]();        
    }
    while(t/=2) 
        rep(i,0,t)
            seg[seg_num][t+i-1] = seg_ope[seg_num](seg[seg_num][2*(t+i)],
            seg[seg_num][2*(t+i)-1]);
}

ll seg_query_inside(int seg_num, int ql, int qr, int x, int l, int r){
    if( l>=ql && r<=qr ) return seg[seg_num][x];
    if( l>qr || r<ql ) return seg_def[seg_num]();
    return  seg_ope[seg_num](
                seg_query_inside(seg_num,ql,qr,2*x+1,l,(l+r)/2),
                seg_query_inside(seg_num,ql,qr,2*x+2,(l+r)/2+1,r)
            );
}
ll seg_query(int seg_num, int l, int r){ 
    return seg_query_inside(seg_num,l,r,0,0,seg_size-1);
}

void seg_update(int seg_num, int x, ll val){
    ll c=seg_size-1+x;
    seg[seg_num][c]=val;
    while(c>0){
        c--; c/=2;
        seg[seg_num][c] = seg_ope[seg_num](seg[seg_num][2*(c+1)],
        seg[seg_num][2*(c+1)-1]);
    }
}

