typedef struct {
	seg_tree_valtype *dat;
	int n; //要素数
	int N; //要素数以上の最小の2のべき乗
	seg_tree_valtype (*f)(seg_tree_valtype x, seg_tree_valtype y);//演算
	seg_tree_valtype e;//演算の単位元
}seg_tree;

//要素n, 演算f, 単位元eのsegment_treeを作る
seg_tree *make_seg_tree(int n, seg_tree_valtype (*f)(seg_tree_valtype x, seg_tree_valtype y), seg_tree_valtype e){
	seg_tree *t = (seg_tree *)malloc(sizeof(seg_tree));
	int N, i;
	for(N = 1; N < n; N *= 2){}
	t->dat = (seg_tree_valtype *)malloc(sizeof(seg_tree_valtype) * (2 * N - 1));
	for(i = 0; i < 2 * N - 1; i++){
		t->dat[i] = e;
	}
	t->n = n;
	t->N = N;
	t->f = f;
	t->e = e;
	return t;
}

//i番目の要素を返す
seg_tree_valtype look_val(int i, seg_tree *t){
	if(i < 0 || t->n <= i){
		printf("In function 'look_val':\nrefered out of array\n");
	}
	return t->dat[i + t->N - 1];
}

//i番目の値をxに更新する
void update(int i, seg_tree_valtype val, seg_tree *t){
	if(i < 0 || t->n <= i){
		printf("In function 'update':\nrefered out of array\n");
	}
	i += t->N - 1;
	t->dat[i] = val;
	while(i > 0){
		i = (i - 1) / 2;
		t->dat[i] = (t->f)(t->dat[2 * i + 1], t->dat[2 * i + 2]);
	}
}

seg_tree_valtype query_sub(int a, int b, int k, int l, int r, seg_tree *t){
	if(r <= a || b <= l){
		return t->e;
	}
	else if(a <= l && r <= b){
		return t->dat[k];
	}
	else{
		int h = (l + r) / 2;
		seg_tree_valtype vl = query_sub(a, b, 2 * k + 1, l, h, t);
		seg_tree_valtype vr = query_sub(a, b, 2 * k + 2, h, r, t);
		return (t->f)(vl, vr);
	}
}

//[a, b)の区間に対しての演算の結果を返す
seg_tree_valtype query(int a, int b, seg_tree *t){
	if(a < 0 || b < 0 || t->n < a || t->n < b){
		printf("In function 'query':\nrefered out of array\n");
	}
	if(a >= b){
		return t->e;
	}
	else{
		return query_sub(a, b, 0, 0, t->N, t);
	}
}

