#include<inttypes.h>

typedef int32_t i32;
typedef int64_t i64;

void update (i64 *bit, i32 x, i64 v) {
  i32 n = bit[0];
  for (i32 i = x; i <= n; i += i & -i) {
    if (bit[i] < v) {
      bit[i] = v;
    }
  }
}

i64 find (i64 *bit, i32 x) {
  i64 max = 0;
  for (i32 i = x; i > 0; i ^= i & -i) {
    if (max < bit[i]) {
      max = bit[i];
    }
  }
  return max;
}

void run (void) {
  i32 n;
  scanf ("%" SCNi32, &n);
  i32 *h = (i32 *) calloc (n, sizeof (i32));
  for (i32 i = 0; i < n; ++i) {
    scanf ("%" SCNi32, h + i);
  }
  i64 *bit = (i64 *) calloc (n + 1, sizeof (i64));
  bit[0] = n;
  for (i32 i = 0; i < n; ++i) {
    i32 a;
    scanf ("%" SCNi32, &a);
    i64 v = a + find (bit, h[i]);
    update (bit, h[i], v);
  }
  printf ("%" PRIi64 "\n", find (bit, n));
}

int main (void) {
  run();
