void update_BIT(int N, long long BIT[], int i, long long k)
{
	while (i <= N) {
		if (k > BIT[i]) BIT[i] = k;
		i += (i & -i);
	}
}

long long max_BIT(long long BIT[], int r)
{
	long long max = 0;
	while (r > 0) {
		if (BIT[r] > max) max = BIT[r];
		r -= (r & -r);
	}
	return max;
}

