//     if( l>qr || r<ql ) return seg_def[seg_num]();
//     if( from>r || to<l ) return seg_def[seg_num]();

    return  S->op(
                seg_prod_inner(S,l,r,2*x+1,from,(from+to)/2),
                seg_prod_inner(S,l,r,2*x+2,(from+to)/2+1,to)
            );
