	}

	static long dp[];
	static long call(int i,int arr[],int w[]) {
		if(i<1)return 0;
		if(i==1)return w[i-1];
		if(dp[i]!=-1)return dp[i];
		long ans=0;

		for(int j=i-1;j>0;j--) {
			if(arr[j-1]<arr[i-1]) {
				ans=Math.max(ans,call(j,arr,w));

			}

		}

		return dp[i]=ans+w[i-1];





	}



