            while(index>1){
                if(index%2==1)
                    max = Math.max(max,tree[index-1]);
                index /=2;
            }
            dp[arr[i]] = max + p[i];
            int x = arr[i]+base;
            tree[x]=dp[arr[i]];
            while(x>0){
                x /=2;
                tree[x]  = Math.max(tree[2*x],tree[2*x +1]);
            }
        }
        long ans =0;
        for(long m : dp)
            ans = Math.max(m,ans);

        System.out.println(ans);
    }
}

