		      for(int i = 1; i <= n ; i++) {
		    	  int ht = Integer.parseInt(heights[i-1]);
		    	  dp[i] = query(ht-1) + Integer.parseInt(beautyLine[i-1]);
		    	  update(ht, dp[i], n);
		      }

		      long maxBeautySum = 0;

		      for(int i = 1; i <= n ; i++) {
		    	  maxBeautySum = Math.max(maxBeautySum, dp[i]);
