		    }

	}

	private static long query(int ht) {
		long answer = 0;
		while(ht > 0) {
			answer = Math.max(answer, bit[ht]);
			ht -= (ht&(-ht));
		}
		return answer;
	}

	private static void update(int ht, long val, int n) {
		while(ht <= n) {
			bit[ht] = Math.max(val, bit[ht]);
			ht += (ht&(-ht));
		}
	}

