    @FunctionalInterface
    interface LongOperator {
        long merge(long a, long b);
    }

    static class bit {
        LongOperator op;
        int n;
        long bit[];

        bit(int size, LongOperator operator) {
            bit = new long[n = size + 1];
            op = operator;
        }

        bit(long[] arr, LongOperator operator) {
            bit = new long[(n = arr.length + 1)];
            op = operator;
            for (int i = 0; i < n - 1; ++i) upd(i, arr[i]);
            ++n;
        }

        void upd(int i, long x) {
            ++i;
            while (i < n) {
                bit[i] = op.merge(bit[i], x);
                i += i & (-i);
            }
        }

        long qry(int i) {
            long ans = 0;
            while (i > 0) {
                ans = op.merge(ans, bit[i]);
                i -= i & (-i);
            }
            return ans;
        }
