		{
			//System.out.print(query(tree, 0, n, 0, h[i], 0)+" ");
			dp[h[i]] = Math.max(dp[h[i]], a[i] + query(tree, 0, n, 0, h[i], 0));
			update(tree, dp[h[i]], 0, n, 0, h[i]);
		}
