class SegmentTree {
    private long[] maxSegmentTree;
    private int n;

    public SegmentTree(long[] arr) {
        n = arr.length;
        maxSegmentTree = new long[2 * n];
        /*
        for (int i = n; i < 2 * n; i++) {
            maxSegmentTree[i] = arr[i - n];
        }
        for (int i = n - 1; i > 0; i--) {
            maxSegmentTree[i] = Math.max(maxSegmentTree[2 * i], maxSegmentTree[2 * i + 1]);
        }
        */
    }

    public void update(int i, long val) {
        i += n;
        maxSegmentTree[i] = val;

        while (i > 1) {
            i /= 2;
            maxSegmentTree[i] = Math.max(maxSegmentTree[2 * i], maxSegmentTree[2 * i + 1]);
        }
    }

    public long getMax(int left, int right) {
        left += n;
        right += n;
        long max = 0;

        while (left < right) {
            if ((left & 1) == 1) {
                max = Math.max(max, maxSegmentTree[left]);
                left++;
            }

            if ((right & 1) == 0) {
                max = Math.max(max, maxSegmentTree[right]);
                right--;
            }

            left >>= 1;
            right >>= 1;
        }

        if (left == right) max = Math.max(max, maxSegmentTree[left]);

        return max;
    }

    public long getItem(int index) {
        return maxSegmentTree[index];
    }
}

import java.util.Arrays;

class SegmentTreeRMQL {
  public int M, H, N;
  public long[] st;

  public SegmentTreeRMQL(int n) {
    N = n;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new long[M];
    Arrays.fill(st, 0, M, Long.MAX_VALUE / 2);
  }

  public SegmentTreeRMQL(long[] a) {
    N = a.length;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new long[M];
    for (int i = 0; i < N; i++) {
      st[H + i] = a[i];
    }
    Arrays.fill(st, H + N, M, Long.MAX_VALUE);
    for (int i = H - 1; i >= 1; i--)
      propagate(i);
  }

  public void update(int pos, long x) {
    st[H + pos] = x;
    for (int i = (H + pos) >>> 1; i >= 1; i >>>= 1)
      propagate(i);
  }

  private void propagate(int i) {
    st[i] = Math.min(st[2 * i], st[2 * i + 1]);
  }

  public long minx(int l, int r) {
    long min = Long.MAX_VALUE;
    if (l >= r)
      return min;
    while (l != 0) {
      int f = l & -l;
      if (l + f > r)
        break;
      long v = st[(H + l) / f];
      if (v < min)
        min = v;
      l += f;
    }

    while (l < r) {
      int f = r & -r;
      long v = st[(H + r) / f - 1];
      if (v < min)
        min = v;
      r -= f;
    }
    return min;
  }

  public long min(int l, int r) {
    return l >= r ? 0 : min(l, r, 0, H, 1);
  }

  private long min(int l, int r, int cl, int cr, int cur) {
    if (l <= cl && cr <= r) {
      return st[cur];
    } else {
      int mid = cl + cr >>> 1;
      long ret = Long.MAX_VALUE;
      if (cl < r && l < mid) {
        ret = Math.min(ret, min(l, r, cl, mid, 2 * cur));
      }
      if (mid < r && l < cr) {
        ret = Math.min(ret, min(l, r, mid, cr, 2 * cur + 1));
      }
      return ret;
    }
  }


}


public class Main {


  private static void solve() {
    int n = ni();
    int[] h = na(n);
    int[] a = na(n);

