			a[i] = Integer.parseInt(st.nextToken());
		}

		long[] dp = new long[N+1];
		bit = new int[N+1];

		dp[0] = a[0];
		for(int i=1; i<N; i++) {
			dp[i] = query(h[i]) + a[i];
			update(a[i], h[i]);
		}

		long ans = 0;
		for(int i=1; i<=N; i++) {
			ans = Math.max(ans, dp[i]);
		}
		System.out.println(ans);

	}
}

