        public long get(int i) {
            long rs = 0;
            while(i>0) {
                rs = Math.max(rs, f[i]);
                i -= i & (-i);
            }
            return rs;
        }
    }


    void solve(InputReader in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        int[] h = new int[n];
        int[] a = new int[n];
        for(int i=0; i<n; i++) {
            h[i] = in.nextInt();
        }
        for(int i=0; i<n; i++) {
            a[i] = in.nextInt();
        }
        BIT bit = new BIT(n);
        long rs = 0;
        for(int i=0; i<n; i++) {
            long x = bit.get(h[i]-1);
            x += a[i];
            rs = Math.max(rs, x);
            bit.update(h[i], x);
        }
        out.println(rs);
    }


