		if(low==high) {
			st[index]=v;
		}
		else {
			int middle=(low+high)/2;
			if(pos<=middle) u1(2*index+1,low,middle,pos,v);
			else u1(2*index+2,middle+1,high,pos,v);
			st[index]=Math.max(st[2*index+1],st[2*index+2]);
		}
	}


