public class Main {
	private static final long MOD = 1000000007;
	InputStream is;
	PrintWriter out;
	String INPUT = "";

	int n;
	int h[];
	int v[];

	void solve() {
		n = ni();
		h = na(n);
		v = na(n);

		long ans = 0;
		TreeMap<Integer, Long> m = new TreeMap<Integer, Long>();
		for (int i = 0; i < n; i++) {
			Entry<Integer, Long> e = m.floorEntry(h[i]);
			long v0 = (e == null ? 0 : e.getValue()) + v[i];
			while ((e = m.ceilingEntry(h[i] + 1)) != null && e.getValue() < v0)
				m.remove(e.getKey());
			m.put(h[i], v0);
			ans = Math.max(ans, v0);
		}

		out.println(ans);
	}

	StringBuffer sb = new StringBuffer();

	void run() throws Exception {
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);
		Thread t = new Thread(null, null, "~", Runtime.getRuntime().maxMemory()) {
			@Override
			public void run() {
				long s = System.currentTimeMillis();
				solve();
				out.flush();
				if (!INPUT.isEmpty())
					tr(System.currentTimeMillis() - s + "ms");
			}
		};
		t.start();
		t.join();

		// long s = System.currentTimeMillis();
