public class Main {

	static int N;
	static long[] bit;

	static void update(int x, long v){
		while(x <= N) {
			bit[x] = Math.max(bit[x], v);
			x += x&-x;
		}
	}

	static long query(int i) {
		long ans = 0;
		while(i > 0) {
			ans = Math.max(ans, bit[i]);
			i -= i&-i;
		}
		return ans;
	}

