	static void updateBIT(long bit[], int idx, long val)
	{
		while(idx<bit.length)
		{
			bit[idx]=Math.max(bit[idx], val);
			idx+=(idx&(-idx));
		}
	}

	static long queryBIT(long bit[], int idx)
	{
		long ans=0;
		while(idx>0)
		{
			ans=Math.max(ans, bit[idx]);
			idx-=(idx&(-idx));
		}
		return ans;
	}

