class Main{
  public static long solve2(int[] h, int[] b){
        long ans = Integer.MIN_VALUE;
        int[] dp = new int[h.length];
        for(int i = 0; i < b.length; i++){
            dp[i] = b[i];
        }
        for(int i = 1; i < h.length; i++){
            for(int j = 0; j < i; j++){
                if(h[i] > h[j] && dp[i] < dp[j]+b[i]){
                    dp[i] = b[i] + dp[j];
                }
            }
        }
        //System.out.println(Arrays.toString(dp));
        for(int i = 0; i < b.length; i++){
            if(ans < dp[i]){
                ans = dp[i];
            }
        }
        return ans;
    }
