public class Main {

    static int N;
    static int[] H, A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        H = sc.nextIntArray(N);
        A = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static long solve() {
        MaxBIT bit = new MaxBIT(N+10);

        long ans = 0;
        for (int i = 0; i < N; i++) {
            long v = bit.get(H[i]-1) + A[i];
            ans = Math.max(v, ans);
            bit.set(H[i], v);
        }
        return ans;
    }

    static class MaxBIT {
        int n;
        long[] bit;

        public MaxBIT(int n) {
            this.n = n;
            this.bit = new long[n+1];
        }

        void set(int i, long v) {
            i++; // to 1 index

            while( i <= n ) {
                bit[i] = Math.max(bit[i], v);
                i += i & -i;
            }
        }

        long get(int i) {
            i++; // to 1 index

            long ret = -1;
            while(i > 0) {
                ret = Math.max(bit[i], ret);
                i -= i & -i;
            }
            return ret;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

import java.util.*;
import java.io.PrintWriter;
public class Main{
	public static void main(String[] args){
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		long[] dp=new long[n];
		int[] h=new int[n];
		int[] a=new int[n];
		for(int i=0; i<n; i++){
			h[i]=sc.nextInt()-1;
		}
		for(int i=0; i<n; i++){
			a[i]=sc.nextInt();
		}
		SegTree st=new SegTree(n);
		for(int i=0; i<n; i++){
			dp[i]=a[i]+st.query(0,h[i]+1);
			st.set(h[i],dp[i]);
		}
		System.out.println(dp[n-1]);
	}
	static class SegTree{
		int n=1;
		long[] v;

		public SegTree(int n) {
			while(this.n<n)this.n*=2;
			v=new long[2*this.n-1];
		}

		void set(int k,long val) {
			k+=n-1;
			v[k]=val;
			while(k>0) {
				k=(k-1)/2;
				v[k]=Math.max(v[2*k+1],v[2*k+2]);
			}
		}
		//bをプラス1
		long query(int a,int b) {
			return query(0,n,a,b,0);
		}

		long query(int l,int r,int a,int b,int k) {
			if(r<=a||b<=l)return 0;
			else if(a<=l&&r<=b)return v[k];
			else {
				long vl=query(l,(l+r)/2,a,b,2*k+1);
				long vr=query((l+r)/2,r,a,b,2*k+2);
				return Math.max(vl,vr);
			}
		}
	}
}

