    public static long memo(int[] flowers, int[] price, int n, int prev, HashMap<String, Long> memo){
        if(n < 0)
            return 0;
        if(memo.containsKey(prev+" "+n)){
       // System.out.println("used");
            return memo.get(prev+" "+n);
        }
        long ans = Long.MIN_VALUE;
        if(prev == -1 || flowers[prev] > flowers[n])
        ans = Math.max(ans, price[n] + memo(flowers,price,n-1,n,memo));
        ans = Math.max(ans, 0 + memo(flowers,price,n-1,prev,memo));

        memo.put(prev+" "+n,ans);
        return memo.get(prev+" "+n);
    }

    public static long solve(int[] flowers, int[] price){

        long[] dp = new long[flowers.length];
        for(int i = 0; i < flowers.length; i++)
            dp[i] = price[i];

        for(int i = 0; i < price.length; i++){
            for(int j = i-1; j >= 0; j--){
                if(flowers[j] < flowers[i]){
                    long current = dp[j] + price[i];
                    if(dp[i] < current)
                        dp[i] = current;
                }
            }
        }

        long ans = Long.MIN_VALUE;
        for(long i : dp)
            ans = Math.max(ans,i);
        return ans;
    }


