public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int count = scanner.nextInt();
        int[] heights = new int[count];
        int[] values = new int[count];
        for (int i = 0; i < count; ++i) {
            heights[i] = scanner.nextInt();
        }
        for (int i = 0; i < count; ++i) {
            values[i] = scanner.nextInt();
        }

        FenwickTree fenwickTree = new FenwickTree(count);

        for (int i = 0; i < count; ++i) {
            long value = fenwickTree.max(heights[i] - 1) + values[i];
            fenwickTree.update(heights[i] - 1, value);
        }
        System.out.println(fenwickTree.max(count - 1));
    }

    public static class FenwickTree {
        private final List<Long> values;

        public FenwickTree(int size) {
            this.values = new ArrayList<>(Collections.nCopies(size, 0L));
        }

        long max(int right) {
            long result = 0;
            for (int i = right; i >= 0; i = (i & (i + 1)) - 1) {
                result = Math.max(result, values.get(i));
            }
            return result;
        }

        void update(int pos, long value) {
            for (int i = pos; i < values.size(); i = i | (i + 1)) {
                values.set(i, Math.max(values.get(i), value));
            }
        }
    }
}

import java.util.Arrays;

class SegmentTreeRMQL {
  public int M, H, N;
  public long[] st;

  public SegmentTreeRMQL(int n) {
    N = n;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new long[M];
    Arrays.fill(st, 0, M, Long.MAX_VALUE);
  }

  public SegmentTreeRMQL(long[] a) {
    N = a.length;
    M = Integer.highestOneBit(Math.max(N - 1, 1)) << 2;
    H = M >>> 1;
    st = new long[M];
    for (int i = 0; i < N; i++) {
      st[H + i] = a[i];
    }
    Arrays.fill(st, H + N, M, Long.MAX_VALUE);
    for (int i = H - 1; i >= 1; i--)
      propagate(i);
  }

  public void update(int pos, long x) {
    st[H + pos] = x;
    for (int i = (H + pos) >>> 1; i >= 1; i >>>= 1)
      propagate(i);
  }

  private void propagate(int i) {
    st[i] = Math.min(st[2 * i], st[2 * i + 1]);
  }

  public long minx(int l, int r) {
    long min = Long.MAX_VALUE;
    if (l >= r)
      return min;
    while (l != 0) {
      int f = l & -l;
      if (l + f > r)
        break;
      long v = st[(H + l) / f];
      if (v < min)
        min = v;
      l += f;
    }

    while (l < r) {
      int f = r & -r;
      long v = st[(H + r) / f - 1];
      if (v < min)
        min = v;
      r -= f;
    }
    return min;
  }

  public long min(int l, int r) {
    return l >= r ? 0 : min(l, r, 0, H, 1);
  }

  private long min(int l, int r, int cl, int cr, int cur) {
    if (l <= cl && cr <= r) {
      return st[cur];
    } else {
      int mid = cl + cr >>> 1;
      long ret = Long.MAX_VALUE;
      if (cl < r && l < mid) {
        ret = Math.min(ret, min(l, r, cl, mid, 2 * cur));
      }
      if (mid < r && l < cr) {
        ret = Math.min(ret, min(l, r, mid, cr, 2 * cur + 1));
      }
      return ret;
    }
  }


}


