	static class data{
		public long sum;

		data(long val){
		    this.sum = val;
		}

		data(){}

		data combine(data l, data r) {
		    data res = new data();
		    res.sum = max(l.sum , r.sum);
		    return res;
		}
	}

	static class Seg_Tree extends data{
		public int n;
		data [] seg;

		Seg_Tree(int sz){
			this.n = sz;
			seg = new data[4*n+4];
		}

		void build(long a[], int v, int tl, int tr) {
		    if (tl == tr) {
		        seg[v] = new data(a[tl]);
		    } else {
		        int tm = (tl + tr) / 2;
		        build(a, v*2, tl, tm);
		        build(a, v*2+1, tm+1, tr);
		        seg[v] = combine(seg[v*2],seg[v*2+1]);
		    }
		}

		void update(int v, int tl, int tr, int pos, long new_val) {
		    if (tl == tr) {
		        seg[v] = new data(new_val);
		    } else {
		        int tm = (tl + tr) / 2;
		        if (pos <= tm)
		            update(v*2, tl, tm, pos, new_val);
		        else
		            update(v*2+1, tm+1, tr, pos, new_val);
		        seg[v] = combine(seg[v*2],seg[v*2+1]);
		    }
		}

		data query(int v, int tl, int tr, int l, int r) {
		    if (l > r) 
		        return new data(0);
		    if (l == tl && r == tr) 
		        return seg[v];
		    int tm = (tl + tr) / 2;
		    return combine(query(v*2, tl, tm, l, min(r, tm)),query(v*2+1, tm+1, tr, max(l, tm+1), r));
		}
	}

	static class Bit_Tree{
		static int n;
		static int [] bit;

		Bit_Tree(int sz){
			Bit_Tree.n = sz;
			Bit_Tree.bit = new int[n+1];
		}

		static int child(int x) {
			return x + (x & (-x));
		}

		static int parent(int x) {
			return x - (x & (-x));
		}

		static void build(int [] a) {
			for(int i = 0; i<a.length; i++) {
				int start = i+1;
				while(start <= n) {
					bit[start] += a[i];
					start = child(start);
				}
			}
		}

		static void update(int idx,int new_val) {
			idx += 1;
			while(idx <= n) {
				bit[idx] += new_val;
				idx = child(idx);
			}
		}

		static int query(int right) {
			int res = 0;
			while(right > 0) {
				res += bit[right];
				right = parent(right);
			}
			return res;
		}

		static int query(int left,int right) {
			return query(right) - query(left-1);
		}
	}
}

import java.io.*;
import java.util.*;

public class Main {
  private static long solve(int n, int[] hs, int[] as) {
    TreeMap<Integer, Long> map = new TreeMap<>();
    map.put(0, 0L);
    for (int i = 0; i < n; i++) {
      int height = hs[i];
      long aSum = map.lowerEntry(height).getValue() + as[i];
      map.put(height, aSum);
      while (true) {
        Map.Entry<Integer, Long> higherEntry = map.higherEntry(hs[i]);
        if (higherEntry == null || higherEntry.getValue() > aSum) {
          break;
        }
        map.remove(higherEntry.getKey());
      }
    }
    return map.lastEntry().getValue();
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[] hs = reader.nextInt(n);
    int[] as = reader.nextInt(n);
    out.println(solve(n, hs, as));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader reader;
  private StringTokenizer tokenizer;

  ContestReader(InputStream in) {
    reader = new BufferedReader(new InputStreamReader(in));
  }

  public String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  public char nextChar() {
    return next().charAt(0);
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }

  public String[] next(int n) {
    String[] array = new String[n];
    for (int i = 0; i < n; i++) {
      array[i] = next();
    }
    return array;
  }

  public char[] nextChar(int n) {
    char[] array = new char[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextChar();
    }
    return array;
  }

  public int[] nextInt(int n) {
    int[] array = new int[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextInt();
    }
    return array;
  }

  public long[] nextLong(int n) {
    long[] array = new long[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextLong();
    }
    return array;
  }

