	static class Task {

		public void solve(int testNumber, FastReader sc, PrintWriter pw) {
			int n = sc.nextInt();
			int[][] x = new int[2][n];
			for(int i=0;i<n;i++){
				x[0][i]=sc.nextInt();
			}
			for(int i=0;i<n;i++){
				x[1][i]=sc.nextInt();
			}
			long max = 0;
			segt s = new segt(200004);
			for(int i=0;i<n;i++){
				long ss = s.get_max(1,0,200003,0,x[0][i])+x[1][i];
				max=Math.max(ss,max);
				s.update(1,0,200003,x[0][i],ss);
			}
			pw.println(max);
		}
	}

	static class segt {
		long[] t;
		public segt(int n) {
			t = new long[4*n];
		}
		void build(int a[], int v, int tl, int tr) {
			if (tl == tr) {
				t[v] = a[tl];
			} else {
				int tm = (tl + tr) / 2;
				build(a, v*2, tl, tm);
				build(a, v*2+1, tm+1, tr);
				t[v] = Math.max(t[v*2], t[v*2+1]);
			}
		}
		long get_max(int v, int tl, int tr, int l, int r) {
			if (l > r)
				return Integer.MIN_VALUE;
			if (l == tl && r == tr)
				return t[v];
			int tm = (tl + tr) / 2;
			return Math.max(get_max(v*2, tl, tm, l, Math.min(r, tm)),
					get_max(v*2+1, tm+1, tr, Math.max(l, tm+1), r));
		}
			void update(int v, int tl, int tr, int pos, long new_val) {
			if (tl == tr) {
				t[v] = new_val;
			} else {
				int tm = (tl + tr) / 2;
				if (pos <= tm)
					update(v*2, tl, tm, pos, new_val);
				else
					update(v*2+1, tm+1, tr, pos, new_val);
				t[v] = Math.max(t[v*2], t[v*2+1]);
			}
		}
	}
	static void shuffle(int[] a) {
		Random get = new Random();
		for (int i = 0; i < a.length; i++) {
