                public boolean isSpaceChar(int ch);
            }
        }
        class Pair{
            int le;
            int p;
            Pair(int leaves,int parent){
                le=leaves;
                p=parent;
            }
        }
        class SegmentTree{
            long s[];int n;
            SegmentTree(int length){
                n=length;

                s=new long[4*length+2];
               // createSegmentTreeUtil(a, 0, 0, a.length-1);
            }


            long getValue(int gl,int gr){
                return getValueUtil(0, 0, n-1, gl, gr);
            }
            long getValueUtil(int root,int l,int r,int gl,int gr){
                if(l>=gl&&r<=gr){
                    return s[root];
                }
                if(l>gr||r<gl){
                    return 0;
                }
                return Compare(getValueUtil(2*root+1, l, (l+r)/2, gl, gr), getValueUtil(2*root+2, (l+r)/2+1, r, gl, gr));
            }
            void update(long p,int k){
                updateUtil(p, k,0,0,n-1);
            }
            long updateUtil(long p,int k,int root,int l,int r){
                if(l==r&&l==k){
                    return s[root]=p;
                }
                else if(l>k||r<k)
                return s[root];
                else{
                    return s[root]=Compare(updateUtil(p, k, 2*root+1, l, (l+r)/2), updateUtil(p, k, 2*root+2,(l+r)/2+1,r ));
                }
            }
            long Compare(long a,long b){
                return Math.max(a, b);
            }
