        public class IntervalTreeDownUpMax
        {
            private readonly int n;

            private readonly long[] tree;

            public IntervalTreeDownUpMax(int count)
            {
                n = count;
                tree = new long[2 * n];
            }

            public long GetMax(int l, int r)
            {
                l += n;
                r += n + 1;
                long ans = 0;
                while (l < r)
                {
                    if ((l & 1) > 0)
                    {
                        ans = Math.Max(ans, tree[l++]);
                    }
                    if ((r & 1) > 0)
                    {
                        ans = Math.Max(ans, tree[--r]);
                    }
                    l >>= 1;
                    r >>= 1;
                }
                return ans;
            }

            public void Update(int pos, long newValue)
            {
                pos += n;
                tree[pos] = newValue;
                while (pos > 1)
                {
                    tree[pos >> 1] = Math.Max(tree[pos], tree[pos ^ 1]);
                    pos >>= 1;
                }
            }
        }

