        static public List<int> Slist() { return ReadLine().Split().Select(int.Parse).ToList(); }
        class lower_bound<T> : IComparer<T> where T : IComparable<T>
        {
            public int Compare(T x, T y) => 0 <= x.CompareTo(y) ? 1 : -1;
        }
        class upper_bound<T> : IComparer<T> where T : IComparable<T>
        {
            public int Compare(T x, T y) => 0 < x.CompareTo(y) ? 1 : -1;
        }
        class pair<T>
        {
            public T h { get; }
            public T lis { get; }
            public T i { get; }
            public T v { get; }
            public pair(T h, T lis, T i, T v)
            {
                this.h = h;
                this.lis = lis;
                this.i = i;
                this.v = v;
            }
        }

        static int N;
        static long[,,] dp;
        static readonly long Mod = 1000000000 + 7;
        static int[] H;
        static int[] A;
        static void Main(string[] args)
        {
            N = Sarray()[0];
            H = Sarray();
            A = Sarray();
            var hno = new List<pair<int>>();
            var lis = new List<int>();
            lis.Add(H[0]);
            hno.Add(new pair<int>(H[0], 0, 0,A[0]));
            for (var i = 1; i < N ; ++i)
            {
                var no = ~lis.BinarySearch(H[i], new lower_bound<int>());
                if (lis.Count <= no)
                    lis.Add(H[i]);
                else
                    lis[no] = H[i];
                hno.Add(new pair<int>(H[i], no, i, A[i]));
            }
            hno.Sort((l, r) => l.lis - r.lis);
            var dph = new long[N];
            for (var i = 0; i < N; ++i)
            {
                long max = 0L;
                for (var j = 0; j < i; ++j)
                {
                    if (hno[j].h < hno[i].h && hno[j].i < hno[i].i)
                        max = Max(dph[j], max);
                }
                dph[i] = max + hno[i].v;
            }
            WriteLine(dph.Max());
        }
    }
}

