class RMQ
{
	int N2;
	long[] segtree;
	public RMQ(int N) : this(new long[N]) { }
	public RMQ(long[] array)
	{
		N2 = 1;
		while (N2 < array.Length) N2 <<= 1;
		segtree = new long[2 * N2 - 1];
		for (var i = 0; i < 2 * N2 - 1; i++) segtree[i] = 0;
		for (var i = 0; i < array.Length; i++) segtree[i + N2 - 1] = array[i];
		for (var i = N2 - 2; i >= 0; i--) segtree[i] = Math.Max(segtree[2 * i + 1], segtree[2 * i + 2]);
	}
	public void Update(int index, long value)
	{
		index += N2 - 1;
		segtree[index] = value;
		while (index > 0)
		{
			index = (index - 1) / 2;
			segtree[index] = Math.Max(segtree[index * 2 + 1], segtree[index * 2 + 2]);
		}
	}
	public long this[int n] { get { return Max(n, n + 1); } set { Update(n, value); } }
	public long Max(int from, int to) => Max(from, to, 0, 0, N2);
	long Max(int from, int to, int node, int l, int r)
	{
		if (to <= l || r <= from) return 0;
		if (from <= l && r <= to) return segtree[node];
		return Math.Max(Max(from, to, 2 * node + 1, l, (l + r) >> 1), Max(from, to, 2 * node + 2, (l + r) >> 1, r));
	}
}

