using System;
using System.Linq;
using System.Collections.Generic;

namespace AtCoder.DP
{
    public class SegmentTree<T>
    {
        private readonly T ex;

        private readonly int n;

        private readonly int offset;

        private readonly T[] node;

        private readonly Func<T, T, T> func;

        public T this[int index] => node[offset + index];

        public SegmentTree(int m, Func<T, T, T> func, T ex)
        {
            this.func = func;
            this.ex = ex;

            n = 1;
            while (n < m)
                n *= 2;
            offset = n - 1;
            node = new T[n * 2 - 1];
            for (int i = 0; i < node.Length; i++)
                node[i] = ex;
        }

        public SegmentTree(int n, Func<T, T, T> operation, T init, T ex) : this(n, operation, ex)
        {
            for (int i = offset; i < offset + n; i++)
                node[i] = init;
        }

        public SegmentTree(T[] values, Func<T, T, T> operation, T ex) : this(values.Length, operation, ex)
        {
            Array.Copy(values, 0, node, offset, values.Length);
            UpdateTree();
        }

        public void Assign(int i, T value)
            => node[offset + i] = value;

        public void AssignAndUpdate(int i, T value)
        {
            i += offset;
            node[i] = value;

            while (i > 0)
            {
                i = (i - 1) / 2;
                node[i] = func(node[2 * i + 1], node[2 * i + 2]);
            }
        }

        public void UpdateTree()
        {
            for (int i = offset - 1; i >= 0; i--)
                node[i] = func(node[2 * i + 1], node[2 * i + 2]);
        }

        public T Query(int head, int foot)
            => Query(head, foot, 0, 0, n);

        private T Query(int head, int foot, int k, int left, int right)
        {
            T leftValue = ex;
            T rightValue = ex;
            int d = offset;

            while (head != foot)
            {
                if ((head & 1) == 1)
                    leftValue = func(leftValue, node[d + head++]);
                if ((foot & 1) == 0)
                    rightValue = func(rightValue, node[d + foot--]);
                head >>= 1;
                foot >>= 1;
                d >>= 1;
            }
            return func(leftValue, rightValue);
        }
    }

    class EDPC_Q
    {
        public static void Main()
        {
            var n = int.Parse(Console.ReadLine());
            var h = Console.ReadLine().Split(' ').Select(i => int.Parse(i)).ToArray();
            var a = Console.ReadLine().Split(' ').Select(i => long.Parse(i)).ToArray();

            // i本目までの最大高さがjである場合についてdpを行う
            var dp = new long[n + 1];
            var segmentTree = new SegmentTree<long>(n, (long x, long y) => Math.Max(x, y), 0, 0);

            for (int i = 0; i < n; i++)
            {
                var max = segmentTree.Query(0, h[i] - 1);
                segmentTree.AssignAndUpdate(h[i] - 1, max + a[i]);
            }
            Console.WriteLine(segmentTree.Query(0, n));
        }
    }
}

using System;
using System.Linq;
using System.Collections.Generic;

public static class Program {
    static int N;
    static long[]table;
    public static void Main() {
        int n=int.Parse(Console.ReadLine());
        int[]h=Console.ReadLine().Split().Select(int.Parse).ToArray();
        for(int i=0;i<n;i++)h[i]--;
        long[]a=Console.ReadLine().Split().Select(long.Parse).ToArray();

        N=1;
        while(N<n)N*=2;
        table=new long[2*N];
        for(int i=0;i<n;i++){
            Update(h[i],a[i]+Query(0,h[i]));
        }
        Console.WriteLine(table[1]);
    }
    public static void Update(int i, long x){
        i+=N;
        table[i]=x;
        for(i/=2;1<=i;i/=2){
            table[i]=Math.Max(table[2*i],table[2*i+1]);
        }
    }
    public static long Query(int l, int r){
        l+=N; r+=N;
        long ans=0;
        for(;l<r;l/=2,r/=2){
            if(l%2==1)ans=Math.Max(ans,table[l++]);
            if(r%2==1)ans=Math.Max(ans,table[--r]);
        }
        return ans;
    }
}

