                if (0 < i) res += rec(i - 1, j, k) * i;
                if (0 < j) res += rec(i + 1, j - 1, k) * j;
                if (0 < k) res += rec(i, j + 1, k - 1) * k;
                res += N;
                res /= i + j + k;
                dp[i, j, k] = res;
                return res;
            };

            int[] sara = new int[3];
            foreach (var a in A)
            {
                sara[a - 1]++;
            }

            double ans = rec(sara[0], sara[1], sara[2]);
            Console.WriteLine(ans);
        }

