    class BIT
    {
        int bitA;
        long[] bit;
        const long INF = long.MaxValue - 10;

        public BIT(int maxa)
        {
            bitA = maxa;
            bit = new long[bitA + 1];
            for (int i = 0; i < bitA; i++)
            {
                bit[i] = 0;
            }
        }

        public void bitErase(int a)
        {
            for (int i = a; i <= bitA; i += i & -i)
            {
                bit[i] = -INF;
            }
        }
        public void bitUpdate(int a, long val)
        {
            for (int i = a; i <= bitA; i += i & -i)
            {
                bit[i] = Math.Max(bit[i], val);
            }
        }
        public long bitCal(int a)
        {
            long ret = 0;
            for (int i = a; i > 0; i &= i - 1)
            {
                ret = Math.Max(ret, bit[i]);
            }
            return ret;
        }
    }





}


