public class SegmentTree<T>
{
    private List<T> item;
    private int _num;
    private Func<T, T, T> _func;
    private Func<T, T, T> updateFunc;
    private T _init;

    private int Parent(int index)
        => (index - 1) / 2;
    private int Left(int index)
        => 2 * index + 1;
    private int Right(int index)
        => 2 * (index + 1);

    public SegmentTree(int num, T init, Func<T, T, T> func, Func<T, T, T> updateFunc = null)
    {
        _func = func;
        _num = 1;
        _init = init;
        this.updateFunc = updateFunc ?? ((T val1, T val2) => val2);
        while (_num < num)
            _num *= 2;
        item = new List<T>(2 * _num - 1);
        for (var i = 0; i < 2 * _num - 1; i++)
            item.Add(init);
    }
    public void Update(int index, T value)
    {
        index += _num - 1;
        item[index] = updateFunc(item[index], value);
        while (index > 0)
        {
            index = Parent(index);
            item[index] = _func(item[Left(index)], item[Right(index)]);
        }
    }
    public T Query(int left, int right)
        => Query(left, right, 0, 0, _num);
    public T Query(int left, int right, int k, int l, int r)
    {
        if (r <= left || right <= l) return _init;
        if (left <= l && r <= right) return item[k];
        else
            return _func(Query(left, right, Left(k), l, (l + r) / 2), Query(left, right, Right(k), (l + r) / 2, r));
    }
}

using System;
using System.Collections.Generic;
class Program{
	const int mod=1000000007;
	static long[] dat;
	static int m=1;
	static void Main(){
		int n=int.Parse(Console.ReadLine());
		int[] h=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		int[] a=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		while(m<=n+1){m*=2;}
		dat=new long[m+n];
		long ans=a[0];
		fdu(h[0],a[0]);
		for(int i=1;i<n;i++){
			long p=fdg(0,h[i]-1,0,0,m-1)+a[i];
			fdu(h[i],p);
			ans=Math.Max(ans,p);
		}
		Console.WriteLine(ans);
	}
	static void fdu(int q,long b){
		q+=m-1;
		dat[q]=b;
		while(q>0){
			dat[(q-1)/2]=Math.Max(dat[(q-1)/2],b);
			q=(q-1)/2;
		}
	}
	static long fdg(int a,int b,int k,int l,int r){
		if(r<a||b<l){return -1;}
		if(a<=l&&r<=b){return dat[k];}
		else{return Math.Max(fdg(a,b,k*2+1,l,(l+r)/2),fdg(a,b,k*2+2,(l+r+1)/2,r));}
	}
}

using System;
using System.Collections.Generic;

class Q
{
	static void Main()
	{
		Func<int[]> read = () => Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
		var n = int.Parse(Console.ReadLine());
		var h = read();
		var a = read();

		var l = new List<int>(n) { 0 };
		var dp = new long[n + 1];
		for (int i = 0; i < n; i++)
		{
			var li = ~l.BinarySearch(h[i]);
			var v = dp[l[li - 1]] + a[i];
			while (li < l.Count && dp[l[li]] <= v) l.RemoveAt(li);
			l.Insert(li, h[i]);
			dp[h[i]] = v;
		}
		Console.WriteLine(dp[l[l.Count - 1]]);
	}
}

