        max = Math.Max(max, nums[i]);
      }
      for(long i = 450*rightPosition; i <= rightNum; i++)//右区間内
      {
        min = Math.Min(min, nums[i]);
        max = Math.Max(max, nums[i]);
      }
      for(long i = leftPosition+1; i < rightPosition; i++)//見ていない区間内
      {
        min = Math.Min(min, numSetsSub[i]);
        max = Math.Max(max, numSetsSub[i]);
      }
    }
    if(minOrMax == -1) return min;
    else return max;
  }

  static long AreaAddMaxGetAnswer(int leftNum, int rightNum)
  {//区間以上以下の値に全てchangeNum加算し、区間以上以下の最大値を求める。出力側
    return AreaAddMaxMinGetAnswer(leftNum, rightNum, 1);
  }

  static long AreaAddMinGetAnswer(int leftNum, int rightNum)
  {//区間以上以下の値に全てchangeNum加算し、区間以上以下の最小値を求める。出力側
    return AreaAddMaxMinGetAnswer(leftNum, rightNum, -1);
  }

  static void NumberApply(int pointNum)
  {//控え中の数を個々に割り当てる
    int numPosition = WherePosition(pointNum);

    if(numSetsSub[numPosition] != long.MinValue/2)
    {
      for(int i = 0; i < 450; i++)//区間内全てを見る
      {
        nums[numPosition*450+i] = numSetsSub[numPosition];
      }
      numSetsSub[numPosition] = long.MinValue/2;
    }
  }

  static void NumberApply(int leftNum, int rightNum)
  {
    NumberApply(leftNum);
    NumberApply(rightNum);
  }

  static void NumberAddMax(int pointNum)
  {//控え中の数を個々に加算した後、最大値を求める
    int numPosition = WherePosition(pointNum);

    if(numSets[numPosition] != 0)
    {
      for(int i = 0; i < 450; i++)//区間内全てを見る
      {
        nums[numPosition*450+i] += numSets[numPosition];
      }
      numSets[numPosition] = 0;
    }

    long max = long.MinValue/2;
    for(int i = 0; i < 450; i++)
    {
      if(nums[numPosition*450+i] > max) max = nums[numPosition*450+i];
    }

    numSetsSub[numPosition] = max;
  }

  static void NumberAddMin(int pointNum)
  {//控え中の数を個々に加算した後、最小値を求める
    int numPosition = WherePosition(pointNum);

    if(numSets[numPosition] != 0)
    {
      for(int i = 0; i < 450; i++)//区間内全てを見る
      {
        nums[numPosition*450+i] += numSets[numPosition];
      }
      numSets[numPosition] = 0;
    }

    long min = long.MaxValue/2;
    for(int i = 0; i < 450; i++)
    {
      if(nums[numPosition*450+i] < min) min = nums[numPosition*450+i];
    }

    numSetsSub[numPosition] = min;
  }

  static void NumberAddMin(int leftNum, int rightNum)
  {
    NumberAddMin(leftNum);
    NumberAddMin(rightNum);
  }

  static void NumberAddMax(int leftNum, int rightNum)
  {
    NumberAddMax(leftNum);
    NumberAddMax(rightNum);
  }

  static int WherePosition(int num)//左から何番目の分類に属するか
  {
    return num / 450;
  }

}

