public class SegmentTree<T>
{
	private long N;
	private T INI;
	private Func<T, T, T> Func;
	private T[] dat;

	public T this[long index]
	{
		get { return dat[index + N - 1]; }
		set { Update(index, value); }
	}

	public SegmentTree(long n, T ini, Func<T, T, T> func)
	{
		N = 1;		
		while(N < n)
			N <<= 1;

		INI = ini;
		Func = func;

		dat = new T[2 * N - 1];
		for(long i = 0; i < 2 * N - 1; i++)
			dat[i] = INI;
	}

	public void Update(long k, T a)
	{
		k += N - 1;
		dat[k] = a;
		while(k > 0)
		{
			k = (k - 1) / 2;
			dat[k] = Func(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}

	public T Query(long a, long b, long k = 0, long l = 0, long r = -1)
	{
		if(r == -1)
			r = N;

		if(r <= a || b <= l)
			return INI;

		if(a <= l && r <= b)
			return dat[k];
		else
		{
			T vl = Query(a, b, k * 2 + 1, l, (l + r) / 2);
			T vr = Query(a, b, k * 2 + 2, (l + r) / 2, r);
			return Func(vl, vr);
		}
	}
}

