    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var h = consoleReader.Split.Int;
            var a = consoleReader.Split.Int;

            long allMax = 0;
            var beautyPoints = new long[h.Max() + 1];
            var indecis = new List<int>();

            for (int i = 0; i < N; i++)
            {
                var beauty = a[i];
                var height = h[i];

                long max = 0;
                foreach (var old in indecis)
                {
                    if (old > height) break;
                    max = Math.Max(max, beautyPoints[old]);
                }
                if (beautyPoints[height] == 0)
                {
                    indecis.Add(height);
                    indecis.Sort();
                }
                beautyPoints[height] = max + beauty;
                allMax = Math.Max(allMax, max + beauty);
            }
            return allMax;
        }


