// 实现一个线段数, 保存的是最大值
// 查询, 从节点n(范围是tl~tr), 查询线段(l~r)之间的最大值
func query(A []int, n int, tl int, tr int, l int, r int) int {
	if tl == l && tr == r {
		return A[n]
	}
	if tl > tr {
		return 0
	}
	if l > r {
		return 0
	}

	mid := tl+(tr-tl)/2
	if r <= mid {
		// 左侧分支
		return query(A, 2*n, tl, mid, l, r)
	}
	if l > mid {
		// 右侧分支
		return query(A, 2*n+1, mid+1, tr, l, r)
	}

	// r>mid && l<=mid
	n1 := query(A, 2*n, tl, mid, l, mid)
	n2 := query(A, 2*n+1, mid+1, tr, mid+1, r)
	return max(n1, n2)
}

// 更新
func update(A []int, n int, tl int, tr int, idx int, val int) {
	if tl == tr && tl == idx {
		A[n] = val
		return
	}

	mid := tl+(tr-tl)/2
	if idx <= mid {
		update(A, 2*n, tl, mid, idx, val)
	} else {
		update(A, 2*n+1, mid+1, tr, idx, val)
	}

	A[n] = max(A[2*n], A[2*n+1])
}

func main() {
	bf := bufio.NewReader(os.Stdin)

	N := readLineNums(bf)[0]
	H := readLineNums(bf)
	A := readLineNums(bf)

	// 线段数
	tree := make([]int, 4*(N+1)+1) // 保存的范围是1~N

	dp := make([]int, N+1)
	for i:=0; i<N; i++ {
		hi := H[i]
		ai := A[i]
		best := query(tree, 1, 1, N, 1, hi-1)
		dp[hi] = best+ai
		update(tree, 1, 1, N, hi, dp[hi])
	}

	ans := 0
	for _, ai := range dp {
		ans = max(ans, ai)
	}
	fmt.Println(ans)
}

