type Datas []flower

func (p Datas) Len() int {
	return len(p)
}

func (p Datas) Swap(i, j int) {
	p[i], p[j] = p[j], p[i]
}

func (p Datas) Less(i, j int) bool {
	return p[i].h < p[j].h
}

func solve(N int, d Datas) int {
	seg := segTreeInit(N)

	for i := 0; i < N; i++ {
		v := seg.query(0, d[i].h)
		v += d[i].a
		seg.set(v, d[i].h)
	}

	return seg.query(0, N)
}

