	"os"
)

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	prev := 0
	cur := 1
	var n, max int
	fmt.Fscan(fp, &n)
	aList := make([]int, n)
	hList := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(fp, &hList[i])
		if max < hList[i] {
			max = hList[i]
		}
	}
	for i := 0; i < n; i++ {
		fmt.Fscan(fp, &aList[i])
	}

	dp := make([][]int64, 2)
	dp[prev] = make([]int64, n+1)
	dp[cur] = make([]int64, n+1)
	for i := 0; i < n; i++ {
		for h := 0; h < hList[i]; h++ {
			dp[cur][h] = dp[prev][h]
		}

		dp[cur][hList[i]] = dp[prev][hList[i]]
		if dp[prev][hList[i]-1]+int64(aList[i]) > dp[cur][hList[i]] {
			dp[cur][hList[i]] = dp[prev][hList[i]-1] + int64(aList[i])
		}

		for h := hList[i] + 1; h <= max; h++ {
			dp[cur][h] = dp[prev][h]
			if dp[cur][h-1] > dp[cur][h] {
				dp[cur][h] = dp[cur][h-1]
			}
		}
		prev, cur = cur, prev
	}
	fmt.Println(dp[prev][n])
}

