func max(a, b int64) int64 {
	if a > b {
		return a
	} else {
		return b
	}
}

func parseInt(s string) int64 {
	x, _ := strconv.ParseInt(s, 10, 64)
	return x
}

func readLine(reader *bufio.Reader) string {
	s, _ := reader.ReadString('\n')
	return strings.TrimSuffix(s, "\n")
}

type Beauty struct {
	beauty int64
	height int
}

var n int
var b [200002]int64
var t [200002]int
var h [200001] /*i*/ int
var a [200001] /*i*/ int64

func main() {
	reader := bufio.NewReader(os.Stdin)
	n = int(parseInt(readLine(reader)))
	for i, token := range strings.Fields(readLine(reader)) {
		h[i+1] = int(parseInt(token))
	}
	for i, token := range strings.Fields(readLine(reader)) {
		a[i+1] = parseInt(token)
	}

	k := 1
	for i := 1; i <= n; i++ {
		p := sort.SearchInts(t[:k], h[i])
		bb := b[p-1] + a[i]

		q := p
		for q < k {
			if b[q] > bb {
				break
			}
			q++
		}

		if q == p {
			for j := k; j > p; j-- {
				t[j], b[j] = t[j-1], b[j-1]
			}
			k++
		} else if q >= p+2 {
			delta := q - p - 1
			for j := q; j < k; j++ {
				t[j-delta], b[j-delta] = t[j], b[j]
			}
			k -= delta
		}
		t[p] = h[i]
		b[p] = bb
	}

	fmt.Println(b[k-1])
}

