class SegmentTree {
public:
  this(long l, long r, long[] a) {
    this.l = l;
    this.r = r;
    if (r == l + 1) {
      v = a[l];
    } else {
      auto m = (l + r) / 2;
      lc = new SegmentTree(l, m, a);
      rc = new SegmentTree(m, r, a);
      v = max(lc.v, rc.v);
    }
  }

  void update(long idx, long v) {
    if(idx < l || r <= idx) {
      return;
    }
    if(l == idx && r == idx+1) {
      this.v = max(this.v, v);
    } else {
      lc.update(idx, v);
      rc.update(idx, v);
      this.v = max(lc.v, rc.v);
    }
  }

  Nullable!long read(long l, long r) {
    if(r <= this.l || this.r <= l) {
      return Nullable!long.init;
    }
    if(l <= this.l && this.r <= r) {
      return this.v.nullable;
    } else {
      auto l_read = lc.read(l, r);
      auto r_read = rc.read(l, r);
      if(l_read.isNull) {
        return r_read;
      }
      if(r_read.isNull) {
        return l_read;
      }
      return max(l_read, r_read);
    }
  }

private:
  long l, r;
  long v;
  SegmentTree lc, rc;
}

