// [l, r)を管理するセグツリー
class SegmentTree(T, alias F) if (is(typeof(binaryFun!F))) {
  alias f = binaryFun!F;
public:
  this(size_t l, size_t r, T t) {
    this.l = l;
    this.r = r;
    if (r == l + 1) {
      v = t;
    } else {
      auto m = (l + r) / 2;
      lc = new SegmentTree(l, m, t);
      rc = new SegmentTree(m, r, t);
      v = f(lc.v, rc.v);
    }
  }
  this(size_t n, T t) {
    this(0, n, t);
  }

  void update(size_t l, size_t r, T v) {
    if(this.r <= l || r <= this.l) {
      return;
    }
    if(l <= this.l && this.r <= r) {
      this.v = v;
    } else {
      lc.update(l, r, v);
      rc.update(l, r, v);
      this.v = f(lc.v, rc.v);
    }
  }

  void update(size_t idx, T v) {
    update(idx, idx+1, v);
  }

  auto read(size_t l, size_t r) {
    assert(this.l <= l && r <= this.r);
    if (l == this.l && this.r == r) {
      return this.v;
    } else {
      if(r <= lc.r) {
        return lc.read(l, r);
      } else if(rc.l <= l) {
        return rc.read(l, r);
      } else {
        return f(lc.read(l, lc.r), rc.read(rc.l, r));
      }
    }
  }

private:
  size_t l, r;
  T v;
  SegmentTree lc, rc;
}

