class SegTreeMax():
    def __init__(self, l):
        self.N = 1
        while self.N < len(l):
            self.N *= 2
        self.L = [0 for _ in range(self.N*2-1)]
        for i in range(len(l)):
            self.L[i+self.N-1] = l[i]
        for i in range(self.N-2, -1, -1):
            self.L[i] = max(self.L[i*2+1], self.L[i*2+2])

    def update(self, k, v):
        k += self.N-1
        self.L[k] = v
        while k > 0 and self.L[(k-1)//2] < v:
            k = (k-1)//2
            self.L[k] = v

    def query(self, a, b):
        return self.inquiry(0, self.N, 0, a, b)

    def inquiry(self, l, r, k, a, b):
        if r <= a or l >= b:
            return 0
        if a <= l and b >= r:
            return self.L[k]
        vl = self.inquiry(l, (l+r)//2, k*2+1, a, b)
        vr = self.inquiry((l+r)//2, r, k*2+2, a, b)
        return max(vl, vr)


