    def __init__(self, n, sentinel=0):
        self.n = 1 << n.bit_length()
        self.offset = self.n - 1
        m = (self.n << 1) - 1
        self.data = [sentinel] * m
        self.sentinel = sentinel

    def update(self, k, x):
        i = k + self.offset
        self.data[i] = max(self.data[i], x)
        while i:
            i = (i - 1) // 2
            self.data[i] = max(self.data[i], x)

