def query(l, r,tree,n,fun) :  
    if fun == "max":
        res = -1*sys.maxsize
    if fun == "min":
        res = sys.maxsize
    if fun == "sum":
        res = 0
    # loop to find the sum in the range  
    l += n; 
    r += n; 
    while l < r : 
        if (l & 1) : 
            # res += tree[l]  
            res = seg_fun(fun,res,tree[l])
            l += 1

        if (r & 1) : 
            r -= 1
            # res += tree[r]  
            res = seg_fun(fun,res,tree[r])

        l >>= 1
        r >>= 1

    return res;  


