    def __init__(self, N):
        self.size = N
        self.tree = [0] * (N + 1)
    def max(self, i):
        s = 0
        while i > 0:
            if s < self.tree[i]:
                s = self.tree[i]
            i -= i & -i
        return s
    def __setitem__(self, i, x):
        while i <= self.size:
            if self.tree[i] < x:
                self.tree[i] = x
            i += i & -i


