class SegmentTree:

    def __init__(self, array, aggregator):
        self.array = array
        self.aggregator = aggregator
        N = 1
        while N < len(array):
            N *= 2
        self.tree = [0]*(2*N-1)
        self.construct_tree(0, len(array)-1, 0)

    def construct_tree(self, low, high, pos):
        if low == high:
            self.tree[pos] = self.array[low]
        else:
            mid = (low+high)//2
            self.construct_tree(low, mid, 2*pos+1)
            self.construct_tree(mid+1, high, 2*pos+2)
            self.tree[pos] = self.aggregator(self.tree[2*pos+1],
                                             self.tree[2*pos+2])

    def query(self, qlow, qhigh):
        return self._query(qlow, qhigh, 0, len(self.array)-1, 0)

    def _query(self, qlow, qhigh, low, high, pos):
        if qlow <= low and high <= qhigh:
            return self.tree[pos]
        if qlow > high or qhigh < low:
            return 0
        mid = (low+high)//2
        return self.aggregator(self._query(qlow, qhigh, low, mid, 2*pos+1),
                               self._query(qlow, qhigh, mid+1, high, 2*pos+2))


    def update(self, index, value):
        self._update(index, value, 0, len(self.array)-1, 0)

    def _update(self, index, value, low, high, pos):
        if index < low or index > high:
            return
        if low == high:
            self.tree[pos] = value
        else:
            mid = (low+high)//2
            self._update(index, value, low, mid, 2*pos+1)
            self._update(index, value, mid+1, high, 2*pos+2)
            self.tree[pos] = self.aggregator(self.tree[2*pos+1], self.tree[2*pos+2])

    def __str__(self):
        start, end = 0, 1
        levels = []
        while end-1 <= len(self.tree):
            levels.append(self.tree[start:end])
            start, end = end, end+(end-start)*2
        return '\n'.join(map(str, levels))


