class SegTree:

    def __init__(self, A, intv, initialize = True):
        self.N = len(A)
        self.N0 = 2**(self.N-1).bit_length()
        self.dep = self.N0.bit_length()
        if initialize:
            self.data = [intv]*(self.N0-1) + A + [intv]*(self.N0 - self.N + 1)
            for i in range(self.N0-2, -1, -1):
                self.data[i] = max(self.data[2*i+1], self.data[2*i+2]) 
        else:
            self.data = [intv]*(2*self.N0)

    def segf(self, a, b):
        return max(a, b)

    def update(self, k, x):
        k += self.N0-1
        self.data[k] = x
        for _ in range(self.dep - 1):
            k = (k-1)//2
            self.data[k] = max(self.data[2*k+1], self.data[2*k+2])

    def query(self, l, r):
        L, R = l+self.N0, r+self.N0
        s = 0
        while L < R:
            if R & 1:
                R -= 1
                s = max(s, self.data[R-1])
            if L & 1:

                s = max(s, self.data[L-1])
                L += 1
            L >>= 1
            R >>= 1
        return s

