class Bucket:
    def __init__(self, a, k, func=max, one=-10**18):
        self.n = len(a)
        self.k = k
        self.func = func
        self.one = one

        self.a = a[:]
        self.b = []
        for i in range(self.n // self.k):
            s = self.one
            for j in range(i * self.k, i * self.k + self.k):
                s = func(s, self.a[j])
            self.b.append(s)
        s = self.one
        for i in range(self.n // self.k * self.k, self.n):
            s = self.func(s, self.a[i])
        self.b.append(s)

    def get_0(self, index):
        s = self.one
        j = index // self.k

        for i in range(j):
            s = self.func(s, self.b[i])
        for i in range(j * self.k, index + 1):
            s = self.func(s, self.a[i])
        return s

    def get(self, index1, index2):
        s = self.one
        j1 = index1 // self.k
        j2 = index2 // self.k

        if j1 == j2:
            s = self.one
            for i in range(index1, index2 + 1):
                s = self.func(s, self.a[i])
            return s

        for i in range(index1, j1 * self.k + self.k):
            s = self.func(s, self.a[i])
        for i in range(j1+1, j2):
            s = self.func(s, self.b[i])
        for i in range(j2 * self.k, index2 + 1):
            s = self.func(s, self.a[i])
        return s

    def update(self, index, x):
        self.a[index] = self.func(x, self.a[index])
        self.b[index//self.k] = self.func(self.b[index//self.k], x)


