struct SegmentTree {
    n: usize,
    data: Vec<i64>,
}

impl SegmentTree {
    fn f(&self, a: i64, b: i64) -> i64 {
        max(a as usize, b as usize) as i64
    }

    pub fn initial() -> i64 {
        0
    }

    fn new(size: usize) -> Self {
        let n = {
            let mut res = 1;
            while res < size {
                res <<= 1
            }
            res
        };
        let data = vec![Self::initial(); n * 2 - 1];
        SegmentTree { n: n, data: data }
    }

    fn update(&mut self, k: usize, a: i64) {
        let mut index = k + self.n - 1;
        self.data[index] = a;
        while index > 0 {
            index = (index - 1) / 2;
            self.data[index] = self.f(self.data[index * 2 + 1], self.data[index * 2 + 2]);
        }
    }

    // [a, b)
    fn query(&mut self, a: usize, b: usize) -> i64 {
        let (l, r) = (0, self.n);
        self.query_iter(a, b, 0, l, r)
    }

    fn query_iter(&mut self, a: usize, b: usize, k: usize, l: usize, r: usize) -> i64 {
        if r <= a || b <= l {
            Self::initial()
        } else if a <= l && r <= b {
            self.data[k]
        } else {
            let vl = self.query_iter(a, b, k * 2 + 1, l, (l + r) / 2);
            let vr = self.query_iter(a, b, k * 2 + 2, (l + r) / 2, r);
            self.f(vl, vr)
        }
    }
}

fn main() {
    input! {
        n: usize,
        h: [usize; n],
        a: [usize; n],
    }

    let m = h.iter().max().unwrap();
    let mut segtree = SegmentTree::new(m + 1);

    for i in 0..n {
        let opt = segtree.query(0, h[i]) as usize + a[i];
        let next = max(segtree.query(h[i], h[i] + 1), opt as i64);
        segtree.update(h[i], next);
    }

    let ans = segtree.query(0, m + 1);
    println!("{}", ans);
}

