struct Bit {
    elements: Vec<i64>,
}

impl Bit {
    fn update(&mut self, index: usize, value: i64) {
        let mut index = index + 1;
        while index < self.elements.len() {
            self.elements[index] = max(self.elements[index], value);
            index += (index as i64 & -(index as i64)) as usize;
        }
    }

    fn find_max(&self, index: usize) -> i64 {
        let mut index = 1 + index as i64;
        let mut result = 0;
        while index > 0 {
            result = max(result, self.elements[index as usize]);
            index -= index & -index;
        }
        result
    }
}

fn run() -> Result<(), Box< Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input);
    let n = input.trim().parse::<i32>().unwrap();
    input.clear();
    io::stdin().read_line(&mut input);
    let hs: Vec<i64> = input
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();
    input.clear();
    io::stdin().read_line(&mut input);
    let vs: Vec<i64> = input
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();
    input.clear();
    // (h, v)
    let mut pairs = vec![];
    for i in 0..n as usize {
        pairs.push((hs[i], vs[i]));
    }
    pairs.sort_by_key(|&(h, _)| h);

    let mut bit = Bit {
        elements: vec![0; 1 + n as usize],
    };
    let mut result = 0;
    for i in 0..n as usize {
        let target_index = pairs.binary_search_by_key(&hs[i], |&(h, _)| h).unwrap();
        let mut new_max = pairs[target_index].1;
        if target_index != 0 {
            new_max += bit.find_max(target_index - 1);
        }
        bit.update(target_index, new_max);
        result = max(result, bit.find_max(target_index));
    }
    println!("{:?}", result);
    Ok(())
}

