struct FenwickTree<T, F> {
    n: usize,
    a: Vec<T>,
    id: T,
    op: F
}

impl<T: Clone, F: Fn(T, T) -> T> FenwickTree<T, F> {
    pub fn new (n: usize, id: T, op: F) -> FenwickTree<T, F> {
        FenwickTree {
            n: n,
            a: vec![id.clone(); n + 1],
            id: id,
            op: op,
        }
    }
    pub fn update (&mut self, x: usize, v: T) {
        let mut k = x;
        while k <= self.n {
            self.a[k] = (self.op) (self.a[k].clone(), v.clone());
            k += k & (!k + 1);
        }
    }
    pub fn find (&self, x: usize) -> T {
        let mut v = self.id.clone();
        let mut k = x;
        while k > 0 {
            v = (self.op) (v.clone(), self.a[k].clone());
            k -= k & (!k + 1);
        }
        v
    }
}

fn run() {
    input! {
        n: usize,
        h: [usize; n],
        a: [u64; n],
    }
    let mut bit = FenwickTree::new(n, 0, std::cmp::max);
    for i in 0..n {
        let v = bit.find(h[i]) + a[i];
        bit.update (h[i], v);
    }
    let ans = bit.find (n);
    println! ("{}", ans);
}

