            let mm = v
                .iter()
                .zip([a, b, c].iter())
                .map(|(v1, &a)| (v1.iter().sum::<usize>() as i64 - a as i64).abs())
                .sum::<i64>();
            m + mm
        })
        .min()
        .unwrap();

    println!("{}", ans);
}

