impl SqDecomposition {
    fn new(n: usize) -> SqDecomposition {
        let d = (n as f64).sqrt().ceil() as usize;
        SqDecomposition {
            all: vec![0; n],
            sq: vec![0; d],
            d: d,
        }
    }
    fn max(&self, n: usize) -> u64 {
        let mut ret = 0;
        for i in 0..n / self.d {
            chmax!(ret, self.sq[i]);
        }
        for i in 0..n % self.d {
            chmax!(ret, self.all[n - n % self.d + i]);
        }
        ret
    }

