    fn sum(&self, n: usize) -> u64 {
        let mut ret = 0;
        for i in 0..n / self.d {
            ret += self.sq[i];
        }
        for i in 0..n % self.d {
            ret += self.all[n - n % self.d + i];
        }
        ret
    }
    fn lower_bound_of_sum(&self, mut sum: u64) -> usize {
        let mut i = 0;
        while sum > self.sq[i] {
            sum -= self.sq[i];
            i += 1;
        }
        for j in self.d * i..self.d * (i + 1) {
            if self.all[j] >= sum {
                return j;
            }
            sum -= self.all[j];
        }
        panic!();
    }
