    fn sum(i:i64, bit:&Vec<i64>)->i64{
        let mut s = 0;
        let mut i = i;
        while(i>0){
            s = cmp::max(s, bit[i as usize]);
            i-=i&-i;
        }
        s
    }
    fn add(i:i64, x:i64, bit:&mut Vec<i64>, n:i64){
        let mut i = i;
        while(i<=n){
            bit[i as usize] = cmp::max(x, bit[i as usize]);
            i += i&-i;
        }
    }
    let mut dp = vec![0;n+1];
    for i in 0..n{
        dp[h[i] as usize] = sum(h[i], &bit) + a[i];
        add(h[i], dp[h[i] as usize], &mut bit, n as i64);
    }
    let mut res = 0;
    for i in 0..n+1{
        res = cmp::max(dp[i], res);
    }
