struct RMQ {
    blocks: Vec<usize>,
    data: Vec<usize>,
}


impl RMQ {
    fn new(data: Vec<usize>) -> Self {
        let block_size = (data.len() as f64).sqrt() as usize + 1;
        let mut blocks = vec![0; block_size];
        for i in 0..data.len() {
            let block_index = i/block_size;
            blocks[block_index] = max(data[i], blocks[block_index]);
        }
        RMQ {
            blocks: blocks,
            data: data,
        }
    }

    fn update(&mut self, i:usize, v: usize) {
        self.data[i] = v;
        let block_index = i/self.blocks.len();
        self.blocks[block_index] = max(self.blocks[block_index], v);
    }

    // [l,r]
    fn query(&self, l: usize, r:usize) -> usize {
        assert!(l <= r);
        let block_size = self.blocks.len();
        let lb = l/block_size;
        let rb = r/block_size;
        let mut cur = lb;
        let mut ans = 0;
        while cur <= rb {
            if cur == lb || cur == rb {
                let mut ll = cur * block_size;
                let mut rr = (cur+1) * block_size - 1;
                if cur == lb { ll = l; }
                if cur == rb { rr = r; }

                for i in ll..rr+1 {
                    ans = max(ans, self.data[i]);
                }
            } else {
                ans = max(ans, self.blocks[cur]);
            }
            cur += 1;
        }
        ans
    }
}


fn main() {
    input!{
      n: usize,
      hs: [usize; n],
      aa: [usize; n],
    }
    let mut rmq = RMQ::new(vec![0; n+1]);

    for i in 0..n {
        let h = hs[i];
        let max_v = rmq.query(0, h-1);
        rmq.update(h, max_v+aa[i]);
    }
    let ans = rmq.query(0, n);
    println!("{}", ans);
}

use proconio::{input, marker::Usize1};

struct DP {
    dp: Vec<u64>,
    dpn: usize,
}

impl DP {
    fn new(n: usize) -> DP {
        let mut dpn = 1;
        while dpn < n {
            dpn <<= 1;
        }
        DP {
            dp: vec![0; 2 * dpn - 1],
            dpn: dpn,
        }
    }

    fn update_max(&mut self, i: usize, v: u64) {
        let mut i = i + self.dpn - 1;
        self.dp[i] = v;
        while i > 0 {
            i = (i - 1) / 2;
            self.dp[i] = self.dp[2 * i + 1].max(self.dp[2 * i + 2]);
        }
    }

    fn get_max(&self, e: usize, k: usize, rng: Option<(usize, usize)>) -> u64 {
        let (l, r) = if let Some(rng) = rng { rng } else { (0, self.dpn) };
        if l >= e || r <= 0 {
            0
        } else if r <= e {
            self.dp[k]
        } else {
            let m = (l + r) / 2;
            let vl = self.get_max(e, 2 * k + 1, Some((l, m)));
            let vr = self.get_max(e, 2 * k + 2, Some((m, r)));
            vl.max(vr)
        }
    }
}

fn main() {
    input! {
        n: usize,
        h: [Usize1; n],
        a: [u64; n],
    }

    let mut dp = DP::new(n);
    dp.update_max(h[0], a[0]);
    for i in 1..n {
        let m = dp.get_max(h[i] + 1, 0, None);
        dp.update_max(h[i], m + a[i]);
    }

    println!("{}", dp.get_max(n, 0, None));
}

use std::cmp::max;
use std::error::Error;
use std::io;

fn main() {
    if let Err(e) = run() {
        panic!("failed.");
    }
}

fn run() -> Result<(), Box< Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input);
    let n = input.trim().parse::<i32>().unwrap();
    input.clear();
    io::stdin().read_line(&mut input);
    let hs: Vec<i64> = input
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();
    input.clear();
    io::stdin().read_line(&mut input);
    let vs: Vec<i64> = input
        .trim()
        .split_whitespace()
        .map(|s| s.parse::<i64>().unwrap())
        .collect();
    input.clear();

    let mut dp = vec![0; n as usize];
    // height & index.
    let mut queue: Vec<(i64, usize)> = vec![];
    for i in 0..n as usize {
        let target_index = queue
            .binary_search_by_key(&hs[i], |&(h, i)| h)
            .err()
            .unwrap();
        dp[i] = vs[i];

        if i == 0 || target_index == 0 || target_index < i - queue[target_index - 1].1 {
            for j in 0..target_index {
                dp[i] = max(dp[i], dp[queue[j].1] + vs[i]);
            }
        } else {
            for j in queue[target_index - 1].1..i {
                if queue[j].0 < hs[i] {
                    dp[i] = max(dp[i], dp[queue[j].1] + vs[i]);
                }
            }
        }
        queue.insert(target_index, (hs[i], i));
    }
    let mut result = 0;
    for i in 0..n as usize {
        result = max(result, dp[i]);
    }
    println!("{:?}", result);
    Ok(())
}

