    let n: usize = read();
    let h: Vec<i64> = read_vec();
    let a: Vec<i64> = read_vec();
    let mut dp = SegmentTree::new_max(&vec![0; n+1]);
    let mut ans = 0;
    println!("ans = {}", ans);
    for i in 0..n {
      let tmp = a[i] + dp.get_max(1, h[i] as usize + 1);
      ans = max(ans, tmp);
