#[allow(dead_code)]
struct SqDecomposition {
    all: Vec<u64>,
    sq: Vec<u64>,
    d: usize,
    op: Box<Fn(u64, u64) -> u64>,
    init: u64,
}
#[allow(dead_code)]
impl SqDecomposition {
    fn new<B>(n: usize, op: B, init: u64) -> SqDecomposition
    where
        B: Fn(u64, u64) -> u64 + 'static,
    {
        let d = (n as f64).sqrt().ceil() as usize;
        SqDecomposition {
            all: vec![init; n],
            sq: vec![init; d],
            d: d,
            op: Box::new(op),
            init: init,
        }
    }
    fn update(&mut self, i: usize, a: u64) {
        self.all[i] = (self.op)(self.all[i], a);
        self.sq[i / self.d] = (self.op)(self.sq[i / self.d], a);
    }
    #[doc = " [0,n)"]
    fn fold(&self, n: usize) -> u64 {
        let mut ret = self.init;
        for i in 0..n / self.d {
            ret = (self.op)(ret, self.sq[i]);
        }
        for i in 0..n % self.d {
            ret = (self.op)(ret, self.all[n - n % self.d + i]);
        }
        ret
    }
}

