use std::ops::{AddAssign, Sub};
trait BIT<T: Copy + Clone + Sub + AddAssign> {
   fn add(&mut self, idx: usize, w: T);
   fn sum(&self, idx: usize) -> T;
}

impl BIT<usize> for [usize] {
   /// let mut bit = vec![0; n+1];
   /// for (i, w) in 0..q {
   ///    bit.add(i, w);
   /// }
   fn add(&mut self, idx: usize, w: usize) {
      let mut j = (idx + 1) as i64;
      while j < self.len() as i64 {
         self[j as usize] = std::cmp::max(self[j as usize], w);
         j += j & -j;
      }
   }
   /// [0, r]
   fn sum(&self, idx: usize) -> usize {
      let mut i = (idx + 1) as i64;
      let mut sum = self[0];
      while i != 0 {
         sum = std::cmp::max(sum, self[i as usize]);
         i -= i & -i;
      }
      sum
   }
}

