	let a: Vec<i64> = s.take(n).map(|a| a.parse().unwrap()).collect();
	let mut bit = BIT::new(n, 0, |a, b| std::cmp::max(a, b));
	for (h, a) in h.into_iter().zip(a.into_iter()) {
		let m = bit.fold(h - 1);
		bit.apply(h - 1, m + a);
	}
	println!("{}", bit.fold(n));
}

pub struct BIT<T, F> {
	data: Vec<T>,
	e: T,
	op: F,
}

impl<T, F> BIT<T, F>
where
	T: Clone,
	F: Fn(T, T) -> T,
{
	pub fn new(n: usize, e: T, op: F) -> Self {
		Self {
			data: vec![e.clone(); n],
			e,
			op,
		}
	}

	pub fn fold(&self, i: usize) -> T {
		let mut r = self.e.clone();
		let mut i = i;
		while i > 0 {
			r = (self.op)(self.data[i - 1].clone(), r);
			i &= i - 1;
		}
		r
	}

	pub fn apply(&mut self, i: usize, value: T) {
		let mut i = i;
		while i < self.data.len() {
			self.data[i] = (self.op)(self.data[i].clone(), value.clone());
			i |= i + 1;
		}
	}
}

