struct Monoid<T> {
    id: T,
    op: Box<Fn(&T, &T) -> T>,
}
impl<T> Monoid<T> {
    fn new(id: T, op: Box<Fn(&T, &T) -> T>) -> Monoid<T> {
        Monoid { id: id, op: op }
    }
}
impl Monoid<usize> {
    fn max() -> Monoid<usize> {
        Monoid::new(std::usize::MIN, Box::new(|x, y| std::cmp::max(*x, *y)))
    }
}
struct BinaryIndexedTree<T: Clone> {
    bit: Vec<T>,
    op: Monoid<T>,
}
impl<T: Clone> BinaryIndexedTree<T> {
    fn new(n: usize, op: Monoid<T>) -> BinaryIndexedTree<T> {
        let bit = vec![op.id.clone(); n + 1];
        BinaryIndexedTree { bit: bit, op: op }
    }
    fn query(&self, i: usize) -> T {
        let mut res = self.op.id.clone();
        let mut i = i as isize + 1;
        while i > 0 {
            res = (self.op.op)(&res, &self.bit[i as usize]);
            i -= i & -i;
        }
        res
    }
    fn update(&mut self, i: usize, x: T) {
        let mut i = i as isize + 1;
        while i < self.bit.len() as isize {
            self.bit[i as usize] = x.clone();
            i += i & -i;
        }
    }
}
fn main() {
    input! { n, h: [usize; n], a: [usize; n] };
    let mut bit = BinaryIndexedTree::new(n + 1, Monoid::max());
    for i in 0..n {
        let pa = bit.query(h[i] - 1);
        bit.update(h[i], pa + a[i]);
    }
    println!("{}", bit.query(n));
}
